    local function refreshFormat()
        local key = normalizeAccessKey(input.Text)
        local blocks = 0
        local rest = key:match("^YINYANG%-(.*)$")
        if rest then
            for part in rest:gmatch("[^%-]+") do
                if part:match("^%w%w%w$") then blocks = blocks + 1 end
            end
        end
        local ready = isAccessKeyFormat(key)
        formatText.Text = math.min(blocks, 5) .. "/5"
        formatText.TextColor3 = ready and K.OK or T.TextDim
        formatDot.BackgroundColor3 = ready and K.OK or (key ~= "" and K.WORK or T.TextDim)
        markSteps(ready and 3 or (key ~= "" and 2 or 1))
    end
