local LIBRARY_LOAD_ATTEMPTS = 3
local LIBRARY_LOAD_RETRY_WAIT = 1.5

local function notifyLoadStatus(text, duration, textEnglish)
    pcall(function()
        local lang = string.lower(tostring(game:GetService("LocalizationService").SystemLocaleId or ""))
        if textEnglish and lang:sub(1, 2) ~= "es" then text = textEnglish end
    end)
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = "Yin Yang",
            Text = text,
            Duration = duration or 6,
        })
    end)
end

local success = false
local lastLoadError = nil

for attempt = 1, LIBRARY_LOAD_ATTEMPTS do
    local ok, err = pcall(function()
        local source = nil
        if attempt == 1 then
            while not LibraryPrefetch.done do
                task.wait()
            end
            source = LibraryPrefetch.source
            LibraryPrefetch.source = nil
        end
        loadstring(source or game:HttpGet(LIBRARY_URL))()
    end)

    if ok and _G.YinYang then
        success = true
        break
    end

    lastLoadError = err
    warn(string.format("[Yin Yang] Intento %d/%d de carga fallido: %s", attempt, LIBRARY_LOAD_ATTEMPTS, tostring(err)))

    if attempt < LIBRARY_LOAD_ATTEMPTS then
        notifyLoadStatus("No se pudo cargar la interfaz, reintentando (" .. attempt .. "/" .. LIBRARY_LOAD_ATTEMPTS .. ")...", 4,
            "Couldn't load the interface, retrying (" .. attempt .. "/" .. LIBRARY_LOAD_ATTEMPTS .. ")...")
        task.wait(LIBRARY_LOAD_RETRY_WAIT)
    end
end

if not success then
    notifyLoadStatus("No se pudo cargar la interfaz tras " .. LIBRARY_LOAD_ATTEMPTS .. " intentos. Revisa tu conexión y volvé a ejecutar el script.", 10,
        "Couldn't load the interface after " .. LIBRARY_LOAD_ATTEMPTS .. " tries. Check your connection and run the script again.")
    error("ERROR: Failed to load Yin Yang v28 Final — " .. tostring(lastLoadError))
    return
end

print("LIBRARY: Yin Yang v28 Final loaded successfully")
task.wait()

print("SYSTEM: Initialization completed")

print("\nCreating EVADE v5.2 Beta interface...")

function GetSavedTheme()
    local theme = "Dark"
    pcall(function()
        if isfile and isfile("Yin_Yang_Config.txt") then
            local content = readfile("Yin_Yang_Config.txt")
            if content and content ~= "" then
                local value = content:match("theme:([^|]+)")
                if value then
                    theme = value
                end
            end
        end
    end)
    return theme
end

local UI = _G.YinYang:CreateWindow("Yin Yang", GetSavedTheme())

-- Reemplaza unicamente el titulo principal por la imagen indicada.
-- La libreria se crea de forma asincrona, por eso se busca durante unos segundos.
task.spawn(function()
    local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")
    local titleLabel = nil

    for attempt = 1, 40 do
        for _, instance in ipairs(PlayerGui:GetDescendants()) do
            if instance:IsA("TextLabel")
                and instance.Text == "Yin Yang"
                and math.abs(instance.Position.Y.Offset) <= 15
                and instance.Parent
                and not instance:FindFirstChild("YinYangTitleImage") then
                titleLabel = instance
                break
            end
        end

        if titleLabel then break end
        task.wait(0.25)
    end

    if not titleLabel then
        warn("[Yin Yang] No se encontro el TextLabel del titulo principal; no se modifico la interfaz.")
        return
    end

    titleLabel.Text = ""

    local titleImage = YYKitMake("ImageLabel")
    titleImage.Name = "YinYangTitleImage"
    titleImage.Position = titleLabel.Position
    titleImage.Size = titleLabel.Size
    titleImage.AnchorPoint = titleLabel.AnchorPoint
    titleImage.BackgroundTransparency = 1
    titleImage.Image = "rbxassetid://139893075722317"
    titleImage.ScaleType = Enum.ScaleType.Fit
    titleImage.ZIndex = titleLabel.ZIndex + 1
    titleImage.Parent = titleLabel.Parent
end)

