-- ===== TRADUCCIÓN DE SLIDERS =====
-- La librería muestra el texto del slider tal cual (un solo idioma). Se envuelve CreateSlider de estas 3 pestañas:
-- el nombre sale traducido según el idioma detectado y la etiqueta lleva TextSpanish/TextEnglish para que
-- refreshScriptLanguage la cambie si se cambia el idioma de la interfaz.
YYSliderNames = {
    ["Speed"] = "Velocidad", ["Accel"] = "Aceleración", ["Bhop Accel"] = "Acel. bhop", ["Max Accel"] = "Acel. máx.",
    ["Min Accel"] = "Acel. mín.", ["Max Speed"] = "Vel. máx.", ["Bounce"] = "Rebote", ["Edge Power"] = "Fuerza borde",
    ["Fall Limit"] = "Límite caída", ["Goat Range"] = "Rango Goat", ["Goat Height"] = "Altura Goat", ["TP Speed"] = "Vel. paso",
    ["Height"] = "Altura", ["Slide Speed"] = "Vel. slide", ["Jump Rate"] = "Saltos/seg", ["Crouch Rate"] = "Agachadas/seg",
    ["Boost"] = "Impulso", ["Jumps"] = "Saltos", ["Impulse"] = "Fuerza", ["Front Speed"] = "Vel. frontal",
    ["Front Ramp"] = "Rampa frontal", ["Ramp Power"] = "Fuerza rampa", ["Back Speed"] = "Vel. atrás", ["Back Ramp"] = "Rampa atrás",
    ["Gravity"] = "Gravedad", ["Trimp Power"] = "Fuerza trimp", ["Fall Speed"] = "Vel. caída", ["Radius"] = "Radio",
    ["Outer Radius"] = "Radio externo", ["Inner Ratio"] = "Radio interno", ["Pull %"] = "Tirón %", ["Damping %"] = "Amortiguación %",
    ["Range"] = "Alcance", ["Carry Range"] = "Rango", ["Grab Delay"] = "Espera agarre", ["Cola Duration"] = "Duración cola",
    ["Cola Speed"] = "Vel. cola", ["Emote Speed"] = "Vel. emote", ["Stretch X"] = "Estirar X", ["Stretch Y"] = "Estirar Y",
    ["Spyder Speed"] = "Vel. Spyder", ["Spyder Hover"] = "Distancia Spyder", ["Spyder Turn"] = "Giro Spyder",
    ["Bot Distance"] = "Distancia bot", ["Bot Speed"] = "Revisión bot",
    ["Ticket Speed %"] = "Vel. ticket %",
}
function YYWrapSliders(tab)
    local original = tab and tab.CreateSlider
    if type(original) ~= "function" then return end
    tab.CreateSlider = function(self, text, ...)
        local es = YYSliderNames[text]
        local shown = es and scriptText(es, text) or text
        local result = original(self, shown, ...)
        if es then
            pcall(function()
                -- la etiqueta está en el último elemento creado de la pestaña (la tarjeta del slider)
                local kids = self.Page:GetChildren()
                for i = #kids, 1, -1 do
                    if kids[i]:IsA("GuiObject") then
                        for _, d in ipairs(kids[i]:GetDescendants()) do
                            if d:IsA("TextLabel") and d.Text == shown and d:GetAttribute("TextSpanish") == nil then
                                d:SetAttribute("TextSpanish", es)
                                d:SetAttribute("TextEnglish", text)
                            end
                        end
                        break
                    end
                end
            end)
        end
        return result
    end
end
YYWrapSliders(TabMove)
YYWrapSliders(TabMap)
