function YYPersistLoad()
    local ok, data = pcall(function()
        if isfile and isfile(YYPersist.File) then
            local content = readfile(YYPersist.File)
            if content and content ~= "" then
                return game:GetService("HttpService"):JSONDecode(content)
            end
        end
        return nil
    end)
    if ok and type(data) == "table" then
        if type(data.opts) ~= "table" then data.opts = {} end
        YYPersist.Data = data
    end
end
YYPersistLoad()

-- escribe el archivo con una pequeña espera, para juntar varios cambios seguidos en una sola escritura
function YYPersistSchedule()
    if YYPersist.Dirty then return end
    YYPersist.Dirty = true
    task.delay(0.6, function()
        YYPersist.Dirty = false
        pcall(function()
            writefile(YYPersist.File, game:GetService("HttpService"):JSONEncode(YYPersist.Data))
        end)
    end)
end

function YYPersistSet(key, value)
    YYPersist.Data.opts[key] = value
    YYPersistSchedule()
end

function YYPersistWrapTab(tab, tabName)
    if not tab then return end
    local origToggle = tab.CreateToggle
    local origFloat = tab.CreateFloatingToggle
    local origSlider = tab.CreateSlider

    -- CreateToggle(es, en, default, callback, ...) o CreateToggle(es, default, callback, ...)
    local function wrapToggle(orig, isFloat)
        return function(self, ...)
            -- CreateFloatingToggle crea internamente un CreateToggle: ese no se vuelve a envolver
            if YYPersist.InFloating then
                return orig(self, ...)
            end
            local args = table.pack(...)
            local hasEn = type(args[2]) == "string"
            local di = hasEn and 3 or 2
            local cb = args[di + 1]
            local key = tabName .. "|T|" .. tostring(args[1])
            if not YYPersistIncluded[key] or type(cb) ~= "function" then
                return orig(self, ...)
            end
            local default = args[di] and true or false
            local saved = YYPersist.Data.opts[key]
            local initial = default
            if type(saved) == "boolean" then initial = saved end
            args[di] = initial
            args[di + 1] = function(v)
                YYPersistSet(key, v and true or false)
                return cb(v)
            end
            if isFloat then YYPersist.InFloating = true end
            local ok, res = pcall(orig, self, table.unpack(args, 1, args.n))
            YYPersist.InFloating = false
            if not ok then error(res, 0) end
            if tabName == "Avatar" then
                table.insert(YYPersist.AvatarItems, { obj = res, cb = cb })
            elseif type(saved) == "boolean" and saved ~= default then
                table.insert(YYPersist.Pending, function() cb(saved) end)
            end
            return res
        end
    end

    -- CreateSlider(texto, min, max, default, callback, isMirror)
    local function wrapSlider(orig)
        return function(self, text, min, max, default, cb, isMirror)
            local key = tabName .. "|S|" .. tostring(text) .. "|" .. tostring(min) .. "|" .. tostring(max)
            if isMirror or not YYPersistIncluded[key] or type(cb) ~= "function" then
                return orig(self, text, min, max, default, cb, isMirror)
            end
            local res = orig(self, text, min, max, default, function(v)
                local n = tonumber(v)
                if n then YYPersistSet(key, n) end
                return cb(v)
            end, isMirror)
            local saved = tonumber(YYPersist.Data.opts[key])
            if saved and saved ~= default then
                saved = math.clamp(saved, min, max)
                -- la librería reajusta el slider al valor por defecto en un task.defer: por eso se mueve al final
                table.insert(YYPersist.Pending, function()
                    if res and res.Set then pcall(res.Set, saved) end
                    cb(saved)
                end)
            end
            return res
        end
    end

    if type(origToggle) == "function" then tab.CreateToggle = wrapToggle(origToggle, false) end
    if type(origFloat) == "function" then tab.CreateFloatingToggle = wrapToggle(origFloat, true) end
    if type(origSlider) == "function" then tab.CreateSlider = wrapSlider(origSlider) end
end
YYPersistWrapTab(TabMove, "Move")
YYPersistWrapTab(TabMap, "Map")
YYPersistWrapTab(TabAvatar, "Avatar")

-- ===== AVATAR: guardar el look (skin de otro jugador y objetos del catálogo) =====
-- Se guarda la HumanoidDescription que quedó puesta en el rig visual (Workspace.Rigs.<jugador>) cada vez que se aplica
-- un avatar por nombre (ApplyAvatarByUsername) o un objeto del catálogo (applyDescription). Al entrar se espera al rig
-- y se vuelve a poner. Korblox/Headless se guardan aparte (son toggles de la pestaña Avatar).
YYAvatarListProps = { "HatAccessory", "HairAccessory", "FaceAccessory", "NeckAccessory", "ShouldersAccessory", "FrontAccessory", "BackAccessory", "WaistAccessory" }
YYAvatarIdProps = { "HatAccessory", "HairAccessory", "FaceAccessory", "NeckAccessory", "ShouldersAccessory", "FrontAccessory", "BackAccessory", "WaistAccessory",
    "Shirt", "Pants", "GraphicTShirt", "Face", "Head", "Torso", "LeftArm", "RightArm", "LeftLeg", "RightLeg" }
YYAvatarColorProps = { "HeadColor", "TorsoColor", "LeftArmColor", "RightArmColor", "LeftLegColor", "RightLegColor" }
YYAvatarScaleProps = { "BodyTypeScale", "DepthScale", "HeadScale", "HeightScale", "ProportionScale", "WidthScale" }
YYAvatarBodyOverrides = nil -- lo completa la sección "PARTES CORPORALES" (CustomBodyPartState.Saved)

function YYAvatarRemember(desc, fromUsername)
    if not desc then return end
    local look = { props = {}, colors = {}, scales = {}, layered = {} }
    local prev = YYPersist.Data.avatar
    look.strip = (fromUsername == true) or (type(prev) == "table" and prev.strip == true)
    for _, p in ipairs(YYAvatarIdProps) do
        local ok, v = pcall(function() return desc[p] end)
        if ok and v ~= nil then look.props[p] = v end
    end
    -- si Korblox/Headless están puestos, se guarda la pieza original (el toggle vuelve a ponerla al restaurar)
    if type(YYAvatarBodyOverrides) == "table" then
        for p, original in pairs(YYAvatarBodyOverrides) do
            if look.props[p] ~= nil and original ~= nil then look.props[p] = original end
        end
    end
    for _, p in ipairs(YYAvatarColorProps) do
        pcall(function()
            local c = desc[p]
            if typeof(c) == "Color3" then look.colors[p] = { c.R, c.G, c.B } end
        end)
    end
    for _, p in ipairs(YYAvatarScaleProps) do
        pcall(function()
            local n = tonumber(desc[p])
            if n then look.scales[p] = n end
        end)
    end
    pcall(function()
        for _, e in ipairs(desc:GetAccessories(false)) do
            local typeName = nil
            pcall(function() typeName = e.AccessoryType.Name end)
            if e.AssetId and typeName then
                table.insert(look.layered, { id = e.AssetId, t = typeName, o = e.Order })
            end
        end
    end)
    YYPersist.Data.avatar = look
    YYPersistSchedule()
end

function YYAvatarRestoreLook()
    local look = YYPersist.Data.avatar
    if type(look) ~= "table" then return false end
    local rig, humanoid = GetAvatarVisualHumanoid()
    if not (rig and humanoid) then return false end
    local ok, desc = pcall(function() return humanoid:GetAppliedDescription() end)
    if not ok or not desc then return false end
    for p, v in pairs(look.props or {}) do
        pcall(function()
            if table.find(YYAvatarListProps, p) then
                desc[p] = tostring(v)
            else
                desc[p] = tonumber(v) or 0
            end
        end)
    end
    for p, c in pairs(look.colors or {}) do
        pcall(function() desc[p] = Color3.new(c[1], c[2], c[3]) end)
    end
    for p, n in pairs(look.scales or {}) do
        pcall(function() desc[p] = tonumber(n) end)
    end
    if type(look.layered) == "table" then
        local list = {}
        for i, e in ipairs(look.layered) do
            local okT, accessoryType = pcall(function() return Enum.AccessoryType[e.t] end)
            if okT and accessoryType then
                list[#list + 1] = { AssetId = tonumber(e.id), AccessoryType = accessoryType, IsLayered = true, Order = tonumber(e.o) or i }
            end
        end
        pcall(function() desc:SetAccessories(list, false) end)
    end
    if look.strip then pcall(AvatarStripRig, rig) end
    local okApply = AvatarApplyDescriptionSafe(humanoid, desc)
    return okApply == true
end

function YYAvatarWaitRig(timeout)
    local waited = 0
    while waited < timeout do
        local ok, rig, humanoid = pcall(GetAvatarVisualHumanoid)
        if ok and rig and humanoid then return true end
        task.wait(1)
        waited = waited + 1
    end
    return false
end

-- (arreglo de Hydra) cada cambio de avatar sube la versión y el rig donde se aplicó queda marcado con ella (atributo
-- YYLook). El vigilante de YYAvatarBoot mira cada medio segundo el rig que se ve y, si no tiene la versión actual, se la pone.
YYAvatarVersion = 1
YYAvatarReapplying = false
YYAvatarBusy = false
YYAvatarCurrentRig = nil
YYAvatarOwnDesc = nil
function YYAvatarMark(rig)
    if rig then pcall(function() rig:SetAttribute("YYLook", YYAvatarVersion) end) end
end
function YYAvatarBump(rig)
    if YYAvatarReapplying then return end -- mientras se vuelve a poner todo, se marca una sola vez al final
    YYAvatarVersion = YYAvatarVersion + 1
    YYAvatarMark(rig or (GetAvatarVisualHumanoid()))
end
-- vuelve a correr los toggles de Avatar que estén prendidos (Korblox / Headless / Headless + Deleted)
function YYAvatarReapplyToggles()
    -- la pierna original se vuelve a leer del rig actual (no la de otro rig o de otro avatar)
    if type(YYAvatarBodyOverrides) == "table" then YYAvatarBodyOverrides.RightLeg = nil end
    local was = YYAvatarReapplying
    YYAvatarReapplying = true
    for _, item in ipairs(YYPersist.AvatarItems) do
        local on = false
        pcall(function() on = item.obj.GetValue() == true end)
        if on then pcall(item.cb, true) end
    end
    YYAvatarReapplying = was
end

-- vuelve a poner el look guardado y después los toggles de Avatar que estén prendidos (Korblox / Headless)
function YYAvatarReapply()
    local rig, humanoid = GetAvatarVisualHumanoid()
    if not (rig and humanoid) then return end
    YYAvatarReapplying = true
    if type(YYPersist.Data.avatar) == "table" then
        pcall(YYAvatarRestoreLook)
    elseif rig:GetAttribute("YYLook") ~= nil then
        -- este rig tenía un look viejo y lo restableciste: vuelve tu avatar
        if not YYAvatarOwnDesc then
            local ok, desc = pcall(function() return Players:GetHumanoidDescriptionFromUserId(LocalPlayer.UserId) end)
            if ok then YYAvatarOwnDesc = desc end
        end
        if YYAvatarOwnDesc then
            pcall(AvatarStripRig, rig)
            pcall(AvatarApplyDescriptionSafe, humanoid, YYAvatarOwnDesc)
        end
    end
    pcall(YYAvatarReapplyToggles)
    YYAvatarReapplying = false
    YYAvatarMark(rig)
end

function YYAvatarHasSaved()
    if type(YYPersist.Data.avatar) == "table" then return true end
    for key, value in pairs(YYPersist.Data.opts) do
        if value == true and string.sub(key, 1, 9) == "Avatar|T|" then return true end
    end
    return false
end

function YYAvatarBoot()
    -- (arreglo de Hydra) Evade cambia el rig que se ve (partida, menú, rigs guardados que reusa): cada medio segundo se
    -- mira cuál se ve y, si no tiene la versión actual del look (o tenía uno viejo), se le vuelve a poner. Así sigue al
    -- volver al menú y al entrar a otra partida.
    task.spawn(function()
        while true do
            task.wait(0.5)
            local okRig, rig = pcall(GetAvatarVisualHumanoid)
            if not okRig then rig = nil end
            YYAvatarCurrentRig = rig
            if rig and not YYAvatarBusy and not YYAvatarResetBusy then
                local mark = rig:GetAttribute("YYLook")
                if mark ~= YYAvatarVersion and (YYAvatarHasSaved() or mark ~= nil) then
                    task.wait(0.6) -- deja que el juego termine de vestirlo
                    local okNow, now = pcall(GetAvatarVisualHumanoid)
                    if okNow and now == rig and not YYAvatarBusy and not YYAvatarResetBusy then
                        YYAvatarBusy = true
                        pcall(YYAvatarReapply)
                        YYAvatarBusy = false
                    end
                end
            end
        end
    end)
    if YYAvatarHasSaved() then
        if not YYAvatarWaitRig(120) then
            for _, item in ipairs(YYPersist.AvatarItems) do
                pcall(function() item.obj.SetValue(false) end)
            end
        end
    end
end

-- se llama una sola vez al final del script
function YYPersistFlush()
    task.spawn(function()
        task.wait(1)
        local queue = YYPersist.Pending
        YYPersist.Pending = {}
        for _, fn in ipairs(queue) do
            task.spawn(function() pcall(fn) end)
        end
    end)
    task.spawn(function() pcall(YYAvatarBoot) end)
end

-- ===== TIENDA PROPIA: botón "Pases" en la barra superior (reemplaza la bolsa de Roblox) =====
-- Verificado en CoreGui (to_nick.zip): la bolsa es CoreGui.RobloxGui.Modules.Chrome.Integrations.InExperienceShop.ShopEntrypoint
-- y se registra con ChromeUtils.setCoreGuiAvailability(..., Enum.CoreGuiType.ExperienceShop): escucha
-- StarterGui.CoreGuiChangedSignal, así que StarterGui:SetCoreGuiEnabled(ExperienceShop, false) la oculta (API oficial).
-- Pases (IDs tomados del propio código): Yin Yang Colors 2026508642 (este script) · Yin Yang Studio Logos 2025722662 (librería).
-- Al comprar, los sistemas premium que ya existen escuchan PromptGamePassPurchaseFinished y se desbloquean solos.
-- Funcion global (no local) por el limite de 200 registros del chunk principal.
function setupPassesShop()
    local StarterGui = game:GetService("StarterGui")
    local MPS = game:GetService("MarketplaceService")
    local TS = game:GetService("TweenService")
    local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")
    local OWNERS = { "mousoza", "sephtis_morana" }
    local PASSES = {
        { Id = 2026508642, Name = "Yin Yang Colors",
          Es = "Bordes animados y colores premium en la pestaña Color", En = "Animated borders and premium colors in the Color tab" },
        { Id = 2025722662, Name = "Yin Yang Studio Logos",
          Es = "Estudio de logos premium de la interfaz", En = "Premium logo studio for the interface" },
    }
    local State = {} -- [Id] = { owned = bool|nil, price = number|nil, icon = string|nil, name = string|nil }
    local Cards = {} -- [Id] = function() (refresca la tarjeta si el panel está abierto)

    -- ---------- ocultar la bolsa de Roblox ----------
    -- Verificado en CoreGui.RobloxGui.Modules.TopBar.Components.Presentational.TopBarApp: además de la bolsa del
    -- menú (Chrome) existe una bolsa SUELTA al lado del menú, creada con la clave "ShopGlobalIcon" (React usa la
    -- clave como nombre de la instancia). Esa no depende de CoreGuiType: se oculta directo si el ejecutor deja ver CoreGui.
    local shopIcons = setmetatable({}, { __mode = "k" })
    local function hideGlobalShopIcon()
        pcall(function()
            local coreGui = game:GetService("CoreGui")
            for _, d in ipairs(coreGui:GetDescendants()) do
                if d.Name == "ShopGlobalIcon" and d:IsA("GuiObject") and not shopIcons[d] then
                    shopIcons[d] = true
                    d.Visible = false
                    d:GetPropertyChangedSignal("Visible"):Connect(function()
                        if d.Visible then d.Visible = false end
                    end)
                end
            end
        end)
    end
    local function hideRobloxShop()
        pcall(function()
            if StarterGui:GetCoreGuiEnabled(Enum.CoreGuiType.ExperienceShop) then
                StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.ExperienceShop, false)
            end
        end)
        hideGlobalShopIcon()
    end
    hideRobloxShop()

    -- ---------- datos de los pases ----------
    local function isOwnerAccount()
        local me = string.lower(LocalPlayer.Name)
        for _, n in ipairs(OWNERS) do
            if string.lower(n) == me then return true end
        end
        return false
    end
    local function loadPass(pass)
        local st = State[pass.Id] or {}
        State[pass.Id] = st
        local okInfo, info = pcall(function()
            return MPS:GetProductInfo(pass.Id, Enum.InfoType.GamePass)
        end)
        if okInfo and type(info) == "table" then
            st.price = tonumber(info.PriceInRobux)
            st.name = type(info.Name) == "string" and info.Name ~= "" and info.Name or nil
            if tonumber(info.IconImageAssetId) and tonumber(info.IconImageAssetId) > 0 then
                st.icon = "rbxassetid://" .. tostring(info.IconImageAssetId)
            end
            local creator = info.Creator
            if type(creator) == "table" and tonumber(creator.CreatorTargetId) == LocalPlayer.UserId then
                st.owned = true
            end
        end
        if st.owned ~= true then
            if isOwnerAccount() then
                st.owned = true
            else
                local okOwn, owns = pcall(function()
                    return MPS:UserOwnsGamePassAsync(LocalPlayer.UserId, pass.Id)
                end)
                if okOwn then st.owned = owns == true end
            end
        end
        st.loaded = true
        if Cards[pass.Id] then pcall(Cards[pass.Id]) end
    end
    local function loadAll()
        for _, pass in ipairs(PASSES) do
            task.spawn(loadPass, pass)
        end
    end
    pcall(function()
        MPS.PromptGamePassPurchaseFinished:Connect(function(player, passId, purchased)
            if player ~= LocalPlayer then return end
            local st = State[tonumber(passId)]
            if st then
                st.buying = false
                if purchased then st.owned = true end
                if Cards[tonumber(passId)] then pcall(Cards[tonumber(passId)]) end
            end
        end)
    end)

    -- ---------- panel ----------
    local Panel = { Gui = nil, Open = false }
    local function make(class, props, parent)
        return YYKitMake(class, props, parent)
    end

    local function closePanel()
        local W = Panel.Win
        if not W or W.Closed or not Panel.Open then return end
        Panel.Open = false
        W:Destroy() -- animación de salida de la librería (fondo y escala)
        Cards = {}
        Panel.Win, Panel.Gui = nil, nil
    end

    local function openPanel()
        if Panel.Open then closePanel() return end
        if Panel.Win then pcall(function() Panel.Win.Gui:Destroy() end) end
        -- el panel lo arma la librería (YinYang.Kit.Window modal) con el tema activo; acá solo van los pases
        local K = _G.YinYang and _G.YinYang.Kit
        if not K or not K.Window then
            warn("[Pases] La librería UI no tiene el kit de ventanas (actualizala)")
            return
        end
        Panel.Open = true
        -- ancho adaptable en celulares chicos (16 px de margen a cada lado)
        local cam = Workspace.CurrentCamera
        local vw = cam and cam.ViewportSize.X or 400
        local W = K.Window({Name = "YYPassesPanel", DisplayOrder = 260, IgnoreGuiInset = true, Modal = true, FlatHeader = true,
            Width = math.clamp(vw - 32, 240, 340), Radius = 20, Pad = 16, Gap = 10, TitleSize = 18,
            Title = scriptText("Pases Yin Yang", "Yin Yang Passes"),
            Subtitle = scriptText("Apoyá el script y desbloqueá extras", "Support the script and unlock extras"),
            OnClose = function() closePanel() return true end})
        Panel.Win, Panel.Gui = W, W.Gui

        local status = nil
        local function setStatus(es, en)
            if status then status.Text = scriptText(es, en) end
        end

        -- tarjetas
        for _, pass in ipairs(PASSES) do
            local I = W:Item({Title = pass.Name, Desc = scriptText(pass.Es, pass.En), Button = "···"})

            local function refresh()
                if not I.Row.Parent then return end
                local st = State[pass.Id] or {}
                if st.name then I.Name.Text = st.name end
                I.Icon.Image = st.icon or ("rbxthumb://type=GamePass&id=" .. tostring(pass.Id) .. "&w=150&h=150")
                if st.owned == true then
                    I:SetButton(scriptText("✓ Tuyo", "✓ Owned"), "muted")
                elseif st.buying then
                    I.Button.Text = "···"
                elseif st.price then
                    I:SetButton("R$ " .. tostring(st.price), "accent")
                elseif st.loaded then
                    I.Button.Text = scriptText("Ver", "View")
                end
            end
            Cards[pass.Id] = refresh
            refresh()

            I.Button.Activated:Connect(function()
                local st = State[pass.Id] or {}
                State[pass.Id] = st
                if st.owned == true or st.buying then return end
                st.buying = true
                refresh()
                local link = "https://www.roblox.com/game-pass/" .. tostring(pass.Id)
                local ok = pcall(function() MPS:PromptGamePassPurchase(LocalPlayer, pass.Id) end)
                if type(setclipboard) == "function" then pcall(setclipboard, link) end
                if ok then
                    setStatus("Se abrió la compra de Roblox · el link también quedó copiado", "Roblox purchase opened · link also copied")
                else
                    st.buying = false
                    setStatus("Link copiado: compralo en el navegador", "Link copied: buy it in your browser")
                end
                -- por si Roblox no avisa (compra cerrada sin respuesta), se libera el botón
                task.delay(20, function()
                    if st.buying then st.buying = false pcall(refresh) end
                end)
                refresh()
            end)
        end

        status = W:Text("", {Dim = true, Size = 11, Height = 14, Wrap = true, Font = Enum.Font.Gotham, Align = Enum.TextXAlignment.Center})
        loadAll() -- precios y "Tuyo" siempre frescos al abrir
    end

    -- ---------- botón de la barra (mismo estilo que Zoom / Cámara / Tabla) ----------
    local Button = nil
    local function findTargetParent()
        local topbar = PlayerGui:FindFirstChild("TopbarStandard")
        local main = topbar and topbar:FindFirstChild("Main")
        local holders = main and main:FindFirstChild("Holders")
        local left = holders and holders:FindFirstChild("Left")
        if left then return left end
        -- barra de respaldo que crea el script en celular si Evade no tiene la suya
        return topbar and topbar:FindFirstChild("Right", true) or nil
    end
    local function ownParent()
        local gui = PlayerGui:FindFirstChild("YYPassesTopbar")
        if not gui then
            gui = make("ScreenGui", { Name = "YYPassesTopbar", ResetOnSpawn = false, DisplayOrder = 100,
                ScreenInsets = Enum.ScreenInsets.TopbarSafeInsets }, PlayerGui)
            local holder = make("Frame", { Name = "Holder", Size = UDim2.new(1, -24, 1, 0), Position = UDim2.fromOffset(12, 0), BackgroundTransparency = 1 }, gui)
            make("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, VerticalAlignment = Enum.VerticalAlignment.Center,
                SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 12) }, holder)
        end
        return gui.Holder
    end

    local function createButton(parent)
        -- el botón redondo (bolsa dibujada, YYRing, marca YYTopbar para la pestaña Color) lo da la librería
        local K = _G.YinYang and _G.YinYang.Kit
        if not K or not K.TopbarButton then
            warn("[Pases] La librería UI no tiene el kit de ventanas (actualizala)")
            return
        end
        local b = K.TopbarButton(parent, {Name = "YYPassesButton", LayoutOrder = 996, OnClick = function()
            local ok, err = pcall(openPanel)
            if not ok then warn("[Pases] " .. tostring(err)) end
        end})
        Button = b
        if type(getgenv) == "function" and type(getgenv().YYTopbarRebind) == "function" then
            task.defer(function() pcall(getgenv().YYTopbarRebind) end)
        end
    end

    local function ensureButton()
        if Button and Button.Parent and Button:IsDescendantOf(PlayerGui) then return end
        local parent = findTargetParent() or ownParent()
        local stale = parent:FindFirstChild("YYPassesButton")
        if stale then stale:Destroy() end
        createButton(parent)
    end

    -- espera la barra de Evade hasta 20 s (igual que los otros botones); si no aparece, usa una propia
    local waited = 0
    while not findTargetParent() and waited < 20 do
        task.wait(0.5)
        waited = waited + 0.5
    end
    ensureButton()
    task.spawn(loadAll)

    -- ---------- cerrar el hueco que deja la bolsa oculta (v2) ----------
    -- La bolsa suelta sigue reservando su lugar aunque esté oculta, y la barra de Evade empieza después.
    -- Objetivo: que nuestro primer botón empiece donde empezaba la bolsa. Se prueba, en orden, con verificación:
    --   1) correr la barra de Evade (Holders.Left)  2) correr su contenedor (Holders)
    --   3) si Evade no deja moverlas: pasar nuestros botones (marcados YYTopbar) a una barra propia ("YYTopbarDock")
    --      ubicada justo donde estaba la bolsa (la pestaña Color también los busca ahí).
    local Gap = { Mode = nil, Inst = nil, Base = nil, Shift = nil, Busy = false, Conn = nil, Dock = nil, Tried = {} }
    local function evadeLeft()
        local topbar = PlayerGui:FindFirstChild("TopbarStandard")
        local main = topbar and topbar:FindFirstChild("Main")
        local holders = main and main:FindFirstChild("Holders")
        return holders and holders:FindFirstChild("Left") or nil, topbar
    end
    local function shopIcon()
        for icon in pairs(shopIcons) do
            if icon.Parent and icon.AbsoluteSize.X > 4 then return icon end
        end
        return nil
    end
    local function setOffset(inst, offset)
        Gap.Busy = true
        local pos = inst.Position
        inst.Position = UDim2.new(pos.X.Scale, offset, pos.Y.Scale, pos.Y.Offset)
        Gap.Busy = false
    end
    local function holdShift(inst)
        if Gap.Conn then Gap.Conn:Disconnect() Gap.Conn = nil end
        Gap.Conn = inst:GetPropertyChangedSignal("Position"):Connect(function()
            if Gap.Busy or Gap.Inst ~= inst then return end
            Gap.Base = inst.Position.X.Offset -- la movió Evade: nueva base
            task.defer(function()
                if Gap.Inst == inst then setOffset(inst, Gap.Base - Gap.Shift) end
            end)
        end)
    end
    local function tryMove(inst, need)
        if not inst or Gap.Tried[inst] then return false end
        Gap.Tried[inst] = true
        local before = Button.AbsolutePosition.X
        local base = inst.Position.X.Offset
        setOffset(inst, base - need)
        task.wait(0.15)
        if math.abs((before - Button.AbsolutePosition.X) - need) <= 3 then
            Gap.Mode, Gap.Inst, Gap.Base, Gap.Shift = "move", inst, base, need
            holdShift(inst)
            return true
        end
        setOffset(inst, base) -- no se movió: se deja como estaba
        return false
    end
    local function dockButtons(shop)
        local topbar = PlayerGui:FindFirstChild("TopbarStandard")
        local inset = game:GetService("GuiService"):GetGuiInset()
        local screenY = Button.AbsolutePosition.Y + ((topbar and topbar:IsA("ScreenGui") and not topbar.IgnoreGuiInset) and inset.Y or 0)
        local dock = PlayerGui:FindFirstChild("YYTopbarDock")
        if not dock then
            dock = YYKitMake("ScreenGui")
            dock.Name = "YYTopbarDock"
            dock.ResetOnSpawn = false
            dock.IgnoreGuiInset = true
            dock.DisplayOrder = 100
            pcall(function() dock.ScreenInsets = Enum.ScreenInsets.None end)
            dock.Parent = PlayerGui
            local holder = YYKitMake("Frame")
            holder.Name = "Holder"
            holder.BackgroundTransparency = 1
            holder.Parent = dock
            local layout = YYKitMake("UIListLayout")
            layout.FillDirection = Enum.FillDirection.Horizontal
            layout.VerticalAlignment = Enum.VerticalAlignment.Center
            layout.SortOrder = Enum.SortOrder.LayoutOrder
            layout.Padding = UDim.new(0, 12)
            layout.Parent = holder
        end
        local holder = dock.Holder
        holder.Position = UDim2.fromOffset(shop.AbsolutePosition.X, screenY)
        holder.Size = UDim2.fromOffset(800, Button.AbsoluteSize.Y)
        Gap.Mode, Gap.Dock = "dock", dock
    end
    local function closeShopGap()
        if not (Button and Button.Parent) then return end
        local shop = shopIcon()
        if not shop then return end
        if Gap.Mode == "dock" then
            -- los botones que se recrean en la barra de Evade se vuelven a pasar a la propia
            local left = evadeLeft()
            if left and Gap.Dock and Gap.Dock:FindFirstChild("Holder") then
                for _, child in ipairs(left:GetChildren()) do
                    if child:IsA("GuiObject") and child:GetAttribute("YYTopbar") then
                        child.Parent = Gap.Dock.Holder
                    end
                end
            end
            return
        end
        local need = Button.AbsolutePosition.X - shop.AbsolutePosition.X
        if need <= 3 or need > shop.AbsoluteSize.X * 3 then return end -- ya está bien o la medida no tiene sentido
        if Gap.Mode == "move" and Gap.Inst and Gap.Inst.Parent then
            Gap.Shift = Gap.Shift + need
            setOffset(Gap.Inst, Gap.Base - Gap.Shift)
            return
        end
        local left = evadeLeft()
        if tryMove(left, need) then return end
        if tryMove(left and left.Parent, need) then return end
        dockButtons(shop)
        closeShopGap()
    end

    -- vigilante liviano: recrea el botón si la barra se reinicia y mantiene oculta la bolsa de Roblox
    while true do
        task.wait(3)
        pcall(ensureButton)
        hideRobloxShop()
        pcall(closeShopGap)
    end
end
task.spawn(function()
    local ok, err = pcall(setupPassesShop)
    if not ok then warn("[Pases] Error: " .. tostring(err)) end
end)

-- ===== GANCHO DE AGARRE (Grapple Hook / Grapple Shot) · primero en la pestaña Extra =====
-- Verificado en el código del juego (to_nick.zip):
--   · Tirón: ReplicatedStorage.Objects.Game.ToolProfile.ViewmodelVisuals.Types.Grapple (cliente) clona su hijo
--     "SpringConstraint" en cada enganche y lo une a HumanoidRootPart.VelPos → se modifica la PLANTILLA
--     (sin require: también sirve en Solara). Al apagar se devuelven los valores originales.
--   · Alcance: el servidor manda Speed 470 · Lifetime 0.12 y TU cliente simula el tiro en
--     GenericImpulse.Types.Assets.Projectile (pasos de 0.2 s → 470 × 0.2 = 94 studs por paso). Con Lifetime 0.12
--     el tiro hace UN solo paso y muere. El enganche y el tirón salen de esa simulación local (el servidor no crea
--     el proyectil), así que subir el Lifetime que recibe TU cliente le da más pasos = más alcance.
--     Eso necesita require → no se usa en Solara (allí require crea copias y puede matar al personaje).
--   · Pared invisible: el tiro solo engancha en partes con Transparency ~= 1 y CanCollide ~= false, fuera de
--     workspace.Effects / Players / Rigs. Si delante no hay nada dentro del alcance, se mantiene una pared local
--     casi invisible justo antes del límite para que el tiro se agarre ahí.
-- Funcion global (no local) por el limite de 200 registros del chunk principal.
function setupGrappleSection()
    local env = (type(getgenv) == "function" and getgenv()) or _G
    local isSolara = false
    pcall(function()
        if identifyexecutor then
            isSolara = string.find(string.lower(tostring(identifyexecutor())), "solara", 1, true) ~= nil
        end
    end)

    local STEP = 94          -- studs por paso de simulación (470 × 0.2)
    local WALL_MARGIN = 10   -- la pared queda 10 studs antes del límite (el servidor puede verte unos studs atrás)
    local G = { Enabled = false, Pull = 100, Damp = 100, Orig = nil, Range = STEP }
    local PROPS = { "Stiffness", "Damping", "FreeLength", "MaxForce" }

    -- estado compartido con el envoltorio de Projectile.new (sobrevive a re-ejecutar el script)
    env.YYGrappleRange = env.YYGrappleRange or { Steps = 1, Hooked = false }
    local RangeCfg = env.YYGrappleRange
    RangeCfg.Steps = 1

    local function template()
        local ok, spring = pcall(function()
            return ReplicatedStorage.Objects.Game.ToolProfile.ViewmodelVisuals.Types.Grapple:FindFirstChild("SpringConstraint")
        end)
        if ok and spring and spring:IsA("SpringConstraint") then return spring end
        return nil
    end

    local function setLabel(label, es, en)
        if not label then return end
        pcall(function()
            label:SetAttribute("TextSpanish", es)
            label:SetAttribute("TextEnglish", en)
            label.Text = scriptText(es, en)
        end)
    end

    YYPlace(TabExtra, 1.00)
    TabExtra:CreateLabel("GANCHO DE AGARRE", "GRAPPLE HOOK", 14)
    TabExtra:CreateDivider()
    local infoLabel = TabExtra:CreateLabel("Gancho original: esperando partida…", "Original grapple: waiting for a match…", 11)

    local function showOriginal()
        local o = G.Orig
        if not (o and o.Stiffness and o.Damping) then return end
        setLabel(infoLabel,
            string.format("Gancho original · fuerza %.0f · amortiguación %.0f · alcance %d studs", o.Stiffness, o.Damping, STEP),
            string.format("Original grapple · pull %.0f · damping %.0f · range %d studs", o.Stiffness, o.Damping, STEP))
    end

    local function readOriginal(spring)
        if G.Orig then return end
        G.Orig = {}
        for _, prop in ipairs(PROPS) do
            local ok, value = pcall(function() return spring[prop] end)
            if ok then G.Orig[prop] = value end
        end
        showOriginal()
    end

    local function apply()
        local spring = template()
        if not spring then return false end
        readOriginal(spring)
        local o = G.Orig
        pcall(function()
            if G.Enabled then
                spring.Stiffness = o.Stiffness * G.Pull / 100
                spring.Damping = o.Damping * G.Damp / 100
                -- si el resorte tiene un tope de fuerza, sube junto con la fuerza del tirón
                if o.MaxForce and o.MaxForce < math.huge then
                    spring.MaxForce = o.MaxForce * math.max(1, G.Pull / 100)
                end
            else
                for _, prop in ipairs(PROPS) do
                    if o[prop] ~= nil then spring[prop] = o[prop] end
                end
            end
        end)
        return true
    end

    -- ---------- ALCANCE (envoltorio de Projectile.new, solo fuera de Solara) ----------
    local function installRangeHook()
        if RangeCfg.Hooked then return true end
        if isSolara then return false end
        local ok, mod = pcall(function()
            return require(ReplicatedStorage.Services.Shared.GenericImpulse.Types.Assets.Projectile)
        end)
        if not ok or type(mod) ~= "table" or type(mod.new) ~= "function" then
            warn("[Gancho] No se pudo leer GenericImpulse.Types.Assets.Projectile: " .. tostring(mod))
            return false
        end
        -- el original se guarda en getgenv para no envolver dos veces si el script se ejecuta de nuevo
        local original = env.YYGrappleProjectileNew or mod.new
        env.YYGrappleProjectileNew = original
        mod.new = function(data, ...)
            if type(data) == "table" then
                local cfg = env.YYGrappleRange
                local steps = cfg and tonumber(cfg.Steps) or 1
                if steps > 1 then
                    local proj = data.Projectile
                    local isGrapple = proj == "Grapple" or (typeof(proj) == "Instance" and proj.Name == "Grapple")
                    if isGrapple and data.Creator ~= nil and data.Creator == LocalPlayer.Character then
                        -- el bucle corta cuando el tiempo pasado >= Lifetime, revisado después de cada paso de 0.2 s
                        data.Lifetime = steps * 0.2 - 0.1
                    end
                end
            end
            return original(data, ...)
        end
        RangeCfg.Hooked = true
        return true
    end

    local function rangeSteps()
        return math.max(1, math.floor(G.Range / STEP + 0.5))
    end

    local rangeLabel
    local function updateRange()
        local steps = rangeSteps()
        if G.Enabled and steps > 1 and not isSolara then
            installRangeHook()
        end
        RangeCfg.Steps = (G.Enabled and RangeCfg.Hooked) and steps or 1
        if isSolara then
            setLabel(rangeLabel, "Alcance: en Solara queda el original (" .. STEP .. " studs)",
                "Range: Solara keeps the original (" .. STEP .. " studs)")
        elseif not G.Enabled then
            setLabel(rangeLabel, "Alcance: original (" .. STEP .. " studs) · activá Mejorar gancho",
                "Range: original (" .. STEP .. " studs) · turn on Boost grapple")
        else
            setLabel(rangeLabel, "Alcance real: " .. (RangeCfg.Steps * STEP) .. " studs",
                "Actual range: " .. (RangeCfg.Steps * STEP) .. " studs")
        end
    end

    local boostToggle
    boostToggle = TabExtra:CreateToggle("Mejorar gancho", "Boost grapple", false, function(enabled)
        G.Enabled = enabled
        if not apply() and enabled then
            warn("[Gancho] No se encontró la plantilla del gancho (ReplicatedStorage.Objects.Game.ToolProfile.ViewmodelVisuals.Types.Grapple.SpringConstraint)")
            G.Enabled = false
            if boostToggle and boostToggle.SetValue then boostToggle.SetValue(false) end
        end
        updateRange()
    end)
    TabExtra:CreateSlider("Pull %", 25, 600, 100, function(value)
        G.Pull = tonumber(value) or 100
        if G.Enabled then apply() end
    end)
    TabExtra:CreateSlider("Damping %", 0, 200, 100, function(value)
        G.Damp = tonumber(value) or 100
        if G.Enabled then apply() end
    end)
    if not isSolara then
        TabExtra:CreateSlider("Range", STEP, STEP * 5, STEP, function(value)
            G.Range = tonumber(value) or STEP
            updateRange()
        end)
    end
    rangeLabel = TabExtra:CreateLabel("Alcance: original", "Range: original", 11)
    updateRange()

    -- ---------- PARED INVISIBLE (funciona también en Solara: no usa require) ----------
    local Wall = { On = false, Part = nil, Conn = nil, Tool = nil, HasGrapple = false, NextToolCheck = 0 }

    local function removeWall()
        if Wall.Part then pcall(function() Wall.Part:Destroy() end) end
        Wall.Part = nil
    end

    local function ensureWall()
        if Wall.Part then
            -- se reutiliza la misma pared (se oculta con Parent = nil); si algo la destruyó, se crea otra
            local ok = pcall(function() Wall.Part.Parent = Workspace end)
            if ok then return Wall.Part end
            Wall.Part = nil
        end
        local p = Instance.new("Part")
        p.Name = "YYGrappleWall"
        p.Size = Vector3.new(18, 18, 1)
        p.Anchored = true
        p.CanCollide = true      -- el tiro ignora partes con CanCollide = false
        p.CanQuery = true
        p.CanTouch = false
        p.CastShadow = false
        p.Material = Enum.Material.SmoothPlastic
        p.Transparency = 0.995   -- con 1 exacto el tiro la atraviesa
        p.Parent = Workspace     -- fuera de Effects / Players / Rigs (que el tiro ignora)
        Wall.Part = p
        return p
    end

    -- busca el gancho en la herramienta del rig visual (igual que hace el juego: partes Grapple / Grapple1 / Grapple2)
    local function grappleTool()
        local now = os.clock()
        if now < Wall.NextToolCheck then return Wall.HasGrapple and Wall.Tool or nil end
        Wall.NextToolCheck = now + 0.25
        Wall.HasGrapple, Wall.Tool = false, nil
        local rigs = Workspace:FindFirstChild("Rigs")
        local rig = rigs and rigs:FindFirstChild(LocalPlayer.Name)
        local tool = rig and rig:FindFirstChild("Tool")
        if tool then
            for _, d in ipairs(tool:GetDescendants()) do
                if d:IsA("BasePart") and (d.Name == "Grapple" or d.Name == "Grapple1" or d.Name == "Grapple2") then
                    Wall.HasGrapple, Wall.Tool = true, tool
                    break
                end
            end
        end
        return Wall.HasGrapple and Wall.Tool or nil
    end

    -- tu tiro en vuelo o enganchado (el juego lo pone en workspace.Effects.Ignore.Projectiles con Creator = tu Tag)
    local function myShot()
        local char = LocalPlayer.Character
        local tag = char and char:GetAttribute("Tag")
        local effects = Workspace:FindFirstChild("Effects")
        local ignore = effects and effects:FindFirstChild("Ignore")
        local folder = ignore and ignore:FindFirstChild("Projectiles")
        if not (folder and tag ~= nil) then return nil end
        for _, child in ipairs(folder:GetChildren()) do
            if child.Name == "Grapple" and child:GetAttribute("Creator") == tag then return child end
        end
        return nil
    end

    -- mismo raycast que el juego: excluye Effects/Players/Rigs, salta Transparency==1 o CanCollide==false
    local function castLikeGame(origin, direction)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.IgnoreWater = true
        local list = {}
        for _, name in ipairs({ "Effects", "Players", "Rigs" }) do
            local f = Workspace:FindFirstChild(name)
            if f then table.insert(list, f) end
        end
        if Wall.Part then table.insert(list, Wall.Part) end
        params.FilterDescendantsInstances = list
        pcall(function() params.CollisionGroup = "Raycast" end)
        for _ = 1, 16 do
            local hit = Workspace:Raycast(origin, direction, params)
            if not hit then return nil end
            if hit.Instance.Transparency ~= 1 and hit.Instance.CanCollide ~= false then return hit end
            table.insert(list, hit.Instance)
            params.FilterDescendantsInstances = list
        end
        return nil
    end

    local function wallStep()
        local tool = grappleTool()
        if not tool then
            if Wall.Part and Wall.Part.Parent then Wall.Part.Parent = nil end
            return
        end
        local shot = myShot()
        if shot or tool:GetAttribute("GrappleActive") then
            -- tiro en curso: la pared queda quieta; ya enganchado, deja de chocar contigo
            if Wall.Part and (shot == nil or shot:GetAttribute("Done") == true) then
                Wall.Part.CanCollide = false
                Wall.Part.CanQuery = false
            end
            return
        end
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local camera = Workspace.CurrentCamera
        if not (hrp and camera) then return end
        local headPos = hrp:FindFirstChild("HeadPos")
        local origin = (headPos and headPos:IsA("Attachment")) and headPos.WorldPosition or (hrp.Position + Vector3.new(0, 1.5, 0))
        local look = camera.CFrame.LookVector
        local reach = STEP * (RangeCfg.Steps or 1) - WALL_MARGIN
        if castLikeGame(origin, look * reach) then
            -- hay algo real dentro del alcance: no hace falta pared
            if Wall.Part and Wall.Part.Parent then Wall.Part.Parent = nil end
            return
        end
        local part = ensureWall()
        part.CanCollide = true
        part.CanQuery = true
        local center = origin + look * reach
        part.CFrame = CFrame.lookAt(center, center + look)
        if part.Parent ~= Workspace then part.Parent = Workspace end
    end

    TabExtra:CreateToggle("Pared al límite", "Edge Wall", false, function(enabled)
        Wall.On = enabled
        if Wall.Conn then Wall.Conn:Disconnect() Wall.Conn = nil end
        if enabled then
            Wall.Conn = RunService.RenderStepped:Connect(function()
                local ok, err = pcall(wallStep)
                if not ok then warn("[Gancho] Pared: " .. tostring(err)) end
            end)
        else
            removeWall()
        end
    end)

    -- ---------- MIRA DEL GANCHO: dónde se va a enganchar antes de disparar ----------
    -- Simula el tiro igual que GenericImpulse.Types.Assets.Projectile: pasos de 0.2 s, velocidad 470,
    -- gravedad (0, -6, 0) del GrappleHook, mismo filtro de raycast. Si "Pared al límite" está prendida,
    -- la pared también cuenta (el tiro real se agarra ahí).
    local Aim = { Conn = nil, Part = nil, Gui = nil, Ring = nil, Dot = nil, Label = nil }
    local AIM_SPEED, AIM_PERIOD, AIM_GRAVITY = 470, 0.2, Vector3.new(0, -6, 0)

    local function aimRemove()
        if Aim.Part then pcall(function() Aim.Part:Destroy() end) end
        Aim.Part, Aim.Gui, Aim.Ring, Aim.Dot, Aim.Label = nil, nil, nil, nil, nil
    end

    local function aimEnsure()
        if Aim.Part and Aim.Part.Parent then return end
        local p = Instance.new("Part")
        p.Name = "YYGrappleAim"
        p.Size = Vector3.new(0.2, 0.2, 0.2)
        p.Transparency = 1
        p.Anchored = true
        p.CanCollide, p.CanQuery, p.CanTouch = false, false, false
        p.Parent = Workspace
        local gui = Instance.new("BillboardGui")
        gui.Size = UDim2.fromOffset(90, 64)
        gui.AlwaysOnTop = true
        gui.LightInfluence = 0
        gui.Adornee = p
        gui.Parent = p
        local ring = YYKitMake("Frame")
        ring.AnchorPoint = Vector2.new(0.5, 0.5)
        ring.Position = UDim2.new(0.5, 0, 0, 16)
        ring.Size = UDim2.fromOffset(26, 26)
        ring.BackgroundTransparency = 1
        ring.Parent = gui
        local rc = YYKitMake("UICorner") rc.CornerRadius = UDim.new(1, 0) rc.Parent = ring
        local rs = YYKitMake("UIStroke") rs.Thickness = 2.5 rs.Parent = ring
        local dot = YYKitMake("Frame")
        dot.AnchorPoint = Vector2.new(0.5, 0.5)
        dot.Position = UDim2.fromScale(0.5, 0.5)
        dot.Size = UDim2.fromOffset(7, 7)
        dot.BorderSizePixel = 0
        dot.Parent = ring
        local dc = YYKitMake("UICorner") dc.CornerRadius = UDim.new(1, 0) dc.Parent = dot
        local label = YYKitMake("TextLabel")
        label.AnchorPoint = Vector2.new(0.5, 0)
        label.Position = UDim2.new(0.5, 0, 0, 33)
        label.Size = UDim2.fromOffset(0, 18)
        label.AutomaticSize = Enum.AutomaticSize.X
        label.BackgroundColor3 = Color3.fromRGB(14, 14, 18)
        label.BackgroundTransparency = 0.25
        label.Font = Enum.Font.GothamBold
        label.TextSize = 11
        label.TextColor3 = Color3.new(1, 1, 1)
        label.Parent = gui
        local lc = YYKitMake("UICorner") lc.CornerRadius = UDim.new(1, 0) lc.Parent = label
        local lp = YYKitMake("UIPadding") lp.PaddingLeft = UDim.new(0, 7) lp.PaddingRight = UDim.new(0, 7) lp.Parent = label
        -- el aro late suave (tween nativo)
        game:GetService("TweenService"):Create(ring, TweenInfo.new(0.6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { Size = UDim2.fromOffset(32, 32) }):Play()
        Aim.Part, Aim.Gui, Aim.Ring, Aim.Dot, Aim.Label = p, gui, rs, dot, label
    end

    -- mismo raycast del juego, pero contando la pared invisible (el tiro real se agarra en ella)
    local function aimCast(origin, direction)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.IgnoreWater = true
        local list = {}
        for _, name in ipairs({ "Effects", "Players", "Rigs" }) do
            local f = Workspace:FindFirstChild(name)
            if f then table.insert(list, f) end
        end
        if Aim.Part then table.insert(list, Aim.Part) end
        params.FilterDescendantsInstances = list
        pcall(function() params.CollisionGroup = "Raycast" end)
        for _ = 1, 16 do
            local hit = Workspace:Raycast(origin, direction, params)
            if not hit then return nil end
            if hit.Instance.Transparency ~= 1 and hit.Instance.CanCollide ~= false then return hit end
            table.insert(list, hit.Instance)
            params.FilterDescendantsInstances = list
        end
        return nil
    end

    local function aimStep()
        local tool = grappleTool()
        local shot = tool and myShot()
        if not tool or shot or tool:GetAttribute("GrappleActive") then
            if Aim.Gui then Aim.Gui.Enabled = false end
            return
        end
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local camera = Workspace.CurrentCamera
        if not (hrp and camera) then return end
        local headPos = hrp:FindFirstChild("HeadPos")
        local pos = (headPos and headPos:IsA("Attachment")) and headPos.WorldPosition or (hrp.Position + Vector3.new(0, 1.5, 0))
        local start = pos
        local velocity = camera.CFrame.LookVector * AIM_SPEED
        local steps = math.max(1, tonumber(RangeCfg.Steps) or 1)
        local hitPos, hitWall = nil, false
        for _ = 1, steps do
            velocity = velocity + AIM_GRAVITY * AIM_PERIOD
            local nextPos = pos + velocity * AIM_PERIOD
            local hit = aimCast(pos, nextPos - pos)
            if hit then
                hitPos = hit.Position
                hitWall = Wall.Part ~= nil and hit.Instance == Wall.Part
                break
            end
            pos = nextPos
        end
        aimEnsure()
        Aim.Gui.Enabled = true
        local green, gold, red = Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 205, 80), Color3.fromRGB(255, 90, 90) -- "green" ahora es blanco
        if hitPos then
            Aim.Part.CFrame = CFrame.new(hitPos)
            local c = hitWall and gold or green
            Aim.Ring.Color, Aim.Dot.BackgroundColor3 = c, c
            local meters = math.floor((hitPos - start).Magnitude + 0.5)
            Aim.Label.Text = (hitWall and scriptText("Pared · ", "Wall · ") or "") .. meters .. " m"
        else
            Aim.Part.CFrame = CFrame.new(pos)
            Aim.Ring.Color, Aim.Dot.BackgroundColor3 = red, red
            Aim.Label.Text = scriptText("Fuera de alcance", "Out of range")
        end
    end

    TabExtra:CreateToggle("Mira del gancho", "Grapple Aim", false, function(enabled)
        if Aim.Conn then Aim.Conn:Disconnect() Aim.Conn = nil end
        if enabled then
            Aim.Conn = RunService.RenderStepped:Connect(function()
                local ok, err = pcall(aimStep)
                if not ok then warn("[Gancho] Mira: " .. tostring(err)) end
            end)
        else
            aimRemove()
        end
    end)
    TabExtra:CreateDivider()

    -- lee los valores originales apenas exista la plantilla (sin cambiarlos)
    task.spawn(function()
        for _ = 1, 30 do
            local spring = template()
            if spring then
                readOriginal(spring)
                return
            end
            task.wait(2)
        end
    end)
end
pcall(setupGrappleSection)

-- ===== CARGAR JUGADOR (Carry) =====
-- Verificado en el código del juego: ReplicatedStorage.Objects.Game.Character.Shared.StateInfo tiene los estados
-- CarryIdle / CarryMove / CarryCrouchIdle / CarryCrouchMove / CarrySlide / CarrySlideAir / CarryAir
-- (Requirements.Carrying = true) con CanUseTools = false y Movement.CanJump = false. ToolProfile, Usables y
-- Movement leen esas tablas en vivo (GetState), así que cambiarlas en el módulo real alcanza.
-- Necesita require → no se usa en Solara (allí require da una copia y el cambio no llegaría al juego).
-- Funcion global (no local) por el limite de 200 registros del chunk principal.
function setupCarrySection()
    local env = (type(getgenv) == "function" and getgenv()) or _G
    local isSolara = false
    pcall(function()
        if identifyexecutor then
            isSolara = string.find(string.lower(tostring(identifyexecutor())), "solara", 1, true) ~= nil
        end
    end)
    local C = { Tools = false, Jump = false, Mod = nil }
    -- originales guardados en getgenv: si el script se re-ejecuta con algo encendido, no se pierden
    env.YYCarryOrig = env.YYCarryOrig or {}
    local Orig = env.YYCarryOrig

    local function stateModule()
        if C.Mod then return C.Mod end
        if isSolara then return nil end
        local ok, mod = pcall(function()
            return require(ReplicatedStorage.Objects.Game.Character.Shared.StateInfo)
        end)
        if ok and type(mod) == "table" and type(mod.GetState) == "function" then C.Mod = mod end
        return C.Mod
    end

    local function carryStates(mod)
        local list = {}
        if type(mod.States) == "table" then
            for _, st in ipairs(mod.States) do
                if type(st) == "table" and type(st.State) == "string" and type(st.Requirements) == "table" and st.Requirements.Carrying == true then
                    table.insert(list, st)
                end
            end
        end
        if #list == 0 then
            for _, name in ipairs({ "CarryIdle", "CarryMove", "CarryCrouchIdle", "CarryCrouchMove", "CarrySlide", "CarrySlideAir", "CarryAir" }) do
                local st = mod:GetState(name)
                if type(st) == "table" then table.insert(list, st) end
            end
        end
        return list
    end

    local function apply()
        local mod = stateModule()
        if not mod then return false end
        for _, st in ipairs(carryStates(mod)) do
            local o = Orig[st.State]
            if not o then
                o = { CanUseTools = st.CanUseTools, CanUseUsables = st.CanUseUsables }
                if type(st.Movement) == "table" then
                    o.CanJump = st.Movement.CanJump
                    o.JumpButtonVisible = st.Movement.JumpButtonVisible
                end
                Orig[st.State] = o
            end
            if C.Tools then
                st.CanUseTools = true
                if o.CanUseUsables ~= nil then st.CanUseUsables = true end
            else
                st.CanUseTools = o.CanUseTools
                st.CanUseUsables = o.CanUseUsables
            end
            if type(st.Movement) == "table" then
                if C.Jump then
                    st.Movement.CanJump = true
                    st.Movement.JumpButtonVisible = true
                else
                    st.Movement.CanJump = o.CanJump
                    st.Movement.JumpButtonVisible = o.JumpButtonVisible
                end
            end
        end
        return true
    end

    YYPlace(TabExtra, 2.40)
    if isSolara then
        TabExtra:CreateLabel("No disponible en Solara", "Not available on Solara", 11)
    end
    local toolsToggle, jumpToggle
    toolsToggle = TabExtra:CreateToggle("Objetos cargando", "Carry Items", false, function(enabled)
        C.Tools = enabled
        if not apply() and enabled then
            warn("[Carry] No se pudo usar StateInfo (Solara o módulo no encontrado)")
            C.Tools = false
            if toolsToggle and toolsToggle.SetValue then toolsToggle.SetValue(false) end
        end
    end)
    jumpToggle = TabExtra:CreateToggle("Saltar cargando", "Carry Jump", false, function(enabled)
        C.Jump = enabled
        if not apply() and enabled then
            warn("[Carry] No se pudo usar StateInfo (Solara o módulo no encontrado)")
            C.Jump = false
            if jumpToggle and jumpToggle.SetValue then jumpToggle.SetValue(false) end
        end
    end)
    TabExtra:CreateDivider()
end
pcall(setupCarrySection)

-- ===== MODO ESPACIO (gravedad cero, el personaje flota y gira como una roca) =====
-- Verificado en el código del juego: el estado "Grappling" de StateInfo (prioridad 999999, Requirements.Grappling = true)
-- pone PlatformStand = true, HumanoidRootPart.Massless = true, prende la fuerza "GrappleForce"
-- (VectorForce hacia arriba = 8.684 × Gravity, cancela el peso) y usa RootPartOrientation "None" (nada te endereza).
-- Es lo que se vio al quedar "trabado" enganchado antes de la pantalla de carga (MapLoading pausa la actualización).
-- Esta opción mantiene DataRegistry "Grappling" = true en TU personaje (CharacterService:GetLocalCharacter) y el juego
-- aplica solo todo lo anterior. Ojo: ese dato se le manda al servidor (DataRegistry.Set → UpdateCharacterDataRegistry).
-- Como "Grappling" le gana a Downed / Ragdolling / Carried, mientras estás caído, en ragdoll o cargado se pausa sola.
-- Necesita require → no se usa en Solara (allí require da una copia y puede matar al personaje).
-- Funcion global (no local) por el limite de 200 registros del chunk principal.
function setupSpaceSection()
    local isSolara = false
    pcall(function()
        if identifyexecutor then
            isSolara = string.find(string.lower(tostring(identifyexecutor())), "solara", 1, true) ~= nil
        end
    end)
    local S = { On = false, Conn = nil, CS = nil, Ours = false }

    local function charService()
        if S.CS then return S.CS end
        if isSolara then return nil end
        local ok, mod = pcall(function()
            return require(ReplicatedStorage.Services.Asset.CharacterService)
        end)
        if ok and type(mod) == "table" and type(mod.GetLocalCharacter) == "function" then S.CS = mod end
        return S.CS
    end

    local function localRegistry()
        local cs = charService()
        if not cs then return nil end
        local ok, c = pcall(function() return cs:GetLocalCharacter() end)
        if ok and type(c) == "table" and type(c.DataRegistry) == "table" then return c.DataRegistry end
        return nil
    end

    local function paused(reg)
        return reg:Get("Downed") == true or reg:Get("Ragdolling") == true or (reg:Get("Carried") or 0) ~= 0
    end

    -- Gravedad ajustable: el estado Grappling sigue cancelando el peso (y sigue sin nada que te enderece, así que
    -- girás igual); encima se suma una fuerza propia hacia abajo = % de tu peso real. 0 % = cero, 100 % ≈ normal.
    local G = { On = false, Pct = 30 }
    local function removeGravity()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local f = hrp:FindFirstChild("YYSpaceGravity")
        if f then pcall(function() f:Destroy() end) end
        local a = hrp:FindFirstChild("YYSpaceGravityAtt")
        if a then pcall(function() a:Destroy() end) end
    end
    local function applyGravity()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local att = hrp:FindFirstChild("YYSpaceGravityAtt")
        if not att then
            att = Instance.new("Attachment")
            att.Name = "YYSpaceGravityAtt"
            att.Parent = hrp
        end
        local f = hrp:FindFirstChild("YYSpaceGravity")
        if not f then
            f = Instance.new("VectorForce")
            f.Name = "YYSpaceGravity"
            f.RelativeTo = Enum.ActuatorRelativeTo.World
            f.ApplyAtCenterOfMass = true
            f.Attachment0 = att
            f.Parent = hrp
        end
        f.Force = Vector3.new(0, -hrp.AssemblyMass * workspace.Gravity * (G.Pct / 100), 0)
    end

    local function step()
        local reg = localRegistry()
        if not reg then return end
        if paused(reg) then
            if S.Ours and reg:Get("Grappling") == true then reg:Set("Grappling", false) end
            S.Ours = false
            removeGravity()
            return
        end
        if reg:Get("Grappling") ~= true then reg:Set("Grappling", true) end
        S.Ours = true
        if G.On and G.Pct > 0 then applyGravity() else removeGravity() end
    end

    local function stop()
        removeGravity()
        if S.Conn then S.Conn:Disconnect() S.Conn = nil end
        if S.Ours then
            local reg = localRegistry()
            if reg then pcall(function() reg:Set("Grappling", false) end) end
        end
        S.Ours = false
    end

    YYPlace(TabExtra, 6.10)
    if isSolara then
        TabExtra:CreateLabel("No disponible en Solara", "Not available on Solara", 11)
    end
    local spaceToggle
    spaceToggle = TabExtra:CreateToggle("Gravedad cero", "Zero Gravity", false, function(enabled)
        S.On = enabled
        stop()
        if not enabled then return end
        if not charService() then
            warn("[Espacio] No se pudo usar CharacterService (Solara o módulo no encontrado)")
            S.On = false
            if spaceToggle and spaceToggle.SetValue then spaceToggle.SetValue(false) end
            return
        end
        S.Conn = RunService.Heartbeat:Connect(function()
            local ok, err = pcall(step)
            if not ok then warn("[Espacio] " .. tostring(err)) end
        end)
    end)
    TabExtra:CreateToggle("Gravedad ajustable", "Adjustable Gravity", false, function(enabled)
        G.On = enabled
        if not enabled then removeGravity() end
    end)
    YYSliderNames["Space Gravity %"] = "Gravedad espacio %"
    TabExtra:CreateSlider("Space Gravity %", 0, 100, G.Pct, function(value)
        G.Pct = tonumber(value) or 30
    end)
    TabExtra:CreateDivider()
end
pcall(setupSpaceSection)

-- ===== GIRO 360 (Extra · Diversión) =====
-- Gira tu HumanoidRootPart sin parar (lo ven los demás: tu cliente manda la física de tu personaje).
-- Evade endereza la raíz de dos formas (verificado en Movement.RootPartOrienter): en el cliente le pone la CFrame
-- mirando a la cámara en cada frame, y el servidor crea "OrienterAttachment.Orienter" en la raíz. Mientras gira,
-- ese Orienter se apaga en tu cliente y la rotación se vuelve a poner justo antes de la física (Stepped) y
-- antes de dibujar (RenderStepped). Al apagarlo todo vuelve como estaba.
-- Funcion global (no local) por el limite de 200 registros del chunk principal.
function setupSpinSection()
    local Spin = { On = false, Speed = 1.5, Angle = 0, Conns = {}, Orienter = nil }

    local function root()
        local char = LocalPlayer.Character
        return char and char:FindFirstChild("HumanoidRootPart")
    end
    local function setOrienter(enabled)
        local hrp = root()
        local att = hrp and hrp:FindFirstChild("OrienterAttachment")
        local o = att and att:FindFirstChild("Orienter")
        if o then
            pcall(function() o.Enabled = enabled end)
            Spin.Orienter = (not enabled) and o or nil
        end
        if enabled and Spin.Orienter then
            pcall(function() Spin.Orienter.Enabled = true end)
            Spin.Orienter = nil
        end
    end
    local function apply()
        local hrp = root()
        if not hrp then return end
        hrp.CFrame = CFrame.new(hrp.Position) * CFrame.Angles(0, Spin.Angle, 0)
    end
    -- Por qué antes solo giraba con Gravedad cero: en los estados normales Evade (RootPartOrienter, cliente) vuelve a
    -- poner la raíz mirando a la cámara en CADA frame con SetCFrame; en el estado Grappling no (orientación "None").
    -- Fuera de Solara se envuelve RootPartOrienter.SetCFrame: si el giro está prendido, a TU raíz se le pone el ángulo
    -- del giro en vez del de la cámara (solo la rotación: la posición es la que manda el juego). Así funciona con la
    -- gravedad normal y se combina con Dara Trimp, Salto frontal, Impulso de salto, etc. (ellos usan la cámara, no la raíz).
    local isSolara = false
    pcall(function()
        if identifyexecutor then
            isSolara = string.find(string.lower(tostring(identifyexecutor())), "solara", 1, true) ~= nil
        end
    end)
    local env = (type(getgenv) == "function" and getgenv()) or _G
    env.YYSpinState = env.YYSpinState or { On = false, Angle = 0 }
    local Shared = env.YYSpinState
    local function hookOrienter()
        if isSolara or env.YYSpinHooked then return end
        local ok, mod = pcall(function()
            return require(ReplicatedStorage.Objects.Game.Character.Client.Movement.RootPartOrienter)
        end)
        if not ok or type(mod) ~= "table" or type(mod.SetCFrame) ~= "function" then return end
        local original = env.YYSpinOriginalSetCFrame or mod.SetCFrame
        env.YYSpinOriginalSetCFrame = original
        mod.SetCFrame = function(self, cf, ...)
            local st = env.YYSpinState
            if st and st.On and typeof(cf) == "CFrame" and self and self.Character == LocalPlayer.Character then
                cf = CFrame.new(cf.Position) * CFrame.Angles(0, st.Angle, 0)
            end
            return original(self, cf, ...)
        end
        env.YYSpinHooked = true
    end
    -- el Humanoid también gira solo hacia donde caminás (AutoRotate): se apaga mientras gira
    local function setAutoRotate(on)
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        if not on then
            if Spin.AutoRotateWas == nil then Spin.AutoRotateWas = hum.AutoRotate end
            hum.AutoRotate = false
        elseif Spin.AutoRotateWas ~= nil then
            hum.AutoRotate = Spin.AutoRotateWas
            Spin.AutoRotateWas = nil
        end
    end

    local function stop()
        for _, c in ipairs(Spin.Conns) do pcall(function() c:Disconnect() end) end
        Spin.Conns = {}
        Shared.On = false
        setOrienter(true)
        pcall(setAutoRotate, true)
    end

    YYPlace(TabExtra, 6.15)
    local spinToggle
    spinToggle = TabExtra:CreateFloatingToggle("Giro 360", "Spin 360", false, function(enabled)
        Spin.On = enabled
        stop()
        if not enabled then return end
        hookOrienter()
        Shared.On = true
        table.insert(Spin.Conns, RunService.Stepped:Connect(function(_, dt)
            Spin.Angle = (Spin.Angle + dt * Spin.Speed * math.pi * 2) % (math.pi * 2)
            Shared.Angle = Spin.Angle
            setOrienter(false)
            pcall(setAutoRotate, false)
            pcall(apply)
        end))
        table.insert(Spin.Conns, RunService.RenderStepped:Connect(function()
            pcall(apply)
        end))
    end)
    TabExtra:CreateSlider("Spin Speed", 0.2, 6, Spin.Speed, function(value)
        Spin.Speed = tonumber(value) or 1.5
    end)
    TabExtra:CreateDivider()
end
YYSliderNames["Spin Speed"] = "Vueltas/seg"
pcall(setupSpinSection)

-- ===== RUTA AL CAÍDO (Map · ESP) =====
-- Busca al jugador caído más cercano (estado "Downed" de StateInfo, sin contar a los que ya llevan) y dibuja
-- en el piso el camino más corto con PathfindingService (esquiva paredes, permite saltos). Se recalcula cada
-- segundo. Si Roblox no encuentra camino, muestra una línea directa en naranja. Todo es local: solo lo ves vos.
function setupDownedRoute()
    local PathfindingService = game:GetService("PathfindingService")
    local R = { On = false, Folder = nil, Dots = {}, Busy = false, Loop = nil, Flow = nil, Target = nil, Gen = 0 }
    local MAX_DOTS = 80

    local function folder()
        if R.Folder and R.Folder.Parent then return R.Folder end
        local f = Instance.new("Folder")
        f.Name = "YYDownedRoute"
        f.Parent = Workspace
        R.Folder = f
        return f
    end
    local function dot(i)
        local d = R.Dots[i]
        if d and d.Parent then return d end
        d = Instance.new("Part")
        d.Name = "Dot"
        d.Shape = Enum.PartType.Ball
        d.Size = Vector3.new(0.55, 0.55, 0.55)
        d.Material = Enum.Material.Neon
        d.Anchored = true
        d.CanCollide, d.CanQuery, d.CanTouch = false, false, false
        d.CastShadow = false
        d.Parent = folder()
        R.Dots[i] = d
        return d
    end
    local function clear()
        for _, d in ipairs(R.Dots) do pcall(function() d.Transparency = 1 end) end
    end
    local function destroyAll()
        if R.Folder then pcall(function() R.Folder:Destroy() end) end
        R.Folder, R.Dots = nil, {}
    end

    local function nearestDowned(myPos)
        local cs = FindCharService and FindCharService()
        if not cs then return nil end
        local ok, chars = pcall(function() return cs:GetCharacters() end)
        if not ok or not chars then return nil end
        local best, bestD = nil, math.huge
        for i = 1, #chars do
            local v = chars[i]
            if type(v) == "table" and v.Done and not v.Local and v.PrimaryPart then
                local okS, state = pcall(function() return v.State and v.State.State end)
                if okS and state == "Downed" then
                    local d = (v.PrimaryPart.Position - myPos).Magnitude
                    if d < bestD then best, bestD = v, d end
                end
            end
        end
        return best
    end

    -- puntos cada ~3 studs sobre la lista de posiciones (así el camino se ve continuo)
    local function draw(points, colorA, colorB)
        local samples = {}
        for i = 1, #points - 1 do
            local a, b = points[i], points[i + 1]
            local len = (b - a).Magnitude
            local n = math.max(1, math.floor(len / 3))
            for k = 0, n - 1 do
                samples[#samples + 1] = a:Lerp(b, k / n)
                if #samples >= MAX_DOTS then break end
            end
            if #samples >= MAX_DOTS then break end
        end
        samples[#samples + 1] = points[#points]
        for i, p in ipairs(samples) do
            local d = dot(i)
            local t = (#samples > 1) and (i - 1) / (#samples - 1) or 1
            d.Color = colorA:Lerp(colorB, t)
            d.CFrame = CFrame.new(p + Vector3.new(0, 0.4, 0))
            d.Transparency = 0.15
            d.Size = (i == #samples) and Vector3.new(1.4, 1.4, 1.4) or Vector3.new(0.55, 0.55, 0.55)
        end
        for i = #samples + 1, #R.Dots do
            R.Dots[i].Transparency = 1
        end
        R.Count = #samples
    end

    local function update()
        if R.Busy then return end
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then clear() return end
        local target = nearestDowned(hrp.Position)
        if not target then clear() return end
        R.Busy = true
        local gen = R.Gen
        local from, to = hrp.Position, target.PrimaryPart.Position
        local path = PathfindingService:CreatePath({ AgentRadius = 2, AgentHeight = 5, AgentCanJump = true, WaypointSpacing = 4 })
        local ok = pcall(function() path:ComputeAsync(from, to) end)
        R.Busy = false
        if gen ~= R.Gen or not R.On then return end
        if ok and path.Status == Enum.PathStatus.Success then
            local pts = {}
            for _, w in ipairs(path:GetWaypoints()) do pts[#pts + 1] = w.Position end
            if #pts >= 2 then
                draw(pts, Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 70, 70))
                return
            end
        end
        -- sin camino: línea directa en naranja (al menos marca la dirección)
        draw({ from - Vector3.new(0, 2.5, 0), to }, Color3.fromRGB(255, 200, 120), Color3.fromRGB(255, 120, 0))
    end

    YYPlace(TabMap, 2.30)
    TabMap:CreateFloatingToggle("Ruta al caído", "Path to Downed", false, function(enabled)
        R.On = enabled
        R.Gen = R.Gen + 1
        if R.Loop then R.Loop:Disconnect() R.Loop = nil end
        if R.Flow then R.Flow:Disconnect() R.Flow = nil end
        if not enabled then destroyAll() return end
        local acc = 1
        R.Loop = RunService.Heartbeat:Connect(function(dt)
            acc = acc + dt
            if acc >= 1 then
                acc = 0
                task.spawn(function() pcall(update) end)
            end
        end)
        -- brillo que recorre el camino hacia el caído (solo cambia el tamaño de unos pocos puntos)
        local head, flowAcc = 0, 0
        R.Flow = RunService.Heartbeat:Connect(function(dt)
            flowAcc = flowAcc + dt
            if flowAcc < 0.05 then return end
            flowAcc = 0
            local n = R.Count or 0
            if n < 3 then return end
            head = head % (n - 1) + 1
            for i = 1, n - 1 do
                local d = R.Dots[i]
                if d then
                    local near = math.abs(i - head) <= 1
                    d.Size = near and Vector3.new(0.85, 0.85, 0.85) or Vector3.new(0.55, 0.55, 0.55)
                end
            end
        end)
    end)
    TabMap:CreateDivider()
end
pcall(setupDownedRoute)

-- ===== ENTRENADOR DE MOVIMIENTO (Move · Salto) =====
-- Panel chico arriba al centro: tu velocidad en vivo, un gráfico de los últimos segundos y, en cada salto,
-- cuánto tardaste en volver a saltar después de tocar el piso (lo que define un buen bhop / trimp):
--   ≤ 0.06 s ¡Perfecto! · ≤ 0.15 s Bien · más = Tarde. Además la racha de perfectos y cuánta velocidad ganaste.
function setupMovementTrainer()
    local Tr = { On = false, Gui = nil, Conn = nil, Bars = {}, Samples = {}, LandTime = nil, Air = false, Streak = 0, LastSpeed = 0, Best = 0 }
    local BARS = 36

    local function build()
        if Tr.Gui and Tr.Gui.Parent then return end
        -- la tarjeta la da la librería (YinYang.Kit.Meter); acá solo se dice qué mostrar
        local K = YYKit()
        if not (K and K.Meter) then warn("[Entrenador] La librería UI no tiene el kit de ventanas (actualizala)") return end
        local M = K.Meter({ Name = "YYMoveTrainer", DisplayOrder = 40, Bars = BARS, Unit = scriptText("studs/s · máx 0", "studs/s · max 0"),
            Chip = scriptText("Saltá para medir", "Jump to measure") })
        Tr.Gui, Tr.Speed, Tr.Unit, Tr.Chip, Tr.ChipScale, Tr.Info, Tr.Bars = M.Gui, M.Value, M.Unit, M.Chip, M.ChipScale, M.Info, M.Bars
    end

    local function verdict(delay, gain)
        local text, color
        if delay <= 0.06 then
            Tr.Streak = Tr.Streak + 1
            text, color = scriptText("¡Perfecto!", "Perfect!"), Color3.fromRGB(70, 210, 120)
        elseif delay <= 0.15 then
            Tr.Streak = 0
            text, color = scriptText("Bien", "Good"), Color3.fromRGB(240, 190, 60)
        else
            Tr.Streak = 0
            text, color = scriptText("Tarde", "Late"), Color3.fromRGB(235, 80, 80)
        end
        Tr.Chip.Text = text .. (Tr.Streak >= 2 and ("  x" .. Tr.Streak) or "")
        Tr.Chip.BackgroundColor3 = color
        Tr.ChipScale.Scale = 1.25
        game:GetService("TweenService"):Create(Tr.ChipScale, TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
        Tr.Info.Text = string.format("%d ms · %s%d", math.floor(delay * 1000 + 0.5), gain >= 0 and "+" or "", math.floor(gain + 0.5))
    end

    local sampleAcc = 0
    local function step(dt)
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not (hrp and hum and Tr.Gui) then return end
        local v = hrp.AssemblyLinearVelocity
        local speed = Vector3.new(v.X, 0, v.Z).Magnitude
        if speed > Tr.Best then Tr.Best = speed end
        Tr.Speed.Text = tostring(math.floor(speed + 0.5))
        Tr.Unit.Text = scriptText("studs/s · máx ", "studs/s · max ") .. math.floor(Tr.Best + 0.5)
        local air = hum.FloorMaterial == Enum.Material.Air
        local now = os.clock()
        if Tr.Air and not air then
            Tr.LandTime = now -- tocó el piso
        elseif not Tr.Air and air and v.Y > 4 then
            -- despegó hacia arriba = salto; se mide solo si antes venía de tocar el piso hace poco
            if Tr.LandTime and now - Tr.LandTime < 1 then
                verdict(now - Tr.LandTime, speed - Tr.LastSpeed)
            end
            Tr.LastSpeed = speed
            Tr.LandTime = nil
        end
        Tr.Air = air
        sampleAcc = sampleAcc + dt
        if sampleAcc >= 0.08 then
            sampleAcc = 0
            table.insert(Tr.Samples, speed)
            if #Tr.Samples > BARS then table.remove(Tr.Samples, 1) end
            local top = math.max(Tr.Best, 1)
            for i, b in ipairs(Tr.Bars) do
                local s = Tr.Samples[i - (BARS - #Tr.Samples)]
                local h = s and math.clamp(s / top, 0.05, 1) or 0.05
                b.Size = UDim2.new(1 / BARS, -1, h, 0)
                b.BackgroundTransparency = s and (0.55 - 0.45 * h) or 0.85
            end
        end
    end

    YYPlace(TabMove, 2.90)
    TabMove:CreateFloatingToggle("Entrenador", "Trainer", false, function(enabled)
        Tr.On = enabled
        if Tr.Conn then Tr.Conn:Disconnect() Tr.Conn = nil end
        if not enabled then
            if Tr.Gui then pcall(function() Tr.Gui:Destroy() end) end
            Tr.Gui = nil
            Tr.Bars, Tr.Samples = {}, {}
            return
        end
        Tr.Best, Tr.Streak, Tr.LandTime = 0, 0, nil
        build()
        Tr.Conn = RunService.Heartbeat:Connect(function(dt) pcall(step, dt) end)
    end)
    TabMove:CreateDivider()
end
pcall(setupMovementTrainer)

-- ===== INTERFAZ (Extra): Menú en ventana + ocultar partes de la barra de Roblox =====
-- Funciones globales (no locales) por el limite de 200 registros del chunk principal.

-- Oculta instancias de CoreGui por nombre y las mantiene ocultas (React puede volver a dibujarlas).
-- Nombres verificados en CoreGui.RobloxGui.Modules.TopBar...TopBarApp: "UnibarLeftFrame" (pastilla con menú,
-- chat y micrófono), "MenuIconHolder" / "MenuIcon" (botón de Roblox de la esquina). React usa la clave como nombre.
function YYMakeCoreHider(names)
    local H = { On = false, Hidden = {}, Conns = {}, Loop = nil }
    local function scan()
        pcall(function()
            for _, d in ipairs(game:GetService("CoreGui"):GetDescendants()) do
                if names[d.Name] and d:IsA("GuiObject") and not H.Hidden[d] then
                    H.Hidden[d] = true
                    d.Visible = false
                    table.insert(H.Conns, d:GetPropertyChangedSignal("Visible"):Connect(function()
                        if H.On and d.Visible then d.Visible = false end
                    end))
                end
            end
        end)
    end
    function H.Set(on)
        H.On = on
        if H.Loop then H.Loop = nil end
        if on then
            scan()
            local token = {}
            H.Loop = token
            task.spawn(function()
                while H.Loop == token do
                    task.wait(3)
                    if H.Loop == token then scan() end
                end
            end)
        else
            for _, c in ipairs(H.Conns) do pcall(function() c:Disconnect() end) end
            H.Conns = {}
            for d in pairs(H.Hidden) do pcall(function() d.Visible = true end) end
            H.Hidden = {}
        end
    end
    return H
end

-- ---------- MENÚ EN VENTANA ----------
-- Verificado en ReplicatedStorage.Services.UI.MenuService y ReplicatedStorage.Objects.Menu.Menu:
-- el menú real se arma con Menu.new(UI):Initialize() sobre una copia de ReplicatedStorage.Assets.UI.Menu.
-- Lo que hace el menú de Evade y acá NO se hace (para no romper la partida):
--   · MenuService:Insert() borra el HUD (GameUIService:Clear)            → no se usa MenuService
--   · SetViewInfo mueve la cámara al MenuView, cambia zoom, chat y lista  → se reemplaza por nada en ESTA ventana
--   · SetMap / SetView cambian mapa, FOV y música                         → SetView propio (solo cambia de pantalla)
--   · Initialize oculta los controles táctiles, borra la NightVision de Lighting, pone música de lobby y
--     cambia la sensibilidad → se guarda y se devuelve todo apenas termina
-- La ventana se puede mover desde su barra, fijar con 📌 y cerrar con ✕ (o con el mismo toggle).
function setupMenuWindow()
    local isSolara = false
    pcall(function()
        if identifyexecutor then
            isSolara = string.find(string.lower(tostring(identifyexecutor())), "solara", 1, true) ~= nil
        end
    end)
    local M = { Gui = nil, Menu = nil, Locked = false, Conn = nil, Toggle = nil,
        MovedView = nil, ViewOldParent = nil, CamPart = nil, CamHooked = false, DataConns = {}, Stage = nil }
    local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")

    -- v42: las pantallas del menú (tienda, inventario, personaje, emotes, modificar objetos) usan workspace.MenuView
    -- (escena 3D del menú). Sin eso, Activate() fallaba en SetVisualModel y las listas quedaban vacías.
    local function findMenuView()
        local inWs = workspace:FindFirstChild("MenuView")
        if inWs then return inWs, true end
        local assets = ReplicatedStorage:FindFirstChild("Assets")
        local src = assets and assets:FindFirstChild("Menu") and assets.Menu:FindFirstChild("MenuView")
        if not src then
            -- MenuService:Destroy() la deja guardada dentro del propio MenuService
            local services = ReplicatedStorage:FindFirstChild("Services")
            local ms = services and services:FindFirstChild("UI") and services.UI:FindFirstChild("MenuService")
            src = ms and ms:FindFirstChild("MenuView")
        end
        return src, false
    end
    local function realMenuOpen()
        local g = PlayerGui:FindFirstChild("Menu")
        return g ~= nil and g ~= M.Gui
    end
    -- la cámara del juego no se toca: lo que la tienda le pide a la cámara se usa solo para el visor de la ventana
    local function hookMenuCamera()
        if M.CamHooked then return end
        local ok, CameraService = pcall(function() return require(ReplicatedStorage.Services.Client.CameraService) end)
        if not ok or type(CameraService) ~= "table" or type(CameraService.SetSubject) ~= "function" then return end
        local original = CameraService.SetSubject
        local okSet = pcall(function()
            CameraService.SetSubject = function(self, subject, ...)
                if M.Menu and typeof(subject) == "Instance" then
                    local mv = workspace:FindFirstChild("MenuView")
                    if mv and subject:IsDescendantOf(mv) then
                        M.CamPart = subject
                        return
                    end
                end
                return original(self, subject, ...)
            end
        end)
        M.CamHooked = okSet
    end

    local function closeMenu()
        if M.Conn then M.Conn:Disconnect() M.Conn = nil end
        for _, c in ipairs(M.DataConns) do pcall(function() c:Disconnect() end) end
        M.DataConns = {}
        if M.Stage then pcall(M.Stage.Destroy) M.Stage = nil end
        if M.Menu then
            local menu = M.Menu
            M.Menu = nil
            pcall(function()
                for _, v in pairs(menu.Views or {}) do
                    local vm = v.ViewModule
                    if vm and vm.SetVisualModel then pcall(function() vm:SetVisualModel(nil) end) end
                end
            end)
            pcall(function() menu:Destroy() end)
        end
        M.CamPart = nil
        M.CharPreview = nil
        -- la escena del menú vuelve a su lugar (si el menú real del juego no la está usando)
        if M.MovedView then
            local view = M.MovedView
            M.MovedView = nil
            if view.Parent == workspace and not realMenuOpen() then
                pcall(function()
                    local vm = view:FindFirstChild("VisualModel")
                    if vm then vm:Destroy() end
                    view.Parent = M.ViewOldParent
                end)
            end
        end
        if M.Gui then pcall(function() M.Gui:Destroy() end) end
        M.Gui = nil
    end

    -- visor 3D dentro de la ventana: copia el modelo que el menú pone en MenuView y lo dibuja con la cámara del menú
    local function makeStage(body, menu)
        local S = { Src = nil, Clone = nil, Map = {}, Dirty = false, DirtyAt = 0, Yaw = 0, Conns = {}, SrcConn = nil }
        local p = GetAvatarPalette()
        local backdrop = YYKitMake("Frame")
        backdrop.Name = "StageBackdrop"
        backdrop.Size = UDim2.fromScale(1, 1)
        backdrop.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        backdrop.BorderSizePixel = 0
        backdrop.ZIndex = 0
        backdrop.Visible = false
        backdrop.Parent = body
        local grad = YYKitMake("UIGradient")
        grad.Rotation = 90
        grad.Color = ColorSequence.new(p.Secondary:Lerp(p.Accent, 0.12), Color3.fromRGB(8, 8, 11))
        grad.Parent = backdrop
        local vp = YYKitMake("ViewportFrame")
        vp.Name = "Stage"
        vp.Size = UDim2.fromScale(1, 1)
        vp.BackgroundTransparency = 1
        vp.Ambient = Color3.fromRGB(165, 165, 175)
        vp.LightColor = Color3.fromRGB(255, 255, 255)
        vp.LightDirection = Vector3.new(-0.6, -1, -0.8)
        vp.ZIndex = 0
        vp.Parent = backdrop
        local cam = Instance.new("Camera")
        cam.FieldOfView = 35
        cam.Parent = vp
        vp.CurrentCamera = cam
        local world = Instance.new("WorldModel")
        world.Parent = vp
        local hint = YYKitMake("TextLabel")
        hint.BackgroundTransparency = 1
        hint.AnchorPoint = Vector2.new(0.5, 1)
        hint.Position = UDim2.new(0.5, 0, 1, -8)
        hint.Size = UDim2.fromOffset(260, 16)
        hint.Font = Enum.Font.GothamMedium
        hint.TextSize = 11
        hint.TextColor3 = p.TextDim
        hint.TextTransparency = 0.3
        hint.Text = scriptText("Arrastrá el modelo para girarlo", "Drag the model to rotate it")
        hint.ZIndex = 0
        hint.Parent = backdrop

        local function clearClone()
            if S.SrcConn then S.SrcConn:Disconnect() S.SrcConn = nil end
            if S.Clone then pcall(function() S.Clone:Destroy() end) end
            S.Clone, S.Map = nil, {}
        end
        local function rebuild(src)
            clearClone()
            S.Src, S.Dirty = src, false
            if not src then return end
            local id = 0
            for _, d in ipairs(src:GetDescendants()) do
                if d:IsA("BasePart") then
                    id = id + 1
                    d:SetAttribute("YYMirror", id)
                end
            end
            local wasArchivable = src.Archivable
            src.Archivable = true
            local ok, copy = pcall(function() return src:Clone() end)
            src.Archivable = wasArchivable
            if not ok or not copy then return end
            local junk, byId = {}, {}
            for _, d in ipairs(copy:GetDescendants()) do
                if d:IsA("BaseScript") or d:IsA("Sound") then
                    junk[#junk + 1] = d
                elseif d:IsA("BasePart") then
                    d.Anchored = true
                    local key = d:GetAttribute("YYMirror")
                    if key then byId[key] = d end
                end
            end
            for _, d in ipairs(junk) do pcall(function() d:Destroy() end) end
            for _, d in ipairs(src:GetDescendants()) do
                if d:IsA("BasePart") then
                    local dst = byId[d:GetAttribute("YYMirror")]
                    if dst then S.Map[d] = dst end
                end
            end
            copy.Parent = world
            S.Clone = copy
            -- accesorios/herramientas que el juego agrega después: se vuelve a copiar
            S.SrcConn = src.DescendantAdded:Connect(function(d)
                if d:IsA("BasePart") or d:IsA("Accessory") or d:IsA("Clothing") then
                    S.Dirty, S.DirtyAt = true, os.clock()
                end
            end)
        end
        local camNames = { Inventory = "InventoryCamPart", Shop = "ShopCamPart" }
        -- v43: tu personaje en la pestaña Personaje = copia del cuerpo que ya tenés en la partida (workspace.Rigs, mismo "Tag")
        local function liveRig()
            local char = LocalPlayer.Character
            local tag = char and char:GetAttribute("Tag")
            local rigs = workspace:FindFirstChild("Rigs")
            if tag == nil or not rigs then return nil end
            for _, r in ipairs(rigs:GetChildren()) do
                if r:IsA("Model") and r:GetAttribute("Tag") == tag then return r end
            end
            return nil
        end
        function S.Step()
            local mv = workspace:FindFirstChild("MenuView")
            local src = mv and mv:FindFirstChild("VisualModel")
            local view = menu.View
            local charMode = view == "Inventory" and M.CharPreview ~= nil and src == nil
            if charMode then src = liveRig() end
            local camName = camNames[view]
            backdrop.Visible = camName ~= nil
            if not camName or not mv then return end
            if src ~= S.Src or (S.Dirty and os.clock() - S.DirtyAt > 0.15) then
                S.Yaw = (src == S.Src) and S.Yaw or 0
                rebuild(src)
            end
            hint.Visible = S.Clone ~= nil
            local cams = mv:FindFirstChild("Parts") and mv.Parts:FindFirstChild("Cameras")
            local camPart = (view == "Shop" and M.CamPart and M.CamPart.Parent and M.CamPart) or (cams and cams:FindFirstChild(camName))
            if camPart and camPart:IsA("BasePart") then cam.CFrame = camPart.CFrame end
            if S.Clone and src and charMode then
                -- cuerpo vivo: se dibuja parado sobre el punto del personaje del menú (copia tus animaciones en tiempo real)
                local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                local spot = mv:FindFirstChild("Parts") and mv.Parts:FindFirstChild("Inventory") and mv.Parts.Inventory:FindFirstChild("CharacterPart")
                if hrp and spot then
                    local base = spot.CFrame * CFrame.Angles(0, S.Yaw, 0)
                    local ref = hrp.CFrame
                    for from, to in pairs(S.Map) do
                        if from.Parent then to.CFrame = base * ref:ToObjectSpace(from.CFrame) end
                    end
                end
            elseif S.Clone and src then
                local root = src.PrimaryPart or next(S.Map)
                local pivot = root and root.Position or Vector3.zero
                local rot = CFrame.new(pivot) * CFrame.Angles(0, S.Yaw, 0) * CFrame.new(-pivot)
                for from, to in pairs(S.Map) do
                    if from.Parent then to.CFrame = rot * from.CFrame end
                end
            end
        end
        -- girar el modelo arrastrando (en la zona libre de la ventana)
        local dragging, lastX = false, 0
        S.Conns[#S.Conns + 1] = UserInputService.InputBegan:Connect(function(input, processed)
            if processed or not backdrop.Visible or not S.Clone then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local pos, size = body.AbsolutePosition, body.AbsoluteSize
            local x, y = input.Position.X, input.Position.Y
            if x >= pos.X and x <= pos.X + size.X and y >= pos.Y and y <= pos.Y + size.Y then
                dragging, lastX = true, x
            end
        end)
        S.Conns[#S.Conns + 1] = UserInputService.InputChanged:Connect(function(input)
            if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                S.Yaw = S.Yaw + (input.Position.X - lastX) * 0.012
                lastX = input.Position.X
            end
        end)
        S.Conns[#S.Conns + 1] = UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = false end
        end)
        function S.Destroy()
            clearClone()
            for _, c in ipairs(S.Conns) do pcall(function() c:Disconnect() end) end
            S.Conns = {}
            pcall(function() backdrop:Destroy() end)
        end
        return S
    end

    local function openMenu()
        closeMenu()
        local okMod, MenuModule = pcall(function()
            return require(ReplicatedStorage.Objects.Menu.Menu)
        end)
        local template = ReplicatedStorage:FindFirstChild("Assets") and ReplicatedStorage.Assets:FindFirstChild("UI") and ReplicatedStorage.Assets.UI:FindFirstChild("Menu")
        if not okMod or type(MenuModule) ~= "table" or not template then
            warn("[Menú] No se encontró el menú de Evade: " .. tostring(MenuModule))
            return false
        end

        -- ventana: la arma la librería (YinYang.Kit.HostWindow) con el tema activo; acá solo se monta el menú de Evade adentro
        local K = _G.YinYang and _G.YinYang.Kit
        if not K or not K.HostWindow then
            warn("[Menú] La librería UI no tiene el kit de ventanas (actualizala)")
            return false
        end
        local W
        W = K.HostWindow({Name = "YYMenuWindow", DisplayOrder = 90, Locked = M.Locked,
            Title = scriptText("MENÚ  ·  arrastrá para mover", "MENU  ·  drag to move"),
            OnLock = function(locked)
                M.Locked = locked
                W:SetTitle(locked and scriptText("MENÚ  ·  fijado", "MENU  ·  locked") or scriptText("MENÚ  ·  arrastrá para mover", "MENU  ·  drag to move"))
            end,
            OnClose = function()
                closeMenu()
                if M.Toggle and M.Toggle.SetValue then M.Toggle.SetValue(false) end
                return true
            end})
        local body = W.Body
        M.Gui = W.Gui
        -- contenido del menú (recortado a la ventana)
        local menuUI = template:Clone()
        if menuUI:IsA("LayerCollector") then
            -- se pasan los hijos del ScreenGui del menú a la ventana (el menú busca UI.Views, UI.Full, etc.)
            local holder = YYKitMake("Frame")
            holder.Name = "MenuUI"
            holder.Size = UDim2.fromScale(1, 1)
            holder.BackgroundTransparency = 1
            holder.Parent = body
            for _, child in ipairs(menuUI:GetChildren()) do
                child.Parent = holder
            end
            menuUI:Destroy()
            menuUI = holder
        else
            menuUI.Parent = body
        end

        -- guardar lo que Initialize cambia
        local lighting = game:GetService("Lighting")
        local nightVision = lighting:FindFirstChild("NightVision")
        if nightVision then nightVision.Parent = nil end
        local sens = UserInputService.MouseDeltaSensitivity
        local touchFrame = PlayerGui:FindFirstChild("TouchGui") and PlayerGui.TouchGui:FindFirstChild("TouchControlFrame")
        local touchVisible = touchFrame and touchFrame.Visible

        -- escena 3D del menú en workspace (igual que hace MenuService:Insert); al cerrar vuelve a su lugar
        local menuView, alreadyIn = findMenuView()
        if menuView and not alreadyIn then
            M.ViewOldParent = menuView.Parent
            local okMove = pcall(function() menuView.Parent = workspace end)
            if okMove then M.MovedView = menuView end
        end
        if not menuView then
            warn("[Menú] No se encontró MenuView: la tienda y el inventario no van a cargar")
        end
        hookMenuCamera()

        local menu = MenuModule.new(menuUI)
        -- reemplazos SOLO en esta ventana: no tocan cámara, mapa, FOV, chat ni música
        menu.SetViewInfo = function() end
        menu.SetMap = function() end
        menu.SetView = function(self, view, payload)
            if self.View == view or self.Transitioning or not self.Views[view] then return end
            self.Transitioning = true
            local current = self.Views[self.View]
            if current then
                current.Frame.Position = UDim2.new()
                current.Frame.Visible = false
                if current.ViewModule and current.ViewModule.Deactivate then pcall(function() current.ViewModule:Deactivate() end) end
            end
            self.Views[view].Frame.Visible = true
            if self.Views[view].ViewModule and self.Views[view].ViewModule.Activate then
                pcall(function() self.Views[view].ViewModule:Activate(payload) end)
            end
            self.View = view
            self.Transitioning = false
        end
        local okInit, errInit = pcall(function() menu:Initialize() end)

        -- devolver lo que Initialize cambió
        if nightVision then pcall(function() nightVision.Parent = lighting end) end
        pcall(function() UserInputService.MouseDeltaSensitivity = sens end)
        if touchFrame and touchVisible ~= nil then pcall(function() touchFrame.Visible = touchVisible end) end
        pcall(function()
            local music = require(ReplicatedStorage.Services.Other.MusicService)
            music:RemoveSong("Default") -- sin música de lobby en la partida
        end)
        if not okInit then
            warn("[Menú] " .. tostring(errInit))
            closeMenu()
            return false
        end
        M.Menu = menu
        -- datos en vivo (lo mismo que conecta MenuService): monedas, inventario, equipamiento, etc.
        pcall(function()
            local hooks = ReplicatedStorage.Shared.UserData.ClientHooks
            local map = {
                useCurrency = "CurrencyUpdated", useLoadout = "LoadoutUpdated", useInventory = "InventoryUpdated",
                useSettings = "SettingsUpdated", useProgression = "ProgressionUpdated", useCounters = "CounterUpdated",
                useEvent = "EventUpdated",
            }
            for moduleName, method in pairs(map) do
                local okHook, hook = pcall(function() return require(hooks:FindFirstChild(moduleName)) end)
                if okHook and type(hook) == "table" and hook.Changed and type(menu[method]) == "function" then
                    local okConn, conn = pcall(function()
                        return hook.Changed:Connect(function()
                            if M.Menu == menu then pcall(function() menu[method](menu) end) end
                        end)
                    end)
                    if okConn and conn then M.DataConns[#M.DataConns + 1] = conn end
                end
            end
        end)
        -- fix4: ClientHooks ya no existe, asi que el bloque de arriba no engancha nada. El loadout avisa ahora por
        -- Loadout.ObserveAll(cb): el callback llega SIN argumentos y devuelve una funcion de baja (log scanner v5).
        -- Se ignora la llamada inicial (la que ocurre al suscribirse) para no cambiar el comportamiento anterior.
        pcall(function()
            local lo = require(ReplicatedStorage.Client.Services.UserData.Inventory.Loadout)
            if type(lo) ~= "table" or type(lo.ObserveAll) ~= "function" or type(menu.LoadoutUpdated) ~= "function" then return end
            local subscribing = true
            local unsub = lo.ObserveAll(function()
                if subscribing then return end
                if M.Menu == menu then pcall(function() menu.LoadoutUpdated(menu) end) end
            end)
            subscribing = false
            if type(unsub) == "function" then
                M.DataConns[#M.DataConns + 1] = { Disconnect = function() pcall(unsub) end }
            end
        end)
        -- si el juego abre su propio menú (por ejemplo al morir) se cierra esta ventana para no pelear por la escena
        M.DataConns[#M.DataConns + 1] = PlayerGui.ChildAdded:Connect(function(child)
            if child.Name == "Menu" and M.Menu == menu then
                task.defer(function()
                    closeMenu()
                    if M.Toggle and M.Toggle.SetValue then M.Toggle.SetValue(false) end
                end)
            end
        end)
        -- v43: el inventario armaba un personaje de vista previa con TU nombre. RigService guarda un solo cuerpo por
        -- nombre de jugador (GetRig/ClearCachedRig): en partida eso le sacaba o movía el cuerpo a tu personaje real
        -- ("se cae al vacío"). En esta ventana la vista de personaje no crea ningún rig: copia tu cuerpo real al visor.
        pcall(function()
            local inv = menu.Views and menu.Views.Inventory and menu.Views.Inventory.ViewModule
            if type(inv) ~= "table" then return end
            local origSetVisualModel = inv.SetVisualModel
            inv.SetVisualModel = function(self, ...)
                M.CharPreview = nil
                return origSetVisualModel(self, ...)
            end
            inv.SetVisualCharacter = function(self, item)
                origSetVisualModel(self, nil)
                M.CharPreview = { Item = item }
            end
        end)
        local okStage, stage = pcall(makeStage, body, menu)
        if okStage then M.Stage = stage else warn("[Menú] visor 3D: " .. tostring(stage)) end
        -- animaciones de las pantallas (lo que hace Menu:Update, sin la parte de cámara/mapa) + visor 3D
        M.Conn = RunService.RenderStepped:Connect(function(dt)
            local v = menu.Views and menu.Views[menu.View]
            if v and v.ViewModule and v.ViewModule.Update then
                pcall(function() v.ViewModule:Update(dt) end)
            end
            if M.Stage then pcall(M.Stage.Step) end
        end)
        -- entrada suave: la hace la ventana de la librería (W:Show al crearse)
        return true
    end

    YYSectionHeader(TabExtra, 6.50, "INTERFAZ", "INTERFACE")
    YYPlace(TabExtra, 6.51)
    if isSolara then
        TabExtra:CreateLabel("Menú: no disponible en Solara", "Menu: not available on Solara", 11)
    end
    M.Toggle = TabExtra:CreateFloatingToggle("Menú", "Menu", false, function(enabled)
        if not enabled then closeMenu() return end
        if isSolara or not openMenu() then
            task.defer(function() if M.Toggle and M.Toggle.SetValue then M.Toggle.SetValue(false) end end)
        end
    end)

    YYPlace(TabExtra, 6.52)
    local unibar = YYMakeCoreHider({ UnibarLeftFrame = true })
    TabExtra:CreateToggle("Ocultar chat, menú y voz", "Hide chat, menu and voice", false, function(enabled)
        unibar.Set(enabled)
    end)
    local robloxButton = YYMakeCoreHider({ MenuIconHolder = true, MenuIcon = true })
    TabExtra:CreateToggle("Ocultar botón de Roblox", "Hide Roblox button", false, function(enabled)
        robloxButton.Set(enabled)
    end)
    TabExtra:CreateDivider()
end
pcall(setupMenuWindow)

-- ===== AUTO COMPRA (v49; reemplaza el multiplicador de v42) =====
-- Por qué el multiplicador no sirvió (verificado en el código del juego): el servidor limita los pedidos con un "balde
-- de fichas" (ReplicatedStorage.Shared.UserData.Misc.RateLimit: maxCalls por ventana de tiempo). Mandar 1000 de golpe
-- solo deja pasar los que entran en el balde; el resto se descarta. Además solo se repiten los objetos con
-- PurchaseInfo.OwnershipType = "Multiple" (Cola, granadas, desfibrilador, desplegables, utilidades...); los "Single"
-- se compran una vez y listo.
-- Ahora: comprás UNA vez a mano el objeto (botón COMPRAR del juego = Requests.Purchase:FireServer(id, 1)) y la auto
-- compra lo repite sola, a la velocidad más alta que el servidor acepta. La velocidad se mide en vivo cada segundo con
-- tu inventario (useInventory.ConsumableCount) o, si no, con tu saldo (useCurrency.Balance): si acepta todo, acelera;
-- si descarta, baja al ritmo que confirmó. Se detiene sola: sin saldo, al llegar a la cantidad, o si el servidor deja
-- de aceptar.
function setupPurchaseMultiplier()
    local A = { On = false, Target = 0, Hooked = false, Firing = false, Args = nil, Gen = 0, Running = false, Status = nil }
    -- v52: en Solara require() crea COPIAS de los módulos del juego (mismo ajuste que Dara Trimp / cámara): ahí no se
    -- leen precio, saldo ni inventario y se compra a un ritmo fijo y seguro; se detiene por cantidad o al apagarla.
    A.Solara = false
    pcall(function()
        if identifyexecutor then
            A.Solara = string.find(string.lower(tostring(identifyexecutor())), "solara", 1, true) ~= nil
        end
    end)
    local remote = nil
    local function getRemote()
        if remote and remote.Parent then return remote end
        pcall(function() remote = ReplicatedStorage.Shared.UserData.Events.Requests.Purchase end)
        return remote
    end
    local function notify(title, text)
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", { Title = title, Text = text, Duration = 4 })
        end)
    end
    local function setStatus(es, en)
        local l = A.Status
        if not l then return end
        pcall(function()
            l:SetAttribute("TextSpanish", es)
            l:SetAttribute("TextEnglish", en)
            l.Text = scriptText(es, en)
        end)
    end
    -- nombre, precio, moneda y tipo de propiedad del objeto (Items.Registry → módulo del objeto)
    local function itemInfo(id)
        local info = {}
        if A.Solara then info.name = tostring(id) return info end
        pcall(function()
            local mod = require(require(ReplicatedStorage.Items.Registry).GetById(id).Module)
            local p = mod.PurchaseInfo or {}
            info.price = tonumber(p.Price)
            info.currency = p.Currency
            info.ownership = p.OwnershipType
            info.name = mod.AppearanceInfo and mod.AppearanceInfo.Name
        end)
        info.name = info.name or tostring(id)
        return info
    end
    local function balance(currency)
        local value = nil
        if A.Solara then return nil end
        pcall(function() value = require(ReplicatedStorage.Client.Services.UserData.Currency).Balance(currency) end)
        return tonumber(value)
    end
    local function owned(id)
        local value = nil
        if A.Solara then return nil end
        pcall(function() value = require(ReplicatedStorage.Client.Services.UserData.Inventory).ConsumableCount(id) end)
        return tonumber(value)
    end

    local function run()
        local args = A.Args
        if not args then
            setStatus("Comprá 1 vez a mano el objeto y sigue solo", "Buy the item once by hand and it keeps going")
            notify(scriptText("Auto compra", "Auto buy"), scriptText("Comprá 1 vez a mano el objeto que querés repetir", "Buy the item you want to repeat once by hand"))
            return
        end
        local id = args[1]
        local info = itemInfo(id)
        if info.ownership and info.ownership ~= "Multiple" then
            setStatus(info.name .. ": se compra una sola vez", info.name .. ": can only be bought once")
            notify(scriptText("Auto compra", "Auto buy"), scriptText(info.name .. " no se puede comprar varias veces", info.name .. " can't be bought more than once"))
            return
        end
        A.Gen = A.Gen + 1
        local gen = A.Gen
        A.Running = true
        -- cómo se cuentan las compras confirmadas: inventario si el juego lo da; si no, saldo gastado / precio
        local count0 = owned(id)
        local bal0 = info.currency and balance(info.currency) or nil
        local function confirmed()
            if count0 then
                local c = owned(id)
                if c then return math.max(c - count0, 0) end
            end
            if bal0 and info.price and info.price > 0 then
                local b = balance(info.currency)
                if b then return math.max(math.floor((bal0 - b) / info.price + 0.5), 0) end
            end
            return nil
        end
        local rate = 8 -- pedidos por segundo al arrancar; se ajusta solo
        local budget, sent, windowSent = 0, 0, 0
        local lastGot, lastCheck, lastAccept = 0, os.clock(), os.clock()
        local reason = nil
        setStatus("Comprando " .. info.name .. "...", "Buying " .. info.name .. "...")
        while A.On and gen == A.Gen do
            local r = getRemote()
            if not r then reason = "remote" break end
            local dt = RunService.Heartbeat:Wait()
            local got = confirmed() or sent
            if info.price and info.currency then
                local b = balance(info.currency)
                if b and b < info.price then reason = "saldo" break end
            end
            if A.Target > 0 and got >= A.Target then reason = "cantidad" break end
            -- enviar a la velocidad actual (sin pasarse de la cantidad contando los que están en camino)
            budget = math.min(budget + dt * rate, math.max(rate * 0.25, 1))
            while budget >= 1 do
                if A.Target > 0 and got + windowSent >= A.Target then break end
                budget = budget - 1
                A.Firing = true
                pcall(function() r:FireServer(table.unpack(args, 1, args.n)) end)
                A.Firing = false
                sent = sent + 1
                windowSent = windowSent + 1
            end
            -- cada segundo: ¿cuántas aceptó el servidor? acelerar o bajar al ritmo real
            local now = os.clock()
            if now - lastCheck >= 1 then
                local acc = got - lastGot
                if acc > 0 then lastAccept = now end
                if A.Solara then
                    rate = 5 -- sin forma de medir lo aceptado: ritmo fijo
                    lastAccept = now
                elseif windowSent > 0 then
                    if acc >= windowSent * 0.85 then
                        rate = math.min(rate * 1.35, 60)
                    else
                        rate = math.max(acc / (now - lastCheck) * 1.05, 1)
                    end
                end
                lastGot, lastCheck, windowSent = got, now, 0
                setStatus(("Comprando %s · %d compradas · %d/s"):format(info.name, got, math.floor(rate + 0.5)),
                    ("Buying %s · %d bought · %d/s"):format(info.name, got, math.floor(rate + 0.5)))
                if now - lastAccept > 8 then reason = "rechazo" break end
            end
        end
        if gen ~= A.Gen then return end -- otra corrida la reemplazó
        A.Running = false
        local total = confirmed() or sent
        local why = ({
            saldo = { "sin saldo", "out of balance" },
            cantidad = { "cantidad lista", "amount reached" },
            rechazo = { "el servidor dejó de aceptar", "server stopped accepting" },
            remote = { "no se encontró el remote Purchase", "Purchase remote not found" },
        })[reason or ""] or { "detenida", "stopped" }
        setStatus(("%s: %d compradas · %s"):format(info.name, total, why[1]), ("%s: %d bought · %s"):format(info.name, total, why[2]))
        notify(scriptText("Auto compra", "Auto buy"), scriptText(("%d × %s · %s"):format(total, info.name, why[1]), ("%d × %s · %s"):format(total, info.name, why[2])))
    end
    local function start()
        if not A.On then return end
        task.spawn(run)
    end

    -- se escucha la compra que hace el juego (manual) para saber qué objeto repetir
    local function onPurchase(args)
        A.Args = args
        if A.On then start() end -- empieza (o cambia de objeto) apenas comprás a mano
    end
    local function hook()
        if A.Hooked then return true end
        local r = getRemote()
        if not r then return false end
        local function isGame(self, method)
            return not A.Firing and self == r and (method == "FireServer" or method == "fireServer")
                and not (checkcaller and checkcaller())
        end
        if hookmetamethod and getnamecallmethod then
            local old
            local handler = function(self, ...)
                if isGame(self, getnamecallmethod()) then onPurchase(table.pack(...)) end
                return old(self, ...)
            end
            local ok = pcall(function()
                old = hookmetamethod(game, "__namecall", newcclosure and newcclosure(handler) or handler)
            end)
            A.Hooked = ok and old ~= nil
        elseif getrawmetatable and setreadonly and getnamecallmethod then
            local ok = pcall(function()
                local meta = getrawmetatable(game)
                local old = meta.__namecall
                local handler = function(self, ...)
                    if isGame(self, getnamecallmethod()) then onPurchase(table.pack(...)) end
                    return old(self, ...)
                end
                setreadonly(meta, false)
                meta.__namecall = newcclosure and newcclosure(handler) or handler
                setreadonly(meta, true)
            end)
            A.Hooked = ok
        end
        return A.Hooked
    end

    YYSectionHeader(TabExtra, 6.60, "COMPRAS", "PURCHASES")
    YYPlace(TabExtra, 6.61)
    local toggle
    toggle = TabExtra:CreateToggle("Auto compra", "Auto buy", false, function(enabled)
        A.On = enabled
        if not enabled then
            A.Gen = A.Gen + 1 -- corta la corrida actual
            if A.Running then
                A.Running = false
                setStatus("Detenida", "Stopped")
            end
            return
        end
        if not hook() then
            A.On = false
            warn("[Auto compra] No disponible: falta el remote Purchase o hookmetamethod/getrawmetatable en este executor")
            task.defer(function() if toggle and toggle.SetValue then toggle.SetValue(false) end end)
            return
        end
        start()
    end)
    YYSliderNames["Auto Buy Amount"] = "Cantidad (0 = hasta quedarte sin saldo)"
    YYPlace(TabExtra, 6.62)
    TabExtra:CreateSlider("Auto Buy Amount", 0, 1000, 0, function(value)
        A.Target = math.clamp(math.floor(tonumber(value) or 0), 0, 1000)
    end)
    YYPlace(TabExtra, 6.63)
    A.Status = TabExtra:CreateLabel("Activala y comprá 1 vez a mano: repite ese objeto lo más rápido que acepte el servidor.",
        "Turn it on and buy once by hand: it repeats that item as fast as the server accepts.", 11)
    TabExtra:CreateDivider()
end
pcall(setupPurchaseMultiplier)

-- ===== CÁMARA LEJANA + FOV (v47) =====
-- v42 reescribía Player.CameraMaxZoomDistance/CameraMinZoomDistance (método de YY_CamDist_TEST_v1). No funcionó en
-- partida: Evade cambia esas propiedades con tweens en cada cambio de cámara (Character.Client.Camera:Change) y en
-- primera persona (0.5) el método no aplica. Ahora se usa lo que el propio juego usa para mover la cámara
-- (verificado en CameraService): CameraService:SetCameraOffset(nombre, CFrame) se aplica sobre la cámara en cada
-- frame (SetOffsets), sin pelear con Evade. Corre en primera y tercera persona y no atraviesa paredes (se acorta
-- con un rayo hacia atrás). El FOV usa CameraService:AdjustFOV (multiplicador, igual que el sprint del juego).
-- En Solara (require da copias) se vuelve al método de zoom viejo, solo en tercera persona.
function setupCameraDistance()
    local isSolara = false
    pcall(function()
        if identifyexecutor then
            isSolara = string.find(string.lower(tostring(identifyexecutor())), "solara", 1, true) ~= nil
        end
    end)
    local C = { On = false, Extra = 12, Height = 1.5, Fov = false, FovValue = 90, Cur = 0, Conn = nil, CS = nil }
    if not isSolara then
        pcall(function() C.CS = require(ReplicatedStorage.Services.Client.CameraService) end)
    end
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    -- respaldo (Solara): zoom nativo
    local Z = { BaseMax = LocalPlayer.CameraMaxZoomDistance, BaseMin = LocalPlayer.CameraMinZoomDistance, OurMax = nil, OurMin = nil, Writing = false, Modified = false }
    local function zoomApply()
        Z.Writing = true
        pcall(function()
            if C.On and C.Extra > 0 and Z.BaseMax > 0.6 then
                Z.OurMax, Z.OurMin, Z.Modified = Z.BaseMax + C.Extra + 0.0123, Z.BaseMin + C.Extra + 0.0123, true
                LocalPlayer.CameraMaxZoomDistance = Z.OurMax
                LocalPlayer.CameraMinZoomDistance = Z.OurMin
                LocalPlayer.CameraMaxZoomDistance = Z.OurMax
            elseif Z.Modified then
                Z.OurMax, Z.OurMin, Z.Modified = nil, nil, false
                LocalPlayer.CameraMaxZoomDistance = Z.BaseMax
                LocalPlayer.CameraMinZoomDistance = Z.BaseMin
                LocalPlayer.CameraMaxZoomDistance = Z.BaseMax
            end
        end)
        Z.Writing = false
    end
    if not C.CS then
        local function changed()
            if Z.Writing then return end
            local mx, mn = LocalPlayer.CameraMaxZoomDistance, LocalPlayer.CameraMinZoomDistance
            local need = false
            if not (Z.OurMax and math.abs(mx - Z.OurMax) < 0.0005) then Z.BaseMax = mx need = true end
            if not (Z.OurMin and math.abs(mn - Z.OurMin) < 0.0005) then Z.BaseMin = mn need = true end
            if need and (C.On or Z.Modified) then zoomApply() end
        end
        LocalPlayer:GetPropertyChangedSignal("CameraMaxZoomDistance"):Connect(changed)
        LocalPlayer:GetPropertyChangedSignal("CameraMinZoomDistance"):Connect(changed)
    end

    local function step(dt)
        local cs = C.CS
        if not cs then return end
        -- distancia: se acorta si hay pared detrás (rayo desde la cámara sin offset, que guarda el juego)
        local want = C.On and C.Extra or 0
        if want > 0 then
            local base = cs.CameraCFrame
            if typeof(base) == "CFrame" then
                local ex = {}
                if LocalPlayer.Character then ex[#ex + 1] = LocalPlayer.Character end
                local pl = workspace:FindFirstChild("Players")
                if pl then ex[#ex + 1] = pl end
                local rigs = workspace:FindFirstChild("Rigs")
                if rigs then ex[#ex + 1] = rigs end
                rp.FilterDescendantsInstances = ex
                local back = base:VectorToWorldSpace(Vector3.new(0, C.Height * (want / 20), want))
                local hit = workspace:Raycast(base.Position, back + back.Unit * 0.8, rp)
                if hit then want = math.max(0, want * ((hit.Distance - 0.8) / (back.Magnitude + 0.8))) end
            end
        end
        C.Cur = C.Cur + (want - C.Cur) * math.min(1, dt * 10) -- suave, como el zoom de Roblox
        if C.Cur < 0.01 and not C.On then
            cs:SetCameraOffset("YYDistance", nil)
        else
            cs:SetCameraOffset("YYDistance", CFrame.new(0, C.Height * (C.Cur / 20), C.Cur))
        end
        -- FOV
        if C.Fov then
            local baseFov = tonumber(cs.BaseFOV) or 70
            cs:AdjustFOV("YYFov", math.clamp(C.FovValue / math.max(baseFov, 1), 0.3, 3))
        else
            cs:AdjustFOV("YYFov", nil)
        end
    end
    local function ensureLoop()
        if C.Conn or not C.CS then return end
        C.Conn = RunService.RenderStepped:Connect(function(dt)
            local ok = pcall(step, dt)
            if not ok then C.Conn:Disconnect() C.Conn = nil end
            if not C.On and not C.Fov and C.Cur < 0.01 and C.Conn then
                pcall(function() C.CS:SetCameraOffset("YYDistance", nil) C.CS:AdjustFOV("YYFov", nil) end)
                C.Conn:Disconnect()
                C.Conn = nil
            end
        end)
    end

    YYPlace(TabExtra, 5.20)
    TabExtra:CreateFloatingToggle("Cámara lejana", "Far camera", false, function(enabled)
        C.On = enabled
        if C.CS then ensureLoop() else zoomApply() end
    end)
    YYSliderNames["Camera Distance"] = "Distancia cámara"
    YYPlace(TabExtra, 5.22)
    TabExtra:CreateSlider("Camera Distance", 0, 40, 12, function(value)
        C.Extra = math.clamp(tonumber(value) or 0, 0, 40)
        if not C.CS and C.On then zoomApply() end
    end)
    YYPlace(TabExtra, 5.24)
    if C.CS then
        TabExtra:CreateFloatingToggle("FOV", "FOV", false, function(enabled)
            C.Fov = enabled
            ensureLoop()
        end)
        YYSliderNames["Field of View"] = "Campo de visión"
        TabExtra:CreateSlider("Field of View", 50, 120, 90, function(value)
            C.FovValue = math.clamp(tonumber(value) or 90, 50, 120)
        end)
    else
        TabExtra:CreateLabel("FOV: no disponible en Solara", "FOV: not available on Solara", 11)
    end
    TabExtra:CreateDivider()
end
pcall(setupCameraDistance)

-- ===== TABLA DE JUGADORES (v48) =====
-- Se abre con el botón de tabla de la barra de arriba (reemplaza a la tabla de Evade).
-- Datos (verificados): la tabla original de Evade lee de CharacterService:GetCharacterFromPlayer(p).DataRegistry
-- "Level", "Streak", "TimeAlive", "GamePoints", "Downed". Los términos que el juego replica a todos
-- (Shared.Networking.Terms) incluyen "Level", "Streak", "Speed", "State", "Downed", "Carried", "Carrying".
-- La XP y las monedas NO se replican para otros jugadores: solo se pueden mostrar las tuyas (tarjeta "TU CUENTA",
-- de ClientHooks useProgression/useCurrency).
function setupPlayerBoard()
    local GENV = (type(getgenv) == "function" and getgenv()) or _G
    local TweenService = game:GetService("TweenService")
    local B = { Gui = nil, Open = false, Rows = {}, Cache = {}, Sort = "Streak", Expanded = {}, Conn = nil, Hooks = {} }
    local serverState = nil
    local function state(key)
        if not serverState then
            pcall(function() serverState = require(ReplicatedStorage.Services.Data.ServerStateRegistryService) end)
        end
        if not serverState then return nil end
        local ok, v = pcall(function() return serverState:Get(key) end)
        return ok and v or nil
    end
    local function hook(name, fn, ...)
        if B.Hooks[name] == nil then
            local ok, h = pcall(function() return require(ReplicatedStorage.Client.Services.UserData:FindFirstChild((string.gsub(name, "^use", "")))) end)
            B.Hooks[name] = ok and h or false
        end
        local h = B.Hooks[name]
        if not h or type(h[fn]) ~= "function" then return nil end
        local ok, v = pcall(h[fn], ...)
        return ok and v or nil
    end
    local function comma(n)
        n = math.floor(tonumber(n) or 0)
        local s = tostring(math.abs(n)):reverse():gsub("(%d%d%d)", "%1,"):reverse()
        if s:sub(1, 1) == "," then s = s:sub(2) end
        return (n < 0 and "-" or "") .. s
    end
    local function short(n)
        n = tonumber(n) or 0
        if n >= 1e6 then return string.format("%.1fM", n / 1e6) end
        if n >= 1e4 then return string.format("%.1fK", n / 1e3) end
        return comma(n)
    end
    local function clock(secs)
        secs = math.floor(tonumber(secs) or 0)
        if secs >= 3600 then return string.format("%d:%02d:%02d", math.floor(secs / 3600), math.floor((secs % 3600) / 60), secs % 60) end
        return string.format("%d:%02d", math.floor(secs / 60), secs % 60)
    end
    local function truthy(v) return v ~= nil and v ~= false and v ~= 0 and v ~= "" end

    local function readPlayer(plr, cs, myPos, bots)
        local c = B.Cache[plr] or {}
        B.Cache[plr] = c
        local ch = nil
        if cs then
            local ok, v = pcall(function() return cs:GetCharacterFromPlayer(plr) end)
            if ok then ch = v end
        end
        local model = plr.Character
        local alive = model ~= nil and model.Parent ~= nil
        c.status, c.dist, c.speed, c.bot = "dead", nil, nil, nil
        if ch and type(ch) == "table" and ch.DataRegistry then
            local reg = ch.DataRegistry
            local function get(k)
                local ok, v = pcall(function() return reg:Get(k) end)
                return ok and v or nil
            end
            c.level = tonumber(get("Level")) or c.level
            c.streak = tonumber(get("Streak")) or c.streak
            c.time = tonumber(get("TimeAlive")) or c.time
            c.points = tonumber(get("GamePoints")) or c.points
            if alive then
                if truthy(get("Downed")) then c.status = "downed"
                elseif truthy(get("Carried")) then c.status = "carried"
                elseif truthy(get("Carrying")) then c.status = "carrying"
                else c.status = "alive" end
            end
            local part = ch.PrimaryPart
            if part and part.Parent then
                local v = part.AssemblyLinearVelocity
                c.speed = Vector3.new(v.X, 0, v.Z).Magnitude
                if myPos then c.dist = (part.Position - myPos).Magnitude end
                local best = nil
                for _, b in ipairs(bots) do
                    local d = (b - part.Position).Magnitude
                    if not best or d < best then best = d end
                end
                c.bot = best
            end
        elseif alive then
            c.status = "alive"
        end
        return c
    end

    local STATUS = {
        alive = { "VIVO", "ALIVE", Color3.fromRGB(120, 235, 130) },
        downed = { "CAÍDO", "DOWNED", Color3.fromRGB(255, 95, 95) },
        carried = { "LO LLEVAN", "CARRIED", Color3.fromRGB(160, 160, 170) },
        carrying = { "CARGANDO", "CARRYING", Color3.fromRGB(110, 200, 255) },
        dead = { "AFUERA", "OUT", Color3.fromRGB(120, 120, 130) },
    }

    local function build()
        -- la ventana la da la librería (YinYang.Kit.Window); acá solo se dice qué mostrar
        local K = YYKit()
        if not (K and K.Window) then error("la librería UI no tiene el kit de ventanas (actualizala)") end
        local W = K.Window({ Name = "YYPlayerBoard", DisplayOrder = 120, IgnoreGuiInset = true, Width = 380, Height = UDim.new(0.8, 0),
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.52), MinSize = Vector2.new(300, 300), MaxSize = Vector2.new(440, 700),
            Title = scriptText("JUGADORES", "PLAYERS"), TitleSize = 18, Subtitle = "", Info = "", HeaderHeight = 62, Radius = 20,
            OnClose = function() if GENV.YYBoardToggle then GENV.YYBoardToggle(false) end return true end })
        -- TU CUENTA: nivel, XP, dinero (tokens) y puntos
        local account = W:Summary({ UserId = LocalPlayer.UserId, Caption = scriptText("TU CUENTA", "YOUR ACCOUNT"),
            Pills = { { Icon = "rbxassetid://7149239101", Color = Color3.fromRGB(163, 255, 87) }, { Icon = "rbxassetid://4648327306", Color = Color3.fromRGB(255, 255, 255) } } })
        account:SetTitle(scriptText("NIVEL -", "LEVEL -"))
        -- orden
        local sortKeys = { { "Streak", "Racha", "Streak" }, { "Level", "Nivel", "Level" }, { "Time", "Tiempo", "Time" }, { "Dist", "Cerca", "Near" } }
        local defs = {}
        for i, s in ipairs(sortKeys) do
            defs[i] = { Text = scriptText(s[2], s[3]), Width = 0.25, Dim = true, OnClick = function() B.Sort = s[1] B.PaintSort() if B.Refresh then B.Refresh() end end }
        end
        local sortButtons = W:Buttons(defs, { Height = 28, Radius = 14 })
        B.PaintSort = function()
            for i, s in ipairs(sortKeys) do sortButtons[i]:SetOn(B.Sort == s[1]) end
        end
        B.PaintSort()
        local labels = { time = { "Tiempo vivo", "Time alive" }, points = { "Puntos ronda", "Round points" }, speed = { "Velocidad", "Speed" },
            dist = { "Distancia", "Distance" }, state = { "Estado", "State" }, bot = { "Bot cerca", "Nearest bot" } }
        local cells = {}
        for _, key in ipairs({ "time", "points", "speed", "dist", "state", "bot" }) do
            cells[#cells + 1] = { Key = key, Label = scriptText(labels[key][1], labels[key][2]) }
        end
        local people = W:People({ Size = UDim2.new(1, 0, 1, -146), Cells = cells,
            Pill = { Icon = "rbxassetid://13518130183", Color = Color3.fromRGB(255, 217, 78), Bg = Color3.fromRGB(58, 46, 12) } })

        -- fila de un jugador: [foto + nivel] [nombre / @usuario / en vivo] [racha]
        local function makeRow(plr)
            local row = people:Row(plr, { UserId = plr.UserId, Name = plr.DisplayName, Sub = "@" .. plr.Name, Highlight = plr == LocalPlayer })
            return { Frame = row.Frame, Ring = row.Ring, Level = row.Badge, Streak = row.Pill, Live = row.Live, Cells = row.Cells, Row = row }
        end

        local function refreshAccount()
            local level = tonumber(hook("useProgression", "Level")) or 1
            local xp = tonumber(hook("useProgression", "XP")) or 0
            local req = tonumber(hook("useProgression", "RequiredXP", level)) or math.max(level * 100, 1)
            local progress = math.clamp(xp / math.max(req, 1), 0, 1)
            account:SetTitle(scriptText("NIVEL ", "LEVEL ") .. level)
            account:SetProgress(progress, string.format("XP %s / %s  ·  %d%%  ·  %s %s", comma(xp), comma(req), math.floor(progress * 100),
                scriptText("faltan", "need"), comma(math.max(req - xp, 0))))
            account:SetPill(1, short(hook("useCurrency", "Balance", "Tokens") or 0))
            account:SetPill(2, short(hook("useCurrency", "Balance", "Points") or 0))
        end

        local function refresh()
            if not B.Open then return end
            pcall(refreshAccount)
            local cs = FindCharService and FindCharService()
            local myRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            local myPos = myRoot and myRoot.Position
            local bots = {}
            if cs then
                local ok, chars = pcall(function() return cs:GetCharacters() end)
                if ok and type(chars) == "table" then
                    for i = 1, #chars do
                        local v = chars[i]
                        if type(v) == "table" and v.AI == true and v.PrimaryPart then bots[#bots + 1] = v.PrimaryPart.Position end
                    end
                end
            end
            local entries, n = {}, { alive = 0, downed = 0, out = 0 }
            for _, plr in ipairs(Players:GetPlayers()) do
                local c = readPlayer(plr, cs, myPos, bots)
                entries[#entries + 1] = { plr = plr, c = c }
                if c.status == "downed" or c.status == "carried" then n.downed = n.downed + 1
                elseif c.status == "dead" then n.out = n.out + 1
                else n.alive = n.alive + 1 end
            end
            local function key(e)
                local c = e.c
                if B.Sort == "Level" then return c.level or 0 end
                if B.Sort == "Time" then return c.time or 0 end
                if B.Sort == "Dist" then return -(c.dist or 1e9) end
                return c.streak or 0
            end
            table.sort(entries, function(a, b)
                local da, db = a.c.status == "dead", b.c.status == "dead"
                if da ~= db then return db end
                return key(a) > key(b)
            end)
            local seen = {}
            for i, e in ipairs(entries) do
                seen[e.plr] = true
                local r = B.Rows[e.plr] or makeRow(e.plr)
                B.Rows[e.plr] = r
                r.Frame.LayoutOrder = i
                local c, st = e.c, STATUS[e.c.status]
                r.Ring.Color = st[3]
                r.Level.Text = c.level and tostring(c.level) or "-"
                r.Streak.Text = c.streak and short(c.streak) or "-"
                local parts = { string.format('<font color="#%s"><b>%s</b></font>', st[3]:ToHex(), scriptText(st[1], st[2])) }
                if c.dist and e.plr ~= LocalPlayer then parts[#parts + 1] = string.format("%d m", math.floor(c.dist)) end
                if c.speed and c.status ~= "dead" then parts[#parts + 1] = string.format("%d vel", math.floor(c.speed + 0.5)) end
                if c.bot then
                    local col = c.bot < 30 and "ff5a5a" or (c.bot < 70 and "ffc85a" or "78e68c")
                    parts[#parts + 1] = string.format('<font color="#%s">bot %d m</font>', col, math.floor(c.bot))
                end
                r.Live.Text = table.concat(parts, "  ·  ")
                r.Cells.time.Text = c.time and clock(c.time) or "-"
                r.Cells.points.Text = c.points and short(c.points) or "-"
                r.Cells.speed.Text = c.speed and string.format("%d", math.floor(c.speed + 0.5)) or "-"
                r.Cells.dist.Text = (c.dist and e.plr ~= LocalPlayer) and string.format("%d m", math.floor(c.dist)) or "-"
                r.Cells.state.Text = scriptText(st[1], st[2])
                r.Cells.state.TextColor3 = st[3]
                r.Cells.bot.Text = c.bot and string.format("%d m", math.floor(c.bot)) or "-"
                r.Frame.BackgroundTransparency = c.status == "dead" and 0.55 or 0.2
            end
            for plr, r in pairs(B.Rows) do
                if not seen[plr] then r.Row:Remove() B.Rows[plr] = nil B.Cache[plr] = nil end
            end
            local bits = {}
            pcall(function()
                local map = workspace:FindFirstChild("Map")
                local id = map and map:GetAttribute("MapName")
                if id then bits[#bits + 1] = require(ReplicatedStorage.Info.Maps[id]).Name or id end
            end)
            pcall(function()
                local gm = state("Gamemode")
                if gm then bits[#bits + 1] = require(ReplicatedStorage.Info.Gamemodes[gm]).Info.Name or gm end
            end)
            pcall(function()
                local total = state("RoundsPerMap")
                if total then bits[#bits + 1] = scriptText("Ronda ", "Round ") .. math.min(total, (state("RoundsCompleted") or 0) + 1) .. "/" .. total end
            end)
            W:SetSubtitle(#bits > 0 and table.concat(bits, "  ·  ") or scriptText("Sin datos de la partida", "No match data"))
            W:SetInfo(string.format('<font color="#78eb82">%d %s</font>   <font color="#ff5f5f">%d %s</font>   <font color="#8c8c96">%d %s</font>   %d bots',
                n.alive, scriptText("vivos", "alive"), n.downed, scriptText("caídos", "downed"), n.out, scriptText("afuera", "out"), #bots))
        end
        B.Refresh = refresh
        B.Gui, B.Scale = W.Gui, W.Scale
    end

    GENV.YYBoardToggle = function(open)
        if open == nil then open = not B.Open end
        if open then
            if not B.Gui or not B.Gui.Parent then
                B.Rows, B.Gui = {}, nil
                local ok, err = pcall(build)
                if not ok then warn("[Tabla] " .. tostring(err)) return false end
            end
            B.Open = true
            B.Gui.Enabled = true
            B.Scale.Scale = 0.92
            TweenService:Create(B.Scale, TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
            pcall(B.Refresh)
            if not B.Conn then
                local acc = 0
                B.Conn = RunService.Heartbeat:Connect(function(dt)
                    acc = acc + dt
                    if acc >= 0.5 then acc = 0 pcall(B.Refresh) end
                end)
            end
        else
            B.Open = false
            if B.Conn then B.Conn:Disconnect() B.Conn = nil end
            if B.Gui then B.Gui.Enabled = false end
        end
        return true
    end
end
pcall(setupPlayerBoard)

-- ===== DIRECCIÓN CON SENSORES (v42): la usan los Bots visuales y Yin IA =====
-- Prueba 16 direcciones con rayos a la altura de rodilla y de pecho, y elige la que más se acerca a donde
-- se quiere ir sin chocar. Recuerda la dirección anterior para que el giro sea suave (sin zig-zag).
-- Devuelve: dirección elegida (o nil), si adelante hay algo bajo que se puede saltar, y distancia libre adelante.
YYSteerDirs = {}
for i = 0, 15 do
    local a = i / 16 * math.pi * 2
    YYSteerDirs[#YYSteerDirs + 1] = Vector3.new(math.cos(a), 0, math.sin(a))
end
function YYContextSteer(origin, wantDir, params, lookAhead, lastDir, kneeDrop)
    kneeDrop = kneeDrop or 1.6
    local knee = origin - Vector3.new(0, kneeDrop, 0)
    local best, bestScore, lowAhead, freeAhead = nil, -math.huge, false, lookAhead
    for _, d in ipairs(YYSteerDirs) do
        local interest = d:Dot(wantDir)
        if interest > -0.35 then
            local hitChest = workspace:Raycast(origin, d * lookAhead, params)
            local hitKnee = workspace:Raycast(knee, d * lookAhead, params)
            local chestFree = hitChest and (hitChest.Position - origin).Magnitude or lookAhead
            local kneeFree = hitKnee and (hitKnee.Position - knee).Magnitude or lookAhead
            -- una pared casi horizontal (piso/rampa) no cuenta como obstáculo
            if hitKnee and hitKnee.Normal.Y > 0.6 then kneeFree = lookAhead end
            if hitChest and hitChest.Normal.Y > 0.6 then chestFree = lookAhead end
            local free = math.min(chestFree, kneeFree)
            local danger = 1 - free / lookAhead
            -- algo bajo (rodilla choca, pecho libre) se puede saltar: pesa poco
            local jumpable = kneeFree < lookAhead * 0.6 and chestFree >= lookAhead * 0.95
            if jumpable then danger = danger * 0.25 end
            local score = interest * 1.0 - danger * 1.6 + (lastDir and d:Dot(lastDir) * 0.3 or 0)
            if score > bestScore then best, bestScore = d, score end
            if d:Dot(wantDir) > 0.97 then
                freeAhead = free
                lowAhead = jumpable
            end
        end
    end
    return best, lowAhead, freeAhead
end

-- ===== BOTS VISUALES (v42, basado en YY_BotSpawnVisual_TEST_v2) =====
-- Bots de ReplicatedStorage.NPCs que existen SOLO en tu pantalla (el servidor no los ve): sirven para practicar,
-- grabar clips o probar Yin IA (la IA los toma como amenaza). El "daño" es solo efecto visual.
-- Mejoras: persecución con sensores + ruta de Pathfinding cuando se traban, ventana nueva con el estilo del script,
-- controles por bot, contador y registro corto.
function setupBotSpawn()
    local GENV = (type(getgenv) == "function" and getgenv()) or _G
    local B = { Built = false, Gui = nil, Window = nil, Spawned = {}, Conns = {}, Selected = nil, Armed = false,
        AI = true, Anim = true, Sound = true, Damage = false, Kill = false, Scale = 1, Speed = 22, Range = 5,
        Hits = 0, KillHits = 0, ShakeUntil = 0, Log = {}, Refresh = nil, SetInfo = nil, Toggle = nil }
    local Debris = game:GetService("Debris")
    local TweenService = game:GetService("TweenService")
    local PathfindingService = game:GetService("PathfindingService")
    local NPCS = nil
    local container = nil
    local BOTS = {}

    local function log(...)
        local parts = {}
        for i = 1, select("#", ...) do parts[i] = tostring((select(i, ...))) end
        local line = table.concat(parts, " ")
        B.Log[#B.Log + 1] = line
        if #B.Log > 120 then table.remove(B.Log, 1) end
        if B.SetInfo then B.SetInfo(line) end
    end
    local function getTemplate(npc)
        local variants = npc:FindFirstChild("Variants")
        if not variants then return nil end
        local d = variants:FindFirstChild("Default")
        if d and d:IsA("Model") then return d end
        for _, c in ipairs(variants:GetChildren()) do
            if c:IsA("Model") then return c end
        end
        return nil
    end
    local function getHRP()
        local ch = LocalPlayer.Character
        return ch and ch:FindFirstChild("HumanoidRootPart")
    end
    local function rayParams()
        local p = RaycastParams.new()
        p.FilterType = Enum.RaycastFilterType.Exclude
        local ex = { container }
        if LocalPlayer.Character then ex[#ex + 1] = LocalPlayer.Character end
        local pl = workspace:FindFirstChild("Players")
        if pl then ex[#ex + 1] = pl end
        p.FilterDescendantsInstances = ex
        return p
    end
    local function groundPos(pos)
        local hit = workspace:Raycast(pos + Vector3.new(0, 20, 0), Vector3.new(0, -200, 0), rayParams())
        return hit and hit.Position or pos
    end
    local function getRoot(model)
        if model.PrimaryPart then return model.PrimaryPart end
        local r = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("RootPart")
        if r and r:IsA("BasePart") then return r end
        local best, vol = nil, -1
        for _, d in ipairs(model:GetDescendants()) do
            if d:IsA("BasePart") then
                local v = d.Size.X * d.Size.Y * d.Size.Z
                if v > vol then best, vol = d, v end
            end
        end
        return best
    end
    -- el juego guarda los Motor6D en una carpeta "Joints" al cachear el rig: se devuelven a su lugar
    local function restoreJoints(model)
        local joints = model:FindFirstChild("Joints")
        if not joints then return end
        for _, j in ipairs(joints:GetChildren()) do
            if j:IsA("Motor6D") and j.Part0 and j.Part1 and j.Part1:IsDescendantOf(model) then j.Parent = j.Part1 end
        end
        joints:Destroy()
    end
    local function sanitize(model)
        for _, d in ipairs(model:GetDescendants()) do
            if d:IsA("BaseScript") then
                d:Destroy()
            elseif d:IsA("Sound") then
                d.Playing = false
                d.Volume = 0
            elseif d:IsA("BasePart") then
                d.CanCollide, d.CanTouch, d.CanQuery, d.Massless = false, false, false, true
            end
        end
    end
    -- con animación: solo la raíz anclada (un Motor6D no mueve piezas ancladas); sin animación: todo anclado
    local function anchorMode(e, animating)
        local model = e.model
        if not animating then
            for _, d in ipairs(model:GetDescendants()) do
                if d:IsA("BasePart") then d.Anchored = true end
            end
            return
        end
        local root = getRoot(model)
        if not root then return end
        for _, d in ipairs(model:GetDescendants()) do
            if d:IsA("BasePart") then d.Anchored = false end
        end
        root.Anchored = true
        local connected = {}
        local ok, parts = pcall(function() return root:GetConnectedParts(true) end)
        if ok and parts then for _, p in ipairs(parts) do connected[p] = true end end
        for _, d in ipairs(model:GetDescendants()) do
            if d:IsA("BasePart") and d ~= root and not connected[d] then d.Anchored = true end
        end
    end
    local function categorize(name)
        local n = name:lower()
        if n:find("sprint", 1, true) or n:find("run", 1, true) then return "Run" end
        if n:find("walk", 1, true) or n:find("move", 1, true) then return "Walk" end
        if n:find("idle", 1, true) or n == "default" then return "Idle" end
        return nil
    end
    local function stopAnims(e)
        for _, t in pairs(e.anims) do pcall(function() t:Stop(0) end) end
        e.anims, e.track = {}, nil
    end
    local function setupAnim(e)
        stopAnims(e)
        local ctl = e.model:FindFirstChildOfClass("Humanoid") or e.model:FindFirstChildOfClass("AnimationController")
        if not ctl then return false end
        local animator = ctl:FindFirstChildOfClass("Animator") or Instance.new("Animator", ctl)
        local found = {}
        for _, d in ipairs(e.model:GetDescendants()) do
            if d:IsA("Animation") and d.AnimationId ~= "" then
                local cat = categorize(d.Name)
                if cat and not found[cat] then found[cat] = d end
            end
        end
        local any = false
        for cat, anim in pairs(found) do
            local ok, track = pcall(function() return animator:LoadAnimation(anim) end)
            if ok and track then
                track.Looped = true
                e.anims[cat] = track
                any = true
            end
        end
        return any
    end
    local function updateAnim(e, speed)
        if not e.animOn then return end
        local a = e.anims
        local want = speed <= 0.2 and "Idle" or (speed <= 24 and "Walk" or "Run")
        local track = a[want] or (want == "Run" and a.Walk) or (want == "Walk" and (a.Run or a.Idle)) or a.Idle or a.Walk or a.Run
        if not track then return end
        if e.track ~= track then
            if e.track then pcall(function() e.track:Stop(0.3) end) end
            pcall(function() track:Play(0.3) end)
            e.track = track
        end
        if want ~= "Idle" then pcall(function() track:AdjustSpeed(math.clamp(speed / 16, 0.6, 2.5)) end) end
    end
    local function setAnimOn(e, on)
        if on then
            restoreJoints(e.model)
            anchorMode(e, true)
            e.animOn = setupAnim(e)
            if not e.animOn then anchorMode(e, false) else updateAnim(e, 0) end
        else
            stopAnims(e)
            e.animOn = false
            anchorMode(e, false)
        end
    end
    -- sonidos: ids del ModuleScript "Voicelines" de cada bot (Idle en bucle, Attack al alcanzarte)
    local voiceCache = {}
    local function loadVoices(name)
        if voiceCache[name] then return voiceCache[name] end
        local result = { idle = nil, attack = {} }
        local npc = NPCS:FindFirstChild(name)
        local mod = npc and npc:FindFirstChild("Voicelines", true)
        if mod and mod:IsA("ModuleScript") then
            local ok, data = pcall(require, mod)
            if ok and type(data) == "table" then
                if type(data.Idle) == "number" and data.Idle > 0 then result.idle = data.Idle end
                if type(data.Attack) == "table" then
                    for _, id in ipairs(data.Attack) do
                        if type(id) == "number" and id > 0 then result.attack[#result.attack + 1] = id end
                    end
                end
            end
        end
        voiceCache[name] = result
        return result
    end
    local function newSound(parent, id, looped)
        local s = Instance.new("Sound")
        s.SoundId = "rbxassetid://" .. id
        s.Volume = 0.6
        s.Looped = looped
        s.RollOffMaxDistance = 120
        s.Parent = parent
        return s
    end
    local function setupSound(e)
        local voices = loadVoices(e.name)
        local root = e.model.Parent and getRoot(e.model)
        if not root then return end
        e.voices = voices
        if voices.idle then
            e.idleSound = newSound(root, voices.idle, true)
            if B.Sound then e.idleSound:Play() end
        end
    end
    local function playVoice(e)
        local v = e.voices
        if not (B.Sound and v and #v.attack > 0) then return end
        local now = os.clock()
        if now - (e.lastVoice or 0) < 1.3 then return end
        local root = getRoot(e.model)
        if not root then return end
        e.lastVoice = now
        local s = newSound(root, v.attack[math.random(#v.attack)], false)
        s.Ended:Connect(function() s:Destroy() end)
        Debris:AddItem(s, 30)
        s:Play()
    end
    local function applySoundState()
        for _, e in ipairs(B.Spawned) do
            local s = e.idleSound
            if s and s.Parent then if B.Sound then s:Play() else s:Stop() end end
        end
    end

    local function spawnBot(name, cf)
        local npc = NPCS and NPCS:FindFirstChild(name)
        local template = npc and getTemplate(npc)
        if not template then log("Sin modelo:", name) return nil end
        local ok, model = pcall(function() return template:Clone() end)
        if not ok or not model then log("No se pudo clonar", name) return nil end
        model.Name = name
        restoreJoints(model)
        sanitize(model)
        local hum = model:FindFirstChildOfClass("Humanoid")
        if hum then
            pcall(function()
                hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                hum.EvaluateStateMachine = false
                hum.PlatformStand = true
            end)
        end
        model.Parent = container
        local e = { model = model, name = name, ai = B.AI, speed = B.Speed, animOn = false, anims = {}, lastHit = 0,
            footOffset = 0, radius = 2, height = 5, dir = nil, nextSteer = 0, stuckT = 0, lastPos = nil,
            path = nil, pathIdx = 0, nextPath = 0, vel = Vector3.zero }
        anchorMode(e, false)
        if B.Scale ~= 1 and B.Scale > 0 then pcall(function() model:ScaleTo(B.Scale) end) end
        local pos = cf.Position
        pcall(function() model:PivotTo(CFrame.new(pos) * cf.Rotation) end)
        local okBB, bbCF, bbSize = pcall(function() return model:GetBoundingBox() end)
        if okBB and bbCF then
            local bottom = bbCF.Position.Y - bbSize.Y / 2
            pcall(function() model:PivotTo(model:GetPivot() + Vector3.new(0, pos.Y - bottom, 0)) end)
            e.height = bbSize.Y
            e.radius = math.max(bbSize.X, bbSize.Z) / 2
        end
        e.footOffset = model:GetPivot().Position.Y - pos.Y
        B.Spawned[#B.Spawned + 1] = e
        task.spawn(setupSound, e)
        if B.Anim then setAnimOn(e, true) end
        log("Invocado:", name)
        if B.Refresh then B.Refresh() end
        return e
    end
    local function removeEntry(e)
        stopAnims(e)
        pcall(function() e.model:Destroy() end)
        for i, x in ipairs(B.Spawned) do
            if x == e then table.remove(B.Spawned, i) break end
        end
        if B.Refresh then B.Refresh() end
    end
    local function clearAll()
        for _, e in ipairs(B.Spawned) do
            stopAnims(e)
            pcall(function() e.model:Destroy() end)
        end
        table.clear(B.Spawned)
        if B.Refresh then B.Refresh() end
        log("Bots quitados")
    end
    local function spawnInFront(name)
        local hrp, cam = getHRP(), workspace.CurrentCamera
        if not (hrp and cam) then log("No hay personaje") return end
        local look = Vector3.new(cam.CFrame.LookVector.X, 0, cam.CFrame.LookVector.Z)
        look = look.Magnitude > 0.01 and look.Unit or hrp.CFrame.LookVector
        local target = groundPos(hrp.Position + look * 14)
        spawnBot(name, CFrame.lookAt(target, Vector3.new(hrp.Position.X, target.Y, hrp.Position.Z)))
    end
    local function spawnAround(name)
        local hrp = getHRP()
        if not hrp then log("No hay personaje") return end
        local a = math.random() * math.pi * 2
        local target = groundPos(hrp.Position + Vector3.new(math.cos(a), 0, math.sin(a)) * 40)
        spawnBot(name, CFrame.lookAt(target, Vector3.new(hrp.Position.X, target.Y, hrp.Position.Z)))
    end

    -- daño visual: flash rojo + sacudida (y "Matar" experimental: Health = 0 en tu personaje, sin verificar)
    local function onVisualHit(e)
        B.Hits = B.Hits + 1
        B.ShakeUntil = os.clock() + 0.3
        if B.Flash then
            B.Flash.BackgroundTransparency = 0.55
            TweenService:Create(B.Flash, TweenInfo.new(0.5), { BackgroundTransparency = 1 }):Play()
        end
        if B.Refresh then B.Refresh(true) end
        if B.Kill then
            B.KillHits = B.KillHits + 1
            if B.KillHits > 2 then
                B.KillHits = 0
                local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                if hum then pcall(function() hum.Health = 0 end) end
                log("Matar: Health = 0 (experimental)")
            end
        end
    end

    -- persecución: sensores en 16 direcciones; si se traba 1 s, pide una ruta de Pathfinding y la sigue
    local function computePath(e, from, to)
        e.nextPath = os.clock() + 1.5
        task.spawn(function()
            local path = PathfindingService:CreatePath({ AgentRadius = math.clamp(e.radius, 1.5, 6), AgentHeight = math.clamp(e.height, 4, 20), AgentCanJump = false })
            local ok = pcall(function() path:ComputeAsync(from, to) end)
            if ok and path.Status == Enum.PathStatus.Success then
                e.path, e.pathIdx = path:GetWaypoints(), 2
            end
        end)
    end
    local function moveAI(e, dt, hrp)
        local pivot = e.model:GetPivot()
        local p = pivot.Position
        local feet = Vector3.new(p.X, p.Y - e.footOffset, p.Z)
        local target = hrp.Position
        -- siguiendo una ruta: el objetivo es el próximo punto
        if e.path and e.path[e.pathIdx] then
            local wp = e.path[e.pathIdx].Position
            if (Vector3.new(wp.X - feet.X, 0, wp.Z - feet.Z)).Magnitude < 3 then e.pathIdx = e.pathIdx + 1 end
            if e.path[e.pathIdx] then target = e.path[e.pathIdx].Position else e.path = nil end
        end
        local flat = Vector3.new(target.X - p.X, 0, target.Z - p.Z)
        local distToPlayer = Vector3.new(hrp.Position.X - p.X, 0, hrp.Position.Z - p.Z).Magnitude
        local stopDist = 2 + e.radius * 0.5
        local curSpeed, np = 0, p
        local face = flat.Magnitude > 0.01 and flat.Unit or pivot.LookVector
        if distToPlayer > stopDist and e.speed > 0 and flat.Magnitude > 0.01 then
            local want = flat.Unit
            if os.clock() >= e.nextSteer then
                e.nextSteer = os.clock() + 0.08
                local origin = Vector3.new(p.X, feet.Y + math.min(e.height * 0.6, 4), p.Z)
                e.dir = YYContextSteer(origin, want, rayParams(), math.max(6, e.speed * 0.45 + e.radius), e.dir, math.min(e.height * 0.45, 2.5))
            end
            local use = e.dir or want
            local step = math.min(e.speed * dt, distToPlayer - stopDist)
            np = p + use * step
            curSpeed = e.speed
            face = use
            -- atasco: casi no avanza aunque quiere -> ruta
            e.stuckT = ((e.lastPos and (p - e.lastPos).Magnitude < e.speed * dt * 0.3) and (e.stuckT + dt)) or 0
            if e.stuckT > 1 and os.clock() > e.nextPath then computePath(e, feet, hrp.Position) e.stuckT = 0 end
        end
        e.lastPos = p
        -- pegado al suelo
        local hit = workspace:Raycast(Vector3.new(np.X, p.Y + 6, np.Z), Vector3.new(0, -80, 0), rayParams())
        local y = np.Y
        if hit then y = p.Y + (hit.Position.Y + e.footOffset - p.Y) * math.min(1, dt * 15) end
        local newPos = Vector3.new(np.X, y, np.Z)
        e.vel = (newPos - p) / math.max(dt, 1 / 240)
        local look = CFrame.lookAt(newPos, newPos + Vector3.new(face.X, 0, face.Z))
        pcall(function() e.model:PivotTo((CFrame.new(newPos) * pivot.Rotation):Lerp(look, math.min(1, dt * 10))) end)
        updateAnim(e, curSpeed)
        local dy = math.abs(hrp.Position.Y - p.Y)
        if distToPlayer <= B.Range + e.radius and dy <= e.height + 5 then
            playVoice(e)
            if B.Damage and os.clock() - e.lastHit >= 0.6 then
                e.lastHit = os.clock()
                onVisualHit(e)
            end
        end
    end

    local function buildEngine()
        if B.Built then return true end
        NPCS = ReplicatedStorage:FindFirstChild("NPCs")
        if not NPCS then warn("[Bots] No existe ReplicatedStorage.NPCs") return false end
        container = Instance.new("Folder")
        container.Name = "YY_BotSpawnVisual"
        container.Parent = workspace
        for _, npc in ipairs(NPCS:GetChildren()) do
            if getTemplate(npc) then BOTS[#BOTS + 1] = npc.Name end
        end
        table.sort(BOTS, function(a, b) return a:lower() < b:lower() end)
        B.Conns[#B.Conns + 1] = RunService.Heartbeat:Connect(function(dt)
            local hrp = getHRP()
            for i = #B.Spawned, 1, -1 do
                local e = B.Spawned[i]
                if not e.model or not e.model.Parent then
                    stopAnims(e)
                    table.remove(B.Spawned, i)
                    if B.Refresh then B.Refresh() end
                elseif e.ai and hrp then
                    local ok = pcall(moveAI, e, dt, hrp)
                    if not ok then e.ai = false end
                else
                    e.vel = Vector3.zero
                    updateAnim(e, 0)
                end
            end
        end)
        B.Conns[#B.Conns + 1] = RunService.RenderStepped:Connect(function()
            if os.clock() < B.ShakeUntil then
                local cam = workspace.CurrentCamera
                if cam then cam.CFrame = cam.CFrame * CFrame.Angles((math.random() - 0.5) * 0.03, (math.random() - 0.5) * 0.03, (math.random() - 0.5) * 0.02) end
            end
        end)
        B.Conns[#B.Conns + 1] = UserInputService.InputBegan:Connect(function(input, processed)
            if processed or not B.Armed or not B.Selected then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local cam = workspace.CurrentCamera
            if not cam then return end
            local loc = input.UserInputType == Enum.UserInputType.Touch and Vector2.new(input.Position.X, input.Position.Y) or UserInputService:GetMouseLocation()
            local ray = input.UserInputType == Enum.UserInputType.Touch and cam:ScreenPointToRay(loc.X, loc.Y) or cam:ViewportPointToRay(loc.X, loc.Y)
            local hit = workspace:Raycast(ray.Origin, ray.Direction * 2000, rayParams())
            if not hit then return end
            local hrp = getHRP()
            local cf = hrp and CFrame.lookAt(hit.Position, Vector3.new(hrp.Position.X, hit.Position.Y, hrp.Position.Z)) or CFrame.new(hit.Position)
            spawnBot(B.Selected, cf)
        end)
        B.Built = true
        log(#BOTS .. " bots disponibles")
        return true
    end

    -- ---------- ventana ----------
    local function buildWindow()
        -- la ventana la da la librería (YinYang.Kit.Window); acá solo se dice qué mostrar y qué hace cada botón
        local K = YYKit()
        if not (K and K.Window) then error("la librería UI no tiene el kit de ventanas (actualizala)") end
        local W
        W = K.Window({ Name = "YYBotSpawn", DisplayOrder = 95, IgnoreGuiInset = true, Width = 300, Height = 430,
            Position = UDim2.new(1, -320, 0.5, -215), Title = scriptText("BOTS VISUALES", "VISUAL BOTS"), Count = true, Minimize = true,
            Scroll = true, Flash = true, Radius = 16,
            OnClose = function()
                if B.Toggle and B.Toggle.SetValue then B.Toggle.SetValue(false) else W.Gui.Enabled = false end
                return true
            end })
        B.Flash = W.Flash
        B.Window = W.Frame
        -- buscador + lista de bots
        local search = W:Search(scriptText("Buscar bot...", "Search bot..."))
        local grid = W:Grid({ Height = 120 })
        local selLabel = W:Text(scriptText("Elegí un bot", "Pick a bot"))
        local function refreshList()
            local q = search.Text:lower()
            local items = {}
            for _, name in ipairs(BOTS) do
                if q == "" or name:lower():find(q, 1, true) then items[#items + 1] = { Key = name, Text = name } end
            end
            grid:Set(items, B.Selected, function(name)
                B.Selected = name
                selLabel.Text = scriptText("Elegido: ", "Picked: ") .. name
                refreshList()
            end)
        end
        search:GetPropertyChangedSignal("Text"):Connect(refreshList)
        local function needSel()
            if not B.Selected then selLabel.Text = scriptText("Primero elegí un bot", "Pick a bot first") return false end
            return true
        end
        W:Section(scriptText("INVOCAR", "SPAWN"))
        local clickBtn
        clickBtn = W:Buttons({
            { Text = scriptText("Al frente", "In front"), Width = 1 / 3, Accent = true, OnClick = function() if needSel() then spawnInFront(B.Selected) end end },
            { Text = scriptText("Alrededor", "Around"), Width = 1 / 3, OnClick = function() if needSel() then spawnAround(B.Selected) end end },
            { Text = scriptText("Clic: no", "Click: off"), Width = 1 / 3, OnClick = function()
                B.Armed = not B.Armed
                clickBtn[3]:SetText(B.Armed and scriptText("Clic: sí", "Click: on") or scriptText("Clic: no", "Click: off"))
                clickBtn[3]:SetOn(B.Armed)
            end },
        })
        -- opciones (encendido/apagado)
        W:Section(scriptText("OPCIONES", "OPTIONS"))
        local function toggles(defs)
            local row
            local list = {}
            for i, d in ipairs(defs) do
                list[i] = { Text = scriptText(d[1], d[2]), Width = 1 / 3, Dim = d[3] ~= nil, OnClick = function()
                    if d.Click then d.Click() return end
                    B[d[3]] = not B[d[3]]
                    row[i]:SetOn(B[d[3]] == true)
                    if d.After then d.After() end
                end }
            end
            row = W:Buttons(list)
            for i, d in ipairs(defs) do if d[3] then row[i]:SetOn(B[d[3]] == true) end end
            return row
        end
        toggles({ { "Persigue", "Chase", "AI" }, { "Anima", "Animate", "Anim" }, { "Sonido", "Sound", "Sound", After = applySoundState } })
        local r3
        r3 = toggles({ { "Daño visual", "Visual hit", "Damage" },
            { "Matar (exp.)", "Kill (exp.)", "Kill", After = function()
                B.KillHits = 0
                if B.Kill and not B.Damage then B.Damage = true r3[1]:SetOn(true) end
            end },
            { "Quitar todo", "Clear all", nil, Click = clearAll } })
        -- valores con - / +
        local function stepper(es, en, key, step, minV, maxV, fmt)
            local st
            local function paint() st:SetValue(string.format(fmt or "%d", B[key])) end
            st = W:Stepper(scriptText(es, en),
                function() B[key] = math.clamp(B[key] - step, minV, maxV) paint() end,
                function() B[key] = math.clamp(B[key] + step, minV, maxV) paint() end)
            paint()
        end
        stepper("Velocidad", "Speed", "Speed", 4, 0, 200)
        stepper("Escala", "Scale", "Scale", 0.25, 0.25, 6, "%.2f")
        stepper("Alcance", "Reach", "Range", 1, 1, 40)
        -- invocados
        W:Section(scriptText("EN PANTALLA", "ON SCREEN"))
        local inv = W:List()
        local info = W:Text("", { Dim = true, Wrap = true, Height = 30, Size = 11 })
        B.SetInfo = function(line) info.Text = line end
        B.Refresh = function(onlyCount)
            W:SetCount(tostring(#B.Spawned))
            if onlyCount then
                info.Text = scriptText("Golpes visuales: ", "Visual hits: ") .. B.Hits
                return
            end
            inv:Clear()
            for i, e in ipairs(B.Spawned) do
                local ai, an
                local buttons = inv:Add(e.name, {
                    { Text = "X", Width = 26, OnClick = function() removeEntry(e) end },
                    { Text = "", Width = 54, OnClick = function() e.ai = not e.ai ai:SetText(e.ai and scriptText("Sigue", "Chase") or scriptText("Quieto", "Still")) ai:SetOn(e.ai) end },
                    { Text = "", Width = 46, OnClick = function() setAnimOn(e, not e.animOn) an:SetText(e.animOn and "Anim" or scriptText("Fijo", "Static")) end },
                }, i)
                ai, an = buttons[2], buttons[3]
                ai:SetText(e.ai and scriptText("Sigue", "Chase") or scriptText("Quieto", "Still"))
                ai:SetOn(e.ai)
                an:SetText(e.animOn and "Anim" or scriptText("Fijo", "Static"))
            end
        end
        refreshList()
        B.Refresh()
        B.SetInfo(scriptText(#BOTS .. " bots disponibles · solo visibles para vos", #BOTS .. " bots available · only visible to you"))
        B.Gui = W.Gui
    end

    -- API para Yin IA y la consola (bots visuales como amenaza de práctica)
    GENV.YY_BotSpawn = {
        Spawn = function(name, cf)
            if not buildEngine() then return nil end
            local hrp = getHRP()
            return spawnBot(name, cf or (hrp and CFrame.new(groundPos(hrp.Position + hrp.CFrame.LookVector * 14))) or CFrame.new())
        end,
        List = function() buildEngine() return BOTS end,
        Entries = function() return B.Spawned end,
        Clear = clearAll,
        Log = B.Log,
    }

    YYPlace(TabExtra, 6.45)
    B.Toggle = TabExtra:CreateFloatingToggle("Bots visuales", "Visual bots", false, function(enabled)
        if enabled then
            if not buildEngine() then
                task.defer(function() if B.Toggle and B.Toggle.SetValue then B.Toggle.SetValue(false) end end)
                return
            end
            if not B.Gui then
                local ok, err = pcall(buildWindow)
                if not ok then warn("[Bots] ventana: " .. tostring(err)) return end
            end
            B.Gui.Enabled = true
        elseif B.Gui then
            B.Gui.Enabled = false -- los bots siguen en pantalla; se quitan con "Quitar todo"
        end
    end)
end
pcall(setupBotSpawn)

-- ===== YIN IA (v43): juega sola mientras estás AFK =====
-- Cómo se mueve (verificado en el código de Evade):
--   * "MoveDirection" sale de PlayerModule.ControlModule:GetMoveVector() y se pasa al mundo con "LookCFrame" =
--     CameraService:GetCFrame(). La IA reemplaza SOLO ese GetMoveVector mientras está activa: Evade mueve al
--     personaje con su propia física (aceleración, sprint, slide, trimp, animaciones), como si apretaras las teclas.
--   * La cámara de Evade NO lee workspace.CurrentCamera: BaseCamera.GetCameraLookVector usa CameraService:GetCFrame()
--     (CameraService.CameraCFrame). Por eso en v42 la cámara "se trababa": se giraba la cámara de Roblox y el juego la
--     pisaba en el frame siguiente. Ahora se gira CameraService.CameraCFrame (y la cámara visible) y el giro queda.
--   * En el aire Evade ignora "adelante" y solo usa el costado (MoveDirection.X): la IA mantiene la tecla hacia donde
--     quiere ir y gira la cámara, que es el air-strafe real. (v42 empujaba de costado aunque estuviera en el piso si
--     no detectaba el suelo: eso la hacía girar en círculos.)
--   * Piso: atributo "Grounded" del personaje (lo usa el propio juego), si no DataRegistry, si no un rayo.
--   * Salta con Movement:AttemptJump(). Revive con Events.Interact "Revive" (igual que Aura revivir). Bots = AI == true.
-- Cerebro: huir > revivir > imitar a un jugador (opcional) > explorar. Sensores con ancho de personaje (Spherecast),
-- detector de vueltas en círculo y rutas con Pathfinding suavizadas. (v45: sin toggles extra: todo activo; sin registro.)
function setupYinIA()
    local isSolara = false
    pcall(function()
        if identifyexecutor then
            isSolara = string.find(string.lower(tostring(identifyexecutor())), "solara", 1, true) ~= nil
        end
    end)
    local GENV = (type(getgenv) == "function" and getgenv()) or _G
    local PathfindingService = game:GetService("PathfindingService")
    local TweenService = game:GetService("TweenService")
    local IA = {
        On = false, Paused = false, Cam = true, Revive = true, Tricks = true, Practice = true, ShowPath = false,
        Follow = true, FollowDelay = 4, FollowKey = nil, FollowName = "", Trail = {}, FollowSince = 0,
        Danger = 42, ReviveRange = 120,
        Mode = "idle", Detail = "", Target = nil, TargetKind = nil, Path = nil, PathIdx = 2, PathFor = nil, Planning = false,
        PathFails = 0, PathProgressT = 0, LastReplan = 0, BadSpots = {}, Boost = 1.35, Boosting = false, BoostUntil = 0, SavedSpeed = nil,
        Heading = nil, SteerDir = nil, NextSteer = 0, LowAhead = false, FreeAhead = 99, MoveWorld = nil,
        WantJump = false, LastJump = 0, Movement = nil, MoveHooked = false, CtlHooked = false, OrigGetMove = nil,
        CameraService = nil, ManualUntil = 0, Visited = {}, BotHist = {}, Threats = {}, Nearest = nil, NearestDist = math.huge,
        StuckT = 0, UnstickUntil = 0, UnstickDir = nil, LastFleePlan = 0, ExploreSince = 0, ReviveBusy = false,
        CamBlocked = false, CamWin = nil, Hud = nil, PathFolder = nil, Toggle = nil, Speed = 0, Grounded = true,
        Turn = {}, Log = nil,
    }
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    local function refreshFilter()
        local ex = {}
        if LocalPlayer.Character then ex[#ex + 1] = LocalPlayer.Character end
        local pl = workspace:FindFirstChild("Players")
        if pl then ex[#ex + 1] = pl end
        local rigs = workspace:FindFirstChild("Rigs")
        if rigs then ex[#ex + 1] = rigs end
        local vb = workspace:FindFirstChild("YY_BotSpawnVisual")
        if vb then ex[#ex + 1] = vb end
        if IA.PathFolder then ex[#ex + 1] = IA.PathFolder end
        rp.FilterDescendantsInstances = ex
    end
    local function flat(v) return Vector3.new(v.X, 0, v.Z) end
    local function myParts()
        local char = LocalPlayer.Character
        return char, char and char:FindFirstChild("HumanoidRootPart"), char and char:FindFirstChildOfClass("Humanoid")
    end
    local function registry(key)
        local m = IA.Movement
        if not m or not m.DataRegistry then return nil end
        local ok, v = pcall(function() return m.DataRegistry:Get(key) end)
        return ok and v or nil
    end
    local function truthy(v) return v ~= nil and v ~= false and v ~= 0 end
    local function cellKey(pos) return math.floor(pos.X / 32) .. ":" .. math.floor(pos.Z / 32) end
    local function log(text)
        if IA.Log then IA.Log(text) end
    end

    -- ---------- sensores con ancho de personaje ----------
    local sphereOk = nil
    local function castWide(origin, dir, len, radius)
        if sphereOk ~= false then
            local ok, res = pcall(function() return workspace:Spherecast(origin, radius, dir * len, rp) end)
            if ok then
                sphereOk = true
                return res and res.Distance or nil, res
            end
            sphereOk = false
        end
        -- sin Spherecast: 3 rayos (centro y bordes del cuerpo)
        local side = Vector3.new(-dir.Z, 0, dir.X) * radius
        local bestD, bestR = nil, nil
        for _, o in ipairs({ origin, origin + side, origin - side }) do
            local r = workspace:Raycast(o, dir * len, rp)
            if r and (not bestD or r.Distance < bestD) then bestD, bestR = r.Distance, r end
        end
        return bestD, bestR
    end
    local DIRS = {}
    for i = 0, 23 do
        local a = i / 24 * math.pi * 2
        DIRS[#DIRS + 1] = Vector3.new(math.cos(a), 0, math.sin(a))
    end
    local function steer(origin, want, len, lastDir)
        local knee = origin - Vector3.new(0, 1.5, 0)
        local best, bestScore, lowAhead, freeAhead = nil, -math.huge, false, len
        for _, d in ipairs(DIRS) do
            local interest = d:Dot(want)
            if interest > -0.4 then
                local dc, rc = castWide(origin, d, len, 1.25)
                local dk, rk = castWide(knee, d, len, 1.1)
                -- piso o rampa (normal hacia arriba) no es obstáculo
                if rc and rc.Normal.Y > 0.6 then dc = nil end
                if rk and rk.Normal.Y > 0.6 then dk = nil end
                local chestFree, kneeFree = dc or len, dk or len
                local free = math.min(chestFree, kneeFree)
                local jumpable = kneeFree < len * 0.7 and chestFree >= len * 0.95
                local danger = 1 - free / len
                if jumpable then danger = danger * 0.3 end
                if free < 2.2 and not jumpable then danger = 2 end -- pegado a una pared: nunca hacia ahí
                -- v47: piso adelante (no correr hacia un vacío o una caída grande)
                local probe = origin + d * math.min(free, 7)
                if not workspace:Raycast(probe, Vector3.new(0, -22, 0), rp) then danger = math.max(danger, 1.6) end
                local score = interest - danger * 1.7 + (lastDir and d:Dot(lastDir) * 0.25 or 0)
                if score > bestScore then best, bestScore = d, score end
                if interest > 0.98 then freeAhead, lowAhead = free, jumpable end
            end
        end
        return best, lowAhead, freeAhead
    end

    -- ---------- hooks: entrada (GetMoveVector) y Movement (salto) ----------
    local function hookControl()
        if IA.CtlHooked then return true end
        local ok, ctl = pcall(function()
            return require(LocalPlayer:WaitForChild("PlayerScripts"):WaitForChild("PlayerModule"):WaitForChild("ControlModule"))
        end)
        if not ok or type(ctl) ~= "table" or type(ctl.GetMoveVector) ~= "function" then return false end
        pcall(function() IA.CameraService = require(ReplicatedStorage.Services.Client.CameraService) end)
        pcall(function() IA.Interaction = require(ReplicatedStorage.Services.Asset.InteractionService) end)
        IA.OrigGetMove = ctl.GetMoveVector
        local okSet = pcall(function()
            ctl.GetMoveVector = function(self, ...)
                local real = IA.OrigGetMove(self, ...)
                if not IA.On or IA.Paused or not IA.MoveWorld then return real end
                if typeof(real) == "Vector3" and real.Magnitude > 0.1 then
                    IA.ManualUntil = os.clock() + 1.5 -- tocaste las teclas: control manual
                end
                if os.clock() < IA.ManualUntil then return real end
                local look = (IA.CameraService and IA.CameraService:GetCFrame()) or workspace.CurrentCamera.CFrame
                return look:VectorToObjectSpace(IA.MoveWorld)
            end
        end)
        IA.CtlHooked = okSet
        return okSet
    end
    local function jumpStep(self)
        if not IA.On or IA.Paused or os.clock() < IA.ManualUntil then
            if IA.SwimHeld then self.JumpHeldDown = false IA.SwimHeld = false end
            return
        end
        -- v48: nadar. Verificado: en el agua (término "Swimming") la función Run sube cuando JumpingActive está activo,
        -- y JumpingActive sale de Movement.JumpHeldDown. Se mantiene apretado mientras nada (sale a la superficie y
        -- trepa los bordes); al salir del agua se suelta.
        local okS, swimming = pcall(function() return self.DataRegistry:Get("Swimming") end)
        if okS and swimming then
            self.JumpHeldDown = true
            IA.SwimHeld = true
        elseif IA.SwimHeld then
            self.JumpHeldDown = false
            IA.SwimHeld = false
        end
        if IA.WantJump and os.clock() - IA.LastJump > 0.25 then
            IA.WantJump = false
            IA.LastJump = os.clock()
            self:AttemptJump()
        end
    end
    local function hookMovement()
        if IA.MoveHooked then return true end
        local ok, Movement = pcall(function() return require(ReplicatedStorage.Objects.Game.Character.Client.Movement) end)
        if not ok or type(Movement) ~= "table" or type(Movement.Update) ~= "function" then return false end
        local old = Movement.Update
        Movement.Update = function(self, ...)
            old(self, ...)
            if self.Character and self.Character == LocalPlayer.Character then
                IA.Movement = self
                if IA.On then pcall(jumpStep, self) end
            end
        end
        IA.MoveHooked = true
        return true
    end
    local function isGrounded(root)
        local char = LocalPlayer.Character
        local attr = char and char:GetAttribute("Grounded")
        if attr ~= nil then return attr == true end
        local reg = registry("Grounded")
        if reg ~= nil then return truthy(reg) end
        return workspace:Raycast(root.Position, Vector3.new(0, -4, 0), rp) ~= nil
    end

    -- ---------- percepción ----------
    local function scan(root)
        local now = os.clock()
        local threats, downed, mates = {}, {}, {}
        local cs = FindCharService and FindCharService()
        if cs then
            local ok, chars = pcall(function() return cs:GetCharacters() end)
            if ok and type(chars) == "table" then
                for i = 1, #chars do
                    local v = chars[i]
                    if type(v) == "table" and v.Done and v.PrimaryPart and v.PrimaryPart.Parent then
                        local name = (v.Model and v.Model.Name) or "?"
                        if v.AI == true then
                            threats[#threats + 1] = { key = v, pos = v.PrimaryPart.Position, name = name }
                        elseif not v.Local then
                            local okS, state = pcall(function() return v.State and v.State.State end)
                            if okS and state == "Downed" and v.Tag then
                                downed[#downed + 1] = { key = v, pos = v.PrimaryPart.Position, tag = v.Tag, name = name }
                            elseif okS and state ~= "Downed" and state ~= "Carried" then
                                mates[#mates + 1] = { key = v, pos = v.PrimaryPart.Position, name = name,
                                    vy = v.PrimaryPart.AssemblyLinearVelocity.Y }
                            end
                        end
                    end
                end
            end
        end
        if IA.Practice and GENV.YY_BotSpawn and GENV.YY_BotSpawn.Entries then
            local ok, list = pcall(GENV.YY_BotSpawn.Entries)
            if ok and type(list) == "table" then
                for _, e in ipairs(list) do
                    if e.ai and e.model and e.model.Parent then
                        threats[#threats + 1] = { key = e, pos = e.model:GetPivot().Position, name = e.name }
                    end
                end
            end
        end
        local seen = {}
        IA.Nearest, IA.NearestDist = nil, math.huge
        for _, t in ipairs(threats) do
            seen[t.key] = true
            local h = IA.BotHist[t.key]
            if h and now - h.t > 0.02 then
                local vel = (t.pos - h.pos) / (now - h.t)
                h.vel = h.vel and h.vel:Lerp(vel, 0.5) or vel
                h.pos, h.t = t.pos, now
            elseif not h then
                h = { pos = t.pos, t = now, vel = Vector3.zero }
                IA.BotHist[t.key] = h
            end
            t.vel = flat(h.vel or Vector3.zero)
            if t.vel.Magnitude > 160 then t.vel = Vector3.zero end
            t.pred = t.pos + t.vel * 0.7
            local dNow = flat(t.pos - root.Position).Magnitude
            t.dist = math.min(flat(t.pred - root.Position).Magnitude, dNow)
            local toMe = flat(root.Position - t.pos)
            local closing = toMe.Magnitude > 0.1 and t.vel:Dot(toMe.Unit) or 0
            t.tti = closing > 1 and dNow / closing or math.huge
            if t.dist < IA.NearestDist then IA.Nearest, IA.NearestDist = t, t.dist end
        end
        for k in pairs(IA.BotHist) do if not seen[k] then IA.BotHist[k] = nil end end
        IA.Threats = threats
        return threats, downed, mates
    end
    local function groundAt(pos)
        local hit = workspace:Raycast(pos + Vector3.new(0, 40, 0), Vector3.new(0, -160, 0), rp)
        if hit and hit.Normal.Y > 0.6 then
            local head = workspace:Raycast(hit.Position + Vector3.new(0, 0.5, 0), Vector3.new(0, 6, 0), rp)
            if not head then return hit.Position end
        end
        return nil
    end
    local function openness(pos)
        local origin = pos + Vector3.new(0, 3, 0)
        local open = 0
        for i = 0, 7 do
            local a = i / 8 * math.pi * 2
            if not workspace:Raycast(origin, Vector3.new(math.cos(a), 0, math.sin(a)) * 16, rp) then open = open + 1 end
        end
        return open
    end
    local function minThreatDist(pos)
        local m = math.huge
        for _, t in ipairs(IA.Threats) do
            m = math.min(m, flat(t.pred - pos).Magnitude, flat(t.pos - pos).Magnitude)
        end
        return m
    end

    -- ---------- destinos ----------
    local function pickFlee(root)
        local away = Vector3.zero
        for _, t in ipairs(IA.Threats) do
            local v = flat(root.Position - t.pred)
            local d = math.max(v.Magnitude, 1)
            if d < IA.Danger * 2 then away = away + v.Unit * (IA.Danger * 2 - d) end
        end
        away = away.Magnitude > 0.01 and away.Unit or flat(root.CFrame.LookVector).Unit
        local cands = {}
        for i = 0, 15 do
            local a = i / 16 * math.pi * 2
            local d = Vector3.new(math.cos(a), 0, math.sin(a))
            for _, dist in ipairs({ 32, 60 }) do
                local g = groundAt(root.Position + d * dist)
                if g and g.Y > root.Position.Y - 22 and (IA.BadSpots[cellKey(g)] or 0) < os.clock() then
                    local blocked = workspace:Raycast(root.Position, (g + Vector3.new(0, 3, 0)) - root.Position, rp) ~= nil
                    cands[#cands + 1] = { pos = g, score = minThreatDist(g) + d:Dot(away) * 22 - (blocked and 18 or 0) + dist * 0.1 }
                end
            end
        end
        table.sort(cands, function(a, b) return a.score > b.score end)
        local best = nil
        for i = 1, math.min(6, #cands) do
            local c = cands[i]
            c.score = c.score + openness(c.pos) * 5
            if not best or c.score > best.score then best = c end
        end
        return best and best.pos or nil
    end
    local function pickExplore(root, mates)
        local now = os.clock()
        IA.Visited[cellKey(root.Position)] = now
        local best, bestScore = nil, -math.huge
        for _ = 1, 18 do
            local a = math.random() * math.pi * 2
            local dist = 40 + math.random() * 110
            local g = groundAt(root.Position + Vector3.new(math.cos(a), 0, math.sin(a)) * dist)
            if g and math.abs(g.Y - root.Position.Y) < 40 then
                local seenAt = IA.Visited[cellKey(g)]
                local novelty = seenAt and math.clamp((now - seenAt) / 60, 0, 1) * 30 or 40
                local safety = math.min(minThreatDist(g), 150) * 0.3
                local group = 0
                for _, m in ipairs(mates) do
                    if flat(m.pos - g).Magnitude < 60 then group = group + 4 end
                end
                local score = novelty + safety + math.min(group, 12) + math.random() * 6
                if score > bestScore then best, bestScore = g, score end
            end
        end
        return best
    end
    local function planPath(root, goal)
        if IA.Planning then return end
        IA.Planning = true
        local from = root.Position
        task.spawn(function()
            local path = PathfindingService:CreatePath({ AgentRadius = 2.2, AgentHeight = 5.5, AgentCanJump = true, WaypointSpacing = 6 })
            local ok = pcall(function() path:ComputeAsync(from, goal) end)
            if IA.Target == goal then
                local wps = (ok and path.Status == Enum.PathStatus.Success) and path:GetWaypoints() or nil
                -- v47: un camino que pasa al lado de un bot no sirve (se marca el lugar y se elige otro)
                local unsafe = false
                if wps and IA.TargetKind ~= "revivestand" then
                    local hard = IA.Danger * 0.5
                    for i = 2, #wps, 2 do
                        for _, t in ipairs(IA.Threats) do
                            if (wps[i].Position - t.pred).Magnitude < hard or (wps[i].Position - t.pos).Magnitude < hard then unsafe = true break end
                        end
                        if unsafe then break end
                    end
                end
                if unsafe then
                    IA.BadSpots[cellKey(goal)] = os.clock() + 6
                    IA.Path, IA.PathFor = nil, goal
                    IA.PathFails = IA.PathFails + 1
                    if IA.TargetKind == "flee" then IA.LastFleePlan = 0 end
                elseif wps then
                    IA.Path, IA.PathIdx, IA.PathFor, IA.PathFails, IA.PathProgressT = wps, 2, goal, 0, os.clock()
                    log(("ruta OK: %d puntos"):format(#IA.Path))
                else
                    IA.Path, IA.PathFor = nil, goal
                    IA.PathFails = IA.PathFails + 1
                    log("sin ruta (" .. tostring(path.Status) .. "): va directo con sensores")
                end
            end
            IA.Planning = false
        end)
    end
    local function setTarget(pos, kind, noPath)
        if not pos then return end
        IA.Target, IA.TargetKind = pos, kind
        IA.Path, IA.PathFor = nil, nil
        local _, root = myParts()
        if root and not noPath then planPath(root, pos) end
    end

    -- ---------- revivir ----------
    -- v48: revivir igual que cuando lo hacés a mano. Verificado en InteractionService: apretar "Interact" con el caído
    -- como interacción activa arranca el revivir (StartActivate) y el propio servicio lo termina solo al pasar
    -- "ReviveLength". Ese largo sale del DataRegistry de QUIEN REVIVE (antes se leía del caído: si no existía usaba
    -- 1.5 s y el final se mandaba antes de tiempo, por eso fallaba). Si la interacción no aparece, queda el remote.
    local function interactActive(kind, tag)
        local IS = IA.Interaction
        local a = IS and IS.Active
        if not a or a.Type ~= kind or not a.Asset then return false, a end
        if tag ~= nil and a.Asset:GetAttribute("Tag") ~= tag then return false, a end
        return true, a
    end
    local function pressInteract(down)
        local IS = IA.Interaction
        if not IS then return false end
        return pcall(function() IS:KeyUsed({ Keybind = "Interact", Key = "Interact", Down = down }) end)
    end
    local function isDowned(d)
        local ok, st = pcall(function() return d.key.State.State end)
        return ok and st == "Downed"
    end
    local function tryRevive(d)
        if IA.ReviveBusy then return end
        IA.ReviveBusy = true
        log("reviviendo a " .. d.name)
        task.spawn(function()
            local length = tonumber(registry("ReviveLength")) or 1.5
            for attempt = 1, 4 do
                if not IA.On or IA.ReviveAbort or not isDowned(d) then break end
                -- esperar a que el juego tenga a ese caído como interacción activa (rango 8 studs)
                local matched = false
                local t0 = os.clock()
                while os.clock() - t0 < 1.2 do
                    if interactActive("Revive", d.tag) then matched = true break end
                    task.wait(0.05)
                end
                local interact = (not matched) and GetInteractRemote and GetInteractRemote() or nil
                if matched then
                    pressInteract(true)
                elseif interact then
                    pcall(function() interact:FireServer("Revive", d.tag, true) end)
                end
                local t1 = os.clock()
                while os.clock() - t1 < length + 0.35 do
                    if not IA.On or IA.ReviveAbort or not isDowned(d) then break end
                    task.wait(0.05)
                end
                if interact and isDowned(d) and not IA.ReviveAbort then
                    pcall(function() interact:FireServer("Revive", d.tag) end)
                end
                task.wait(0.3)
                if not isDowned(d) then log("revivido: " .. d.name) break end
                if IA.ReviveAbort then log("revivir cortado: bot muy cerca") break end
                log("sigue caído, reintento " .. attempt)
            end
            IA.ReviveBusy = false
        end)
    end

    -- ---------- puertas y escaleras (v48) ----------
    -- Puertas: son interacciones "Interact" (Map.Parts.Interactables). Si una puerta cerrada tapa el paso y el juego
    -- la tiene como interacción activa, se aprieta "Interact" una vez (lo mismo que hacés vos con la E / el botón).
    local function tryDoor(pos)
        if not IA.Interaction or os.clock() - (IA.LastDoor or 0) < 1.5 then return false end
        local ok, a = interactActive("Interact")
        if not ok or not a.Asset.PrimaryPart then return false end
        local to = flat(a.Asset.PrimaryPart.Position - pos)
        if to.Magnitude > 12 or (IA.Heading and to.Magnitude > 0.5 and to.Unit:Dot(IA.Heading) < 0.1) then return false end
        IA.LastDoor = os.clock()
        pressInteract(true)
        task.delay(0.1, function() pressInteract(false) end)
        log("abriendo puerta")
        return true
    end
    -- Escaleras: Map.Parts.Ladders. Verificado en Movement: Movement:Climb(escalera) empieza a trepar (lo mismo que
    -- hace la interacción "Climb"); arriba/abajo se controla con "adelante/atrás" (MoveDirection.Z) y el juego la
    -- invierte si la cámara mira para el otro lado; al llegar arriba o abajo suelta sola (ManualEndClimb).
    local function ladders()
        local map = workspace:FindFirstChild("Map")
        local parts = map and map:FindFirstChild("Parts")
        local folder = parts and parts:FindFirstChild("Ladders")
        return folder and folder:GetChildren() or {}
    end
    local function ladderInfo(model)
        local pp = model:IsA("Model") and model.PrimaryPart or nil
        if not pp then return nil end
        local center = pp:FindFirstChild("Center")
        local c = center and center.WorldPosition or pp.Position
        return { model = model, part = pp, bottom = pp.Position.Y - pp.Size.Y / 2, top = pp.Position.Y + pp.Size.Y / 2, center = c }
    end
    local function pickLadder(from, to)
        local up = to.Y > from.Y
        local best, bestCost = nil, math.huge
        local feet = from.Y - 3
        for _, m in ipairs(ladders()) do
            local L = ladderInfo(m)
            if L and (IA.BadLadder or {})[m] == nil then
                local ok
                if up then ok = math.abs(L.bottom - feet) < 8 and L.top >= to.Y - 9
                else ok = math.abs(L.top - feet) < 8 and L.bottom <= to.Y + 9 end
                local near = flat(L.center - from).Magnitude
                if ok and near < 150 then
                    local cost = near + flat(to - L.center).Magnitude
                    if cost < bestCost then best, bestCost = L, cost end
                end
            end
        end
        return best, up
    end
    local function climbingLadder()
        local v = registry("Climbing")
        if typeof(v) == "Instance" then return v end
        return nil
    end

    -- ---------- imitar a un jugador: sigue su mismo recorrido con retraso ----------
    local function displayName(name)
        local plr = Players:FindFirstChild(name)
        return plr and plr.DisplayName or name
    end
    local followSkip = {}
    local function pickFollow(mates, root)
        local options = {}
        local now = os.clock()
        for _, m in ipairs(mates) do
            if minThreatDist(m.pos) > IA.Danger and (followSkip[m.key] or 0) < now then options[#options + 1] = m end
        end
        if #options == 0 then options = mates end
        if #options == 0 then return nil end
        local m = options[math.random(#options)]
        IA.FollowKey, IA.FollowName, IA.Trail, IA.FollowSince = m.key, displayName(m.name), {}, os.clock()
        log("imitando a " .. IA.FollowName)
        return m
    end
    local function followStep(root, mates, now)
        local current = nil
        for _, m in ipairs(mates) do
            if m.key == IA.FollowKey then current = m break end
        end
        -- v45: si el jugador desaparece un momento de la lista, se espera 3 s antes de cambiar (antes saltaba a otro al azar)
        if not current and IA.FollowKey then
            IA.FollowMissing = IA.FollowMissing or now
            if now - IA.FollowMissing > 3 then IA.FollowKey, IA.FollowMissing = nil, nil end
        else
            IA.FollowMissing = nil
        end
        if not current and not IA.FollowKey then
            current = pickFollow(mates, root)
            IA.TrailIdx = 1
        end
        if current then
            local last = IA.Trail[#IA.Trail]
            if not last or (current.pos - last.pos).Magnitude > 0.8 or now - last.t > 0.5 then
                IA.Trail[#IA.Trail + 1] = { t = now, pos = current.pos, jump = (current.vy or 0) > 14 }
            end
        end
        while IA.Trail[1] and now - IA.Trail[1].t > IA.FollowDelay + 40 do
            table.remove(IA.Trail, 1)
            IA.TrailIdx = math.max(1, (IA.TrailIdx or 1) - 1)
        end
        -- si ese jugador está quieto (AFK) hace 8 s, se elige otro que se mueva
        if current and now - IA.FollowSince > 8 then
            local moved = 0
            for i = #IA.Trail, 2, -1 do
                if now - IA.Trail[i].t > 8 then break end
                moved = moved + (IA.Trail[i].pos - IA.Trail[i - 1].pos).Magnitude
            end
            if moved < 10 then
                followSkip[IA.FollowKey] = now + 30
                IA.FollowKey = nil
                current = pickFollow(mates, root)
                if not current then return false end
                IA.Trail[1] = { t = now, pos = current.pos, jump = false }
                IA.TrailIdx = 1
            end
        end
        if #IA.Trail == 0 then return false end
        -- v45: avanza por el recorrido miga por miga y nunca vuelve atrás (antes apuntaba a un punto fijo,
        -- lo pasaba de largo y volvía: eso hacía los círculos que marcó el registro)
        local want = now - IA.FollowDelay
        local idx = math.clamp(IA.TrailIdx or 1, 1, #IA.Trail)
        while IA.Trail[idx + 1] and IA.Trail[idx + 1].t <= want and flat(IA.Trail[idx].pos - root.Position).Magnitude < 6 do
            idx = idx + 1
        end
        IA.TrailIdx = idx
        local crumb = IA.Trail[idx]
        IA.Mode = "follow"
        IA.Detail = string.format("%s · %.1f s", IA.FollowName, IA.FollowDelay)
        local dist = flat(crumb.pos - root.Position).Magnitude
        if dist > 45 then
            -- lejos del recorrido (recién empieza o se trabó): ruta hasta ahí
            if IA.TargetKind ~= "followpath" or not IA.Target or flat(IA.Target - crumb.pos).Magnitude > 20 then setTarget(crumb.pos, "followpath") end
        elseif crumb.t > want and dist < 6 then
            -- ya lo alcanzó: espera a que pase el retraso
            IA.Target, IA.TargetKind, IA.Path = root.Position, "trail", nil
        else
            IA.Target, IA.TargetKind, IA.Path = crumb.pos, "trail", nil
        end
        -- copia los saltos de ese tramo
        for i = idx, math.min(#IA.Trail, idx + 2) do
            local c = IA.Trail[i]
            if c.jump and flat(c.pos - root.Position).Magnitude < 6 then IA.WantJump = true break end
        end
        return true
    end

    -- ---------- cerebro (cada 0.12 s) ----------
    local lastMode = nil
    local function think()
        local _, root, hum = myParts()
        if not root or not hum or hum.Health <= 0 then IA.Mode, IA.MoveWorld = "wait", nil return end
        refreshFilter()
        if truthy(registry("Downed")) then IA.Mode, IA.MoveWorld, IA.Detail = "down", nil, "" return end
        local threats, downed, mates = scan(root)
        local now = os.clock()
        -- 1) peligro
        -- v44: el registro mostró que huía de bots a 80 m (el "tiempo de llegada" saltaba con bots rápidos lejos) y
        -- replanificaba 2 veces por segundo: por eso daba vueltas en la misma zona y cortaba el revivir.
        -- Ahora: entra en peligro a "Distancia peligro" (o si llega en < 1.6 s estando a menos de 1.5x esa distancia)
        -- y sale recién cuando todos están a más de 1.3x (histéresis).
        -- v45: el registro de una ronda mostró que huía de bots a 35-41 m aunque no vinieran hacia ella, y eso cortaba
        -- cada intento de revivir. Ahora: a menos del 55 % de la distancia de peligro huye siempre; hasta la distancia
        -- de peligro, solo si el bot se le está acercando; y mientras va a revivir, solo si está muy cerca.
        local danger, why = false, nil
        local hard = IA.Danger * 0.55
        local reviving = IA.Mode == "revive" or IA.ReviveBusy
        local limit = reviving and hard or (IA.Mode == "flee" and IA.Danger * 1.2 or IA.Danger)
        for _, t in ipairs(threats) do
            local approaching = t.tti < math.huge
            if t.dist < hard or (t.dist < limit and approaching) or (not reviving and t.tti < 1.4 and t.dist < IA.Danger * 1.3) then
                danger, why = true, string.format("%s a %d m", t.name, math.floor(t.dist)) break
            end
        end
        -- revivir en curso: solo se corta si un bot está MUY cerca
        IA.ReviveAbort = IA.NearestDist < hard
        if danger and IA.ReviveBusy and not IA.ReviveAbort then danger = false end
        if danger then
            local unsafe = IA.Target and minThreatDist(IA.Target) < IA.Danger * 0.8
            local reached = IA.Target and flat(IA.Target - root.Position).Magnitude < 6
            if IA.Mode ~= "flee" or IA.TargetKind ~= "flee" or reached or unsafe or now - IA.LastFleePlan > 2.5 then
                IA.LastFleePlan = now
                local spot = pickFlee(root)
                if spot then setTarget(spot, "flee") end
                if IA.Mode ~= "flee" then log("peligro: " .. tostring(why)) end
            end
            IA.Mode = "flee"
            IA.Detail = IA.Nearest and string.format("%s · %d m", IA.Nearest.name, math.floor(IA.NearestDist)) or ""
        else
            -- v48: yendo a una escalera o trepando: no se cambia de objetivo hasta terminar
            local done = IA.Ladder ~= nil
            if done then IA.Detail = scriptText("Escalera", "Ladder") end
            -- 2) revivir
            if IA.Revive and not truthy(registry("Carrying")) then
                local bestD, bestDist = nil, IA.ReviveRange
                for _, d in ipairs(downed) do
                    local dist = (d.pos - root.Position).Magnitude
                    if dist < bestDist and minThreatDist(d.pos) > IA.Danger * 0.65 then bestD, bestDist = d, dist end
                end
                if bestD then
                    done = true
                    IA.Mode = "revive"
                    IA.Detail = string.format("%s · %d m", displayName(bestD.name), math.floor(bestDist))
                    if bestDist < 14 then
                        -- v47: se para encima del caído (como Auto salvar) y revive desde 8 m
                        IA.Target, IA.TargetKind, IA.Path = bestD.pos, "revivestand", nil
                        if bestDist < 7 then tryRevive(bestD) end
                    elseif IA.TargetKind ~= "revive" or not IA.Target or flat(IA.Target - bestD.pos).Magnitude > 6 then
                        setTarget(bestD.pos, "revive")
                    end
                end
            end
            -- 3) imitar jugador
            if not done and IA.Follow then done = followStep(root, mates, now) end
            -- 4) explorar
            if not done then
                IA.Mode = "explore"
                IA.Detail = IA.Nearest and string.format(scriptText("Bot más cerca · %d m", "Nearest bot · %d m"), math.floor(IA.NearestDist)) or ""
                local reached = IA.Target and flat(IA.Target - root.Position).Magnitude < 6
                if not IA.Target or IA.TargetKind ~= "explore" or reached or now - IA.ExploreSince > 14 or IA.PathFails >= 2 then
                    IA.ExploreSince, IA.PathFails = now, 0
                    setTarget(pickExplore(root, mates), "explore")
                end
            end
        end
        -- v48: escalera si el objetivo está en otro piso y no hay ruta (o está casi encima)
        if IA.Target and not IA.Ladder and not climbingLadder() and IA.Mode ~= "flee" and IA.TargetKind ~= "ladder" then
            local dy = IA.Target.Y - root.Position.Y
            local close = flat(IA.Target - root.Position).Magnitude < 30
            local noRoute = IA.PathFails >= 1 or (not IA.Path and not IA.Planning and IA.PathFor == IA.Target)
            if (dy > 7 or dy < -10) and (noRoute or close) then
                local L, up = pickLadder(root.Position, IA.Target)
                if L then
                    IA.Ladder = { info = L, up = up, resume = { IA.Target, IA.TargetKind }, since = now }
                    local foot = Vector3.new(L.center.X, (up and L.bottom or L.top) + 3, L.center.Z)
                    setTarget(foot, "ladder")
                    log("escalera: " .. (up and "subir" or "bajar"))
                end
            end
        end
        if IA.Ladder and IA.TargetKind == "ladder" and not climbingLadder() then
            if flat(IA.Ladder.info.center - root.Position).Magnitude < 3.5 and IA.Movement then
                pcall(function() IA.Movement:Climb(IA.Ladder.info.model) end)
                IA.Ladder.climbing = true
            elseif now - IA.Ladder.since > 14 then
                IA.BadLadder = IA.BadLadder or {}
                IA.BadLadder[IA.Ladder.info.model] = true
                local r = IA.Ladder.resume
                IA.Ladder = nil
                setTarget(r[1], r[2])
            end
        end
        if IA.Ladder and IA.Ladder.climbing and not climbingLadder() then
            -- terminó de trepar: vuelve a lo que estaba haciendo
            local r = IA.Ladder.resume
            IA.Ladder = nil
            if r[1] then setTarget(r[1], r[2]) end
        end
        IA.Visited[cellKey(root.Position)] = IA.Visited[cellKey(root.Position)] and math.max(IA.Visited[cellKey(root.Position)], now) or now
        if IA.Mode ~= lastMode then
            lastMode = IA.Mode
            log("modo: " .. IA.Mode .. (IA.Detail ~= "" and (" (" .. IA.Detail .. ")") or ""))
        end
    end

    -- ---------- movimiento por frame ----------
    local function lineClear(a, b)
        local dir = b - a
        if dir.Magnitude < 0.5 then return true end
        local d = castWide(a, dir.Unit, dir.Magnitude, 1.1)
        return d == nil
    end
    local function unstick(pos, reason)
        IA.WantJump = true
        local h = IA.Heading or Vector3.new(0, 0, -1)
        local side = Vector3.new(-h.Z, 0, h.X) * (math.random() < 0.5 and -1 or 1)
        IA.UnstickDir = (side - h * 0.8).Unit
        IA.UnstickUntil = os.clock() + 0.7
        IA.SteerDir, IA.Heading = IA.UnstickDir, IA.UnstickDir
        IA.Turn = {}
        IA.Visited[cellKey(pos)] = os.clock() + 30
        log("destrabando: " .. reason)
        task.delay(0.7, function()
            if IA.Target and IA.TargetKind ~= "trail" then setTarget(IA.Target, IA.TargetKind) end
        end)
    end
    -- v47: la IA sube su velocidad cuando la necesita (huir, ir a revivir lejos, alcanzar el recorrido) usando el mismo
    -- multiplicador de la opción "Velocidad" (pestaña Move). Si ya tenés "Velocidad" prendida, no la toca.
    local function setBoost(on)
        if on == (IA.Boosting == true) or IA.Boost <= 1.01 and on then return end
        local G = (type(getgenv) == "function" and getgenv()) or _G
        if on then
            if Config.EnableSpeedMultiplier then return end
            IA.SavedSpeed = { Config.EnableSpeedMultiplier, Config.SpeedMultiplierValue }
            Config.EnableSpeedMultiplier, Config.SpeedMultiplierValue = true, IA.Boost
            pcall(function() if SetupSpeedMultiplierHook then SetupSpeedMultiplierHook() end end)
            G.YYSpeedRestoreRequested, G.YYSpeedApplyRequested = false, true
            if G.YYApplySpeedMultiplier then pcall(G.YYApplySpeedMultiplier) end
            IA.Boosting = true
            log("velocidad extra x" .. IA.Boost)
        else
            if IA.Boosting == true and IA.SavedSpeed then
                Config.EnableSpeedMultiplier, Config.SpeedMultiplierValue = IA.SavedSpeed[1], IA.SavedSpeed[2]
                G.YYSpeedRestoreRequested = true
                if G.YYRestoreSpeedMultiplier then pcall(G.YYRestoreSpeedMultiplier) end
            end
            IA.Boosting, IA.SavedSpeed = false, nil
        end
    end
    local function drive(dt)
        local _, root = myParts()
        if not root or not IA.On or IA.Paused or IA.Mode == "wait" or IA.Mode == "down" then IA.MoveWorld = nil return end
        local pos = root.Position
        local vel = flat(root.AssemblyLinearVelocity)
        IA.Speed = vel.Magnitude
        IA.Grounded = isGrounded(root)
        -- v48: trepando una escalera
        local ladder = climbingLadder()
        if ladder then
            local pp = ladder:IsA("Model") and ladder.PrimaryPart
            local center = pp and pp:FindFirstChild("Center")
            local look = (IA.CameraService and IA.CameraService:GetCFrame()) or workspace.CurrentCamera.CFrame
            if pp and center then
                local faceLadder = (pp.Position - center.WorldPosition)
                local up = (not IA.Ladder) or IA.Ladder.up
                local z = up and -1 or 1
                if look.LookVector:Dot(faceLadder) < 0 then z = -z end
                IA.MoveWorld = look:VectorToWorldSpace(Vector3.new(0, 0, z))
                IA.Heading = flat(faceLadder).Magnitude > 0.01 and flat(faceLadder).Unit or IA.Heading
            end
            IA.StuckT = 0
            return
        end
        local push = Vector3.zero
        if IA.Mode == "flee" then
            for _, t in ipairs(IA.Threats) do
                local v = flat(pos - t.pred)
                local d = math.max(v.Magnitude, 1)
                if d < IA.Danger * 1.3 then push = push + v.Unit * ((IA.Danger * 1.3 - d) / IA.Danger) * 1.4 end
            end
        end
        if not IA.Target and push.Magnitude < 0.01 then IA.MoveWorld = nil return end
        -- ruta suavizada: el punto más lejano que se ve sin chocar
        local aim = IA.Target or (pos + push.Unit * 20)
        local path = IA.Path
        if path and IA.Target and IA.PathFor == IA.Target then
            while path[IA.PathIdx] and flat(path[IA.PathIdx].Position - pos).Magnitude < 4 do
                if path[IA.PathIdx].Action == Enum.PathWaypointAction.Jump then IA.WantJump = true end
                IA.PathIdx = IA.PathIdx + 1
                IA.PathProgressT = os.clock()
            end
            -- v47: 3 s sin llegar al próximo punto, o a más de 14 studs del camino -> ruta nueva desde donde está
            local nextWp = path[IA.PathIdx]
            local now0 = os.clock()
            if nextWp and now0 - IA.LastReplan > 1.2 and (now0 - IA.PathProgressT > 3 or flat(nextWp.Position - pos).Magnitude > 14 + 6) then
                IA.LastReplan = now0
                log("ruta nueva (" .. (now0 - IA.PathProgressT > 3 and "sin avanzar" or "fuera del camino") .. ")")
                setTarget(IA.Target, IA.TargetKind)
                path = nil
            end
            local idx = IA.PathIdx
            if path and path[idx] then
                aim = path[idx].Position
                for j = math.min(#path, idx + 6), idx + 1, -1 do
                    local p = path[j].Position + Vector3.new(0, 2.5, 0)
                    if math.abs(p.Y - pos.Y) < 8 and lineClear(pos, p) then aim = path[j].Position break end
                end
                if path[idx].Action == Enum.PathWaypointAction.Jump and flat(path[idx].Position - pos).Magnitude < 7 then IA.WantJump = true end
            end
        end
        local to = flat(aim - pos)
        if to.Magnitude < 2 and IA.TargetKind ~= "flee" then IA.MoveWorld = nil IA.StuckT = 0 return end
        local want = to.Magnitude > 0.01 and to.Unit or flat(root.CFrame.LookVector).Unit
        if push.Magnitude > 0.01 and (want + push).Magnitude > 0.01 then want = (want + push).Unit end
        if os.clock() < IA.UnstickUntil and IA.UnstickDir then want = IA.UnstickDir end
        if os.clock() >= IA.NextSteer then
            IA.NextSteer = os.clock() + 0.05
            local len = math.clamp(IA.Speed * 0.35 + 6, 7, 24)
            IA.SteerDir, IA.LowAhead, IA.FreeAhead = steer(pos, want, len, IA.SteerDir)
        end
        local target = IA.SteerDir or want
        -- giro suave
        local maxTurn = (IA.Mode == "flee" and 9 or 6) * dt
        if not IA.Heading then IA.Heading = target end
        local angle = math.atan2(IA.Heading:Cross(target).Y, IA.Heading:Dot(target))
        local turn = math.clamp(angle, -maxTurn, maxTurn)
        local h = CFrame.Angles(0, turn, 0) * IA.Heading
        IA.Heading = flat(h).Magnitude > 0.01 and flat(h).Unit or target
        -- en el piso y en el aire se "aprieta" hacia donde quiere ir; en el aire Evade usa solo el costado de eso
        IA.MoveWorld = IA.Heading
        local needBoost = (IA.Mode == "flee" and IA.NearestDist < IA.Danger * 1.1)
            or (IA.TargetKind == "revive" and to.Magnitude > 25) or IA.TargetKind == "followpath"
        if needBoost then IA.BoostUntil = os.clock() + 1.5 end
        setBoost(os.clock() < IA.BoostUntil)
        -- v48: puerta cerrada adelante -> abrirla
        if IA.FreeAhead < 7 or IA.StuckT > 0.3 then
            local ahead = workspace:Raycast(pos, IA.Heading * 8, rp)
            local map = workspace:FindFirstChild("Map")
            local inter = map and map:FindFirstChild("Parts") and map.Parts:FindFirstChild("Interactables")
            if ahead and inter and ahead.Instance:IsDescendantOf(inter) then tryDoor(pos) end
        end
        -- saltos
        if IA.LowAhead and IA.FreeAhead < 7 then IA.WantJump = true end
        if IA.Tricks and IA.Grounded then
            local straight = math.abs(angle) < 0.2
            if straight and IA.Speed > 24 and IA.FreeAhead > 22 and to.Magnitude > 25 then IA.WantJump = true end -- bhop
            local under = workspace:Raycast(pos, Vector3.new(0, -6, 0), rp)
            if under and under.Normal.Y < 0.94 and under.Normal.Y > 0.5 and IA.Speed > 26 and flat(under.Normal):Dot(IA.Heading) < -0.12 then
                IA.WantJump = true -- trimp
            end
        end
        -- atasco: quiere moverse y no avanza
        if IA.Speed < 3 and os.clock() > IA.UnstickUntil then
            IA.StuckT = IA.StuckT + dt
            if IA.StuckT > 0.6 then IA.StuckT = 0 unstick(pos, "sin avanzar") end
        else
            IA.StuckT = 0
        end
        -- vueltas en círculo: mucho giro acumulado sin alejarse
        local now = os.clock()
        IA.Turn[#IA.Turn + 1] = { t = now, a = math.abs(turn), p = pos }
        while IA.Turn[1] and now - IA.Turn[1].t > 2.5 do table.remove(IA.Turn, 1) end
        local total = 0
        for _, s in ipairs(IA.Turn) do total = total + s.a end
        if total > math.pi * 2.6 and IA.Turn[1] and flat(pos - IA.Turn[1].p).Magnitude < 8 and now > IA.UnstickUntil then
            unstick(pos, "girando en círculo")
        end
    end

    -- ---------- cámara (gira la de Evade: CameraService.CameraCFrame) ----------
    local function cameraStep(dt)
        if not IA.On or IA.Paused or not IA.Cam or IA.CamBlocked or not IA.Heading then IA.CamWin = nil return end
        if os.clock() < IA.ManualUntil or IA.Mode == "wait" or IA.Mode == "down" then IA.CamWin = nil return end
        local cs = IA.CameraService
        local cam = workspace.CurrentCamera
        local _, root = myParts()
        if not cam or not root then return end
        local base = (cs and typeof(cs.CameraCFrame) == "CFrame") and cs.CameraCFrame or cam.CFrame
        local look = flat(base.LookVector)
        if look.Magnitude < 0.05 then return end
        look = look.Unit
        local angle = math.atan2(look:Cross(IA.Heading).Y, look:Dot(IA.Heading))
        local rate = math.clamp(angle * 4.5, -5, 5) * dt + math.sin(os.clock() * 1.7) * 0.0012
        local focus = (cs and typeof(cs.CameraFocus) == "CFrame") and cs.CameraFocus.Position or (root.Position + Vector3.new(0, 1.5, 0))
        local rot = CFrame.new(focus) * CFrame.Angles(0, rate, 0) * CFrame.new(-focus)
        if cs and typeof(cs.CameraCFrame) == "CFrame" then cs.CameraCFrame = rot * cs.CameraCFrame end
        cam.CFrame = rot * cam.CFrame
        -- ¿el giro queda? ventanas de 1.5 s: si quiere girar y la cámara no se acerca al rumbo, se deja de girar
        local now = os.clock()
        if not IA.CamWin then IA.CamWin = { t = now, a = math.abs(angle) } end
        if now - IA.CamWin.t > 1.5 then
            if IA.CamWin.a > 0.5 and math.abs(angle) > IA.CamWin.a - 0.15 then
                IA.CamWin.fails = (IA.CamWin.fails or 0) + 1
            else
                IA.CamWin.fails = 0
            end
            local fails = IA.CamWin.fails
            IA.CamWin = { t = now, a = math.abs(angle), fails = fails }
            if fails >= 3 then
                IA.CamBlocked = true
                log("cámara: el juego no deja girarla; la IA sigue caminando bien igual")
            end
        end
    end

    -- ---------- ruta visible ----------
    local function drawPath()
        if not IA.ShowPath then
            if IA.PathFolder then IA.PathFolder:ClearAllChildren() end
            return
        end
        if not IA.PathFolder then
            IA.PathFolder = Instance.new("Folder")
            IA.PathFolder.Name = "YYIAPath"
            IA.PathFolder.Parent = workspace
        end
        IA.PathFolder:ClearAllChildren()
        local colors = { flee = Color3.fromRGB(255, 80, 80), revive = Color3.fromRGB(90, 255, 140), follow = Color3.fromRGB(200, 120, 255) }
        local color = colors[IA.Mode] or Color3.fromRGB(120, 180, 255)
        local function dot(pos, size)
            local part = Instance.new("Part")
            part.Shape = Enum.PartType.Ball
            part.Size = Vector3.new(size, size, size)
            part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch = true, false, false, false
            part.Material = Enum.Material.Neon
            part.Color = color
            part.Transparency = 0.25
            part.Position = pos
            part.Parent = IA.PathFolder
        end
        if IA.Mode == "follow" then
            local want = os.clock() - IA.FollowDelay
            local n = 0
            for i = #IA.Trail, 1, -1 do
                local c = IA.Trail[i]
                if c.t <= want + 3 and c.t >= want - 1 then dot(c.pos, c.jump and 1 or 0.5) n = n + 1 end
                if n > 40 then break end
            end
        elseif IA.Path and IA.PathFor == IA.Target then
            for i = IA.PathIdx, math.min(#IA.Path, IA.PathIdx + 25) do dot(IA.Path[i].Position + Vector3.new(0, 0.6, 0), 0.6) end
        end
        if IA.Target then dot(IA.Target + Vector3.new(0, 1, 0), 1.4) end
    end

    -- ---------- HUD ----------
    local MODE_TEXT = {
        explore = { "Explorando", "Exploring", Color3.fromRGB(110, 170, 255) },
        flee = { "Huyendo", "Fleeing", Color3.fromRGB(255, 85, 85) },
        revive = { "Reviviendo", "Reviving", Color3.fromRGB(80, 230, 130) },
        follow = { "Imitando", "Copying", Color3.fromRGB(200, 120, 255) },
        wait = { "Esperando personaje", "Waiting for character", Color3.fromRGB(150, 150, 160) },
        down = { "Derribado", "Downed", Color3.fromRGB(150, 150, 160) },
        idle = { "Lista", "Ready", Color3.fromRGB(150, 150, 160) },
    }
    local function buildHud()
        if IA.Hud then return end
        -- el HUD lo da la librería (YinYang.Kit.Hud); acá solo se dice qué mostrar
        local K = YYKit()
        if not (K and K.Hud) then warn("[Yin IA] La librería UI no tiene el kit de ventanas (actualizala)") return end
        local H = K.Hud({ Name = "YYYinIA", DisplayOrder = 80, Buttons = { { Key = "pause", Text = "", Width = 60 }, { Key = "other", Text = scriptText("Otro", "Next"), Width = 52 } } })
        local title, sub, pause, other = H.Title, H.Subtitle, H.Buttons.pause, H.Buttons.other
        pause.Activated:Connect(function() IA.Paused = not IA.Paused end)
        other.Activated:Connect(function()
            IA.FollowKey = nil -- el próximo ciclo elige otro jugador
            IA.Trail = {}
        end)
        local lastInfo = nil
        IA.Hud = {
            Gui = H.Gui,
            Update = function()
                local info = MODE_TEXT[IA.Mode] or MODE_TEXT.idle
                local text = scriptText(info[1], info[2])
                if IA.Paused then text, info = scriptText("Pausada", "Paused"), MODE_TEXT.idle end
                if os.clock() < IA.ManualUntil then text = scriptText("Control manual", "Manual control") end
                title.Text = "YIN IA  ·  " .. text
                local extra = IA.Detail ~= "" and (IA.Detail .. "  ·  ") or ""
                sub.Text = extra .. string.format("%d vel", math.floor(IA.Speed)) .. (IA.CamBlocked and scriptText("  ·  cámara fija", "  ·  camera locked") or "")
                pause.Text = IA.Paused and scriptText("Seguir", "Resume") or scriptText("Pausa", "Pause")
                other.Visible = IA.Follow
                if lastInfo ~= info then
                    lastInfo = info
                    H:SetDot(info[3])
                end
            end,
        }
    end

    -- ---------- encendido ----------
    local loops = {}
    local function stop()
        pcall(setBoost, false)
        IA.On = false
        IA.MoveWorld, IA.Target, IA.Path, IA.Heading, IA.Mode = nil, nil, nil, nil, "idle"
        for _, c in ipairs(loops) do pcall(function() c:Disconnect() end) end
        loops = {}
        pcall(function() RunService:UnbindFromRenderStep("YYYinIACamera") end)
        if IA.PathFolder then IA.PathFolder:ClearAllChildren() end
        if IA.Hud then pcall(function() IA.Hud.Gui:Destroy() end) IA.Hud = nil end
    end
    local function start()
        if not hookControl() then warn("[Yin IA] No se pudo enganchar ControlModule:GetMoveVector") return false end
        if not hookMovement() then warn("[Yin IA] No se pudo enganchar Movement.Update (saltos)") end
        IA.On, IA.Paused, IA.CamBlocked, IA.CamWin, IA.Turn = true, false, false, nil, {}
        pcall(buildHud)
        log("encendida · Spherecast " .. (sphereOk == false and "no (usa rayos)" or "sí/por probar") .. " · CameraService " .. (IA.CameraService and "OK" or "NO"))
        local acc, pathAcc = 0, 0
        loops[#loops + 1] = RunService.Heartbeat:Connect(function(dt)
            acc, pathAcc = acc + dt, pathAcc + dt
            if acc >= 0.12 then
                acc = 0
                local ok, err = pcall(think)
                if not ok then IA.Detail = "error: " .. tostring(err) log("ERROR think: " .. tostring(err)) end
                if IA.Hud then pcall(IA.Hud.Update) end
            end
            local okD, errD = pcall(drive, dt)
            if not okD then log("ERROR drive: " .. tostring(errD)) end
            if pathAcc >= 0.3 then pathAcc = 0 pcall(drawPath) end
        end)
        pcall(function()
            RunService:BindToRenderStep("YYYinIACamera", Enum.RenderPriority.Camera.Value + 1, function(dt)
                local ok, err = pcall(cameraStep, dt)
                if not ok then IA.CamBlocked = true log("ERROR cámara: " .. tostring(err)) end
            end)
        end)
        loops[#loops + 1] = LocalPlayer.CharacterAdded:Connect(function()
            IA.Target, IA.Path, IA.Heading, IA.SteerDir, IA.Movement = nil, nil, nil, nil, nil
        end)
        return true
    end

    YYSectionHeader(TabExtra, 7.50, "YIN IA", "YIN AI")
    YYPlace(TabExtra, 7.51)
    if isSolara then
        TabExtra:CreateLabel("Yin IA: no disponible en Solara", "Yin AI: not available on Solara", 11)
    end
    IA.Toggle = TabExtra:CreateFloatingToggle("Yin IA", "Yin AI", false, function(enabled)
        if enabled then
            if isSolara or not start() then
                stop()
                task.defer(function() if IA.Toggle and IA.Toggle.SetValue then IA.Toggle.SetValue(false) end end)
            end
        else
            stop()
        end
    end)
    YYSliderNames["AI Danger"] = "Distancia peligro"
    YYSliderNames["AI Revive Range"] = "Rango revivir"
    YYSliderNames["AI Copy Delay"] = "Retraso imitar (s)"
    YYPlace(TabExtra, 7.57)
    TabExtra:CreateSlider("AI Danger", 20, 90, 42, function(v) IA.Danger = math.clamp(tonumber(v) or 42, 20, 90) end)
    TabExtra:CreateSlider("AI Revive Range", 30, 250, 120, function(v) IA.ReviveRange = math.clamp(tonumber(v) or 120, 30, 250) end)
    TabExtra:CreateSlider("AI Copy Delay", 1, 20, 4, function(v) IA.FollowDelay = math.clamp(tonumber(v) or 4, 1, 20) end)
    YYSliderNames["AI Boost"] = "Velocidad extra IA"
    TabExtra:CreateSlider("AI Boost", 1, 2, 1.35, function(v)
        IA.Boost = math.clamp(tonumber(v) or 1.35, 1, 2)
        if IA.Boosting == true then Config.SpeedMultiplierValue = IA.Boost end
    end)
    TabExtra:CreateDivider()
end
pcall(setupYinIA)

-- ===== GRABADOR DE MOVIMIENTO (v50) =====
-- Graba lo que hacés (camino, cámara, saltos, agacharse/slide y la tecla de interactuar) y lo repite moviendo al
-- personaje con los mismos controles que usa Yin IA (verificado en el código de Evade):
--   * Movimiento: PlayerModule.ControlModule:GetMoveVector() (Evade lo pasa al mundo con CameraService:GetCFrame()).
--     En el piso se sigue el camino grabado corrigiendo el rumbo; en el aire se repite la tecla grabada con la cámara
--     grabada (air-strafe real de Evade).
--   * Cámara: CameraService.CameraCFrame (la que lee Evade) + la cámara visible, igual que Yin IA.
--   * Salto: Movement:JumpReact() al apretar y Movement.JumpHeldDown = false al soltar (lo mismo que hace
--     InputService con el botón de salto). Se graba leyendo Movement.JumpHeldDown.
--   * Agacharse / slide: Movement:KeyUsed({ Key = "Crouching", Down }) -> DataRegistry "CrouchKey". Se graba
--     leyendo "CrouchKey".
--   * Interactuar (revivir, puertas, escaleras): InteractionService:KeyUsed({ Keybind = "Interact", Down }).
-- Respeta los tiempos grabados; si te quedás atrás (choque, empujón) el reloj espera a que alcances el camino.
-- Las grabaciones duran solo la sesión. Si al darle Play estás lejos del inicio, primero camina hasta ahí.
function setupMoveRecorder()
    -- v52: usa los mismos módulos que Yin IA (ControlModule, Movement, CameraService, InteractionService). En Solara
    -- require() crea copias y rompe el personaje al reaparecer, así que ahí queda desactivado (igual que Yin IA).
    local isSolara = false
    pcall(function()
        if identifyexecutor then
            isSolara = string.find(string.lower(tostring(identifyexecutor())), "solara", 1, true) ~= nil
        end
    end)
    if isSolara then
        YYSectionHeader(TabExtra, 7.70, "GRABADOR DE MOVIMIENTO", "MOVEMENT RECORDER")
        YYPlace(TabExtra, 7.71)
        TabExtra:CreateLabel("Grabador: no disponible en Solara", "Recorder: not available on Solara", 11)
        TabExtra:CreateDivider()
        return
    end
    local PathfindingService = game:GetService("PathfindingService")
    local R = {
        Recording = false, Playing = false, Mode = "idle", Loop = false, List = {}, Count = 0,
        Cur = nil, Clock = 0, Idx = 1, EvIdx = 1, Behind = 0, MoveWorld = nil, MoveLocal = nil, Heading = nil,
        LastInput = Vector3.zero, Movement = nil, CS = nil, IS = nil, Injecting = false, Gen = 0,
        CtlHooked = false, MoveHooked = false, ISHooked = false, OrigGetMove = nil,
        Toggle = nil, ListFrame = nil, Status = nil, Conn = nil, RecConn = nil,
        HeldJump = false, HeldCrouch = false,
    }
    local SAMPLE_DT = 1 / 30
    local MAX_SECONDS = 15 * 60

    local function flat(v) return Vector3.new(v.X, 0, v.Z) end
    local function parts()
        local char = LocalPlayer.Character
        return char, char and char:FindFirstChild("HumanoidRootPart"), char and char:FindFirstChildOfClass("Humanoid")
    end
    local function notify(es, en)
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = scriptText("Grabador", "Recorder"), Text = scriptText(es, en), Duration = 4 })
        end)
    end
    local function setStatus(es, en)
        local l = R.Status
        if not l then return end
        pcall(function()
            l:SetAttribute("TextSpanish", es)
            l:SetAttribute("TextEnglish", en)
            l.Text = scriptText(es, en)
        end)
    end
    local function fmtTime(sec)
        sec = math.floor(sec + 0.5)
        return ("%d:%02d"):format(math.floor(sec / 60), sec % 60)
    end
    local function camCF()
        local cs = R.CS
        if cs then
            local ok, cf = pcall(function() return cs:GetCFrame() end)
            if ok and typeof(cf) == "CFrame" then return cf end
            if typeof(cs.CameraCFrame) == "CFrame" then return cs.CameraCFrame end
        end
        return workspace.CurrentCamera and workspace.CurrentCamera.CFrame or CFrame.new()
    end
    local function grounded(root)
        local char = LocalPlayer.Character
        local attr = char and char:GetAttribute("Grounded")
        if attr ~= nil then return attr == true end
        local m = R.Movement
        if m and m.DataRegistry then
            local ok, v = pcall(function() return m.DataRegistry:Get("Grounded") end)
            if ok and v ~= nil then return v == true end
        end
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = { char }
        return workspace:Raycast(root.Position, Vector3.new(0, -4, 0), params) ~= nil
    end
    local function crouchKey()
        local m = R.Movement
        if not (m and m.DataRegistry) then return false end
        local ok, v = pcall(function() return m.DataRegistry:Get("CrouchKey") end)
        return ok and v == true
    end

    -- ---------- hooks (encadenados: conviven con los de Yin IA) ----------
    local function hookAll()
        if not R.CtlHooked then
            local ok, ctl = pcall(function()
                return require(LocalPlayer:WaitForChild("PlayerScripts"):WaitForChild("PlayerModule"):WaitForChild("ControlModule"))
            end)
            if ok and type(ctl) == "table" and type(ctl.GetMoveVector) == "function" then
                R.OrigGetMove = ctl.GetMoveVector
                R.CtlHooked = pcall(function()
                    ctl.GetMoveVector = function(self, ...)
                        local real = R.OrigGetMove(self, ...)
                        if typeof(real) == "Vector3" then R.LastInput = real end
                        if R.Mode == "idle" then return real end
                        -- tocaste los controles: se corta la reproducción y manejás vos
                        if typeof(real) == "Vector3" and real.Magnitude > 0.35 then
                            R.Gen = R.Gen + 1
                            R.Mode = "idle"
                            task.defer(function()
                                R.StopPlayback(true)
                                notify("Reproducción detenida: tocaste los controles", "Playback stopped: you used the controls")
                            end)
                            return real
                        end
                        if R.MoveLocal then return R.MoveLocal end
                        if R.MoveWorld then return camCF():VectorToObjectSpace(R.MoveWorld) end
                        return Vector3.zero
                    end
                end)
            end
        end
        if not R.MoveHooked then
            local ok, Movement = pcall(function() return require(ReplicatedStorage.Objects.Game.Character.Client.Movement) end)
            if ok and type(Movement) == "table" and type(Movement.Update) == "function" then
                local old = Movement.Update
                R.MoveHooked = pcall(function()
                    Movement.Update = function(self, ...)
                        old(self, ...)
                        if self.Character and self.Character == LocalPlayer.Character then R.Movement = self end
                    end
                end)
            end
        end
        if not R.CS then pcall(function() R.CS = require(ReplicatedStorage.Services.Client.CameraService) end) end
        if not R.ISHooked then
            local ok, IS = pcall(function() return require(ReplicatedStorage.Services.Asset.InteractionService) end)
            if ok and type(IS) == "table" and type(IS.KeyUsed) == "function" then
                R.IS = IS
                local old = IS.KeyUsed
                R.ISHooked = pcall(function()
                    IS.KeyUsed = function(self, info, ...)
                        if R.Recording and not R.Injecting and type(info) == "table" and info.Keybind == "Interact" and R.Cur then
                            local ev = R.Cur.ev
                            ev[#ev + 1] = { t = os.clock() - R.Cur.t0, k = "i", d = info.Down ~= false }
                        end
                        return old(self, info, ...)
                    end
                end)
            end
        end
        return R.CtlHooked
    end

    -- ---------- grabar ----------
    local function startRecording()
        local _, root = parts()
        if not root then notify("No hay personaje para grabar", "No character to record") return false end
        if R.Playing then R.StopPlayback(false) end
        R.Count = R.Count + 1
        R.Cur = { name = "Grabación " .. R.Count, nameEn = "Recording " .. R.Count, s = {}, ev = {}, t0 = os.clock(), dist = 0 }
        R.Recording = true
        R.HeldJump = R.Movement and R.Movement.JumpHeldDown == true or false
        R.HeldCrouch = crouchKey()
        local lastSample = -1
        local lastPos = root.Position
        local char0 = LocalPlayer.Character
        R.RecConn = RunService.Heartbeat:Connect(function()
            local char, rootNow = parts()
            if not R.Recording or not rootNow or char ~= char0 then
                if R.Recording then R.StopRecording() end
                return
            end
            local rec = R.Cur
            local t = os.clock() - rec.t0
            if t > MAX_SECONDS then R.StopRecording() return end
            -- eventos: salto y agacharse (cada frame, para no perder toques cortos)
            local m = R.Movement
            local jump = m and m.JumpHeldDown == true or false
            if jump ~= R.HeldJump then
                R.HeldJump = jump
                rec.ev[#rec.ev + 1] = { t = t, k = "j", d = jump }
            end
            local crouch = crouchKey()
            if crouch ~= R.HeldCrouch then
                R.HeldCrouch = crouch
                rec.ev[#rec.ev + 1] = { t = t, k = "c", d = crouch }
            end
            if t - lastSample >= SAMPLE_DT then
                lastSample = t
                local p = rootNow.Position
                rec.dist = rec.dist + flat(p - lastPos).Magnitude
                lastPos = p
                rec.s[#rec.s + 1] = { t = t, p = p, lk = camCF().LookVector, mv = R.LastInput, g = grounded(rootNow) }
            end
            setStatus(("● Grabando %s"):format(fmtTime(t)), ("● Recording %s"):format(fmtTime(t)))
        end)
        setStatus("● Grabando 0:00", "● Recording 0:00")
        return true
    end
    function R.StopRecording()
        if not R.Recording then return end
        R.Recording = false
        if R.RecConn then R.RecConn:Disconnect() R.RecConn = nil end
        local rec = R.Cur
        R.Cur = nil
        if R.Toggle and R.Toggle.SetValue then task.defer(function() pcall(R.Toggle.SetValue, false) end) end
        if not rec or #rec.s < 15 then
            R.Count = math.max(R.Count - 1, 0)
            setStatus("Grabación muy corta: descartada", "Recording too short: discarded")
            return
        end
        rec.len = rec.s[#rec.s].t
        table.insert(R.List, rec)
        setStatus(("Guardada: %s (%s) · tocá ▶ abajo para reproducir"):format(rec.name, fmtTime(rec.len)),
            ("Saved: %s (%s) · tap ▶ below to play"):format(rec.nameEn, fmtTime(rec.len)))
        notify(("%s guardada: tocá ▶ en la lista (Extra → Grabador)"):format(rec.name), ("%s saved: tap ▶ in the list (Extra → Recorder)"):format(rec.nameEn))
        R.Render()
    end

    -- ---------- reproducir ----------
    local function sampleAt(rec, t)
        local s = rec.s
        local i = R.Idx
        if i > #s or s[i].t > t then i = 1 end
        while s[i + 1] and s[i + 1].t <= t do i = i + 1 end
        R.Idx = i
        local a, b = s[i], s[i + 1]
        if not b then return a.p, a.lk, a.mv, a.g end
        local f = math.clamp((t - a.t) / math.max(b.t - a.t, 1e-3), 0, 1)
        return a.p:Lerp(b.p, f), a.lk:Lerp(b.lk, f), (f < 0.5 and a.mv or b.mv), (f < 0.5 and a.g or b.g)
    end
    local function aimCamera(look, dt, smooth)
        local cs, cam = R.CS, workspace.CurrentCamera
        if not cam or typeof(look) ~= "Vector3" or look.Magnitude < 0.05 then return end
        look = look.Unit
        local base = (cs and typeof(cs.CameraCFrame) == "CFrame") and cs.CameraCFrame or cam.CFrame
        local cur = base.LookVector
        local fc, fl = flat(cur), flat(look)
        if fc.Magnitude < 0.05 or fl.Magnitude < 0.05 then return end
        fc, fl = fc.Unit, fl.Unit
        local yaw = math.atan2(fc:Cross(fl).Y, fc:Dot(fl))
        local pitch = math.asin(math.clamp(look.Y, -0.99, 0.99)) - math.asin(math.clamp(cur.Y, -0.99, 0.99))
        if smooth then
            yaw = math.clamp(yaw * 4.5, -5, 5) * dt
            pitch = 0
        end
        local _, root = parts()
        local focus = (cs and typeof(cs.CameraFocus) == "CFrame") and cs.CameraFocus.Position
            or (root and root.Position + Vector3.new(0, 1.5, 0)) or base.Position
        local right = base.RightVector
        local rot = CFrame.new(focus) * CFrame.Angles(0, yaw, 0) * CFrame.fromAxisAngle(right, pitch) * CFrame.new(-focus)
        if cs and typeof(cs.CameraCFrame) == "CFrame" then cs.CameraCFrame = rot * cs.CameraCFrame end
        cam.CFrame = rot * cam.CFrame
    end
    local function inject(k, down)
        local m = R.Movement
        if k == "j" then
            if not m then return end
            if down then
                task.spawn(function() pcall(function() m:JumpReact() end) end)
            else
                m.JumpHeldDown = false
            end
            R.HeldJump = down
        elseif k == "c" then
            if not m then return end
            pcall(function() m:KeyUsed({ Key = "Crouching", Keybind = "Crouching", Down = down }) end)
            R.HeldCrouch = down
        elseif k == "i" then
            local IS = R.IS
            if not IS then return end
            R.Injecting = true
            pcall(function() IS:KeyUsed({ Keybind = "Interact", Key = "Interact", Down = down }) end)
            R.Injecting = false
        end
    end
    local function releaseAll()
        if R.HeldJump then inject("j", false) end
        if R.HeldCrouch then inject("c", false) end
        R.HeldJump, R.HeldCrouch = false, false
    end
    function R.StopPlayback(silent)
        R.Gen = R.Gen + 1
        local was = R.Playing
        R.Playing, R.Mode = false, "idle"
        R.MoveWorld, R.MoveLocal = nil, nil
        if R.Conn then R.Conn:Disconnect() R.Conn = nil end
        if R.Done then pcall(function() R.Done:Fire() end) end -- despierta a la reproducción que esperaba
        releaseAll()
        if was then
            if not silent then setStatus("Reproducción detenida", "Playback stopped") end
            R.Render()
        end
    end

    -- caminar hasta un punto (Pathfinding; si falla, en línea recta). Devuelve true al llegar.
    local function walkTo(target, gen)
        local _, root = parts()
        if not root then return false end
        local points = { target }
        pcall(function()
            local path = PathfindingService:CreatePath({ AgentRadius = 2, AgentHeight = 5, AgentCanJump = true, WaypointSpacing = 6 })
            path:ComputeAsync(root.Position, target)
            if path.Status == Enum.PathStatus.Success then
                points = {}
                for _, w in ipairs(path:GetWaypoints()) do
                    points[#points + 1] = { p = w.Position, jump = w.Action == Enum.PathWaypointAction.Jump }
                end
            end
        end)
        R.Mode = "walk"
        local i, t0, lastProgress, best = 1, os.clock(), os.clock(), math.huge
        while gen == R.Gen and R.Mode == "walk" do
            local dt = RunService.Heartbeat:Wait()
            local _, r = parts()
            if not r then return false end
            local pos = r.Position
            if flat(target - pos).Magnitude < 3 and math.abs(target.Y - pos.Y) < 6 then return true end
            local wp = points[i]
            local wpPos = typeof(wp) == "Vector3" and wp or wp.p
            local d = flat(wpPos - pos)
            if d.Magnitude < 2.5 and points[i + 1] then
                i = i + 1
                if type(points[i]) == "table" and points[i].jump and R.Movement then pcall(function() R.Movement:AttemptJump() end) end
            elseif d.Magnitude > 0.1 then
                R.MoveWorld = d.Unit
                R.Heading = d.Unit
                aimCamera(d.Unit, dt, true)
            end
            local remaining = flat(target - pos).Magnitude
            if remaining < best - 1 then best, lastProgress = remaining, os.clock() end
            if os.clock() - lastProgress > 6 or os.clock() - t0 > 45 then return false end
        end
        return false
    end

    local function playOnce(rec, gen)
        local _, root = parts()
        if not root then return "dead" end
        local s = rec.s
        if flat(s[1].p - root.Position).Magnitude > 5 or math.abs(s[1].p.Y - root.Position.Y) > 8 then
            setStatus(("Yendo al inicio de %s..."):format(rec.name), ("Walking to the start of %s..."):format(rec.nameEn))
            if not walkTo(s[1].p, gen) then return gen == R.Gen and "far" or "stop" end
        end
        if gen ~= R.Gen then return "stop" end
        R.MoveWorld = nil
        R.Mode = "play"
        R.Clock, R.Idx, R.EvIdx, R.Behind = 0, 1, 1, 0
        -- la cámara arranca mirando como en la grabación
        aimCamera(s[1].lk, 0, false)
        local finished = nil
        local done = Instance.new("BindableEvent")
        R.Done = done
        R.Conn = RunService.Heartbeat:Connect(function(dt)
            if gen ~= R.Gen then return end
            local _, r, hum = parts()
            if not r or (hum and hum.Health <= 0) then finished = "dead" done:Fire() return end
            local pos = r.Position
            local target = sampleAt(rec, R.Clock)
            local err = flat(target - pos).Magnitude
            -- reloj: a tiempo real; si te quedaste atrás, espera a que alcances el camino
            local speed = err < 4 and 1 or (err < 10 and 0.5 or 0)
            if speed == 0 then
                R.Behind = R.Behind + dt
                if R.Behind > 6 then finished = "lost" done:Fire() return end
            else
                R.Behind = 0
            end
            R.Clock = math.min(R.Clock + dt * speed, rec.len)
            local p, lk, mv, g = sampleAt(rec, R.Clock)
            -- eventos (saltos, agacharse, interactuar) en su momento exacto
            local ev = rec.ev
            while ev[R.EvIdx] and ev[R.EvIdx].t <= R.Clock do
                local e = ev[R.EvIdx]
                inject(e.k, e.d)
                R.EvIdx = R.EvIdx + 1
            end
            aimCamera(lk, dt, false)
            if g and grounded(r) then
                -- en el piso: seguir el camino grabado un poco más adelante
                local ahead = sampleAt(rec, math.min(R.Clock + 0.25, rec.len))
                local want = flat(ahead - pos)
                R.MoveLocal = nil
                if want.Magnitude < 0.4 and (typeof(mv) ~= "Vector3" or mv.Magnitude < 0.1) then
                    R.MoveWorld = Vector3.zero
                else
                    R.MoveWorld = want.Magnitude > 0.05 and want.Unit or Vector3.zero
                end
            else
                -- en el aire: la tecla grabada con la cámara grabada (air-strafe de Evade)
                R.MoveWorld = nil
                R.MoveLocal = typeof(mv) == "Vector3" and mv or Vector3.zero
            end
            if R.Clock >= rec.len then finished = "ok" done:Fire() end
            setStatus(("▶ %s  %s / %s"):format(rec.name, fmtTime(R.Clock), fmtTime(rec.len)),
                ("▶ %s  %s / %s"):format(rec.nameEn, fmtTime(R.Clock), fmtTime(rec.len)))
        end)
        while not finished and gen == R.Gen do done.Event:Wait() end
        if R.Done == done then R.Done = nil end
        done:Destroy()
        if R.Conn then R.Conn:Disconnect() R.Conn = nil end
        R.MoveWorld, R.MoveLocal = nil, nil
        releaseAll()
        return finished or "stop"
    end

    function R.Play(rec)
        if R.Recording then R.StopRecording() end
        R.StopPlayback(true)
        if not hookAll() then
            notify("No disponible en este executor (no se pudo enganchar el control)", "Not available on this executor (control hook failed)")
            return
        end
        R.Gen = R.Gen + 1
        local gen = R.Gen
        R.Playing = true
        R.Cur = nil
        R.PlayingRec = rec
        R.Render()
        task.spawn(function()
            local result
            repeat
                result = playOnce(rec, gen)
            until result ~= "ok" or not R.Loop or gen ~= R.Gen
            if gen ~= R.Gen then return end
            R.Playing, R.Mode, R.PlayingRec = false, "idle", nil
            local msg = ({
                ok = { "Reproducción terminada", "Playback finished" },
                far = { "No pude llegar al inicio de la grabación", "Couldn't reach the recording's start" },
                lost = { "Me desvié del camino: reproducción detenida", "Went off the path: playback stopped" },
                dead = { "Reproducción detenida (personaje caído o muerto)", "Playback stopped (character down or dead)" },
            })[result] or { "Reproducción detenida", "Playback stopped" }
            setStatus(msg[1], msg[2])
            if result ~= "ok" then notify(msg[1], msg[2]) end
            R.Render()
        end)
    end

    -- ---------- interfaz: lista de grabaciones ----------
    local function palette()
        local p = nil
        if type(GetAvatarPalette) == "function" then pcall(function() p = GetAvatarPalette() end) end
        return p or {
            Background = Color3.fromRGB(16, 16, 18), Secondary = Color3.fromRGB(32, 32, 36),
            Text = Color3.fromRGB(245, 245, 248), TextDim = Color3.fromRGB(165, 165, 175), Accent = Color3.fromRGB(235, 235, 240),
        }
    end
    -- v51: la librería usa ZIndex global (ventana 5, páginas 8). Sin ZIndex alto la lista quedaba DETRÁS de la
    -- ventana: se guardaba pero no se veía. Ahora todo va en ZIndex 10+ (por encima de la página).
    local function mk(class, props, parent)
        local o = YYKitMake(class)
        if o:IsA("GuiObject") and props.ZIndex == nil then o.ZIndex = 11 end
        for k, v in pairs(props) do o[k] = v end
        o.Parent = parent
        return o
    end
    local function round(o, r) mk("UICorner", { CornerRadius = UDim.new(0, r) }, o) end
    function R.Render()
        local holder = R.ListFrame
        if not holder then return end
        for _, c in ipairs(holder:GetChildren()) do
            if c:IsA("GuiObject") then c:Destroy() end
        end
        local p = palette()
        if #R.List == 0 then
            mk("TextLabel", {
                Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1, Text = scriptText("Todavía no hay grabaciones", "No recordings yet"),
                TextColor3 = p.TextDim, Font = Enum.Font.GothamMedium, TextSize = 12, LayoutOrder = 1,
            }, holder)
            return
        end
        for i, rec in ipairs(R.List) do
            local playing = R.Playing and R.PlayingRec == rec
            local row = mk("Frame", {
                Size = UDim2.new(1, 0, 0, 46), BackgroundColor3 = p.Secondary, BackgroundTransparency = 0.15,
                BorderSizePixel = 0, LayoutOrder = i, ZIndex = 10,
            }, holder)
            round(row, 12)
            mk("TextLabel", {
                Size = UDim2.new(1, -110, 0, 20), Position = UDim2.fromOffset(12, 5), BackgroundTransparency = 1,
                Text = scriptText(rec.name, rec.nameEn), TextColor3 = p.Text, Font = Enum.Font.GothamBold, TextSize = 14,
                TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
            }, row)
            mk("TextLabel", {
                Size = UDim2.new(1, -110, 0, 16), Position = UDim2.fromOffset(12, 25), BackgroundTransparency = 1,
                Text = ("%s · %d m · %d %s"):format(fmtTime(rec.len), math.floor(rec.dist * 0.28 + 0.5), #rec.ev, scriptText("acciones", "actions")),
                TextColor3 = p.TextDim, Font = Enum.Font.GothamMedium, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left,
            }, row)
            local play = mk("TextButton", {
                AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -52, 0.5, 0), Size = UDim2.fromOffset(40, 32),
                BackgroundColor3 = p.Accent, Text = playing and "■" or "▶", TextColor3 = p.Background,
                Font = Enum.Font.GothamBlack, TextSize = 15, AutoButtonColor = true,
            }, row)
            round(play, 16)
            local del = mk("TextButton", {
                AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -8, 0.5, 0), Size = UDim2.fromOffset(36, 32),
                BackgroundColor3 = Color3.fromRGB(205, 60, 70), Text = "✕", TextColor3 = Color3.new(1, 1, 1),
                Font = Enum.Font.GothamBlack, TextSize = 14, AutoButtonColor = true,
            }, row)
            round(del, 16)
            play.Activated:Connect(function()
                if R.Playing and R.PlayingRec == rec then
                    R.StopPlayback(false)
                else
                    R.Play(rec)
                end
            end)
            del.Activated:Connect(function()
                if R.PlayingRec == rec then R.StopPlayback(true) end
                for j, r2 in ipairs(R.List) do
                    if r2 == rec then table.remove(R.List, j) break end
                end
                setStatus(("Eliminada: %s"):format(rec.name), ("Deleted: %s"):format(rec.nameEn))
                R.Render()
            end)
        end
    end

    YYSectionHeader(TabExtra, 7.70, "GRABADOR DE MOVIMIENTO", "MOVEMENT RECORDER")
    YYPlace(TabExtra, 7.71)
    R.Toggle = TabExtra:CreateFloatingToggle("Grabar movimiento", "Record movement", false, function(enabled)
        if enabled then
            if R.Recording then return end
            if not hookAll() then
                notify("No disponible en este executor (no se pudo enganchar el control)", "Not available on this executor (control hook failed)")
                task.defer(function() if R.Toggle and R.Toggle.SetValue then pcall(R.Toggle.SetValue, false) end end)
                return
            end
            if not startRecording() then
                task.defer(function() if R.Toggle and R.Toggle.SetValue then pcall(R.Toggle.SetValue, false) end end)
            end
        else
            R.StopRecording()
        end
    end)
    YYPlace(TabExtra, 7.72)
    TabExtra:CreateToggle("Repetir en bucle", "Loop playback", false, function(enabled)
        R.Loop = enabled == true
    end)
    YYPlace(TabExtra, 7.73)
    R.Status = TabExtra:CreateLabel("Activá Grabar, movete y apagalo: la grabación aparece abajo.",
        "Turn Record on, move and turn it off: the recording shows up below.", 11)
    YYPlace(TabExtra, 7.74)
    local holder = YYKitMake("Frame")
    holder.Name = "YYMoveRecordings"
    holder.Size = UDim2.new(1, 0, 0, 0)
    holder.AutomaticSize = Enum.AutomaticSize.Y
    holder.BackgroundTransparency = 1
    holder.BorderSizePixel = 0
    holder.ZIndex = 9
    local layout = YYKitMake("UIListLayout")
    layout.Padding = UDim.new(0, 6)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Parent = holder
    holder.Parent = TabExtra._ContentParent or TabExtra.Page
    R.ListFrame = holder
    R.Render()
    YYPlace(TabExtra, 7.75)
    TabExtra:CreateDivider()
    LocalPlayer.CharacterAdded:Connect(function()
        R.Movement = nil
        if R.Recording then R.StopRecording() end
    end)
end
