local function pal()
    return GetAvatarPalette()
end

local function new(class, props, parent)
    local o = YYKitMake(class)
    for k, v in pairs(props) do
        o[k] = v
    end
    if parent then
        o.Parent = parent
    end
    return o
end

local function corner(parent, r)
    return new("UICorner", { CornerRadius = UDim.new(0, r) }, parent)
end

local function text(parent, es, en, size, font, role, props)
    local l = new("TextLabel", {
        BackgroundTransparency = 1,
        Text = scriptText(es, en),
        TextColor3 = pal()[role or "Text"],
        TextSize = size,
        Font = font,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        ZIndex = 282,
    }, parent)
    l:SetAttribute("ThemeTextRole", role or "Text")
    l:SetAttribute("IgnoreTextEffect", true)
    l:SetAttribute("TextSpanish", es)
    l:SetAttribute("TextEnglish", en)
    for k, v in pairs(props or {}) do
        l[k] = v
    end
    return l
end

local function assetTypeName(value)
    if typeof(value) == "EnumItem" then
        return value.Name
    end
    if type(value) == "number" then
        local name = nil
        pcall(function()
            for _, item in ipairs(Enum.AvatarAssetType:GetEnumItems()) do
                if item.Value == value then
                    name = item.Name
                end
            end
        end)
        return name
    end
    return value and tostring(value) or nil
end

local function getVisualHumanoid()
    local _, humanoid = GetAvatarVisualHumanoid()
    return humanoid
end

local function currentDescription()
    local humanoid = getVisualHumanoid()
    if not humanoid then
        return nil
    end
    local ok, desc = pcall(function()
        return humanoid:GetAppliedDescription()
    end)
    return ok and desc or nil
end

local function currentRigType()
    local humanoid = getVisualHumanoid()
    local ok, rigType = pcall(function() return humanoid and humanoid.RigType end)
    return (ok and rigType) or Enum.HumanoidRigType.R6
end

local function isR15()
    return currentRigType() == Enum.HumanoidRigType.R15
end

local function layeredList(desc)
    local ok, list = pcall(function() return desc:GetAccessories(false) end)
    return (ok and type(list) == "table") and list or {}
end

local function idList(value)
    local list = {}
    for id in tostring(value or ""):gmatch("%d+") do
        list[#list + 1] = id
    end
    return list
end

local function isEquipped(desc, assetType, id)
    if desc and LAYERED[assetType] then
        for _, entry in ipairs(layeredList(desc)) do
            if tostring(entry.AssetId) == tostring(id) then
                return true
            end
        end
        return false
    end
    local map = ASSET_PROPS[assetType]
    if not (desc and map) then
        return false
    end
    local value = desc[map[1]]
    if map[2] then
        return table.find(idList(value), tostring(id)) ~= nil
    end
    return tonumber(value) == tonumber(id)
end

-- ---------- ventana ----------
local W = {}

local function setStatus(es, en, color)
    if not W.Status then return end
    W.Status:SetAttribute("TextSpanish", es)
    W.Status:SetAttribute("TextEnglish", en)
    W.Status.Text = scriptText(es, en)
    W.Status.TextColor3 = AvatarAdaptStatusColor(color or Color3.fromRGB(180, 180, 190))
end

-- El cuerpo se centra por el torso (no por la caja de todo el modelo: si el modelo trae partes extra
-- lejos del cuerpo, la caja crece y el personaje queda chiquito en una esquina).
local function corePart(model)
    return model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso")
        or model:FindFirstChild("UpperTorso") or model.PrimaryPart
end

local function placePreview()
    local model = W.PreviewModel
    if not model then return end
    pcall(function()
        -- el torso queda en (0,0,0) y gira sobre si mismo
        model:PivotTo(CFrame.Angles(0, math.rad(AC.Angle), 0) * (W.CoreOffset or CFrame.new()))
    end)
end

local function framePreview()
    -- encuadre fijo de un cuerpo (R6/R15: cabeza a pies ~5 studs + margen para sombreros), centrado en el torso
    local center = Vector3.new(0, -0.35, 0)
    local height = 6.6
    local distance = (height * 0.5) / math.tan(math.rad(W.Camera.FieldOfView * 0.5))
    -- los personajes de Roblox miran hacia -Z: la camara va de ese lado para verlos de frente
    W.Camera.CFrame = CFrame.new(center + Vector3.new(0, 0.4, -distance), center)
end

-- Vista previa: modelo armado desde la descripcion actual (se rehace solo cuando cambia algo)
local function refreshPreview()
    if not W.Viewport then return end
    AC.PreviewToken += 1
    local token = AC.PreviewToken
    W.Loading.Visible = true
    task.spawn(function()
        local desc = currentDescription()
        -- 1) copia del rig visual del juego: muestra exactamente lo que tenes puesto (pelo, accesorios, cosmeticos).
        -- Roblox no copia los objetos con Archivable = false (por eso faltaban los accesorios): se activa un
        -- momento en todo el rig, se copia y se deja como estaba.
        local model = nil
        local rig = GetAvatarVisualHumanoid()
        if rig then
            local changed = {}
            pcall(function()
                if not rig.Archivable then
                    changed[#changed + 1] = rig
                    rig.Archivable = true
                end
                for _, d in ipairs(rig:GetDescendants()) do
                    if not d.Archivable then
                        changed[#changed + 1] = d
                        d.Archivable = true
                    end
                end
            end)
            local okClone, cloned = pcall(function() return rig:Clone() end)
            for _, inst in ipairs(changed) do
                pcall(function() inst.Archivable = false end)
            end
            if okClone and typeof(cloned) == "Instance" then
                model = cloned
            end
        end
        -- 2) respaldo: modelo armado desde la descripcion
        if not model and desc then
            local ok, result = pcall(function()
                -- en una Instance, leer un metodo que no existe tira error (no devuelve nil)
                local hasAsync = pcall(function() return Players.CreateHumanoidModelFromDescriptionAsync end)
                if hasAsync then
                    return Players:CreateHumanoidModelFromDescriptionAsync(desc, currentRigType())
                end
                return Players:CreateHumanoidModelFromDescription(desc, currentRigType())
            end)
            if ok and typeof(result) == "Instance" then
                model = result
            elseif not ok then
                warn("[Catálogo] Vista previa:", result)
            end
        end
        if token ~= AC.PreviewToken then
            if model then pcall(function() model:Destroy() end) end
            return
        end
        if W.PreviewModel then
            pcall(function() W.PreviewModel:Destroy() end)
            W.PreviewModel = nil
        end
        if not model then
            W.Loading.Text = scriptText("Sin vista previa", "No preview")
            return
        end
        for _, d in ipairs(model:GetDescendants()) do
            if d:IsA("Script") or d:IsA("LocalScript") or d:IsA("Sound") then
                pcall(function() d:Destroy() end)
            elseif d:IsA("BasePart") then
                d.Anchored = true
            end
        end
        model.Parent = W.World
        W.PreviewModel = model
        local core = corePart(model)
        W.CoreOffset = CFrame.new()
        if core then
            pcall(function()
                -- pivote del modelo visto desde el torso, sin la inclinacion que pudiera tener el torso
                local upright = CFrame.new(core.Position) * CFrame.Angles(0, select(2, core.CFrame:ToOrientation()), 0)
                W.CoreOffset = upright:Inverse() * model:GetPivot()
            end)
        end
        placePreview()
        -- fuera de la vista previa todo lo que no sea del cuerpo (partes a mas de 10 studs del torso)
        for _, d in ipairs(model:GetDescendants()) do
            if d:IsA("BasePart") and d.Position.Magnitude > 14 then
                pcall(function() d:Destroy() end)
            end
        end
        framePreview()
        W.Loading.Visible = false
    end)
end

local function refreshTiles()
    local desc = currentDescription()
    for _, tile in ipairs(AC.Tiles) do
        tile.Refresh(desc)
    end
end

local renderWorn -- se define abajo

-- aplica una descripcion al rig visual (mismo metodo que "Aplicar avatar")
local function applyDescription(desc, es, en)
    local humanoid = getVisualHumanoid()
    if not humanoid then
        setStatus("No se encontró tu rig visual (entrá a una partida).", "Your visual rig was not found (join a match).", Color3.fromRGB(255, 135, 135))
        return false
    end
    AC.Busy = true
    setStatus("Aplicando...", "Applying...", Color3.fromRGB(195, 215, 255))
    local ok, err = AvatarApplyDescriptionSafe(humanoid, desc)
    AC.Busy = false
    if not ok then
        setStatus("No se pudo aplicar: " .. AvatarShortError(err), "Could not apply: " .. AvatarShortError(err), Color3.fromRGB(255, 135, 135))
        return false
    end
    setStatus(es, en, Color3.fromRGB(145, 255, 180))
    pcall(YYAvatarRemember, desc, false)
    pcall(YYAvatarBump)
    refreshPreview()
    task.delay(0.8, function()
        if W.Overlay and W.Overlay.Visible and not AC.Busy then
            refreshPreview()
        end
    end)
    if AC.Mode == "worn" then
        renderWorn()
    else
        refreshTiles()
    end
    return true
end

local function toggleLayered(id, assetType, name)
    if not isR15() then
        setStatus("La ropa 3D (en capas) solo funciona con avatar R15.", "3D (layered) clothing only works on R15 avatars.", Color3.fromRGB(255, 190, 120))
        return
    end
    local desc = currentDescription()
    if not desc then
        setStatus("No se encontró tu rig visual (entrá a una partida).", "Your visual rig was not found (join a match).", Color3.fromRGB(255, 135, 135))
        return
    end
    local list = layeredList(desc)
    local removed = false
    for i = #list, 1, -1 do
        if tostring(list[i].AssetId) == tostring(id) then
            table.remove(list, i)
            removed = true
        end
    end
    if not removed then
        local okType, accessoryType = pcall(function() return Enum.AccessoryType[LAYERED[assetType]] end)
        if not okType or not accessoryType then
            setStatus("Ese tipo de ropa no está disponible.", "That clothing type is not available.", Color3.fromRGB(255, 190, 120))
            return
        end
        list[#list + 1] = { AssetId = tonumber(id), AccessoryType = accessoryType, IsLayered = true, Order = #list + 1 }
    end
    local okSet, err = pcall(function() desc:SetAccessories(list, false) end)
    if not okSet then
        setStatus("No se pudo poner esa ropa.", "Could not wear that clothing.", Color3.fromRGB(255, 135, 135))
        warn("[Catálogo] SetAccessories:", err)
        return
    end
    task.spawn(applyDescription, desc,
        (removed and "Quitado: " or "Puesto: ") .. tostring(name),
        (removed and "Removed: " or "Equipped: ") .. tostring(name))
end

local function toggleAsset(id, assetType, name)
    if AC.Busy then return end
    if LAYERED[assetType] then
        toggleLayered(id, assetType, name or id)
        return
    end
    local map = ASSET_PROPS[assetType]
    if not map then
        setStatus("Ese tipo de objeto no se puede usar en tu avatar.", "That item type can't be used on your avatar.", Color3.fromRGB(255, 190, 120))
        return
    end
    local desc = currentDescription()
    if not desc then
        setStatus("No se encontró tu rig visual (entrá a una partida).", "Your visual rig was not found (join a match).", Color3.fromRGB(255, 135, 135))
        return
    end
    id = tostring(id)
    name = tostring(name or id)
    local removed
    if map[2] then
        local list = idList(desc[map[1]])
        local index = table.find(list, id)
        if index then
            table.remove(list, index)
        else
            list[#list + 1] = id
        end
        removed = index ~= nil
        desc[map[1]] = table.concat(list, ",")
    else
        removed = tonumber(desc[map[1]]) == tonumber(id)
        desc[map[1]] = removed and 0 or tonumber(id)
    end
    task.spawn(applyDescription, desc,
        (removed and "Quitado: " or "Puesto: ") .. name,
        (removed and "Removed: " or "Equipped: ") .. name)
end

-- paquete de cuerpo: se leen sus partes (BundledItems) y se ponen todas
local function applyBundle(item, onlyParts)
    if AC.Busy then return end
    setStatus("Leyendo el paquete...", "Reading the package...", Color3.fromRGB(195, 215, 255))
    task.spawn(function()
        local ok, details = pcall(function()
            local hasAsync = pcall(function() return AvatarEditorService.GetItemDetailsAsync end)
            if hasAsync then
                return AvatarEditorService:GetItemDetailsAsync(item.Id, Enum.AvatarItemType.Bundle)
            end
            return AvatarEditorService:GetItemDetails(item.Id, Enum.AvatarItemType.Bundle)
        end)
        if not ok or type(details) ~= "table" or type(details.BundledItems) ~= "table" then
            setStatus("No se pudo leer el paquete.", "Could not read the package.", Color3.fromRGB(255, 135, 135))
            return
        end
        local desc = currentDescription()
        if not desc then
            setStatus("No se encontró tu rig visual (entrá a una partida).", "Your visual rig was not found (join a match).", Color3.fromRGB(255, 135, 135))
            return
        end
        local applied = 0
        local r15 = isR15()
        for _, part in ipairs(details.BundledItems) do
            local partType = assetTypeName(part.AssetType)
            -- en R15 la cabeza dinamica (DynamicHead) se pone en la propiedad Head
            if r15 and partType == "DynamicHead" then
                partType = "Head"
            end
            if part.Type == "Asset" and partType and table.find(onlyParts or BODY_PARTS, partType) then
                desc[partType] = tonumber(part.Id)
                applied += 1
            end
        end
        if applied == 0 then
            setStatus("Ese paquete no trae esa parte. Probá otro.", "That package doesn't include that part. Try another.", Color3.fromRGB(255, 190, 120))
            return
        end
        applyDescription(desc, "Paquete puesto: " .. tostring(item.Name), "Package equipped: " .. tostring(item.Name))
    end)
end

local function applySkin(color)
    if AC.Busy then return end
    local desc = currentDescription()
    if not desc then
        setStatus("No se encontró tu rig visual (entrá a una partida).", "Your visual rig was not found (join a match).", Color3.fromRGB(255, 135, 135))
        return
    end
    for _, target in ipairs(SKIN_TARGETS) do
        if target[1] == AC.SkinTarget then
            for _, prop in ipairs(target[4]) do
                desc[prop] = color
            end
        end
    end
    task.spawn(applyDescription, desc, "Color de piel aplicado.", "Skin color applied.")
end

local function clearTiles()
    for _, tile in ipairs(AC.Tiles) do
        pcall(function() tile.Frame:Destroy() end)
    end
    AC.Tiles = {}
end

-- tarjeta de resultado (asset o paquete)
local function makeTile(item, order, isBundle)
    local frame = new("TextButton", {
        Name = "CatalogItem",
        Text = "",
        AutoButtonColor = false,
        BackgroundColor3 = pal().Secondary,
        BackgroundTransparency = 0.25,
        BorderSizePixel = 0,
        LayoutOrder = order,
        ZIndex = 281,
    }, W.Grid)
    frame:SetAttribute("ThemeRole", "Secondary")
    corner(frame, 12)
    local stroke = new("UIStroke", { Thickness = 1, Color = pal().Stroke, Transparency = 0.65 }, frame)
    -- fondo de la miniatura con degradado suave
    local thumbBox = new("Frame", {
        Size = UDim2.new(1, -10, 1, -44),
        Position = UDim2.fromOffset(5, 5),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 0.94,
        BorderSizePixel = 0,
        ZIndex = 281,
    }, frame)
    corner(thumbBox, 9)
    new("UIGradient", {
        Rotation = 90,
        Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 0.7) }),
    }, thumbBox)
    local thumbType = isBundle and "BundleThumbnail" or "Asset"
    new("ImageLabel", {
        Size = UDim2.new(1, -8, 1, -8),
        Position = UDim2.fromOffset(4, 4),
        BackgroundTransparency = 1,
        Image = "rbxthumb://type=" .. thumbType .. "&id=" .. tostring(item.Id) .. "&w=150&h=150",
        ScaleType = Enum.ScaleType.Fit,
        ZIndex = 282,
    }, thumbBox)
    local nameLabel = new("TextLabel", {
        Size = UDim2.new(1, -12, 0, 14),
        Position = UDim2.new(0, 6, 1, -35),
        BackgroundTransparency = 1,
        Text = tostring(item.Name or ""),
        TextColor3 = pal().Text,
        TextSize = 10,
        Font = Enum.Font.GothamBold,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        ZIndex = 282,
    }, frame)
    nameLabel:SetAttribute("ThemeTextRole", "Text")
    nameLabel:SetAttribute("IgnoreTextEffect", true)
    local price = tonumber(item.Price) or 0
    local pricePill = new("TextLabel", {
        Size = UDim2.fromOffset(0, 15),
        AutomaticSize = Enum.AutomaticSize.X,
        Position = UDim2.new(0, 6, 1, -19),
        BackgroundColor3 = price > 0 and Color3.fromRGB(0, 0, 0) or Color3.fromRGB(60, 190, 110),
        BackgroundTransparency = price > 0 and 0.55 or 0.2,
        Text = price > 0 and ("R$ " .. tostring(price)) or scriptText("GRATIS", "FREE"),
        TextColor3 = Color3.fromRGB(255, 255, 255),
        TextSize = 9,
        Font = Enum.Font.GothamBold,
        ZIndex = 282,
    }, frame)
    pricePill:SetAttribute("IgnoreTextEffect", true)
    pricePill.Visible = price >= 0 -- en "Puesto" no hay precio
    corner(pricePill, 7)
    new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }, pricePill)
    local badge = new("TextLabel", {
        AnchorPoint = Vector2.new(1, 0),
        Size = UDim2.fromOffset(0, 18),
        AutomaticSize = Enum.AutomaticSize.X,
        Position = UDim2.new(1, -8, 0, 8),
        BackgroundColor3 = pal().Accent,
        Text = scriptText("PUESTO", "WORN"),
        TextColor3 = AvatarContrastColor(pal().Accent),
        TextSize = 8,
        Font = Enum.Font.GothamBlack,
        Visible = false,
        ZIndex = 283,
    }, frame)
    badge:SetAttribute("IgnoreTextEffect", true)
    corner(badge, 9)
    new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }, badge)
    local scale = new("UIScale", { Scale = 1 }, frame)

    local tile = { Frame = frame }
    tile.Refresh = function(desc)
        local on = (not isBundle) and isEquipped(desc, assetTypeName(item.AssetType), item.Id)
        badge.Visible = on
        stroke.Color = on and pal().Accent or pal().Stroke
        stroke.Thickness = on and 2 or 1
        stroke.Transparency = on and 0 or 0.65
    end
    frame.MouseButton1Down:Connect(function()
        KeyTweenService:Create(scale, TweenInfo.new(0.08), { Scale = 0.95 }):Play()
    end)
    frame.MouseButton1Up:Connect(function()
        KeyTweenService:Create(scale, TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
    end)
    frame.MouseLeave:Connect(function()
        KeyTweenService:Create(scale, TweenInfo.new(0.12), { Scale = 1 }):Play()
    end)
    frame.MouseButton1Click:Connect(function()
        if isBundle then
            applyBundle(item, AC.BundleParts)
        else
            toggleAsset(item.Id, assetTypeName(item.AssetType), item.Name)
        end
    end)
    AC.Tiles[#AC.Tiles + 1] = tile
    return tile
end

local function currentCategory()
    for _, cat in ipairs(CATEGORIES[AC.Mode] or {}) do
        if cat[1] == AC.Category[AC.Mode] then
            return cat
        end
    end
    return nil
end

local function addPage(page)
    local desc = currentDescription()
    for _, item in ipairs(page or {}) do
        local isBundle = item.ItemType == "Bundle"
        local cat = currentCategory()
        local wantBundles = cat and cat[5] ~= nil
        if (isBundle and wantBundles) or (not isBundle and not wantBundles) then
            local tile = makeTile(item, #AC.Tiles + 1, isBundle)
            tile.Refresh(desc)
        end
    end
end

local function enumList(enumType, names)
    local list = {}
    for _, name in ipairs(names or {}) do
        local ok, enumItem = pcall(function() return enumType[name] end)
        if ok and enumItem then
            list[#list + 1] = enumItem
        end
    end
    return list
end

local function resultsText()
    return #AC.Tiles .. " resultados · tocá para ponerte o quitarte", #AC.Tiles .. " results · tap to wear or remove"
end

local function search()
    if AC.Mode == "worn" then return end
    AC.Token += 1
    local token = AC.Token
    clearTiles()
    AC.Pages = nil
    W.More.Visible = false
    W.Empty.Visible = false
    setStatus("Buscando en el catálogo...", "Searching the catalog...", Color3.fromRGB(195, 215, 255))
    local cat = currentCategory()
    AC.BundleParts = cat and cat[6] or nil -- partes que aplica cada paquete en esta categoria
    task.spawn(function()
        local ok, pages = pcall(function()
            local params = CatalogSearchParams.new()
            params.SearchKeyword = W.Search.Text or ""
            if cat and cat[5] then
                params.BundleTypes = enumList(Enum.BundleType, cat[5])
            else
                params.AssetTypes = enumList(Enum.AvatarAssetType, cat and cat[4] or {})
            end
            pcall(function() params.Limit = 30 end)
            local hasAsync = pcall(function() return AvatarEditorService.SearchCatalogAsync end)
            if hasAsync then
                return AvatarEditorService:SearchCatalogAsync(params)
            end
            return AvatarEditorService:SearchCatalog(params)
        end)
        if token ~= AC.Token then return end
        if not ok or not pages then
            setStatus("El catálogo no respondió. Probá de nuevo.", "The catalog did not respond. Try again.", Color3.fromRGB(255, 135, 135))
            warn("[Catálogo] SearchCatalogAsync:", pages)
            return
        end
        AC.Pages = pages
        local okPage, page = pcall(function() return pages:GetCurrentPage() end)
        if not okPage then
            setStatus("No se pudo leer el catálogo.", "Could not read the catalog.", Color3.fromRGB(255, 135, 135))
            return
        end
        addPage(page)
        W.More.Visible = not pages.IsFinished
        W.Empty.Visible = #AC.Tiles == 0
        if #AC.Tiles == 0 then
            setStatus("Sin resultados.", "No results.", Color3.fromRGB(255, 190, 120))
        else
            setStatus(resultsText())
        end
    end)
end

local function loadMore()
    local pages = AC.Pages
    if not pages or pages.IsFinished then return end
    local token = AC.Token
    W.More.Visible = false
    setStatus("Cargando más...", "Loading more...", Color3.fromRGB(195, 215, 255))
    task.spawn(function()
        local ok = pcall(function() pages:AdvanceToNextPageAsync() end)
        if token ~= AC.Token then return end
        if ok then
            local okPage, page = pcall(function() return pages:GetCurrentPage() end)
            if okPage then addPage(page) end
        end
        W.More.Visible = not pages.IsFinished
        setStatus(resultsText())
    end)
end

-- pestaña "Puesto": todo lo que tiene el avatar ahora, tocás y se quita
renderWorn = function()
    clearTiles()
    W.More.Visible = false
    local desc = currentDescription()
    if not desc then
        W.Empty.Visible = true
        setStatus("No se encontró tu rig visual (entrá a una partida).", "Your visual rig was not found (join a match).", Color3.fromRGB(255, 135, 135))
        return
    end
    local order = 0
    for assetType, map in pairs(ASSET_PROPS) do
        local ids = map[2] and idList(desc[map[1]]) or ((tonumber(desc[map[1]]) or 0) > 0 and { tostring(desc[map[1]]) } or {})
        for _, id in ipairs(ids) do
            order += 1
            local names = TYPE_NAMES[assetType] or { assetType, assetType }
            local tile = makeTile({ Id = id, Name = scriptText(names[1], names[2]), AssetType = assetType, Price = -1 }, order, false)
            tile.Refresh(desc)
        end
    end
    for _, entry in ipairs(layeredList(desc)) do
        local assetType = nil
        for typeName, accName in pairs(LAYERED) do
            local okEnum, enumItem = pcall(function() return Enum.AccessoryType[accName] end)
            if okEnum and enumItem == entry.AccessoryType then
                assetType = typeName
            end
        end
        if assetType then
            order += 1
            local names = TYPE_NAMES[assetType] or { assetType, assetType }
            local tile = makeTile({ Id = entry.AssetId, Name = scriptText(names[1], names[2]), AssetType = assetType, Price = -1 }, order, false)
            tile.Refresh(desc)
        end
    end
    W.Empty.Visible = order == 0
    setStatus(order .. " cosas puestas · tocá una para quitarla", order .. " items worn · tap one to remove it", Color3.fromRGB(180, 180, 190))
end

local function refreshChips()
    for key, chip in pairs(W.Chips) do
        local active = chip.Mode == AC.Mode and key == chip.Mode .. ":" .. AC.Category[AC.Mode]
        chip.Button.Visible = chip.Mode == AC.Mode
        chip.Button.BackgroundColor3 = active and pal().Accent or pal().Secondary
        chip.Button.BackgroundTransparency = active and 0.05 or 0.45
        chip.Label.TextColor3 = active and AvatarContrastColor(pal().Accent) or pal().Text
    end
    for key, tab in pairs(W.Tabs) do
        local active = key == AC.Mode
        tab.Button.BackgroundColor3 = active and pal().Accent or pal().Background
        tab.Button.BackgroundTransparency = active and 0 or 1
        tab.Label.TextColor3 = active and AvatarContrastColor(pal().Accent) or pal().TextDim
    end
    for key, chip in pairs(W.SkinChips) do
        local active = key == AC.SkinTarget
        chip.BackgroundColor3 = active and pal().Accent or pal().Secondary
        chip.BackgroundTransparency = active and 0.05 or 0.45
        chip.TextColor3 = active and AvatarContrastColor(pal().Accent) or pal().Text
    end
end

-- acomoda la columna derecha segun el modo (buscador / chips / piel / resultados)
local function layoutRight()
    local y = 0
    local showSearch = AC.Mode ~= "worn"
    W.SearchHolder.Visible = showSearch
    W.ChipScroll.Visible = showSearch
    W.SkinRow.Visible = AC.Mode == "body"
    if showSearch then
        W.SearchHolder.Position = UDim2.fromOffset(0, y)
        y += 40
        W.ChipScroll.Position = UDim2.fromOffset(0, y)
        y += 34
    end
    if AC.Mode == "body" then
        W.SkinRow.Position = UDim2.fromOffset(0, y)
        y += 64
    end
    W.Results.Position = UDim2.fromOffset(0, y)
    W.Results.Size = UDim2.new(1, 0, 1, -y)
end

local function setMode(mode)
    if AC.Mode == mode then return end
    AC.Mode = mode
    AC.Token += 1
    layoutRight()
    refreshChips()
    if mode == "worn" then
        renderWorn()
    else
        search()
    end
end

local function chipButton(parent, es, en, order)
    local b = new("TextButton", {
        Size = UDim2.fromOffset(0, 26),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        AutoButtonColor = false,
        Text = "",
        LayoutOrder = order,
        ZIndex = 282,
    }, parent)
    corner(b, 13)
    new("UIPadding", { PaddingLeft = UDim.new(0, 11), PaddingRight = UDim.new(0, 11) }, b)
    local l = new("TextLabel", {
        Size = UDim2.fromOffset(0, 26),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        Text = scriptText(es, en),
        TextSize = 11,
        Font = Enum.Font.GothamBold,
        ZIndex = 283,
    }, b)
    l:SetAttribute("TextSpanish", es)
    l:SetAttribute("TextEnglish", en)
    l:SetAttribute("IgnoreTextEffect", true)
    return b, l
end

local function build(mainFrame)
    -- Ventana flotante y movible: va directo en el ScreenGui de la libreria porque "Main" recorta
    -- (ClipsDescendants) todo lo que sale de sus bordes. El tamaño y la posicion se calculan al abrir.
    local screenGui = mainFrame:FindFirstAncestorOfClass("ScreenGui") or mainFrame
    W.Main = mainFrame
    W.ScreenGui = screenGui
    W.Overlay = new("Frame", {
        Name = "AvatarCatalogOverlay",
        Size = UDim2.fromOffset(640, 400),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Visible = false,
        ZIndex = 278,
    }, screenGui)
    local panel = new("Frame", {
        Size = UDim2.new(1, 0, 1, 0),
        Position = UDim2.new(0.5, 0, 0.5, 0),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = pal().Background,
        BorderSizePixel = 0,
        Active = true,
        ZIndex = 279,
    }, W.Overlay)
    panel:SetAttribute("ThemeRole", "Background")
    corner(panel, 16)
    local panelStroke = new("UIStroke", { Color = pal().Accent, Thickness = 1.5, Transparency = 0.35 }, panel)
    panelStroke:SetAttribute("ThemeRole", "Accent")
    W.PanelScale = new("UIScale", { Scale = 1 }, panel)

    -- arrastrar la ventana desde la franja de arriba (los botones de arriba quedan por encima y siguen andando)
    -- asa: boton invisible ENCIMA del titulo (zona izquierda) + franja fina arriba de todo;
    -- las pestañas y la X quedan fuera del asa y siguen funcionando
    local dragHandle = new("TextButton", {
        Name = "DragHandle",
        Text = "",
        AutoButtonColor = false,
        Size = UDim2.new(0.5, 0, 0, 50),
        BackgroundTransparency = 1,
        ZIndex = 284,
    }, panel)
    local dragStrip = new("TextButton", {
        Name = "DragStrip",
        Text = "",
        AutoButtonColor = false,
        Size = UDim2.new(1, 0, 0, 8),
        BackgroundTransparency = 1,
        ZIndex = 284,
    }, panel)
    local grip = new("Frame", {
        AnchorPoint = Vector2.new(0.5, 0),
        Size = UDim2.fromOffset(44, 4),
        Position = UDim2.new(0.5, 0, 0, 5),
        BackgroundColor3 = pal().TextDim,
        BackgroundTransparency = 0.5,
        BorderSizePixel = 0,
        ZIndex = 281,
    }, panel)
    grip:SetAttribute("ThemeRole", "TextDim")
    corner(grip, 2)
    local moving, moveStart, moveFrom = false, nil, nil
    -- deja siempre la barra de arriba dentro de la pantalla (para poder agarrarla)
    function W.ClampWindow()
        local screen = W.ScreenGui.AbsoluteSize
        local size = W.Overlay.Size
        local maxX = screen.X - 120
        if maxX < 0 then maxX = 0 end
        local maxY = screen.Y - 60
        if maxY < 0 then maxY = 0 end
        local minX = -size.X.Offset + 120
        if minX > maxX then minX = maxX end
        local x = math.clamp(W.Overlay.Position.X.Offset, minX, maxX)
        local y = math.clamp(W.Overlay.Position.Y.Offset, 0, maxY)
        W.Overlay.Position = UDim2.fromOffset(x, y)
    end
    local function beginMove(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            moving = true
            moveStart = input.Position
            moveFrom = W.Overlay.Position
            grip.BackgroundTransparency = 0.1
        end
    end
    dragHandle.InputBegan:Connect(beginMove)
    dragStrip.InputBegan:Connect(beginMove)
    UserInputService.InputChanged:Connect(function(input)
        if not moving then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local delta = input.Position - moveStart
        W.Overlay.Position = UDim2.fromOffset(moveFrom.X.Offset + delta.X, moveFrom.Y.Offset + delta.Y)
        W.ClampWindow()
    end)
    UserInputService.InputEnded:Connect(function(input)
        if moving and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
            moving = false
            grip.BackgroundTransparency = 0.5
        end
    end)

    -- cabecera: titulo + estado + pestañas + cerrar
    text(panel, "CATÁLOGO DE AVATAR", "AVATAR CATALOG", 15, Enum.Font.GothamBlack, "Text", {
        Size = UDim2.new(0.45, 0, 0, 22), Position = UDim2.fromOffset(16, 9),
    })
    W.Status = text(panel, "", "", 10, Enum.Font.GothamMedium, "TextDim", {
        Size = UDim2.new(0.45, 0, 0, 14), Position = UDim2.fromOffset(16, 31),
    })
    W.Status:SetAttribute("ThemeTextRole", nil)

    local tabBar = new("Frame", {
        AnchorPoint = Vector2.new(1, 0),
        Size = UDim2.fromOffset(0, 32),
        AutomaticSize = Enum.AutomaticSize.X,
        Position = UDim2.new(1, -52, 0, 9),
        BackgroundColor3 = pal().Secondary,
        BackgroundTransparency = 0.2,
        BorderSizePixel = 0,
        ZIndex = 281,
    }, panel)
    tabBar:SetAttribute("ThemeRole", "Secondary")
    corner(tabBar, 16)
    new("UIPadding", { PaddingLeft = UDim.new(0, 3), PaddingRight = UDim.new(0, 3) }, tabBar)
    new("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Padding = UDim.new(0, 2),
        SortOrder = Enum.SortOrder.LayoutOrder,
    }, tabBar)
    W.Tabs = {}
    for order, info in ipairs({ { "catalog", "Ropa", "Clothes" }, { "body", "Cuerpo", "Body" }, { "worn", "Puesto", "Worn" } }) do
        local b, l = chipButton(tabBar, info[2], info[3], order)
        W.Tabs[info[1]] = { Button = b, Label = l }
        b.Activated:Connect(function() setMode(info[1]) end)
    end

