-- Headless: se esconde la cabeza y la cara del rig visual EN CADA FRAME (RenderStepped), en R6 y R15.
-- Antes se intentaba poner la cabeza Headless (15093053680, solo R15) con ApplyDescription y esto era un respaldo de
-- una sola vez: en R6 no fallaba, así que no se escondía nada, y Evade vuelve a poner LocalTransparencyModifier = 0.
-- Cada frame se busca el rig de nuevo, así sigue funcionando si Evade arma uno nuevo. Al apagar se devuelve todo.
function SetHeadlessFallback(visualRig, enabled)
    local state = CustomBodyPartState.HeadlessFallback
    if enabled then
        state.Active = true
        if not state.Conn then
            state.Conn = RunService.RenderStepped:Connect(function()
                local rig = YYAvatarCurrentRig
                if not (rig and rig.Parent) then rig = GetAvatarVisualHumanoid() end
                local head = rig and rig:FindFirstChild("Head")
                if not head or not head:IsA("BasePart") then return end
                head.LocalTransparencyModifier = 1
                for _, child in ipairs(head:GetChildren()) do
                    if child:IsA("Decal") then
                        if state.Faces[child] == nil then state.Faces[child] = child.Transparency end
                        child.Transparency = 1
                    end
                end
            end)
        end
        return true
    end
    if state.Conn then
        pcall(function() state.Conn:Disconnect() end)
    end
    for decal, transparency in pairs(state.Faces) do
        pcall(function()
            if decal.Parent then decal.Transparency = transparency end
        end)
    end
    pcall(function()
        local rig = visualRig or GetAvatarVisualHumanoid()
        local head = rig and rig:FindFirstChild("Head")
        if head and head:IsA("BasePart") then head.LocalTransparencyModifier = 0 end
    end)
    CustomBodyPartState.HeadlessFallback = {
        Active = false,
        Conn = nil,
        Faces = {},
    }
    return true
end

-- Korblox: solo ApplyDescription (cambia lo distinto). Antes, si el rig tenía HumanoidRootPart, se usaba primero
-- ApplyDescriptionReset (reconstruye todo el cuerpo) y las uniones de rig.Joints quedaban en las piezas viejas.
-- Sin HumanoidRootPart (R15 de Evade) se usa AvatarApplyDescriptionSafe, que pone la raíz temporal.
function YYAvatarApplyPart(humanoid, description)
    local rig = humanoid and humanoid.Parent
    if rig and not rig:FindFirstChild("HumanoidRootPart") then
        return AvatarApplyDescriptionSafe(humanoid, description)
    end
    local ok, err = pcall(function()
        humanoid:ApplyDescription(description)
    end)
    pcall(AvatarRepairRigJoints, rig)
    if ok then
        return true, nil
    end
    warn("[Avatar] ApplyDescription (pieza):", err)
    return false, tostring(err)
end

function ApplyCustomBodyPart(partInfo, enabled)
    local visualRig, visualHumanoid = GetAvatarVisualHumanoid()
    if not visualRig or not visualHumanoid then
        SetAvatarStatus("No se encontró el rig visual (entrá a una partida).", "The visual rig was not found (join a match).", Color3.fromRGB(255, 135, 135))
        return false
    end

    if partInfo.Property == "Head" then
        SetHeadlessFallback(visualRig, enabled)
        SetAvatarStatus(
            enabled and "Cabeza invisible aplicada." or "Cabeza restaurada.",
            enabled and "Invisible head applied." or "Head restored.",
            enabled and Color3.fromRGB(145, 255, 180) or Color3.fromRGB(180, 180, 190)
        )
        return true
    end

    local okDescription, descriptionOrError = pcall(function()
        return visualHumanoid:GetAppliedDescription()
    end)
    if not okDescription or not descriptionOrError then
        SetAvatarStatus("No se pudo leer el avatar actual.", "The current avatar description could not be read.", Color3.fromRGB(255, 135, 135))
        warn("[Avatar] GetAppliedDescription error:", descriptionOrError)
        return false
    end

    if enabled then
        if CustomBodyPartState.Saved[partInfo.Property] == nil then
            CustomBodyPartState.Saved[partInfo.Property] = descriptionOrError[partInfo.Property]
        end
        descriptionOrError[partInfo.Property] = partInfo.AssetId
        SetAvatarStatus("Aplicando " .. partInfo.Spanish .. "...", "Applying " .. partInfo.English .. "...", Color3.fromRGB(195, 215, 255))
    else
        descriptionOrError[partInfo.Property] = CustomBodyPartState.Saved[partInfo.Property] or 0
        CustomBodyPartState.Saved[partInfo.Property] = nil
        if partInfo.Property == "Head" and CustomBodyPartState.HeadlessFallback.Active then
            SetHeadlessFallback(visualRig, false)
        end
    end

    local okApply, applyError = YYAvatarApplyPart(visualHumanoid, descriptionOrError)
    if not okApply then
        if enabled and partInfo.Property == "Head" and SetHeadlessFallback(visualRig, true) then
            SetAvatarStatus("Cabeza invisible aplicada localmente.", "Headless fallback applied locally.", Color3.fromRGB(145, 255, 180))
            warn("[Avatar] Headless Dynamic Head fallback used:", applyError)
            return true
        end
        SetAvatarStatus("No se pudo aplicar la pieza: " .. AvatarShortError(applyError),
            "The body part could not be applied: " .. AvatarShortError(applyError), Color3.fromRGB(255, 135, 135))
        return false
    end

    SetAvatarStatus(
        enabled and "Pieza aplicada al rig visual." or "Pieza restaurada.",
        enabled and "Body part applied to the visual rig." or "Body part restored.",
        enabled and Color3.fromRGB(145, 255, 180) or Color3.fromRGB(180, 180, 190)
    )
    return true
end

