local HeadlessDeletedToggle

local function RemoveHeadAccessories(visualRig)
    local typeNames = { Hat = true, Hair = true, Face = true, Eyebrow = true, Eyelash = true }
    local attachmentNames = { HatAttachment = true, HairAttachment = true, FaceFrontAttachment = true, FaceCenterAttachment = true }
    local removed = 0
    for _, child in ipairs(visualRig:GetChildren()) do
        if child:IsA("Accessory") then
            local isHeadItem = false
            local okType, accessoryType = pcall(function()
                return child.AccessoryType
            end)
            if okType and accessoryType and typeNames[accessoryType.Name] then
                isHeadItem = true
            end
            if not isHeadItem then
                local handle = child:FindFirstChild("Handle")
                local attachment = handle and handle:FindFirstChildOfClass("Attachment")
                if attachment and attachmentNames[attachment.Name] then
                    isHeadItem = true
                end
            end
            if isHeadItem then
                child:Destroy()
                removed = removed + 1
            end
        end
    end
    return removed
end

HeadlessDeletedToggle = TabAvatar:CreateToggle(
    "Headless + Deleted",
    "Headless + Deleted",
    false,
    function(enabled)
        if enabled and HeadlessHeadToggle and HeadlessHeadToggle.GetValue() then
            HeadlessHeadToggle.SetValue(false)
        end
        local ok = ApplyCustomBodyPart(CustomBodyParts.Headless, enabled)
        if not ok then
            if enabled then
                HeadlessDeletedToggle.SetValue(false)
            end
            return
        end
        pcall(YYAvatarBump)
        if enabled then
            local visualRig = GetAvatarVisualHumanoid()
            if visualRig then
                RemoveHeadAccessories(visualRig)
                SetAvatarStatus(
                    "Headless aplicada y accesorios de la cabeza eliminados.",
                    "Headless applied and head accessories removed.",
                    Color3.fromRGB(145, 255, 180)
                )
            end
        end
    end
)
end

print("\nConfiguring Move tab...")

local lastSpeedSelf, lastSpeedState, lastSpeedValue = nil, nil, nil
getgenv().YYSpeedRestoreRequested = false
getgenv().YYRestoreSpeedMultiplier = nil

do
    local FakeTrimp = {
        Enabled = false,
        MovementType = "Camera",
        CameraDirection = Vector3.new(0, 0, -1),
        SmoothAcceleration = true,
        SpeedAcceleration = 9,
        MaxSpeed = 99,
        State = { MoveDir = Vector3.new(1, 0, 0) }
    }

    local currentSpeed = 0
    local currentDir = Vector3.new(1, 0, 0)
    local oldUpdate = nil
    local DaraTrimpToggle = nil

    -- Ajuste PC (verificado con Death Log en Solara): en Solara require() crea una COPIA del módulo
    -- Movement y en el siguiente spawn SharedUIService:69 falla y el personaje muere. Por eso en Solara
    -- NUNCA se llama a require(); en el resto (celular) todo sigue igual que antes.
    local trimpSafeMode = false
    pcall(function()
        if identifyexecutor then
            trimpSafeMode = string.find(string.lower(tostring(identifyexecutor())), "solara", 1, true) ~= nil
        end
    end)

    local movementOk, Movement = false, nil
    if not trimpSafeMode then
        movementOk, Movement = pcall(function()
            return require(ReplicatedStorage.Objects.Game.Character.Client.Movement)
        end)
    end
    local trimpReady = movementOk and type(Movement) == "table" and Movement.Update ~= nil

    local function FakeTimpUpdate(self, dt)
        oldUpdate(self, dt)
        if not FakeTrimp.Enabled then
            currentSpeed = 0
            return
        end

        local hrp = self.Character and self.Character:FindFirstChild("HumanoidRootPart")
        local humanoid = self.Character and self.Character:FindFirstChildOfClass("Humanoid")
        if not hrp or not humanoid then return end

        local moveDir = Vector3.new()
        if FakeTrimp.MovementType == "Camera" then
            local cam = workspace.CurrentCamera
            if cam then
                local lookDir = cam.CFrame:VectorToWorldSpace(FakeTrimp.CameraDirection)
                moveDir = Vector3.new(lookDir.X, 0, lookDir.Z).Unit
            end
        else
            moveDir = humanoid.MoveDirection
        end

        if moveDir.Magnitude > 0 then
            FakeTrimp.State.MoveDir = moveDir.Unit
        end

        currentDir = FakeTrimp.State.MoveDir
        local targetSpeed = FakeTrimp.MaxSpeed * 90

        if FakeTrimp.SmoothAcceleration then
            currentSpeed = currentSpeed + (targetSpeed - currentSpeed) * math.min(FakeTrimp.SpeedAcceleration * dt, 1)
        else
            currentSpeed = targetSpeed
        end

        local newVelocity = currentDir * currentSpeed
        self.DataRegistry:Set("Velocity", newVelocity)

        local horizontal = Vector3.new(newVelocity.X, 0, newVelocity.Z) / 90
        hrp.AssemblyLinearVelocity = Vector3.new(horizontal.X, hrp.AssemblyLinearVelocity.Y, horizontal.Z)
    end

    if trimpReady and not oldUpdate then
        oldUpdate = Movement.Update
        Movement.Update = FakeTimpUpdate
    end

    -- Modo PC (Solara): misma cuenta que FakeTimpUpdate pero sin tocar el módulo del juego;
    -- la velocidad horizontal se aplica al HumanoidRootPart en Stepped (antes de la física). La vertical no se toca.
    if trimpSafeMode then
        trimpReady = true
        game:GetService("RunService").Stepped:Connect(function(_, dt)
            if not FakeTrimp.Enabled then
                currentSpeed = 0
                return
            end
            local character = game:GetService("Players").LocalPlayer.Character
            local hrp = character and character:FindFirstChild("HumanoidRootPart")
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if not hrp or not humanoid or humanoid.Health <= 0 then return end

            local moveDir = Vector3.new()
            if FakeTrimp.MovementType == "Camera" then
                local cam = workspace.CurrentCamera
                if cam then
                    local lookDir = cam.CFrame:VectorToWorldSpace(FakeTrimp.CameraDirection)
                    moveDir = Vector3.new(lookDir.X, 0, lookDir.Z).Unit
                end
            else
                moveDir = humanoid.MoveDirection
            end
            if moveDir.Magnitude > 0 then
                FakeTrimp.State.MoveDir = moveDir.Unit
            end

            currentDir = FakeTrimp.State.MoveDir
            local targetSpeed = FakeTrimp.MaxSpeed * 90
            if FakeTrimp.SmoothAcceleration then
                currentSpeed = currentSpeed + (targetSpeed - currentSpeed) * math.min(FakeTrimp.SpeedAcceleration * dt, 1)
            else
                currentSpeed = targetSpeed
            end

            local newVelocity = currentDir * currentSpeed
            local horizontal = Vector3.new(newVelocity.X, 0, newVelocity.Z) / 90
            hrp.AssemblyLinearVelocity = Vector3.new(horizontal.X, hrp.AssemblyLinearVelocity.Y, horizontal.Z)
        end)
    end

    YYPlace(TabMove, 3.10)
    DaraTrimpToggle = TabMove:CreateFloatingToggle(
        "Dara Trimp",
        "Dara Trimp",
        false,
        function(enabled)
            if not trimpReady then
                if enabled and DaraTrimpToggle then DaraTrimpToggle.SetValue(false) end
                warn("[Dara Trimp] No disponible: no se encontro ReplicatedStorage.Objects.Game.Character.Client.Movement en este juego")
                return
            end
            FakeTrimp.Enabled = enabled
            if not enabled then currentSpeed = 0 end
        end,
        {
            imageId = "rbxassetid://77466337396355",
            name = "Darks",
            description = "Thanks to one of the creators of dara hub for contributing with us!"
        }
    )

    TabMove:CreateSlider(
        "Speed",
        1, 200, FakeTrimp.MaxSpeed,
        function(value)
            FakeTrimp.MaxSpeed = tonumber(value) or 99
        end
    )

    TabMove:CreateSlider(
        "Accel",
        1, 30, FakeTrimp.SpeedAcceleration,
        function(value)
            FakeTrimp.SpeedAcceleration = tonumber(value) or 9
        end
    )

    TabMove:CreateToggle(
        "Suave",
        "Smooth",
        FakeTrimp.SmoothAcceleration,
        function(enabled)
            FakeTrimp.SmoothAcceleration = enabled
        end
    )

    TabMove:CreateToggle(
        "Seguir movimiento",
        "Follow Movement",
        false,
        function(enabled)
            FakeTrimp.MovementType = enabled and "Humanoid" or "Camera"
        end
    )
    -- fix12: la tecla Q prendía/apagaba el Fake Trimp sin que nadie lo pidiera. Ahora solo funciona si se prende este toggle.
    TabMove:CreateToggle(
        "Atajo Q",
        "Q Shortcut",
        false,
        function(enabled)
            FakeTrimp.QHotkey = enabled == true
        end
    )
    TabMove:CreateDivider()

    UserInputService.InputBegan:Connect(function(input, gpe)
        if gpe then return end
        if input.KeyCode == Enum.KeyCode.Q then
            if not FakeTrimp.QHotkey then return end
            if not trimpReady then return end
            FakeTrimp.Enabled = not FakeTrimp.Enabled
            if not FakeTrimp.Enabled then currentSpeed = 0 end
            if DaraTrimpToggle then DaraTrimpToggle.SetValue(FakeTrimp.Enabled) end
            pcall(YYPersistSet, "Move|T|Dara Trimp", FakeTrimp.Enabled == true)
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "Fake Trimp",
                Text = FakeTrimp.Enabled and "ON" or "OFF",
                Duration = 2
            })
        end
    end)
end

-- ===== TRIMP x FRONTAL (v51) =====
-- Junta lo mejor de las dos:
--   * Movimiento = Dara Trimp: velocidad horizontal hacia donde mira la cámara (o hacia donde caminás), con aceleración
--     suave hasta la velocidad máxima. Se aplica igual que Dara: DataRegistry "Velocity" (x90) + velocidad del
--     HumanoidRootPart, dentro de Movement.Update (en Solara, sin require: en Stepped, como el modo PC de Dara).
--   * Salto = multiplicador de Salto frontal: si en el piso hay una rampa/obstáculo adelante (rayo de 10 studs, como
--     ActivateFrontalJump) salta solo y 0,1 s después pone la velocidad vertical = Fuerza x Multiplicador x 0,8
--     (la misma cuenta de Salto frontal: FrontalJumpSpeed * RampMultiplier * 0.8).
-- v54: nunca salta en piso plano: solo con rampa u obstáculo adelante (rayo a la rodilla, sin jugadores/bots). En el
-- aire, contra un obstáculo lo usa de rampa (como Impulso de salto: no se traba). "Potenciar mis saltos" apagado de
-- fábrica y solo actúa si apretaste saltar de verdad.
do
    local TXF = {
        Enabled = false, MaxSpeed = 99, Accel = 9, Smooth = true, FollowMove = false,
        JumpPower = 42, JumpMult = 1.55, BoostManual = false,
        Speed = 0, Dir = Vector3.new(1, 0, 0), LastAuto = 0, LastAir = 0, WasGrounded = true, OurJumpUntil = 0, Toggle = nil,
    }
    local safeMode = false
    pcall(function()
        if identifyexecutor then
            safeMode = string.find(string.lower(tostring(identifyexecutor())), "solara", 1, true) ~= nil
        end
    end)
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    -- v55: ignorar partes sin colisión (zonas invisibles, efectos, decoración atravesable): antes las tomaba como
    -- obstáculo y a veces saltaba en el piso
    pcall(function() rp.RespectCanCollide = true end)

    local function boostVy()
        return TXF.JumpPower * TXF.JumpMult * 0.8
    end
    local function applyVy(root, vy)
        pcall(function()
            local v = root.AssemblyLinearVelocity
            if v.Y < vy then root.AssemblyLinearVelocity = Vector3.new(v.X, vy, v.Z) end
        end)
    end
    local function wantedDir(humanoid)
        if TXF.FollowMove then
            local md = humanoid.MoveDirection
            return md.Magnitude > 0.05 and Vector3.new(md.X, 0, md.Z).Unit or nil
        end
        local cam = workspace.CurrentCamera
        if not cam then return nil end
        local look = cam.CFrame.LookVector
        local f = Vector3.new(look.X, 0, look.Z)
        return f.Magnitude > 0.05 and f.Unit or nil
    end

    -- un paso: movimiento (Dara) + saltos (Frontal). registry/grounded salen de Movement si existe.
    -- v54: obstáculo/rampa adelante. Rayo a la altura de la rodilla (no ve el piso plano ni cordones bajos) y se
    -- ignoran jugadores y bots. Plano (normal hacia arriba) = nada. Rampa o pared = se usa de rampa (como Salto
    -- frontal / Impulso de salto). Devuelve el golpe y si es rampa inclinada.
    local function obstacleAhead(char, root, dir, speed)
        local ex = { char }
        local pl = workspace:FindFirstChild("Players")
        if pl then ex[#ex + 1] = pl end
        local rigs = workspace:FindFirstChild("Rigs")
        if rigs then ex[#ex + 1] = rigs end
        local vb = workspace:FindFirstChild("YY_BotSpawnVisual")
        if vb then ex[#ex + 1] = vb end
        rp.FilterDescendantsInstances = ex
        local dist = math.clamp(speed * 0.15, 5, 12)
        local hit = workspace:Raycast(root.Position - Vector3.new(0, 1.5, 0), dir * dist, rp)
        -- v55: pendientes suaves que se caminan normal (menos de ~25°) no cuentan como rampa
        if not hit or hit.Normal.Y > 0.9 then return nil end
        local isRamp = hit.Normal.Y >= 0.2
        if not isRamp then
            local n = Vector3.new(hit.Normal.X, 0, hit.Normal.Z)
            if n.Magnitude > 0.05 and dir:Dot(-n.Unit) < 0.3 then return nil end -- pared de costado: no
        end
        return hit, isRamp
    end

    -- un paso: movimiento (Dara) + rampa con multiplicador (Frontal). Nunca salta en piso plano.
    local function step(char, root, humanoid, dt, registry, grounded, jumpFn, jumpHeld)
        local dir = wantedDir(humanoid)
        local moving = dir ~= nil and (not TXF.FollowMove or humanoid.MoveDirection.Magnitude > 0.05)
        if dir then TXF.Dir = dir end
        local target = moving and TXF.MaxSpeed or 0
        if TXF.Smooth then
            -- sube con "Accel"; al soltar frena más suave (no se corta en seco)
            local rate = target > TXF.Speed and TXF.Accel or TXF.Accel * 0.6
            TXF.Speed = TXF.Speed + (target - TXF.Speed) * math.min(rate * dt, 1)
        else
            TXF.Speed = target
        end
        local vel = TXF.Dir * TXF.Speed
        if registry then pcall(function() registry:Set("Velocity", vel * 90) end) end
        local cur = root.AssemblyLinearVelocity
        root.AssemblyLinearVelocity = Vector3.new(vel.X, cur.Y, vel.Z)

        local now = os.clock()
        if moving and TXF.Speed > 3 then
            local hit = obstacleAhead(char, root, TXF.Dir, TXF.Speed)
            -- v55: el obstáculo tiene que verse 2 cuadros seguidos (descarta objetos que pasan de golpe o un rayo suelto)
            TXF.Seen = hit and (TXF.Seen or 0) + 1 or 0
            if TXF.Seen < 2 then hit = nil end
            if hit then
                if grounded and now - TXF.LastAuto > 0.45 then
                    -- en el piso con rampa/obstáculo adelante: salto con multiplicador (cuenta de Salto frontal)
                    TXF.LastAuto = now
                    TXF.OurJumpUntil = now + 0.4
                    jumpFn()
                    task.delay(0.1, function()
                        if root.Parent then applyVy(root, boostVy()) end
                    end)
                elseif not grounded and now - TXF.LastAir > 0.3 then
                    -- en el aire contra un obstáculo: lo usa de rampa (sube y sigue, no se traba)
                    TXF.LastAir = now
                    applyVy(root, boostVy() * 0.6)
                end
            end
        end
        -- tus saltos (solo si apretaste saltar de verdad) con el multiplicador
        if TXF.BoostManual and jumpHeld and TXF.WasGrounded and not grounded and now > TXF.OurJumpUntil then
            TXF.OurJumpUntil = now + 0.4
            applyVy(root, boostVy())
        end
        TXF.WasGrounded = grounded
    end

    local ready = false
    if not safeMode then
        local ok, Movement = pcall(function() return require(ReplicatedStorage.Objects.Game.Character.Client.Movement) end)
        if ok and type(Movement) == "table" and type(Movement.Update) == "function" then
            local old = Movement.Update
            ready = pcall(function()
                Movement.Update = function(self, dt, ...)
                    old(self, dt, ...)
                    if not TXF.Enabled then TXF.Speed = 0 return end
                    if not (self.Character and self.Character == LocalPlayer.Character) then return end
                    local hrp = self.Character:FindFirstChild("HumanoidRootPart")
                    local hum = self.Character:FindFirstChildOfClass("Humanoid")
                    if not hrp or not hum or hum.Health <= 0 then return end
                    local okG, g = pcall(function() return self.DataRegistry:Get("Grounded") end)
                    local grounded = (okG and g ~= nil) and (g == true) or hum.FloorMaterial ~= Enum.Material.Air
                    pcall(step, self.Character, hrp, hum, tonumber(dt) or (1 / 60), self.DataRegistry, grounded, function()
                        pcall(function() self:AttemptJump() end)
                    end, self.JumpHeldDown == true)
                end
            end)
        end
    end
    if safeMode then
        ready = true
        RunService.Stepped:Connect(function(_, dt)
            if not TXF.Enabled then TXF.Speed = 0 return end
            local char = LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum or hum.Health <= 0 then return end
            pcall(step, char, hrp, hum, dt, nil, hum.FloorMaterial ~= Enum.Material.Air, function()
                hum:ChangeState(Enum.HumanoidStateType.Jumping)
            end, hum.Jump == true)
        end)
    end

    YYPlace(TabMove, 3.15)
    TXF.Toggle = TabMove:CreateFloatingToggle("Trimp x Frontal", "Trimp x Frontal", false, function(enabled)
        if enabled and not ready then
            warn("[Trimp x Frontal] No disponible: no se encontró el módulo Movement de Evade")
            task.defer(function() if TXF.Toggle and TXF.Toggle.SetValue then TXF.Toggle.SetValue(false) end end)
            return
        end
        TXF.Enabled = enabled == true
        TXF.Speed = 0
        if enabled and Config and Config.EnableFrontalJump then
            pcall(function()
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "Trimp x Frontal",
                    Text = scriptText("Apagá Salto frontal y Dara Trimp: se pisan con esta opción", "Turn off Front Jump and Dara Trimp: they conflict with this"),
                    Duration = 4,
                })
            end)
        end
    end)
    YYSliderNames["TxF Speed"] = "Velocidad TxF"
    YYSliderNames["TxF Accel"] = "Aceleración TxF"
    YYSliderNames["TxF Jump Power"] = "Fuerza salto TxF"
    YYSliderNames["TxF Jump Mult"] = "Multiplicador salto TxF"
    TabMove:CreateSlider("TxF Speed", 1, 200, TXF.MaxSpeed, function(v) TXF.MaxSpeed = tonumber(v) or 99 end)
    TabMove:CreateSlider("TxF Accel", 1, 30, TXF.Accel, function(v) TXF.Accel = tonumber(v) or 9 end)
    TabMove:CreateSlider("TxF Jump Power", 30, 110, TXF.JumpPower, function(v) TXF.JumpPower = tonumber(v) or 42 end)
    TabMove:CreateSlider("TxF Jump Mult", 0.1, 5, TXF.JumpMult, function(v) TXF.JumpMult = tonumber(v) or 1.55 end)
    TabMove:CreateToggle("Suave (TxF)", "Smooth (TxF)", true, function(enabled) TXF.Smooth = enabled ~= false end)
    TabMove:CreateToggle("Seguir movimiento (TxF)", "Follow movement (TxF)", false, function(enabled) TXF.FollowMove = enabled == true end)
    TabMove:CreateToggle("Potenciar mis saltos", "Boost my jumps", false, function(enabled) TXF.BoostManual = enabled == true end)
    TabMove:CreateDivider()
end

YYPlace(TabMove, 6.10)
TabMove:CreateCombinedToggle("Combinado (prueba)", "Combined (test)")
TabMove:CreateDivider()

-- ===== Bunny Hop + Infinite Slide (Dara Hub): UN SOLO hook de Movement.Update, misma logica y misma prioridad que dara =====
-- dara: bhop, slide infinito y wall hop corren en el mismo Movement.Update y comparten lastFriction; el slide tiene prioridad sobre el bhop.
-- La interfaz del Slide Inf esta mas abajo (seccion "SLIDE INFINITO") y usa GENV.YY_DaraMovement.EnsureHook para instalar este mismo hook.
do
    local DARA_DEFAULT_FRICTION = 5           -- dara: defaultMovementValues.Friction
    local autoJumpEnabled = false             -- dara: autoJumpEnabled
    local autoJumpType = "Simulation"         -- dara: autoJumpType
    local bhopHoldEnabled = false             -- dara: bhopHoldEnabled
    local accelerationMethod = "Acceleration" -- dara: accelerationMethod
    local accelerationValue = -0.2            -- dara: accelerationValue
    local autoAccelerationEnabled = false     -- dara: autoAccelerationEnabled
    local maxAcceleration = 3                 -- dara: maxAcceleration
    local minAcceleration = -1                -- dara: minAcceleration
    local maxAutoAccelSpeed = 70              -- dara: maxAutoAccelSpeed
    local AutowallHop = false                 -- dara: AutowallHop
    local lastFriction = nil                  -- dara: lastFriction (compartido por bhop y slide, como en dara)
    local movementHooked = false
    local movementOldUpdate = nil
    local movementCharacterService = nil
    local DaraBhopToggle = nil
    local DaraBhopHoldToggle = nil
    local DaraAutoWallHopToggle = nil
    local slideExit = { Until = 0, Cap = nil, Jumped = false } -- v53/v54: seguro al levantarse del slide
    -- la fricción negativa la pone el slide infinito o el Bunny Hop (Bhop acelerado / Auto acelerar). El seguro de
    -- "te levantaste del slide" solo debe saltar cuando la puso el SLIDE: con la del Bunny Hop frenaba cada salto
    local slideFrictionOn = false

    -- dara: MovementValueSet (aqui el Tag del personaje se lee en cada llamada para no quedar viejo tras respawn)
    local function movementValueSet(movementType, value)
        if not firesignal then return end
        local character = LocalPlayer.Character
        local tag = character and character:GetAttribute("Tag")
        if not tag then return end
        pcall(function()
            firesignal(ReplicatedStorage.Events.CharacterTask.OnClientEvent, tag, "ModifyMovement", { movementType, value })
        end)
    end

    -- dara: getCurrentSpeed (identica)
    local function getCurrentSpeed(character)
        if not character then return 0 end
        local hrp = character:FindFirstChild("HumanoidRootPart")
        if not hrp then return 0 end
        for _, child in ipairs(hrp:GetChildren()) do
            if child:IsA("LinearVelocity") and child.Name:find("LinearVelocity") then
                local pv = child.PlaneVelocity
                return (pv.X * pv.X + pv.Y * pv.Y) ^ 0.5
            end
        end
        local velocity = hrp.AssemblyLinearVelocity
        return (velocity.X * velocity.X + velocity.Z * velocity.Z) ^ 0.5
    end

    -- dara: CharacterService (ReplicatedStorage.Services.Asset.CharacterService), se pide una sola vez
    local function movementGetCharacterService()
        if movementCharacterService then return movementCharacterService end
        local ok, svc = pcall(function()
            local services = ReplicatedStorage:FindFirstChild("Services")
            local asset = services and services:FindFirstChild("Asset")
            local module = asset and asset:FindFirstChild("CharacterService")
            return module and require(module) or nil
        end)
        if ok and svc then movementCharacterService = svc end
        return movementCharacterService
    end

    -- dara: updateBhopEnabled
    local function updateBhopEnabled()
        local shouldEnable = (autoJumpEnabled or bhopHoldEnabled) and accelerationMethod == "Acceleration"
        movementValueSet("BhopEnabled", shouldEnable)
    end

    -- dara: cuerpo del hook de Movement.Update (aislado en una funcion para correrlo con pcall y no romper el Movement del juego)
    local function movementStep(self)
        local humanoid = self.Character and self.Character:FindFirstChild("Humanoid")
        if not humanoid then return end

        local state = nil
        local svc = movementGetCharacterService()
        if svc then
            local charData = svc:GetCharacterFromPlayer(LocalPlayer)
            local movementData = charData and charData.Movement
            state = movementData and movementData.State
        end
        if not state then
            state = self.State
        end
        local grounded = self.DataRegistry:Get("Grounded")

        local desiredFriction = nil

        -- dara: el slide infinito tiene prioridad (friccion = slideFriction)
        local isInfSlide = (state == "Slide" or state == "EmotingSlide" or state == "CarrySlide")
        -- v53: si ya soltaste agacharse, no se vuelve a poner la fricción negativa (te estás levantando)
        if isInfSlide and slideKeyReleased(self) then isInfSlide = false end
        if isInfSlide then
            if Config.EnableInfiniteSlide then
                desiredFriction = -Config.InfiniteSlideBoost
            end
        end
        -- v54: seguro al levantarse (ver arreglo más abajo): durante la ventana se limita velocidad y "pop" vertical
        if not isInfSlide and os.clock() < slideExit.Until then
            pcall(slideExitGuard, self)
        end

        -- dara: el bhop solo actua si el slide no puso friccion
        if desiredFriction == nil and accelerationMethod == "Acceleration" then
            local isBhopActive = autoJumpEnabled or (bhopHoldEnabled and humanoid.Jump == true)
            if isBhopActive and not grounded then
                local currentSpeed = getCurrentSpeed(self.Character)
                if autoAccelerationEnabled then
                    if currentSpeed > maxAutoAccelSpeed then
                        desiredFriction = maxAcceleration
                    elseif currentSpeed < maxAutoAccelSpeed then
                        desiredFriction = minAcceleration
                    else
                        desiredFriction = accelerationValue
                    end
                else
                    desiredFriction = accelerationValue
                end
            end
        end

        slideFrictionOn = isInfSlide and desiredFriction ~= nil
        if desiredFriction ~= lastFriction then
            if desiredFriction ~= nil then
                movementValueSet("Friction", desiredFriction)
            else
                movementValueSet("Friction", DARA_DEFAULT_FRICTION)
            end
            lastFriction = desiredFriction
        end

        if (state == "WallrunRight" or state == "WallrunLeft") and AutowallHop then
            self:AttemptJump()
        end

        if autoJumpEnabled and grounded then
            if autoJumpType == "Realistic" then
                self:AttemptJump()
            else
                humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
            end
        end

        if bhopHoldEnabled and grounded and humanoid.Jump == true then
            self:AttemptJump()
        end
    end

    -- v53: ARREGLO "me manda volando al levantarme del slide". Verificado en el código de Evade:
    --   * Slide (MoveFunction) aplica la fricción x0.1; Run (caminar) la aplica x1 (Helpers.ApplyFriction).
    --   * La fricción del slide infinito es NEGATIVA (-Velocidad slide): suma velocidad en vez de restar.
    --   * Este hook corría DESPUÉS del Update del juego. El frame en que te levantás, el juego ya calculaba Run con
    --     la fricción negativa todavía puesta (x1 = 10 veces más fuerte que en el slide) y además el cambio a
    --     fricción normal viajaba por firesignal (llega un frame después o más). Resultado: un empujón enorme.
    -- Ahora: ANTES del Update del juego, si soltaste agacharse se vuelve a la fricción normal en el acto (directo en
    -- MoveStats, lo mismo que hace el handler ModifyMovement del juego) y, por las dudas, durante 0,35 s la
    -- velocidad no puede superar la que traías en el slide.
    function slideKeyReleased(self)
        local ok, held = pcall(function() return self.DataRegistry:Get("CrouchKey") end)
        return ok and held ~= true
    end
    local function frictionSetDirect(self, value)
        local ms = self and self.MoveStats
        if ms then
            local ok = pcall(function()
                if not ms.Modifiers then ms.Modifiers = {} end
                ms.Modifiers.Friction = value
                ms:Reset()
            end)
            if ok then return end
        end
        movementValueSet("Friction", value)
    end
    -- v54: el v53 no alcanzó. Segunda causa (verificada en StateInfo de Movement): el Slide achica el
    -- HumanoidRootPart (RootSize 2.55) y al levantarte vuelve a su tamaño: la física te "levanta" del piso y en el
    -- AIRE Evade casi no frena (Air solo aplica fricción yendo para atrás). Con la velocidad acumulada del slide
    -- infinito (hasta 5000 = 55 studs/s, el tope del Slide) salís volando hacia adelante.
    -- Ahora, al levantarte: la velocidad se baja al máximo normal de correr del juego (Speed x SprintCap de
    -- MoveStats, ~3000 = 33 studs/s) y, si no apretaste saltar, se anula el "pop" hacia arriba durante 0,4 s.
    -- Si saltás para salir del slide (slide-jump) no se toca la altura.
    function slideExitGuard(self)
        local cap = slideExit.Cap or 3000
        local v = self.DataRegistry:Get("Velocity")
        if typeof(v) == "Vector3" and v.Magnitude > cap then
            self.DataRegistry:Set("Velocity", v.Unit * cap)
        end
        local hrp = self.Character and self.Character:FindFirstChild("HumanoidRootPart")
        if hrp then
            local av = hrp.AssemblyLinearVelocity
            local flatV = Vector3.new(av.X, 0, av.Z)
            local capS = cap / 90
            local vy = av.Y
            if self.JumpHeldDown ~= true and not slideExit.Jumped and vy > 4 then vy = 0 end
            if self.JumpHeldDown == true then slideExit.Jumped = true end
            if flatV.Magnitude > capS then flatV = flatV.Unit * capS end
            if vy ~= av.Y or flatV.Magnitude < Vector3.new(av.X, 0, av.Z).Magnitude - 0.01 then
                hrp.AssemblyLinearVelocity = Vector3.new(flatV.X, vy, flatV.Z)
            end
        end
    end
    local function movementPreStep(self)
        if not (self.Character and self.Character == LocalPlayer.Character) then return end
        if os.clock() < slideExit.Until then pcall(slideExitGuard, self) end
        -- arreglo: solo si la fricción negativa era del SLIDE. La del Bunny Hop también es negativa y, como al saltar
        -- no tenés agacharse apretado, esto creía que te levantabas del slide en cada frame del aire: anulaba la subida
        -- del salto (vy = 0, "choca con un techo") y bajaba la velocidad a la de correr.
        if lastFriction == nil or lastFriction >= 0 or not slideFrictionOn or not slideKeyReleased(self) then return end
        -- estaba la fricción del slide y soltaste agacharse: fricción normal YA, antes de que el juego calcule
        frictionSetDirect(self, DARA_DEFAULT_FRICTION)
        lastFriction = nil
        slideFrictionOn = false
        local runMax = 3000
        pcall(function()
            local st = self.MoveStats.MoveStats
            runMax = (tonumber(st.Speed) or 1500) * (tonumber(st.SprintCap) or 2)
        end)
        slideExit.Cap = runMax
        slideExit.Jumped = self.JumpHeldDown == true
        slideExit.Until = os.clock() + 0.4
        pcall(slideExitGuard, self)
    end

    -- El hook se instala la primera vez que se activa algo (no cuesta nada por frame si nunca se usa)
    local function movementEnsureHook()
        if movementHooked then return true end
        local ok, Movement = pcall(function()
            return require(ReplicatedStorage.Objects.Game.Character.Client.Movement)
        end)
        if not ok or type(Movement) ~= "table" or Movement.Update == nil then return false end

        movementOldUpdate = Movement.Update
        Movement.Update = function(self, ...)
            pcall(movementPreStep, self) -- v53: antes del juego (ver arreglo de arriba)
            movementOldUpdate(self, ...)
            pcall(movementStep, self)
        end
        movementHooked = true
        return true
    end

    -- Lo usa la interfaz del Slide Inf (seccion mas abajo) para instalar este mismo hook
    getgenv().YY_DaraMovement = { EnsureHook = movementEnsureHook }

    -- Al encender algo que necesita el hook: si no se puede instalar, el toggle vuelve a apagarse
    local function movementTryEnable(toggleRef)
        if not firesignal or not movementEnsureHook() then
            if toggleRef and toggleRef.SetValue then toggleRef.SetValue(false) end
            warn("[Bunny Hop] No disponible: falta firesignal o ReplicatedStorage.Objects.Game.Character.Client.Movement en este juego")
            return false
        end
        return true
    end

    -- dara: toggle "Bhop" (ToggleBhop)
    YYPlace(TabMove, 2.30)
    DaraBhopToggle = TabMove:CreateFloatingToggle(
        "Bunny Hop",
        "Bunny Hop",
        false,
        function(enabled)
            if enabled and not movementTryEnable(DaraBhopToggle) then return end
            autoJumpEnabled = enabled
            updateBhopEnabled()
        end,
        {
            imageId = "rbxassetid://77466337396355",
            name = "Darks",
            description = "Thanks to one of the creators of dara hub for contributing with us!"
        }
    )

    -- dara: toggle "Bhop Hold Jump" (ToggleBhopHold)
    DaraBhopHoldToggle = TabMove:CreateToggle(
        "Mantener salto",
        "Hold Jump",
        false,
        function(enabled)
            if enabled and not movementTryEnable(DaraBhopHoldToggle) then return end
            bhopHoldEnabled = enabled
            updateBhopEnabled()
        end
    )

    -- dara: dropdown "Bhop Mode" (No Acceleration / Acceleration) -> toggle (encendido = "Acceleration", como el valor por defecto de dara)
    TabMove:CreateToggle(
        "Bhop acelerado",
        "Bhop Accel",
        true,
        function(enabled)
            accelerationMethod = enabled and "Acceleration" or "No Acceleration"   -- dara: SetAccelerationMethod
            updateBhopEnabled()
            if not (autoJumpEnabled or bhopHoldEnabled) then
                movementValueSet("Friction", DARA_DEFAULT_FRICTION)
                lastFriction = nil
            end
        end
    )

    -- dara: dropdown "Auto Jump Mode" (Simulation / Realistic) -> toggle (encendido = "Realistic", apagado = "Simulation" como dara por defecto)
    TabMove:CreateToggle(
        "Salto realista",
        "Realistic Jump",
        false,
        function(enabled)
            autoJumpType = enabled and "Realistic" or "Simulation"
        end
    )

    -- dara: input "Bhop Acceleration (Negative Only)"
    TabMove:CreateSlider(
        "Bhop Accel",
        -3, 0, accelerationValue,
        function(value)
            local n = tonumber(value)
            if n then
                accelerationValue = n
            end
        end
    )

    -- dara: toggle "Auto Wall Hop" (AutowallHop)
    YYPlace(TabMove, 3.60)
    DaraAutoWallHopToggle = TabMove:CreateToggle(
        "Wall Hop",
        "Wall Hop",
        false,
        function(enabled)
            if enabled and not movementTryEnable(DaraAutoWallHopToggle) then return end
            AutowallHop = enabled
        end
    )

    -- dara: seccion "Auto Acceleration"
    YYPlace(TabMove, 2.35)
    TabMove:CreateToggle(
        "Auto acelerar",
        "Auto Accel",
        false,
        function(enabled)
            autoAccelerationEnabled = enabled
        end
    )

    TabMove:CreateSlider(
        "Max Accel",
        -3, 10, maxAcceleration,
        function(value)
            local n = tonumber(value)
            if n then
                maxAcceleration = n
            end
        end
    )

    TabMove:CreateSlider(
        "Min Accel",
        -3, 10, minAcceleration,
        function(value)
            local n = tonumber(value)
            if n then
                minAcceleration = n
            end
        end
    )

    TabMove:CreateSlider(
        "Max Speed",
        1, 300, maxAutoAccelSpeed,
        function(value)
            local n = tonumber(value)
            if n and n > 0 then
                maxAutoAccelSpeed = n
            end
        end
    )
    TabMove:CreateDivider()
end

-- ===== Super Bounce (Dara Hub: "Supper Bounce") =====
do
    local BounceHeight = 190             -- dara: BounceHeight
    local DaraSuperBounceToggle = nil

    -- dara: triggerSuperBounce (identica)
    local function triggerSuperBounce()
        if not LocalPlayer.Character then return end
        local humanoid = LocalPlayer.Character:FindFirstChild("Humanoid")
        local rootPart = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")

        if humanoid and rootPart then
            humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
            rootPart.Velocity = Vector3.new(rootPart.Velocity.X, BounceHeight, rootPart.Velocity.Z)
        end
    end

    -- En dara el toggle muestra un boton en pantalla que dispara el rebote; aqui el propio toggle flotante es ese boton:
    -- al encenderlo hace un rebote y vuelve a apagarse solo.
    YYPlace(TabMove, 4.10)
    DaraSuperBounceToggle = TabMove:CreateFloatingToggle(
        "Súper rebote",
        "Super Bounce",
        false,
        function(enabled)
            if not enabled then return end
            triggerSuperBounce()
            task.defer(function()
                if DaraSuperBounceToggle then DaraSuperBounceToggle.SetValue(false) end
            end)
        end
    )

    TabMove:CreateSlider(
        "Bounce",
        10, 500, BounceHeight,
        function(value)
            BounceHeight = tonumber(value) or 50
        end
    )
    TabMove:CreateDivider()
end

-- ===== Modify Edge Trimp (Dara Hub: "Modify Edge Trimp") =====
do
    local BounceMultiplier = 5          -- dara: BounceMultiplier
    local FallSpeedThreshold = 69       -- dara: FallSpeedThreshold
    local EdgeTrimpEnabled = false
    local LastFloorMaterial = Enum.Material.Air
    local LastPosition = Vector3.new()
    local WasFalling = false
    local EdgeDetected = false
    local EdgeCharacter = nil
    local EdgeHumanoid = nil
    local EdgeRootPart = nil
    local edgeTrimpConnection = nil
    local charAddedConnection = nil

    -- dara: handleCharacterAdded
    local function handleCharacterAdded(NewCharacter)
        EdgeCharacter = NewCharacter
        EdgeHumanoid = EdgeCharacter:WaitForChild("Humanoid")
        EdgeRootPart = EdgeCharacter:WaitForChild("HumanoidRootPart")
        LastPosition = EdgeRootPart.Position
        WasFalling = false
        EdgeDetected = false
    end

    -- dara: toggle "Modify Edge Trimp" (misma logica del Heartbeat)
    YYPlace(TabMove, 3.40)
    TabMove:CreateFloatingToggle(
        "Edge Trimp",
        "Edge Trimp",
        false,
        function(State)
            EdgeTrimpEnabled = State
            if State then
                if LocalPlayer.Character then
                    handleCharacterAdded(LocalPlayer.Character)
                end
                charAddedConnection = LocalPlayer.CharacterAdded:Connect(handleCharacterAdded)

                edgeTrimpConnection = RunService.Heartbeat:Connect(function()
                    if not (EdgeCharacter and EdgeHumanoid and EdgeRootPart) then return end

                    local CurrentPosition = EdgeRootPart.Position
                    local Velocity = (CurrentPosition - LastPosition) / RunService.Heartbeat:Wait()
                    LastPosition = CurrentPosition
                    local CurrentFloorMaterial = EdgeHumanoid.FloorMaterial
                    local IsFalling = EdgeHumanoid:GetState() == Enum.HumanoidStateType.Freefall or EdgeHumanoid:GetState() == Enum.HumanoidStateType.Jumping

                    if CurrentFloorMaterial ~= LastFloorMaterial and CurrentFloorMaterial == Enum.Material.Air and not IsFalling then
                        EdgeDetected = true
                    else
                        EdgeDetected = false
                    end

                    if EdgeDetected and EdgeHumanoid:GetState() ~= Enum.HumanoidStateType.Freefall then
                        local FallVelocity = Velocity.Y
                        if FallVelocity < -FallSpeedThreshold then
                            local BounceVelocity = math.abs(FallVelocity) * BounceMultiplier
                            EdgeRootPart.Velocity = Vector3.new(EdgeRootPart.Velocity.X, BounceVelocity, EdgeRootPart.Velocity.Z)
                        end
                    end

                    LastFloorMaterial = CurrentFloorMaterial
                    WasFalling = IsFalling
                end)
            else
                if edgeTrimpConnection then
                    edgeTrimpConnection:Disconnect()
                    edgeTrimpConnection = nil
                end
                if charAddedConnection then
                    charAddedConnection:Disconnect()
                    charAddedConnection = nil
                end
            end
        end
    )

    -- dara: input "Bounce Height Multiplier" (aqui slider)
    TabMove:CreateSlider(
        "Edge Power",
        1, 20, BounceMultiplier,
        function(value)
            local Num = tonumber(value)
            if Num and Num > 0 then
                BounceMultiplier = Num
            end
        end
    )

    -- dara: input "Falling Threshold" (aqui slider)
    TabMove:CreateSlider(
        "Fall Limit",
        10, 200, FallSpeedThreshold,
        function(value)
            local Num = tonumber(value)
            if Num and Num > 0 then
                FallSpeedThreshold = Num
            end
        end
    )
    TabMove:CreateDivider()
end

-- ===== Yin Yang Goat v4 (v48) =====
-- v4: predice el aterrizaje siguiendo la parábola real (choca con paredes/techos), si ya vas a caer sobre algo chico no
-- corrige nada, elige el punto de la cara de arriba más cercano (no el centro), descarta objetos que necesitarían un
-- tirón imposible o que tienen una pared en el medio, y el desplazamiento acelera y frena suave (no empuje constante).
-- (Debajo queda la descripción original de v3.)
-- ===== Yin Yang Goat v3 (aterrizaje asistido, planeo temprano) =====
-- Apenas empiezas a caer predice DONDE vas a aterrizar (posicion + velocidad horizontal x tiempo de caida)
-- y busca el objeto PEQUENO mas cercano a ese punto (cactus, etc.; ignora pisos y casas grandes).
-- Te acerca de a poco por frame, repartido en el tiempo que falta para el impacto, con limite de velocidad lateral.
-- Solo toca la POSICION (CFrame): nunca escribe la velocidad, asi que Dara Trimp y Goat no se pisan.
-- Toggle "Goat: apuntar con camara": en vez del mas cercano, elige el objeto que esta mas alineado con donde apunta la camara.
do
    local GoatRange = 6                 -- studs (slider): radio horizontal de busqueda alrededor del punto de aterrizaje previsto
    local GoatConnection = nil
    local GoatCameraMode = false        -- toggle: elegir objetivo segun la camara
    local GoatJump = false              -- toggle "Jump": al tocar el objeto al que Goat te mando, saltas
    local GoatJumpHeight = 15           -- studs (slider): altura del salto al tocar ese objeto

    local MIN_FALL_SPEED = 3            -- studs/s hacia abajo para considerar que estas cayendo
    local EARLY_FINISH = 0.05           -- s antes del impacto en que la correccion ya termino
    local RESEARCH_INTERVAL = 0.15      -- s entre busquedas de objetivo
    local MAX_CANDIDATES = 25           -- partes que se revisan por busqueda
    local SWITCH_MARGIN = 2             -- studs de mejora necesarios para cambiar de objetivo (evita saltos)
    local SMALL_MAX = 12                -- studs: lado horizontal maximo para considerar un objeto "pequeno"
    local MAX_LATERAL_SPEED = 40        -- studs/s: maximo que Goat te mueve de lado (evita tirones)
    local MAX_PREDICT_TIME = 2          -- s: tope del tiempo de caida usado para predecir el aterrizaje
    local JUMP_REAPPLY_TIME = 0.06      -- s (~3-4 frames): tiempo en que se re-aplica la velocidad del salto de Goat (para que un auto-salto no la pise)

    local overlapParams = OverlapParams.new()
    overlapParams.FilterType = Enum.RaycastFilterType.Exclude
    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Exclude
    pcall(function() overlapParams.RespectCanCollide = true end)
    pcall(function() rayParams.RespectCanCollide = true end)

    local lockedPart = nil              -- parte objetivo
    local lockedLocal = nil             -- punto de aterrizaje en espacio local de esa parte
    local lastSearch = 0
    local feetOffset = nil              -- distancia root -> planta de los pies
    local wasFalling = false
    local lastErr = nil
    local jumpPart = nil                -- ultimo objeto al que Goat te mando (para el salto del toggle Jump)
    local justJumped = false            -- true si el ultimo aterrizaje fue seguido de un salto de Goat (evita rebote infinito)
    local jumpBoostVy = 0               -- velocidad vertical inicial del ultimo salto de Goat
    local jumpBoostStart = 0            -- os.clock() del ultimo salto de Goat
    local jumpBoostUntil = 0            -- os.clock() hasta el que se re-aplica (0 = inactivo)

    local function partTopY(part)
        local cf, s = part.CFrame, part.Size
        local ext = 0.5 * (math.abs(cf.RightVector.Y) * s.X + math.abs(cf.UpVector.Y) * s.Y + math.abs(cf.LookVector.Y) * s.Z)
        return cf.Position.Y + ext
    end

    local function computeFeetOffset(character, root)
        local lowest = math.huge
        for _, child in ipairs(character:GetChildren()) do
            if child:IsA("BasePart") then
                local bottom = 2 * child.Position.Y - partTopY(child)
                if bottom < lowest then lowest = bottom end
            end
        end
        if lowest == math.huge then return nil end
        return root.Position.Y - lowest
    end

    -- lado horizontal (X, Z del mundo) de la caja que envuelve la parte
    local function partHorizontalSize(part)
        local cf, s = part.CFrame, part.Size
        local ex = math.abs(cf.RightVector.X) * s.X + math.abs(cf.UpVector.X) * s.Y + math.abs(cf.LookVector.X) * s.Z
        local ez = math.abs(cf.RightVector.Z) * s.X + math.abs(cf.UpVector.Z) * s.Y + math.abs(cf.LookVector.Z) * s.Z
        return ex, ez
    end

    -- tiempo (s) para caer una distancia d con velocidad de caida speed (studs/s, positiva)
    local function fallTime(speed, d)
        local g = Workspace.Gravity
        if g > 0 then
            return (-speed + math.sqrt(speed * speed + 2 * g * d)) / g
        end
        return d / math.max(speed, 0.001)
    end

    -- direccion horizontal de la camara (nil si miras casi recto arriba/abajo)
    local function cameraFlatLook()
        local cam = Workspace.CurrentCamera
        if not cam then return nil end
        local look = cam.CFrame.LookVector
        local flat = Vector3.new(look.X, 0, look.Z)
        if flat.Magnitude < 0.05 then return nil end
        return flat.Unit
    end

    -- puntaje de un punto (menor = mejor): distancia al punto de aterrizaje previsto,
    -- o en modo camara, distancia perpendicular al rayo de la camara (solo hacia adelante)
    local function scorePoint(p, landing, pos, camLook)
        if GoatCameraMode and camLook then
            local rel = Vector3.new(p.X - pos.X, 0, p.Z - pos.Z)
            local along = rel:Dot(camLook)
            if along < 0 then return nil end
            return (rel - camLook * along).Magnitude
        end
        return Vector3.new(p.X - landing.X, 0, p.Z - landing.Z).Magnitude
    end

    -- v4: estado del deslizamiento suave (velocidad lateral aplicada, con aceleración limitada)
    local G4 = { vel = Vector3.zero, maxSpeed = MAX_LATERAL_SPEED }

    -- v4: ¿dónde caería sin ayuda? Se sigue la parábola real (velocidad + gravedad) en pasos de 0.05 s y se tira un
    -- rayo entre cada par de puntos, así se tienen en cuenta paredes, techos y bordes (antes se miraba solo para abajo).
    local function traceLanding(character, root, vel)
        local g = Workspace.Gravity
        local pos = root.Position - Vector3.new(0, feetOffset or 3, 0)
        local prev = pos
        rayParams.FilterDescendantsInstances = { character }
        for i = 1, 80 do
            local t = i * 0.05
            local p = pos + Vector3.new(vel.X * t, vel.Y * t - 0.5 * g * t * t, vel.Z * t)
            local hit = Workspace:Raycast(prev, p - prev, rayParams)
            if hit then return hit, t end
            if p.Y < Workspace.FallenPartsDestroyHeight then return nil, t end
            prev = p
        end
        return nil, 4
    end

    -- v4: punto de la cara de arriba de la parte más cercano a 'near' (con margen para no quedar en el borde)
    local function topPointNear(part, near)
        local cf, s = part.CFrame, part.Size
        local lp = cf:PointToObjectSpace(near)
        local mx, mz = math.max(s.X / 2 - 0.45, 0), math.max(s.Z / 2 - 0.45, 0)
        return cf:PointToWorldSpace(Vector3.new(math.clamp(lp.X, -mx, mx), s.Y / 2, math.clamp(lp.Z, -mz, mz)))
    end

    local function findTarget(character, root, feetY, vel, camLook)
        local pos = root.Position
        local natural, tLand = traceLanding(character, root, vel)
        local landing = natural and natural.Position or Vector3.new(pos.X + vel.X * tLand, feetY - 50, pos.Z + vel.Z * tLand)
        -- si ya vas a caer sobre algo pequeño, ese es el objetivo (corrección cero: lo más natural)
        if natural and natural.Instance and natural.Instance:IsA("BasePart") and not natural.Instance:IsA("Terrain") and natural.Normal.Y > 0.6 and not GoatCameraMode then
            local ex, ez = partHorizontalSize(natural.Instance)
            if math.max(ex, ez) <= SMALL_MAX and natural.Instance.CanCollide then
                return { part = natural.Instance, localPoint = natural.Instance.CFrame:PointToObjectSpace(natural.Position), score = 0 }
            end
        end
        local bottomY = math.max(Workspace.FallenPartsDestroyHeight, landing.Y - 8)
        local height = (feetY - 0.25) - bottomY
        if height <= 1 then return nil end
        overlapParams.FilterDescendantsInstances = { character }
        local parts = Workspace:GetPartBoundsInBox(
            CFrame.new(landing.X, bottomY + height * 0.5, landing.Z),
            Vector3.new(GoatRange * 2, height, GoatRange * 2),
            overlapParams
        )
        local g = Workspace.Gravity
        local list = {}
        for _, part in ipairs(parts) do
            if part.CanCollide and part.Transparency < 1 then
                local ex, ez = partHorizontalSize(part)
                if math.max(ex, ez) <= SMALL_MAX and partTopY(part) < feetY - 0.25 then
                    local model = part:FindFirstAncestorOfClass("Model")
                    if not (model and model:FindFirstChildOfClass("Humanoid")) then
                        local top = topPointNear(part, Vector3.new(landing.X, partTopY(part), landing.Z))
                        -- corrección que hace falta: dónde caerías a esa altura vs. el punto del objeto
                        local tI = fallTime(math.max(-vel.Y, 0), math.max(feetY - top.Y, 0))
                        local nat = Vector3.new(pos.X + vel.X * tI, 0, pos.Z + vel.Z * tI)
                        local corr = Vector3.new(top.X - nat.X, 0, top.Z - nat.Z).Magnitude
                        local need = corr / math.max(tI - EARLY_FINISH, 0.05)
                        if g > 0 and need <= G4.maxSpeed and corr <= GoatRange * 1.5 then
                            local score = scorePoint(top, Vector3.new(nat.X, 0, nat.Z), pos, camLook)
                            if score then
                                -- leve preferencia por objetos más chicos y por menos corrección
                                list[#list + 1] = { part = part, top = top, score = score + math.max(ex, ez) * 0.08 + need * 0.02 }
                            end
                        end
                    end
                end
            end
        end
        table.sort(list, function(a, b) return a.score < b.score end)
        local checked = 0
        for _, c in ipairs(list) do
            if checked >= MAX_CANDIDATES then break end
            checked = checked + 1
            -- desde arriba se tiene que tocar ESTE objeto (no un techo o piso que lo tape)
            local hit = Workspace:Raycast(Vector3.new(c.top.X, pos.Y, c.top.Z), Vector3.new(0, -(pos.Y - c.top.Y) - 1, 0), rayParams)
            if hit and hit.Instance == c.part and hit.Normal.Y > 0.3 then
                -- camino libre: entre tus pies y el objeto no puede haber una pared
                local from = pos - Vector3.new(0, feetOffset or 3, 0)
                local block = Workspace:Raycast(from, (hit.Position + Vector3.new(0, 0.3, 0)) - from, rayParams)
                if not block or block.Instance == c.part then
                    return { part = c.part, localPoint = c.part.CFrame:PointToObjectSpace(hit.Position), score = c.score }
                end
            end
        end
        return nil
    end

    local function goatStep(dt)
        local character = LocalPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not (humanoid and root) or humanoid.Health <= 0 or humanoid.SeatPart then
            lockedPart = nil
            wasFalling = false
            G4.vel = Vector3.zero
            return
        end

        -- salto de Goat: durante unos frames se mantiene la velocidad vertical que corresponde a la altura elegida
        -- (siguiendo la gravedad), para que otro salto automatico (ej. Jump Aceleracion) no la pise
        if jumpBoostUntil > 0 then
            local jnow = os.clock()
            if jnow >= jumpBoostUntil then
                jumpBoostUntil = 0
            else
                local jv = root.AssemblyLinearVelocity
                root.AssemblyLinearVelocity = Vector3.new(jv.X, jumpBoostVy - Workspace.Gravity * (jnow - jumpBoostStart), jv.Z)
            end
        end

        local vel = root.AssemblyLinearVelocity
        local falling = vel.Y <= -MIN_FALL_SPEED and humanoid.FloorMaterial == Enum.Material.Air
        if not falling then
            -- aterrizaje: si toco el objeto al que Goat me mando y el toggle Jump esta activo, salta
            if wasFalling and humanoid.FloorMaterial ~= Enum.Material.Air then
                local part = jumpPart
                local allow = not justJumped
                justJumped = false
                jumpPart = nil
                local g = Workspace.Gravity
                if GoatJump and allow and part and feetOffset and g > 0 then
                    rayParams.FilterDescendantsInstances = { character }
                    local touching = false
                    local hit = Workspace:Raycast(root.Position, Vector3.new(0, -(feetOffset + 2), 0), rayParams)
                    if hit and hit.Instance == part then
                        touching = true
                    end
                    if not touching then
                        overlapParams.FilterDescendantsInstances = { character }
                        local rp = root.Position
                        local near = Workspace:GetPartBoundsInBox(
                            CFrame.new(rp.X, rp.Y - feetOffset - 0.25, rp.Z),
                            Vector3.new(5, 3.5, 5),
                            overlapParams
                        )
                        for _, p in ipairs(near) do
                            if p == part then
                                touching = true
                                break
                            end
                        end
                    end
                    if touching then
                        local jumpVy = math.sqrt(2 * g * GoatJumpHeight)
                        humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                        root.AssemblyLinearVelocity = Vector3.new(vel.X, jumpVy, vel.Z)
                        justJumped = true
                        jumpBoostVy = jumpVy
                        jumpBoostStart = os.clock()
                        jumpBoostUntil = jumpBoostStart + JUMP_REAPPLY_TIME
                    end
                end
            end
            lockedPart = nil
            wasFalling = false
            G4.vel = Vector3.zero
            return
        end

        if not wasFalling then
            wasFalling = true
            feetOffset = computeFeetOffset(character, root)
            lastSearch = 0
            lockedPart = nil
            jumpPart = nil
            G4.vel = Vector3.zero
            -- con más alcance se permite más corrección lateral (sigue con aceleración suave)
            G4.maxSpeed = math.clamp(MAX_LATERAL_SPEED * (0.75 + GoatRange / 24), MAX_LATERAL_SPEED * 0.75, MAX_LATERAL_SPEED * 2)
        end
        if not feetOffset then return end

        local pos = root.Position
        local feetY = pos.Y - feetOffset
        local camLook = cameraFlatLook()

        local now = os.clock()
        if now - lastSearch >= RESEARCH_INTERVAL then
            lastSearch = now
            local found = findTarget(character, root, feetY, vel, camLook)
            if found then
                if lockedPart and lockedPart.Parent and found.part ~= lockedPart then
                    local lockedWorld = lockedPart.CFrame:PointToWorldSpace(lockedLocal)
                    local tEst = math.min(fallTime(-vel.Y, math.max(feetY - lockedWorld.Y, 0)), MAX_PREDICT_TIME)
                    local landing = Vector3.new(pos.X + vel.X * tEst, 0, pos.Z + vel.Z * tEst)
                    local lockedScore = scorePoint(lockedWorld, landing, pos, camLook)
                    if (not lockedScore) or found.score < lockedScore - SWITCH_MARGIN then
                        lockedPart, lockedLocal = found.part, found.localPoint
                    end
                else
                    lockedPart, lockedLocal = found.part, found.localPoint
                end
            elseif not (lockedPart and lockedPart.Parent) then
                lockedPart = nil
            end
        end

        if not (lockedPart and lockedPart.Parent) then
            lockedPart = nil
            G4.vel = G4.vel:Lerp(Vector3.zero, math.min(1, dt * 8))
            return
        end
        jumpPart = lockedPart

        local target = lockedPart.CFrame:PointToWorldSpace(lockedLocal)
        local d = feetY - target.Y
        if d <= 0.1 then
            lockedPart = nil
            return
        end

        local t = fallTime(-vel.Y, d)
        local landingX = pos.X + vel.X * t
        local landingZ = pos.Z + vel.Z * t
        local offset = Vector3.new(target.X - landingX, 0, target.Z - landingZ)
        local mag = offset.Magnitude
        if mag > GoatRange * 1.5 then
            lockedPart = nil
            return
        end

        -- v4: deslizamiento natural. En vez de un empujón constante, la velocidad lateral sube y baja suave
        -- (aceleración limitada) hasta cubrir la corrección justo antes de tocar el objeto. En los últimos
        -- instantes se completa lo que falte para no errar.
        local remaining = math.max(t - EARLY_FINISH, dt)
        local step
        if remaining <= 0.12 then
            step = offset * math.clamp(dt / remaining, 0, 1)
        else
            local desired = offset / remaining
            if desired.Magnitude > G4.maxSpeed then desired = desired.Unit * G4.maxSpeed end
            local accel = G4.maxSpeed * 6 * dt
            local diff = desired - G4.vel
            if diff.Magnitude > accel then diff = diff.Unit * accel end
            G4.vel = G4.vel + diff
            step = G4.vel * dt
            if step.Magnitude > mag then step = offset end
        end
        if step.Magnitude < 0.0005 then return end
        root.CFrame = root.CFrame + step
    end

    YYPlace(TabMove, 4.20)
    TabMove:CreateFloatingToggle(
        "Salto Goat",
        "Goat Jump",
        false,
        function(enabled)
            if GoatConnection then
                GoatConnection:Disconnect()
                GoatConnection = nil
            end
            lockedPart = nil
            wasFalling = false
            if enabled then
                GoatConnection = RunService.Heartbeat:Connect(function(dt)
                    local ok, err = pcall(goatStep, dt)
                    if not ok and tostring(err) ~= lastErr then
                        lastErr = tostring(err)
                        warn("[Yin Yang Goat] " .. lastErr)
                    end
                end)
            end
        end
    )

    TabMove:CreateSlider(
        "Goat Range",
        1, 100, GoatRange,
        function(value)
            local n = tonumber(value)
            if n and n > 0 then
                GoatRange = n
            end
        end
    )

    TabMove:CreateSlider(
        "Goat Height",
        1, 100, GoatJumpHeight,
        function(value)
            local n = tonumber(value)
            if n and n > 0 then
                GoatJumpHeight = n
            end
        end
    )

    TabMove:CreateToggle(
        "Apuntar con cámara",
        "Aim with Camera",
        false,
        function(enabled)
            GoatCameraMode = enabled
            lockedPart = nil
        end
    )

    TabMove:CreateToggle(
        "Saltar",
        "Jump",
        false,
        function(enabled)
            GoatJump = enabled
        end
    )
    TabMove:CreateDivider()
end

-- ===== Do not fall (suelo invisible) =====
-- Al activarlo guarda la altura de tus pies en ese momento y mantiene un piso invisible a esa altura,
-- siguiendote en X/Z, sin importar el lugar. Al apagarlo el piso se elimina. La altura se guarda al activar:
-- si reapareces con el toggle encendido, apagalo y encendelo de nuevo para fijar la nueva altura.
do
    local FLOOR_SIZE = 14               -- studs: lado del piso invisible (cuadrado)
    local FLOOR_THICKNESS = 1           -- studs: grosor del piso
    local floorConnection = nil
    local floorPart = nil
    local floorY = nil                  -- altura (Y) de la superficie del piso
    local floorErr = nil

    local function destroyFloor()
        if floorConnection then
            floorConnection:Disconnect()
            floorConnection = nil
        end
        if floorPart then
            floorPart:Destroy()
            floorPart = nil
        end
        floorY = nil
    end

    -- distancia del root a la planta de los pies (parte mas baja del personaje)
    local function floorFeetOffset(character, root)
        local lowest = math.huge
        for _, child in ipairs(character:GetChildren()) do
            if child:IsA("BasePart") then
                local bottom = child.Position.Y - child.Size.Y * 0.5
                if bottom < lowest then lowest = bottom end
            end
        end
        if lowest == math.huge then return 3 end
        return root.Position.Y - lowest
    end

    local function floorStep()
        local character = LocalPlayer.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not root then return end
        if not floorY then
            floorY = root.Position.Y - floorFeetOffset(character, root)
        end
        if not (floorPart and floorPart.Parent) then
            floorPart = Instance.new("Part")
            floorPart.Name = "YY_DoNotFallFloor"
            floorPart.Anchored = true
            floorPart.CanCollide = true
            floorPart.CanTouch = false
            floorPart.CanQuery = false
            floorPart.Transparency = 1
            floorPart.CastShadow = false
            floorPart.Size = Vector3.new(FLOOR_SIZE, FLOOR_THICKNESS, FLOOR_SIZE)
            floorPart.Parent = Workspace
        end
        floorPart.CFrame = CFrame.new(root.Position.X, floorY - FLOOR_THICKNESS * 0.5, root.Position.Z)
    end

    YYPlace(TabMove, 4.30)
    TabMove:CreateFloatingToggle(
        "Anti caída",
        "No Fall",
        false,
        function(enabled)
            destroyFloor()
            if enabled then
                floorConnection = RunService.Heartbeat:Connect(function()
                    local ok, err = pcall(floorStep)
                    if not ok and tostring(err) ~= floorErr then
                        floorErr = tostring(err)
                        warn("[Do not fall] " .. floorErr)
                    end
                end)
            end
        end
    )
    TabMove:CreateDivider()
end

