function setupBetaNewRainbow()
    local PlayerGui = Players.LocalPlayer:WaitForChild("PlayerGui")
    task.wait(1.2)
    
    if PlayerGui:FindFirstChild("Yin") then
        local ScreenGui = PlayerGui.Yin
        
        for _, child in pairs(ScreenGui:GetDescendants()) do
            if child:IsA("TextLabel") and child.Text:find("Frontal Jump") then
                local parentFrame = child.Parent
                
                if parentFrame then
                    local BetaNewLabel = YYKitMake("TextLabel")
                    BetaNewLabel.Name = "BetaLabel"
                    BetaNewLabel.Text = "Beta"
                    BetaNewLabel.Font = Enum.Font.GothamBold
                    BetaNewLabel.TextSize = 12
                    BetaNewLabel.BackgroundTransparency = 1
                    BetaNewLabel.TextColor3 = Color3.fromRGB(255, 255, 0)
                    BetaNewLabel.Size = UDim2.new(0.25, 0, 1, 0)
                    BetaNewLabel.Position = UDim2.new(0.7, 0, 0, 0)
                    BetaNewLabel.TextXAlignment = Enum.TextXAlignment.Right
                    BetaNewLabel.ZIndex = child.ZIndex + 2
                    BetaNewLabel.Parent = parentFrame
                    
                    print("™ Creating Yellow-Black rainbow effect for Beta...")
                    
                    -- Optimizacion: tween nativo de ida y vuelta (amarillo <-> negro en 3 s) en vez de RenderStepped
                    BetaNewLabel.TextColor3 = Color3.fromRGB(255, 255, 0)
                    KeyTweenService:Create(BetaNewLabel,
                        TweenInfo.new(3, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1, true),
                        { TextColor3 = Color3.fromRGB(0, 0, 0) }):Play()
                    
                    print("✓ Yellow-Black rainbow effect activated for Beta")
                    return
                end
            end
        end
    end
end

task.delay(1.5, setupBetaNewRainbow)

local AfkMapSpawnCFrame  = nil
local AfkMapRespawnConn  = nil
local AntiAfkConn        = nil
local AFk_MAP_FILE       = "yin_yang_map.json"
local AFK_MAP_URL        = "https://raw.githubusercontent.com/Yinyangzx/yin_map/refs/heads/main/yin_yang_map.json"

function loadAfkMap()
    if isfile then
        local ok, raw = pcall(game.HttpGet, game, AFK_MAP_URL)
        if ok and raw and raw ~= "" then
            pcall(writefile, AFk_MAP_FILE, raw)
        end
    end
    if not isfile or not isfile(AFk_MAP_FILE) then return false, "Archivo no encontrado" end
    local ok, raw = pcall(readfile, AFk_MAP_FILE)
    if not ok then return false, "Error leyendo archivo" end
    local ok2, data = pcall(function() return game:GetService("HttpService"):JSONDecode(raw) end)
    if not ok2 or not data or not data.parts then return false, "Archivo inválido" end
    local old = workspace:FindFirstChild("YinYangAfkMap")
    if old then old:Destroy() end
    local folder = Instance.new("Folder")
    folder.Name = "YinYangAfkMap"
    folder.Parent = workspace
    local spawnCFrame = nil
    for _, p in ipairs(data.parts) do
        pcall(function()
            local part = Instance.new(p.t or "Part")
            part.Size = Vector3.new(p.sx, p.sy, p.sz)
            part.CFrame = CFrame.new(p.px, p.py, p.pz) * CFrame.Angles(math.rad(p.rx), math.rad(p.ry), math.rad(p.rz))
            part.Color = Color3.fromRGB(p.cr, p.cg, p.cb)
            pcall(function() part.Material = Enum.Material:GetEnumItems()[p.m] or Enum.Material.SmoothPlastic end)
            part.Transparency = p.tr or 0
            part.Anchored = p.an == 1
            part.CanCollide = p.ca == 1
            part.CastShadow = false
            part.Parent = folder
            if part:IsA("SpawnLocation") then
                spawnCFrame = part.CFrame
            end
        end)
    end
    AfkMapSpawnCFrame = (spawnCFrame or CFrame.new(0, 10, 0)) + Vector3.new(0, 5, 0)
    return true, data.count or #data.parts
end

function setAfkMapEnabled(state)
    Config.EnableAfkMap = state
    if state then
        if AfkMapSpawnCFrame then
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if hrp then hrp.CFrame = AfkMapSpawnCFrame end
        end
        if AfkMapRespawnConn then AfkMapRespawnConn:Disconnect() end
        AfkMapRespawnConn = LocalPlayer.CharacterAdded:Connect(function()
            task.wait(0.5)
            if Config.EnableAfkMap and AfkMapSpawnCFrame then
                local c = LocalPlayer.Character
                local h = c and c:FindFirstChild("HumanoidRootPart")
                if h then h.CFrame = AfkMapSpawnCFrame end
            end
        end)
    else
        if AfkMapRespawnConn then AfkMapRespawnConn:Disconnect() AfkMapRespawnConn = nil end
        AfkMapSpawnCFrame = nil
        local old = workspace:FindFirstChild("YinYangAfkMap")
        if old then old:Destroy() end
    end
    SaveSettings()
end

do -- bloque de locales: libera 5 variables locales del script principal
local GagMapCachedScript  = nil
local GagMapSpawnCFrame   = nil
local GagMapRespawnConn   = nil
local GAG_MAP_URL         = "https://raw.githubusercontent.com/Yinyangzx/yin_map/refs/heads/main/Map.lua"
local GAG_MAP_FOLDER      = "__YY_GagMap"

function loadGagMap()
    if not GagMapCachedScript then
        local ok, raw = pcall(game.HttpGet, game, GAG_MAP_URL)
        if not ok or not raw or raw == "" then
            return false, "Error descargando el mapa"
        end
        GagMapCachedScript = raw
        print("[GagMap] Descargado y guardado en caché (" .. #raw .. " bytes)")
    else
        print("[GagMap] Usando caché en memoria (sin re-descarga)")
    end
    local fn, compileErr = loadstring(GagMapCachedScript)
    if not fn then return false, "Error compilando: " .. tostring(compileErr) end
    local old = workspace:FindFirstChild(GAG_MAP_FOLDER)
    if old then old:Destroy() end
    local folder = Instance.new("Folder")
    folder.Name = GAG_MAP_FOLDER
    folder.Parent = workspace
    local beforeSet = {}
    for _, child in ipairs(workspace:GetChildren()) do
        beforeSet[child] = true
    end
    local ok2, err2 = pcall(fn)
    if not ok2 then
        folder:Destroy()
        return false, "Error ejecutando: " .. tostring(err2)
    end
    local spawnCFrame = nil
    local count = 0
    for _, child in ipairs(workspace:GetChildren()) do
        if not beforeSet[child] and child ~= folder then
            if child:IsA("SpawnLocation") then
                spawnCFrame = child.CFrame
            end
            child.Parent = folder
            count = count + 1
        end
    end
    GagMapSpawnCFrame = (spawnCFrame or CFrame.new(-104.5, 0.5, -13.5)) + Vector3.new(0, 5, 0)
    return true, count
end

function setGagMapEnabled(state)
    Config.EnableGagMap = state
    if state then
        if GagMapSpawnCFrame then
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if hrp then hrp.CFrame = GagMapSpawnCFrame end
        end
        if GagMapRespawnConn then GagMapRespawnConn:Disconnect() end
        GagMapRespawnConn = LocalPlayer.CharacterAdded:Connect(function()
            task.wait(0.5)
            if Config.EnableGagMap and GagMapSpawnCFrame then
                local c = LocalPlayer.Character
                local h = c and c:FindFirstChild("HumanoidRootPart")
                if h then h.CFrame = GagMapSpawnCFrame end
            end
        end)
    else
        if GagMapRespawnConn then GagMapRespawnConn:Disconnect() GagMapRespawnConn = nil end
        GagMapSpawnCFrame = nil
        local old = workspace:FindFirstChild(GAG_MAP_FOLDER)
        if old then old:Destroy() end
    end
    SaveSettings()
end
end -- fin del bloque de locales

function setAntiAfkEnabled(state)
    Config.EnableAntiAfk = state
    if state then
        if AntiAfkConn then return end
        local antiAfkNext = os.clock() + 60
        AntiAfkConn = game:GetService("RunService").Heartbeat:Connect(function()
            if os.clock() >= antiAfkNext then
                antiAfkNext = os.clock() + 60
                pcall(function()
                    game:GetService("VirtualInputManager"):SendMouseWheelEvent(0, 0, true, game)
                end)
            end
        end)
    else
        if AntiAfkConn then AntiAfkConn:Disconnect() AntiAfkConn = nil end
    end
    SaveSettings()
end

-- Tarjeta de ESP (v2): cara del avatar con aro de estado + nombre + línea secundaria + chip de estado.
-- Todo va dentro de un CanvasGroup para poder desvanecerla entera según la distancia (lejos = más chica y
-- más transparente, así varias tarjetas no tapan la pantalla). Debajo, un piquito apunta al jugador.
-- La cara usa rbxthumb:// (miniatura de Roblox, sin pedidos extra y en cache del motor).
-- Temas: "normal" (oscura, aro blanco) · "downed" (roja, aro que late) · "carried" (negra: alguien lo lleva)
function makeEspCard(adornee, parent, userId, displayName, studsOffsetY)
    local billboard = Instance.new("BillboardGui")
    billboard.Adornee = adornee
    billboard.AlwaysOnTop = true
    billboard.LightInfluence = 0
    pcall(function()
        billboard.MaxDistance = math.huge
    end)
    billboard.Size = UDim2.new(0, 300, 0, 74)
    billboard.StudsOffset = Vector3.new(0, studsOffsetY or 3.8, 0)

    local holder = YYKitMake("Frame")
    holder.Name = "Holder"
    holder.BackgroundTransparency = 1
    holder.Size = UDim2.fromScale(1, 1)
    holder.Parent = billboard
    local scale = YYKitMake("UIScale")
    scale.Parent = holder

    local group = YYKitMake("CanvasGroup")
    group.Name = "Card"
    group.AnchorPoint = Vector2.new(0.5, 0)
    group.Position = UDim2.new(0.5, 0, 0, 2)
    group.Size = UDim2.new(0, 0, 0, 54)
    group.AutomaticSize = Enum.AutomaticSize.X
    group.BackgroundColor3 = Color3.fromRGB(14, 14, 18)
    group.BackgroundTransparency = 0.12
    group.BorderSizePixel = 0
    group.Parent = holder
    local groupCorner = YYKitMake("UICorner")
    groupCorner.CornerRadius = UDim.new(0, 16)
    groupCorner.Parent = group
    local sheen = YYKitMake("UIGradient") -- brillo suave de arriba hacia abajo
    sheen.Rotation = 90
    sheen.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(190, 190, 200))
    sheen.Parent = group
    local pad = YYKitMake("UIPadding")
    pad.PaddingLeft = UDim.new(0, 7)
    pad.PaddingRight = UDim.new(0, 12)
    pad.Parent = group
    local row = YYKitMake("UIListLayout")
    row.FillDirection = Enum.FillDirection.Horizontal
    row.VerticalAlignment = Enum.VerticalAlignment.Center
    row.Padding = UDim.new(0, 9)
    row.SortOrder = Enum.SortOrder.LayoutOrder
    row.Parent = group

    -- el borde va afuera del CanvasGroup (así no lo recorta) en un marco del mismo tamaño
    local edge = YYKitMake("Frame")
    edge.Name = "Edge"
    edge.AnchorPoint = Vector2.new(0.5, 0)
    edge.Position = UDim2.new(0.5, 0, 0, 2)
    edge.BackgroundTransparency = 1
    edge.Size = UDim2.new(0, 0, 0, 54)
    edge.Parent = holder
    local edgeCorner = YYKitMake("UICorner")
    edgeCorner.CornerRadius = UDim.new(0, 16)
    edgeCorner.Parent = edge
    local cardStroke = YYKitMake("UIStroke")
    cardStroke.Color = Color3.fromRGB(255, 255, 255)
    cardStroke.Transparency = 0.45
    cardStroke.Thickness = 1.5
    cardStroke.Parent = edge
    group:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
        edge.Size = UDim2.new(0, group.AbsoluteSize.X / math.max(scale.Scale, 0.01), 0, 54)
    end)

    -- piquito que apunta al jugador
    local tip = YYKitMake("Frame")
    tip.Name = "Tip"
    tip.AnchorPoint = Vector2.new(0.5, 0.5)
    tip.Position = UDim2.new(0.5, 0, 0, 57)
    tip.Size = UDim2.fromOffset(10, 10)
    tip.Rotation = 45
    tip.BackgroundColor3 = Color3.fromRGB(14, 14, 18)
    tip.BackgroundTransparency = 0.12
    tip.BorderSizePixel = 0
    tip.ZIndex = 0
    tip.Parent = holder

    -- cara con aro de estado y puntito
    local face = YYKitMake("Frame")
    face.Name = "Face"
    face.BackgroundTransparency = 1
    face.Size = UDim2.fromOffset(42, 42)
    face.LayoutOrder = 1
    face.Parent = group
    local avatar = YYKitMake("ImageLabel")
    avatar.Name = "Avatar"
    avatar.Size = UDim2.fromScale(1, 1)
    avatar.BackgroundColor3 = Color3.fromRGB(40, 40, 48)
    avatar.BorderSizePixel = 0
    avatar.ScaleType = Enum.ScaleType.Crop
    if tonumber(userId) then
        avatar.Image = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(userId) .. "&w=60&h=60"
    end
    avatar.Parent = face
    local avatarCorner = YYKitMake("UICorner")
    avatarCorner.CornerRadius = UDim.new(1, 0)
    avatarCorner.Parent = avatar
    local avatarRing = YYKitMake("UIStroke")
    avatarRing.Color = Color3.fromRGB(255, 255, 255)
    avatarRing.Thickness = 2.5
    avatarRing.Transparency = 0.05
    avatarRing.Parent = avatar
    local dot = YYKitMake("Frame")
    dot.Name = "Dot"
    dot.AnchorPoint = Vector2.new(1, 1)
    dot.Position = UDim2.fromScale(1.02, 1.02)
    dot.Size = UDim2.fromOffset(12, 12)
    dot.BackgroundColor3 = Color3.fromRGB(80, 230, 130)
    dot.BorderSizePixel = 0
    dot.ZIndex = 3
    dot.Parent = face
    local dotCorner = YYKitMake("UICorner")
    dotCorner.CornerRadius = UDim.new(1, 0)
    dotCorner.Parent = dot
    local dotStroke = YYKitMake("UIStroke")
    dotStroke.Color = Color3.fromRGB(14, 14, 18)
    dotStroke.Thickness = 2
    dotStroke.Parent = dot

    local column = YYKitMake("Frame")
    column.Name = "Text"
    column.BackgroundTransparency = 1
    column.Size = UDim2.new(0, 0, 0, 40)
    column.AutomaticSize = Enum.AutomaticSize.X
    column.LayoutOrder = 2
    column.Parent = group
    local col = YYKitMake("UIListLayout")
    col.FillDirection = Enum.FillDirection.Vertical
    col.VerticalAlignment = Enum.VerticalAlignment.Center
    col.SortOrder = Enum.SortOrder.LayoutOrder
    col.Parent = column

    local name = YYKitMake("TextLabel")
    name.Name = "Name"
    name.BackgroundTransparency = 1
    name.AutomaticSize = Enum.AutomaticSize.X
    name.Size = UDim2.new(0, 0, 0, 20)
    name.Font = Enum.Font.GothamBlack
    name.TextSize = 16
    name.TextColor3 = Color3.fromRGB(255, 255, 255)
    name.TextXAlignment = Enum.TextXAlignment.Left
    name.Text = tostring(displayName or "?")
    name.LayoutOrder = 1
    name.Parent = column

    local sub = YYKitMake("TextLabel")
    sub.Name = "Sub"
    sub.BackgroundTransparency = 1
    sub.AutomaticSize = Enum.AutomaticSize.X
    sub.Size = UDim2.new(0, 0, 0, 15)
    sub.Font = Enum.Font.GothamBold
    sub.TextSize = 11
    sub.TextColor3 = Color3.fromRGB(190, 190, 205)
    sub.TextXAlignment = Enum.TextXAlignment.Left
    sub.Text = ""
    sub.LayoutOrder = 2
    sub.Parent = column

    -- chip de estado (CAÍDO / LO LLEVAN); oculto en el tema normal
    local chip = YYKitMake("TextLabel")
    chip.Name = "Chip"
    chip.Size = UDim2.fromOffset(0, 22)
    chip.AutomaticSize = Enum.AutomaticSize.X
    chip.BackgroundColor3 = Color3.fromRGB(255, 70, 70)
    chip.BorderSizePixel = 0
    chip.Font = Enum.Font.GothamBlack
    chip.TextSize = 10
    chip.TextColor3 = Color3.fromRGB(255, 255, 255)
    chip.Text = ""
    chip.Visible = false
    chip.LayoutOrder = 3
    chip.Parent = group
    local chipCorner = YYKitMake("UICorner")
    chipCorner.CornerRadius = UDim.new(1, 0)
    chipCorner.Parent = chip
    local chipPad = YYKitMake("UIPadding")
    chipPad.PaddingLeft = UDim.new(0, 8)
    chipPad.PaddingRight = UDim.new(0, 8)
    chipPad.Parent = chip

    local ui = {
        billboard = billboard,
        card = group,
        group = group,
        tip = tip,
        stroke = cardStroke,
        avatar = avatar,
        ring = avatarRing,
        dot = dot,
        chip = chip,
        name = name,
        sub = sub,
        scale = scale,
        theme = nil,
        pulse = nil,
    }
    billboard.Parent = parent
    return ui
end

function setEspCardTheme(ui, theme)
    if not ui or ui.theme == theme then
        return
    end
    ui.theme = theme
    if ui.pulse then
        pcall(function() ui.pulse:Cancel() end)
        ui.pulse = nil
    end
    local TS = game:GetService("TweenService")
    local bg, stroke, ring, dot, subColor, chipText, chipColor
    if theme == "downed" then
        bg, stroke, ring, dot = Color3.fromRGB(60, 10, 14), Color3.fromRGB(255, 70, 70), Color3.fromRGB(255, 70, 70), Color3.fromRGB(255, 70, 70)
        subColor = Color3.fromRGB(255, 150, 150)
        chipText, chipColor = scriptText("CAÍDO", "DOWNED"), Color3.fromRGB(230, 45, 55)
    elseif theme == "carried" then
        bg, stroke, ring, dot = Color3.fromRGB(0, 0, 0), Color3.fromRGB(255, 255, 255), Color3.fromRGB(120, 120, 130), Color3.fromRGB(120, 120, 130)
        subColor = Color3.fromRGB(170, 170, 180)
        chipText, chipColor = scriptText("LO LLEVAN", "CARRIED"), Color3.fromRGB(45, 45, 52)
    else
        bg, stroke, ring, dot = Color3.fromRGB(14, 14, 18), Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 255, 255), Color3.fromRGB(80, 230, 130)
        subColor = Color3.fromRGB(190, 190, 205)
    end
    ui.group.BackgroundColor3 = bg
    ui.tip.BackgroundColor3 = bg
    ui.stroke.Color = stroke
    ui.stroke.Transparency = theme == "normal" and 0.45 or 0.05
    ui.ring.Color = ring
    ui.dot.BackgroundColor3 = dot
    ui.sub.TextColor3 = subColor
    ui.chip.Visible = chipText ~= nil
    if chipText then
        ui.chip.Text = chipText
        ui.chip.BackgroundColor3 = chipColor
    end
    if theme == "downed" then
        -- el aro de la cara late (tween nativo, sin código por frame)
        ui.ring.Transparency = 0
        ui.pulse = TS:Create(ui.ring, TweenInfo.new(0.7, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { Transparency = 0.7 })
        ui.pulse:Play()
    else
        ui.ring.Transparency = 0.05
    end
end

-- Cerca = grande y nítida · lejos = más chica y transparente (no tapa la pantalla).
-- Los caídos y los que llevan siempre se ven un poco más fuertes, porque son los que se buscan.
function setEspCardDistance(ui, distance)
    if not ui or not ui.group then return end
    local d = tonumber(distance) or 0
    local t = math.clamp((d - 40) / 260, 0, 1) -- 0 hasta 40 studs, 1 desde 300
    local important = ui.theme == "downed" or ui.theme == "carried"
    ui.scale.Scale = 1 - t * (important and 0.2 or 0.32)
    local fade = t * (important and 0.25 or 0.5)
    ui.group.GroupTransparency = fade
    ui.tip.BackgroundTransparency = 0.12 + fade
    ui.stroke.Transparency = (ui.theme == "normal" and 0.45 or 0.05) + fade * 0.8
end

local playerEspRigService = nil
local playerEspWhistleTemplate = nil
local playerEspEntries = {}
local playerEspConnections = {}
local playerEspAccumulator = 0
local PLAYER_ESP_WHITE = Color3.fromRGB(255, 255, 255)
local PLAYER_ESP_RED = Color3.fromRGB(255, 70, 70)
local PLAYER_ESP_REFRESH = 0.10

pcall(function()
    local services = ReplicatedStorage:WaitForChild("Services", 5)
    local asset = services and services:WaitForChild("Asset", 5)
    local rigModule = asset and asset:WaitForChild("RigService", 5)
    if rigModule then
        playerEspRigService = require(rigModule)
    end
end)

pcall(function()
    local objects = ReplicatedStorage:WaitForChild("Objects", 5)
    local gameFolder = objects and objects:WaitForChild("Game", 5)
    local characterFolder = gameFolder and gameFolder:WaitForChild("Character", 5)
    local actionVisuals = characterFolder and characterFolder:WaitForChild("ActionVisuals", 5)
    local actions = actionVisuals and actionVisuals:WaitForChild("Actions", 5)
    local whistle = actions and actions:WaitForChild("Whistle", 5)
    playerEspWhistleTemplate = whistle and whistle:FindFirstChild("WhistleHighlight")
end)

function playerEspDisconnect(connection)
    if connection then
        pcall(function()
            connection:Disconnect()
        end)
    end
end

function playerEspSetVisible(entry, visible)
    -- con ESP caídos encendido, a los caídos / llevados los muestra esa tarjeta (antes salían 2 tarjetas)
    local shown = visible and Config.EnableWhistleESP and not ((entry.downed or entry.carried) and Config.EnableEspDown)
    if entry.highlight then
        entry.highlight.Enabled = shown
    end
    if entry.billboard then
        entry.billboard.Enabled = shown
    end
end

function playerEspApplyColor(entry)
    if not entry or not entry.highlight then
        return
    end

    local color = entry.carried and Color3.fromRGB(40, 40, 46) or (entry.downed and PLAYER_ESP_RED or PLAYER_ESP_WHITE)
    pcall(function()
        entry.highlight.FillColor = color
        entry.highlight.OutlineColor = entry.carried and PLAYER_ESP_WHITE or color
    end)
    if entry.cardUI then
        setEspCardTheme(entry.cardUI, entry.carried and "carried" or (entry.downed and "downed" or "normal"))
    end
end

function playerEspClearVisual(entry)
    if not entry then
        return
    end

    playerEspDisconnect(entry.died)
    entry.died = nil

    if entry.highlight then
        pcall(function()
            entry.highlight:Destroy()
        end)
        entry.highlight = nil
    end
    if entry.billboard then
        pcall(function()
            entry.billboard:Destroy()
        end)
        entry.billboard = nil
    end

    entry.label = nil
    entry.sub = nil
    entry.cardUI = nil
    entry.root = nil
    entry.visualRoot = nil
    entry.visualModel = nil
    entry.rigData = nil
    entry.downed = false
    entry.humanoid = nil
    entry.character = nil
end

function playerEspDestroyEntry(player)
    local entry = playerEspEntries[player]
    if not entry then
        return
    end

    playerEspDisconnect(entry.characterAdded)
    playerEspDisconnect(entry.characterRemoving)
    playerEspClearVisual(entry)
    playerEspEntries[player] = nil
end

function playerEspGetRigData(character)
    if not playerEspRigService or not character then
        return nil
    end

    local tag = character:GetAttribute("Tag")
    if not tag then
        return nil
    end

    local ok, rig = pcall(function()
        return playerEspRigService:GetRigFromTag(tag)
    end)
    if ok and rig and rig.Model and rig.Model:IsA("Model") then
        return rig
    end

    return nil
end

function playerEspResolveVisual(player, character)
    local rigData = playerEspGetRigData(character)
    local visualModel = rigData and rigData.Model or nil
    if visualModel then
        local visualRoot = visualModel:FindFirstChild("HumanoidRootPart", true)
            or visualModel.PrimaryPart
            or visualModel:FindFirstChildWhichIsA("BasePart", true)
        if visualRoot then
            return visualModel, visualRoot, rigData
        end
    end

    local playersFolder = Workspace:FindFirstChild("Players")
    visualModel = playersFolder and playersFolder:FindFirstChild(player.Name)
    if visualModel and visualModel:IsA("Model") then
        local visualRoot = visualModel:FindFirstChild("HumanoidRootPart", true)
            or visualModel.PrimaryPart
            or visualModel:FindFirstChildWhichIsA("BasePart", true)
        if visualRoot then
            return visualModel, visualRoot, nil
        end
    end

    local characterRoot = character and character:FindFirstChild("HumanoidRootPart")
    return character, characterRoot, nil
end

function playerEspIsDowned(rigData, character)
    if rigData and rigData.DataRegistry then
        local okDowned, downed = pcall(function()
            return rigData.DataRegistry:Get("Downed")
        end)
        if okDowned and downed == true then
            return true
        end

        local okState, state = pcall(function()
            return rigData.DataRegistry:Get("State")
        end)
        if okState and state == "Downed" then
            return true
        end
    end

    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    return humanoid ~= nil and humanoid.Health <= 0
end

-- Estado "Carried" de StateInfo: un caído al que otro jugador está llevando
function playerEspIsCarried(rigData)
    if rigData and rigData.DataRegistry then
        local okState, state = pcall(function()
            return rigData.DataRegistry:Get("State")
        end)
        if okState and state == "Carried" then
            return true
        end
        local okCarried, carried = pcall(function()
            return rigData.DataRegistry:Get("Carried")
        end)
        if okCarried and carried ~= nil and carried ~= 0 and carried ~= false then
            return true
        end
    end
    return false
end

function playerEspCreateEntry(player, character)
    if player == LocalPlayer then
        return
    end

    local entry = playerEspEntries[player]
    if not entry then
        entry = {}
        playerEspEntries[player] = entry
    else
        playerEspClearVisual(entry)
    end

    local characterRoot = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not character or not characterRoot or not humanoid then
        return
    end

    local visualModel, visualRoot, rigData = playerEspResolveVisual(player, character)
    if not visualModel or not visualRoot then
        return
    end

    local downed = playerEspIsDowned(rigData, character)
    local oldHighlight = character:FindFirstChild("Beta_PlayerESP_WhistleHighlight")
    if oldHighlight then
        oldHighlight:Destroy()
    end
    local oldBillboard = visualRoot:FindFirstChild("Beta_PlayerESP_Label")
    if oldBillboard then
        oldBillboard:Destroy()
    end

    local highlight
    if playerEspWhistleTemplate then
        highlight = playerEspWhistleTemplate:Clone()
        highlight.Name = "Beta_PlayerESP_WhistleHighlight"
        highlight.Adornee = visualModel
        highlight.Enabled = Config.EnableWhistleESP
        highlight.Parent = character
    else
        highlight = Instance.new("Highlight")
        highlight.Name = "Beta_PlayerESP_WhistleHighlight_Fallback"
        highlight.Adornee = visualModel
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.FillTransparency = 1
        highlight.OutlineTransparency = 0
        highlight.Enabled = Config.EnableWhistleESP
        highlight.Parent = character
    end

    local cardUI = makeEspCard(visualRoot, nil, player.UserId, player.DisplayName, 3.8)
    local billboard = cardUI.billboard
    billboard.Name = "Beta_PlayerESP_Label"
    billboard.Enabled = Config.EnableWhistleESP
    billboard.Parent = visualRoot
    cardUI.sub.Text = "@" .. player.Name
    local label = cardUI.name

    entry.character = character
    entry.root = characterRoot
    entry.visualModel = visualModel
    entry.visualRoot = visualRoot
    entry.rigData = rigData
    entry.downed = downed
    entry.humanoid = humanoid
    entry.highlight = highlight
    entry.billboard = billboard
    entry.label = label
    entry.sub = cardUI.sub
    entry.cardUI = cardUI
    playerEspApplyColor(entry)

    entry.died = humanoid.Died:Connect(function()
        if playerEspEntries[player] == entry then
            entry.downed = true
            playerEspApplyColor(entry)
        end
    end)
end

function playerEspAttachPlayer(player)
    if player == LocalPlayer then
        return
    end

    playerEspDestroyEntry(player)
    local entry = {
        characterAdded = player.CharacterAdded:Connect(function(character)
            task.defer(function()
                if Config.EnableWhistleESP then
                    local root = character:WaitForChild("HumanoidRootPart", 5)
                    local humanoid = character:FindFirstChildOfClass("Humanoid")
                    if root and humanoid then
                        playerEspCreateEntry(player, character)
                    end
                end
            end)
        end),
        characterRemoving = player.CharacterRemoving:Connect(function()
            local current = playerEspEntries[player]
            if current then
                playerEspClearVisual(current)
            end
        end),
    }
    playerEspEntries[player] = entry

    if player.Character then
        playerEspCreateEntry(player, player.Character)
    end
end

function playerEspAttachAll()
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LocalPlayer then
            playerEspAttachPlayer(player)
        end
    end
end

function playerEspRefresh()
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LocalPlayer and not playerEspEntries[player] then
            playerEspAttachPlayer(player)
        end
    end

    local localCharacter = LocalPlayer.Character
    local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
    local camera = Workspace.CurrentCamera
    local observerPosition = localRoot and localRoot.Position or (camera and camera.CFrame.Position)
    if not observerPosition then
        return
    end

    for player, entry in pairs(playerEspEntries) do
        if not player.Parent then
            playerEspDestroyEntry(player)
        elseif entry.character and entry.character.Parent and entry.root and entry.root.Parent then
            local visualModel, visualRoot, rigData = playerEspResolveVisual(player, entry.character)
            if visualModel ~= entry.visualModel or visualRoot ~= entry.visualRoot then
                playerEspCreateEntry(player, entry.character)
                entry = playerEspEntries[player]
            elseif entry then
                entry.rigData = rigData or entry.rigData
            end

            if entry and entry.visualRoot and entry.visualRoot.Parent then
                entry.carried = playerEspIsCarried(entry.rigData)
                entry.downed = entry.carried or playerEspIsDowned(entry.rigData, entry.character)
                playerEspApplyColor(entry)
                local distance = (entry.visualRoot.Position - observerPosition).Magnitude
                playerEspSetVisible(entry, Config.EnableWhistleESP and distance <= math.huge)
                setEspCardDistance(entry.cardUI, distance)
                if entry.sub then
                    local meters = math.floor(distance + 0.5)
                    entry.sub.Text = (entry.downed and not entry.carried)
                        and string.format("%s · %d m", scriptText("Necesita ayuda", "Needs help"), meters)
                        or string.format("@%s · %d m", player.Name, meters)
                end
            end
        else
            playerEspSetVisible(entry, false)
        end
    end
end

function playerEspSetEnabled(state)
    Config.EnableWhistleESP = state and true or false
    if Config.EnableWhistleESP then
        playerEspAttachAll()
    else
        for player in pairs(playerEspEntries) do
            playerEspDestroyEntry(player)
        end
    end
    SaveSettings()
end

table.insert(playerEspConnections, Players.PlayerAdded:Connect(function(player)
    if Config.EnableWhistleESP then
        playerEspAttachPlayer(player)
    end
end))
table.insert(playerEspConnections, Players.PlayerRemoving:Connect(function(player)
    playerEspDestroyEntry(player)
end))
table.insert(playerEspConnections, RunService.Heartbeat:Connect(function(deltaTime)
    playerEspAccumulator = playerEspAccumulator + deltaTime
    if playerEspAccumulator >= PLAYER_ESP_REFRESH then
        playerEspAccumulator = 0
        if Config.EnableWhistleESP then
            playerEspRefresh()
        end
    end
end))

