YYPlace(TabExtra, 2.10)
TabExtra:CreateFloatingToggle("Auto cargar", "Auto Carry", Config.EnableAutoCarry, function(state)
    Config.EnableAutoCarry = state
    print(state and "✓ Auto Carry ENABLED" or "X Auto Carry DISABLED")
    SaveSettings()
end)

