    TimeGradient.Parent = TimeDisplay
    end

    local StatusLabel = MainTimer:FindFirstChild("About")
    if not StatusLabel then
    StatusLabel = YYKitMake("TextLabel")
    StatusLabel.Name = "About"
    StatusLabel.FontFace = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal)
    StatusLabel.Text = scriptText("RONDA ACTIVA", "ROUND ACTIVE")
    StatusLabel.TextColor3 = Color3.fromRGB(165, 194, 255)
    StatusLabel.TextScaled = true
    StatusLabel.TextSize = 14
    StatusLabel.TextStrokeTransparency = 0.95
    StatusLabel.TextWrapped = true
    StatusLabel.AnchorPoint = Vector2.new(0.5, 0.5)
    StatusLabel.BackgroundTransparency = 1
    StatusLabel.Position = UDim2.new(0.5, 0, 0.25, 0)
    StatusLabel.Size = UDim2.new(0.8, 0, 0.25, 0)
    StatusLabel.ZIndex = 3
    StatusLabel.Parent = MainTimer
    local StatusStroke = YYKitMake("UIStroke")
    StatusStroke.Thickness = 2
    StatusStroke.Transparency = 0.7
    StatusStroke.Parent = StatusLabel
    local StatusGradient = YYKitMake("UIGradient")
    StatusGradient.Color = ColorSequence.new({
    ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
    ColorSequenceKeypoint.new(1, Color3.fromRGB(194, 194, 194))
    })
    StatusGradient.Rotation = 90
    StatusGradient.Parent = StatusLabel
    end

    local MainTimerStroke = MainTimer:FindFirstChildOfClass("UIStroke")
    if not MainTimerStroke then
    MainTimerStroke = YYKitMake("UIStroke")
    MainTimerStroke.Transparency = 0.8
    MainTimerStroke.Parent = MainTimer
    end

    local MainTimerImage = MainTimer:FindFirstChildOfClass("ImageLabel")
    if not MainTimerImage then
    MainTimerImage = YYKitMake("ImageLabel")
    MainTimerImage.Name = "Background"
    MainTimerImage.Image = "rbxassetid://196969716"
    MainTimerImage.ImageColor3 = Color3.fromRGB(21, 21, 21)
    MainTimerImage.ImageTransparency = 0.7
    MainTimerImage.AnchorPoint = Vector2.new(0.5, 0.5)
    MainTimerImage.BackgroundTransparency = 1
    MainTimerImage.Position = UDim2.new(0.5, 0, 0.5, 0)
    MainTimerImage.Size = UDim2.new(1, 0, 1, 0)
    MainTimerImage.ZIndex = 0
    MainTimerImage.Parent = MainTimer
    local MainTimerImageCorner = YYKitMake("UICorner")
    MainTimerImageCorner.CornerRadius = UDim.new(0, 4)
    MainTimerImageCorner.Parent = MainTimerImage
    end

    local SpecialRound = YYKitMake("Frame")
    SpecialRound.Name = "SpecialRound"
    SpecialRound.AnchorPoint = Vector2.new(0.5, 0)
    SpecialRound.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    SpecialRound.BackgroundTransparency = 0.6
    SpecialRound.BorderSizePixel = 0
    SpecialRound.Position = UDim2.new(0.5, 0, 0.15, 0)
    SpecialRound.Size = UDim2.new(0.23, 0, 0.05, 0)
    SpecialRound.Parent = Top
    SpecialRound.Visible = false

    local SpecialRoundLabel = YYKitMake("TextLabel")
    SpecialRoundLabel.Name = "Label"
    SpecialRoundLabel.FontFace = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal)
    SpecialRoundLabel.Text = scriptText("Sin datos", "No Data")
    SpecialRoundLabel.TextColor3 = Color3.fromRGB(255, 208, 115)
    SpecialRoundLabel.TextScaled = true
    SpecialRoundLabel.TextSize = 14
    SpecialRoundLabel.TextStrokeTransparency = 0.95
    SpecialRoundLabel.TextWrapped = true
    SpecialRoundLabel.AnchorPoint = Vector2.new(0.5, 0.5)
    SpecialRoundLabel.BackgroundTransparency = 1
    SpecialRoundLabel.Position = UDim2.new(0.5, 0, 0.5, 0)
    SpecialRoundLabel.Size = UDim2.new(0.9, 0, 0.6, 0)
    SpecialRoundLabel.ZIndex = 3
    SpecialRoundLabel.Parent = SpecialRound

    local SpecialRoundStroke = YYKitMake("UIStroke")
    SpecialRoundStroke.Thickness = 2
    SpecialRoundStroke.Transparency = 0.7
    SpecialRoundStroke.Parent = SpecialRoundLabel

    local SpecialRoundEmptyFrame = YYKitMake("Frame")
    SpecialRoundEmptyFrame.AnchorPoint = Vector2.new(0, 0.5)
    SpecialRoundEmptyFrame.BackgroundTransparency = 1
    SpecialRoundEmptyFrame.Position = UDim2.new(0.775, 0, 0.6, 0)
    SpecialRoundEmptyFrame.Size = UDim2.new(0.225, 0, 0.45, 0)
    SpecialRoundEmptyFrame.Parent = SpecialRound

    local SpecialRoundListLayout = YYKitMake("UIListLayout")
    SpecialRoundListLayout.FillDirection = Enum.FillDirection.Horizontal
    SpecialRoundListLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    SpecialRoundListLayout.SortOrder = Enum.SortOrder.LayoutOrder
    SpecialRoundListLayout.VerticalAlignment = Enum.VerticalAlignment.Top
    SpecialRoundListLayout.Parent = SpecialRoundEmptyFrame

    local SpecialRoundCorner = YYKitMake("UICorner")
    SpecialRoundCorner.CornerRadius = UDim.new(0, 4)
    SpecialRoundCorner.Parent = SpecialRound

    local SpecialRoundBackground = YYKitMake("ImageLabel")
    SpecialRoundBackground.Name = "Background"
    SpecialRoundBackground.Image = "rbxassetid://196969716"
    SpecialRoundBackground.ImageColor3 = Color3.fromRGB(21, 21, 21)
    SpecialRoundBackground.ImageTransparency = 0.7
    SpecialRoundBackground.AnchorPoint = Vector2.new(0.5, 0.5)
    SpecialRoundBackground.BackgroundTransparency = 1
    SpecialRoundBackground.Position = UDim2.new(0.5, 0, 0.5, 0)
    SpecialRoundBackground.Size = UDim2.new(1, 0, 1, 0)
    SpecialRoundBackground.ZIndex = 0
    SpecialRoundBackground.Parent = SpecialRound

    local SpecialRoundBackgroundCorner = YYKitMake("UICorner")
    SpecialRoundBackgroundCorner.CornerRadius = UDim.new(0, 4)
    SpecialRoundBackgroundCorner.Parent = SpecialRoundBackground

    local SpecialRoundUIStroke = YYKitMake("UIStroke")
    SpecialRoundUIStroke.Transparency = 0.8
    SpecialRoundUIStroke.Parent = SpecialRound

    return {
    ScreenGui = ScreenGui,
    TimeDisplay = TimeDisplay,
    SpecialRoundLabel = SpecialRoundLabel,
    StatusLabel = StatusLabel,
    MainTimer = MainTimer,
    SpecialRound = SpecialRound,
    MainTimerStroke = MainTimerStroke,
    MainTimerImage = MainTimerImage
    }
    end

    function destroyTimerGUI()
    if TimerGUI then
    StopGameTimerCheck()
    StopAttributeMonitor()
    TimerGUI.ScreenGui:Destroy()
    TimerGUI = nil
    end
    TimerEnabled = false
    SpecialRoundEnabled = false
    end

    function ensureTimerGUI()
    if not TimerGUI then
    TimerGUI = createTimerGUI()
    end
    end

    function GetRoundTitle(roundName)
    if not roundName or roundName == "" then
    return ""
    end

    local specialRoundsFolder = ReplicatedStorage:FindFirstChild("Info")
    if not specialRoundsFolder then return roundName end

    specialRoundsFolder = specialRoundsFolder:FindFirstChild("SpecialRounds")
    if not specialRoundsFolder then return roundName end

    local roundModule = specialRoundsFolder:FindFirstChild(roundName)
    if not roundModule then return roundName end

    local success, moduleData = pcall(function()
    return require(roundModule)
    end)

    if success and moduleData and moduleData.Title then
    return moduleData.Title
    end

    return roundName
    end

    function SetTime(seconds)
    if not TimerGUI then return end
    if type(seconds) == "number" then
    local minutes = math.floor(seconds / 60)
    local remainingSeconds = math.floor(seconds % 60)
    TimerGUI.TimeDisplay.Text = string.format("%d:%02d", minutes, remainingSeconds)

    if seconds <= 5 then
    TimerGUI.TimeDisplay.TextColor3 = Color3.fromRGB(215, 100, 100)
    TimerGUI.StatusLabel.TextColor3 = Color3.fromRGB(215, 100, 100)
    if TimerGUI.MainTimerStroke then
    TimerGUI.MainTimerStroke.Color = Color3.fromRGB(255, 138, 138)
    end
    if TimerGUI.MainTimerImage then
    TimerGUI.MainTimerImage.ImageColor3 = Color3.fromRGB(255, 138, 138)
    end
    else
    TimerGUI.TimeDisplay.TextColor3 = Color3.fromRGB(165, 194, 255)
    TimerGUI.StatusLabel.TextColor3 = Color3.fromRGB(165, 194, 255)
    if TimerGUI.MainTimerStroke then
    TimerGUI.MainTimerStroke.Color = Color3.fromRGB(165, 194, 255)
    end
    if TimerGUI.MainTimerImage then
    TimerGUI.MainTimerImage.ImageColor3 = Color3.fromRGB(21, 21, 21)
    end
    end
    else
    TimerGUI.TimeDisplay.Text = tostring(seconds)
    end
    end

    function SetSpecialRound(roundName)
    if not TimerGUI then return end
    if roundName and roundName ~= "" then
    CurrentSpecialRoundName = roundName
    local roundTitle = GetRoundTitle(roundName)
    TimerGUI.SpecialRoundLabel.Text = roundTitle
    TimerGUI.SpecialRound.Visible = SpecialRoundEnabled
    else
    CurrentSpecialRoundName = ""
    TimerGUI.SpecialRound.Visible = false
    end
    end

    function SetStatus(text)
    if not TimerGUI then return end
    TimerGUI.StatusLabel.Text = text:upper()
    end

    function SetTimerVisible(visible)
    TimerEnabled = visible
    OriginalTimerVisible = visible

    if CheckingGameTimer then
    CheckGameTimerVisibility()
    else
    if TimerGUI then
    TimerGUI.MainTimer.Visible = visible
    end
    end
    end

    function SetSpecialRoundVisible(visible)
    SpecialRoundEnabled = visible

    if TimerGUI and visible and CurrentSpecialRoundName ~= "" then
    TimerGUI.SpecialRound.Visible = true
    elseif TimerGUI then
    TimerGUI.SpecialRound.Visible = false
    end
    end

    function CheckGameTimerVisibility()
    if not TimerEnabled or not TimerGUI then
    if TimerGUI then TimerGUI.MainTimer.Visible = false end
    return
    end

    local hud = PlayerGui:FindFirstChild("Shared")
    if not hud then
    TimerGUI.MainTimer.Visible = OriginalTimerVisible
    return
    end

    hud = hud:FindFirstChild("HUD")
    if not hud then
    TimerGUI.MainTimer.Visible = OriginalTimerVisible
    return
    end

    hud = hud:FindFirstChild("Overlay")
    if not hud then
    TimerGUI.MainTimer.Visible = OriginalTimerVisible
    return
    end

    hud = hud:FindFirstChild("Default")
    if not hud then
    TimerGUI.MainTimer.Visible = OriginalTimerVisible
    return
    end

    hud = hud:FindFirstChild("RoundOverlay")
    if not hud then
    TimerGUI.MainTimer.Visible = OriginalTimerVisible
    return
    end

    hud = hud:FindFirstChild("Round")
    if not hud then
    TimerGUI.MainTimer.Visible = OriginalTimerVisible
    return
    end

    local roundTimer = hud:FindFirstChild("RoundTimer")
    if not roundTimer then
    TimerGUI.MainTimer.Visible = OriginalTimerVisible
    return
    end

    if roundTimer.Visible then
    TimerGUI.MainTimer.Visible = false
    else
    TimerGUI.MainTimer.Visible = OriginalTimerVisible
    end
    end

    function StartGameTimerCheck()
    if CheckingGameTimer then return end

    CheckingGameTimer = true

    spawn(function()
    while CheckingGameTimer do
    CheckGameTimerVisibility()
    wait(0.1)
    end
    end)
    end

    function StopGameTimerCheck()
    CheckingGameTimer = false
    if TimerGUI then
    TimerGUI.MainTimer.Visible = OriginalTimerVisible
    end
    end

    function UpdateFromAttributes()
    if not resolveServerState() then return end
    local timerValue = ServerStateRegistryService.Registry.Time
    local specialRoundValue = ServerStateRegistryService.Registry.SpecialRound
    local roundStatus = ServerStateRegistryService.Registry.RoundStatus

    if timerValue and timerValue ~= -1 then
    SetTime(timerValue)
    end

    if roundStatus == 2 then
    SetStatus(scriptText("Ronda activa", "Round Active"))
    elseif roundStatus == 1 or 0 then
    SetStatus(scriptText("Intermedio", "Intermission"))
    else
    SetStatus("nil")
    end

    if specialRoundValue and specialRoundValue ~= false then
    SetSpecialRound(tostring(specialRoundValue))
    else
    SetSpecialRound("")
    end
    end

    function StartAttributeMonitor()
    StopAttributeMonitor()
    if not resolveServerState() then
    warn("[Timer] ServerStateRegistryService no disponible")
    return
    end

    local lastTimer = ServerStateRegistryService.Registry.Time
    local lastRoundStatus = ServerStateRegistryService.Registry.RoundStatus
    local lastSpecialRound = ServerStateRegistryService.Registry.SpecialRound

    _attributeConnection = RunService.Heartbeat:Connect(function()
    local currentTimer = ServerStateRegistryService.Registry.Time
    local currentRoundStatus = ServerStateRegistryService.Registry.RoundStatus
    local currentSpecialRound = ServerStateRegistryService.Registry.SpecialRound

    if currentTimer ~= lastTimer or currentRoundStatus ~= lastRoundStatus or currentSpecialRound ~= lastSpecialRound then
    lastTimer = currentTimer
    lastRoundStatus = currentRoundStatus
    lastSpecialRound = currentSpecialRound
    UpdateFromAttributes()
    end
    end)

    UpdateFromAttributes()
    end

    function StopAttributeMonitor()
    if _attributeConnection then
    _attributeConnection:Disconnect()
    _attributeConnection = nil
    end
    if _attributeConnection2 then
    _attributeConnection2:Disconnect()
    _attributeConnection2 = nil
    end
    if _attributeConnection3 then
    _attributeConnection3:Disconnect()
    _attributeConnection3 = nil
    end
    end

    function handleTimerToggles()
    local timerOn = TimerEnabled
    local specialOn = SpecialRoundEnabled

    if not timerOn and not specialOn then
    destroyTimerGUI()
    else
    ensureTimerGUI()
    if timerOn then
    SetTimerVisible(true)
    StartAttributeMonitor()
    StartGameTimerCheck()
    end
    if specialOn then
    SetSpecialRoundVisible(true)
    end
    end
    end

    YYPlace(TabExtra, 3.30)
    TabExtra:CreateFloatingToggle("Temporizador", "Timer", false, function(state)
        TimerEnabled = state
        handleTimerToggles()
    end)

    TabExtra:CreateFloatingToggle("Ronda especial", "Special Round", false, function(state)
        SpecialRoundEnabled = state
        handleTimerToggles()
    end)
end

-- ===== VER STATS (v46): tarjeta nueva =====
-- Datos (verificados en el código de Evade): ClientHooks useCurrency (Tokens/Points), useProgression (Level, XP,
-- RequiredXP(level), Progress), useEvent (tickets), useCounters (Survivals/Streak, mismas claves que usa
-- "Modificar stats"). En vivo, del personaje propio de CharacterService: State.State, DataRegistry "Speed",
-- "Carrying", "EquippedName" (nombre del objeto en mano, lo escribe ToolProfile:Equip). Bots = AI == true.
-- La sesión cuenta desde que prendés la tarjeta.
function setupStatsCard()
    local TweenService = game:GetService("TweenService")
    local hooks = {}
    local Card = nil
    local observers = {}
    local session = nil

    local function fmt(n)
        n = math.floor(tonumber(n) or 0)
        local s = tostring(math.abs(n))
        local out = s:reverse():gsub("(%d%d%d)", "%1,"):reverse()
        if out:sub(1, 1) == "," then out = out:sub(2) end
        return (n < 0 and "-" or "") .. out
    end
    local function short(n)
        n = tonumber(n) or 0
        if math.abs(n) >= 1e6 then return string.format("%.1fM", n / 1e6) end
        if math.abs(n) >= 1e4 then return string.format("%.1fK", n / 1e3) end
        return fmt(n)
    end
    local function call(hook, fn, ...)
        local h = hooks[hook]
        if not h or type(h[fn]) ~= "function" then return nil end
        local ok, v = pcall(h[fn], ...)
        return ok and v or nil
    end
    local function currency(name)
        local v = call("useCurrency", "Balance", name)
        if v == nil then
            local all = call("useCurrency", "All")
            v = type(all) == "table" and all[name] or nil
        end
        return tonumber(v) or 0
    end
    local function counter(name)
        local v = call("useCounters", "Get", name)
        if (v == nil or v == 0) then
            local all = call("useCurrency", "All") -- respaldo: la versión vieja lo leía de acá
            if type(all) == "table" and all[name] then v = all[name] end
        end
        return tonumber(v) or 0
    end
    local function localChar()
        local cs = FindCharService and FindCharService()
        if not cs then return nil, {} end
        local ok, chars = pcall(function() return cs:GetCharacters() end)
        if not ok or type(chars) ~= "table" then return nil, {} end
        local mine, bots = nil, {}
        for i = 1, #chars do
            local v = chars[i]
            if type(v) == "table" and v.Done and v.PrimaryPart then
                if v.Local then mine = v elseif v.AI == true then bots[#bots + 1] = v end
            end
        end
        return mine, bots
    end
    local function pretty(name)
        name = tostring(name or "")
        if name == "" or name == "Weaponless" then return scriptText("Nada", "Nothing") end
        return (name:gsub("(%l)(%u)", "%1 %2"))
    end

    local function destroyCard()
        for _, d in ipairs(observers) do pcall(d) end
        observers = {}
        if Card then pcall(function() Card.Gui:Destroy() end) end
        Card = nil
    end

    local function buildCard()
        -- la tarjeta la da la librería (YinYang.Kit.Window); acá solo se dice qué mostrar
        local K = YYKit()
        if not (K and K.Window) then warn("[Ver stats] La librería UI no tiene el kit de ventanas (actualizala)") return end
        local W = K.Window({ Name = "PlayerStats", DisplayOrder = 333, Width = 286, Position = UDim2.fromOffset(16, 110), Avatar = LocalPlayer.UserId,
            Title = LocalPlayer.DisplayName, Subtitle = "@" .. LocalPlayer.Name, Badge = true, Minimize = true, Close = false, Gap = 10 })
        W:SetBadge(scriptText("NV ", "LV ") .. "1")
        -- barra de XP (queda visible al minimizar)
        local xp = W:Pinned():Progress()
        xp:Set(0, "XP 0 / 0", "0%")
        -- monedas y contadores (3 columnas)
        W:Section(scriptText("CUENTA", "ACCOUNT"))
        local tiles = W:Tiles({
            { Key = "Tokens", Label = scriptText("Tokens", "Tokens"), Icon = "rbxassetid://7149239101", Color = Color3.fromRGB(163, 255, 87) },
            { Key = "Points", Label = scriptText("Puntos", "Points"), Icon = "rbxassetid://4648327306", Color = Color3.fromRGB(255, 255, 255) },
            { Key = "Tickets", Label = scriptText("Tickets", "Tickets"), Icon = "rbxassetid://14478137255", Color = Color3.fromRGB(255, 121, 121) },
            { Key = "Survivals", Label = scriptText("Victorias", "Wins"), Icon = "rbxassetid://88681516628510", Color = Color3.fromRGB(255, 188, 110) },
            { Key = "Streak", Label = scriptText("Racha", "Streak"), Icon = "rbxassetid://13518130183", Color = Color3.fromRGB(255, 217, 78) },
            { Key = "ToLevel", Label = scriptText("Para subir", "To level up"), Icon = "rbxassetid://4648327306" },
        })
        local tileMap = {}
        for key, it in pairs(tiles.Items) do tileMap[key] = { value = it.Value, pop = it.Pop, last = nil } end
        -- ahora: estado, velocidad, objeto, bot
        W:Section(scriptText("AHORA", "NOW"))
        local now = W:Box()
        local stateChip, stateStroke, speedText = now:ChipValue()
        local speedFill = now:Bar()
        local itemText = now:Row(scriptText("Objeto en mano", "Holding"))
        local botText = now:Row(scriptText("Bot más cerca", "Nearest bot"))
        -- sesión
        W:Section(scriptText("ESTA SESIÓN", "THIS SESSION"))
        local ses = W:Box({ Gap = 4 })
        local sesTime = ses:Row(scriptText("Tiempo", "Time"), { Split = 0.4 })
        local sesXP = ses:Row(scriptText("XP ganada", "XP earned"), { Split = 0.4 })
        local sesTokens = ses:Row(scriptText("Tokens", "Tokens"), { Split = 0.4 })
        local sesPoints = ses:Row(scriptText("Puntos", "Points"), { Split = 0.4 })
        local sesWins = ses:Row(scriptText("Victorias", "Wins"), { Split = 0.4 })

        Card = {
            Gui = W.Gui, Level = W.BadgeChip, XPLeft = xp.Left, XPRight = xp.Right, Fill = xp.Fill, Tiles = tileMap,
            StateChip = stateChip, StateStroke = stateStroke, Speed = speedText, SpeedFill = speedFill, Item = itemText, Bot = botText,
            SesTime = sesTime, SesXP = sesXP, SesTokens = sesTokens, SesPoints = sesPoints, SesWins = sesWins,
        }
    end

    -- valores con "+N" verde cuando suben
    local function setTile(key, value, text)
        local t = Card and Card.Tiles[key]
        if not t then return end
        t.value.Text = text or short(value)
        if t.last and value > t.last and key ~= "ToLevel" then
            t.pop.Text = "+" .. short(value - t.last)
            t.pop.TextTransparency = 0
            TweenService:Create(t.pop, TweenInfo.new(1.6, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { TextTransparency = 1 }):Play()
        end
        t.last = value
    end
    local function updateAccount()
        if not Card then return end
        setTile("Tokens", currency("Tokens"))
        setTile("Points", currency("Points"))
        setTile("Tickets", tonumber(call("useEvent", "Balance")) or 0)
        setTile("Survivals", counter("Survivals"))
        setTile("Streak", counter("Streak"))
    end
    local function updateLevel()
        if not Card then return end
        local level = tonumber(call("useProgression", "Level")) or 1
        local xp = tonumber(call("useProgression", "XP")) or 0
        local req = tonumber(call("useProgression", "RequiredXP", level)) or math.max(level * 100, 1)
        local progress = math.clamp(tonumber(call("useProgression", "Progress")) or (xp / math.max(req, 1)), 0, 1)
        -- XP ganada en la sesión (cuenta también las subidas de nivel)
        if session then
            if session.lvl and session.xp then
                if level == session.lvl then
                    session.xpGained = session.xpGained + math.max(0, xp - session.xp)
                elseif level > session.lvl then
                    session.xpGained = session.xpGained + math.max(0, (session.req or 0) - session.xp) + xp
                end
            end
            session.lvl, session.xp, session.req = level, xp, req
        end
        Card.Level.Text = scriptText("NV ", "LV ") .. level
        Card.XPLeft.Text = "XP " .. fmt(xp) .. " / " .. fmt(req)
        Card.XPRight.Text = math.floor(progress * 100) .. "%"
        TweenService:Create(Card.Fill, TweenInfo.new(0.4, Enum.EasingStyle.Quad), { Size = UDim2.fromScale(progress, 1) }):Play()
        setTile("ToLevel", math.max(req - xp, 0), short(math.max(req - xp, 0)) .. " XP")
    end
    local STATES = {
        run = { "Corriendo", "Running", Color3.fromRGB(110, 170, 255) },
        idle = { "Quieto", "Idle", Color3.fromRGB(160, 160, 170) },
        air = { "En el aire", "In the air", Color3.fromRGB(180, 140, 255) },
        downed = { "Derribado", "Downed", Color3.fromRGB(255, 85, 85) },
        carried = { "Te llevan", "Being carried", Color3.fromRGB(70, 70, 80) },
        carrying = { "Cargando", "Carrying", Color3.fromRGB(80, 230, 130) },
        none = { "Sin personaje", "No character", Color3.fromRGB(120, 120, 130) },
    }
    local function updateLive()
        if not Card then return end
        local mine, bots = localChar()
        local stateKey, speed, item = "none", 0, nil
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if mine then
            local okS, st = pcall(function() return mine.State and mine.State.State end)
            local reg = mine.DataRegistry
            local function get(k)
                if not reg then return nil end
                local ok, v = pcall(function() return reg:Get(k) end)
                return ok and v or nil
            end
            speed = tonumber(get("Speed")) or (root and Vector3.new(root.AssemblyLinearVelocity.X, 0, root.AssemblyLinearVelocity.Z).Magnitude) or 0
            item = get("EquippedName")
            local carrying = get("Carrying")
            if okS and st == "Downed" then stateKey = "downed"
            elseif okS and st == "Carried" then stateKey = "carried"
            elseif carrying ~= nil and carrying ~= false and carrying ~= 0 then stateKey = "carrying"
            elseif char and char:GetAttribute("Grounded") == false then stateKey = "air"
            elseif speed > 1 then stateKey = "run"
            else stateKey = "idle" end
        end
        local s = STATES[stateKey]
        Card.StateChip.Text = scriptText(s[1], s[2])
        Card.StateChip.TextColor3 = s[3]:Lerp(Color3.new(1, 1, 1), 0.35)
        Card.StateStroke.Color = s[3]
        Card.Speed.Text = string.format("%d", math.floor(speed + 0.5)) .. scriptText(" vel", " spd")
        Card.SpeedFill.Size = UDim2.fromScale(math.clamp(speed / 80, 0, 1), 1)
        Card.Item.Text = mine and pretty(item) or "-"
        local best, bestDist = nil, math.huge
        if root then
            for _, b in ipairs(bots) do
                local d = (b.PrimaryPart.Position - root.Position).Magnitude
                if d < bestDist then best, bestDist = b, d end
            end
        end
        if best then
            local name = (best.Model and best.Model.Name) or "Bot"
            Card.Bot.Text = string.format("%s · %d m", name, math.floor(bestDist))
            Card.Bot.TextColor3 = bestDist < 30 and Color3.fromRGB(255, 90, 90) or (bestDist < 70 and Color3.fromRGB(255, 200, 90) or Color3.fromRGB(120, 230, 140))
        else
            Card.Bot.Text = scriptText("Ninguno", "None")
            Card.Bot.TextColor3 = Color3.fromRGB(120, 230, 140)
        end
    end
    local function updateSession()
        if not Card or not session then return end
        local mins = math.max((os.clock() - session.t0) / 60, 1 / 60)
        local secs = math.floor(os.clock() - session.t0)
        Card.SesTime.Text = string.format("%d:%02d", math.floor(secs / 60), secs % 60)
        local tokens = currency("Tokens") - session.tokens
        local points = currency("Points") - session.points
        local wins = counter("Survivals") - session.wins
        Card.SesXP.Text = string.format("+%s  ·  %s/min", short(session.xpGained), short(session.xpGained / mins))
        Card.SesTokens.Text = string.format("%s%s  ·  %s/min", tokens >= 0 and "+" or "", short(tokens), short(tokens / mins))
        Card.SesPoints.Text = string.format("%s%s  ·  %s/min", points >= 0 and "+" or "", short(points), short(points / mins))
        Card.SesWins.Text = (wins >= 0 and "+" or "") .. short(wins)
    end

    local function enable()
        local ok, err = pcall(function()
            local folder = ReplicatedStorage.Client.Services.UserData
            for _, name in ipairs({ "useCurrency", "useProgression", "useEvent", "useCounters" }) do
                local okH, h = pcall(function() return require(folder:FindFirstChild((string.gsub(name, "^use", "")))) end)
                hooks[name] = okH and h or nil
            end
        end)
        if not ok or not hooks.useCurrency or not hooks.useProgression then
            warn("[Ver stats] No se pudieron cargar los datos del juego: " .. tostring(err))
            return
        end
        destroyCard()
        buildCard()
        session = { t0 = os.clock(), tokens = currency("Tokens"), points = currency("Points"), wins = counter("Survivals"), xpGained = 0 }
        for name, fn in pairs({ useCurrency = updateAccount, useEvent = updateAccount, useCounters = updateAccount, useProgression = updateLevel }) do
            local h = hooks[name]
            if h and type(h.Observe) == "function" then
                local okO, disconnect = pcall(h.Observe, function() pcall(fn) end)
                if okO and type(disconnect) == "function" then observers[#observers + 1] = disconnect end
            end
        end
        local acc, accS = 0, 0
        local conn = RunService.Heartbeat:Connect(function(dt)
            acc, accS = acc + dt, accS + dt
            if acc >= 0.2 then acc = 0 pcall(updateLive) end
            if accS >= 1 then accS = 0 pcall(updateSession) end
        end)
        observers[#observers + 1] = function() conn:Disconnect() end
        pcall(updateAccount)
        pcall(updateLevel)
        pcall(updateLive)
        pcall(updateSession)
    end

    TabExtra:CreateFloatingToggle("Ver stats", "Show Stats", false, function(state)
        if state then enable() else destroyCard() session = nil end
    end)
    TabExtra:CreateDivider()
end
