function AllDesign.CurrentIcon(key)
    local themeName = nil
    pcall(function()
        themeName = UI.CurrentTheme
    end)
    local themed = AllDesign.TabIcons[themeName]
    if type(themed) == "table" and themed[key] then
        return themed[key]
    end
    return AllDesign.DefaultTabIcons[key]
end

-- Las piezas las arma la librería (YinYang.Kit.Page) con el tema activo; acá solo se pasan nombres y textos.
-- Mismas firmas que antes: las pestañas que las usan no cambian.
function AllDesign.Page()
    local K = YYKit()
    if not (K and K.Page) then error("la librería UI no tiene las piezas de página (actualizala)") end
    return K.Page
end

function AllDesign.Card(page, name, height, transparency)
    return AllDesign.Page().Card(page, {Name = name, Height = height, Transparency = transparency})
end

function AllDesign.Label(parent, spanish, english, textSize, font, role, position, size)
    return AllDesign.Page().Label(parent, {Text = scriptText(spanish, english), Es = spanish, En = english, TextSize = textSize, Font = font,
        Role = role, Position = position, Size = size})
end

function AllDesign.Header(page, titleSpanish, titleEnglish, descSpanish, descEnglish, iconKey)
    iconKey = iconKey or "All"
    local header = AllDesign.Page().Header(page, {Name = "AllDesignHeader", BarName = "AllDesignAccentBar",
        IconFn = function() return AllDesign.CurrentIcon(iconKey) end,
        Title = scriptText(titleSpanish, titleEnglish), TitleEs = titleSpanish, TitleEn = titleEnglish,
        Desc = scriptText(descSpanish, descEnglish), DescEs = descSpanish, DescEn = descEnglish})
    return header
end

function AllDesign.Field(page, titleSpanish, titleEnglish, placeholderSpanish, placeholderEnglish)
    return AllDesign.Page().Field(page, {Name = "AllDesignField",
