-- ===== PESTAÑA COLOR: colores del HUD de Evade (ruedas, vida, velocidad y botones de celular) =====
-- El juego vuelve a pintar varios de estos elementos (SetHealth, ButtonActive, hover de las ruedas),
-- asi que cada propiedad se escucha con GetPropertyChangedSignal y se repinta con el color elegido.
-- No hay nada por frame: solo reacciona cuando el juego cambia un color.
-- El HUD (PlayerGui.Game) se borra y se vuelve a crear entre partidas: se re-engancha solo.
-- Los colores se guardan en su propio archivo (no toca SaveSettings).
function setupColorTab()
local TabColor = UI:CreateTab("Color", "Color", "rbxassetid://78348824672381")
local page = TabColor.Page

local HC = {
    File = "YinYang_HudColors.json",
    Saved = {},      -- ["Item:parte"] = Color3 elegido (nil = color original del juego)
    Items = {},
    Entries = {},    -- una por item+parte
    Hud = nil,       -- PlayerGui.Game.HUD actual
    Jump = nil,      -- PlayerGui.TouchGui.TouchControlFrame.JumpButton actual
    HudConns = {},
    LastLive = 0,
    Orig = setmetatable({}, { __mode = "k" }), -- [inst] = { [prop] = ultimo color puesto por el juego }
}

local WHITE = Color3.new(1, 1, 1)
local PRESS_GRAY = Color3.new(0.1, 0.1, 0.1)      -- MobileButtons:ButtonActive (icono presionado)
local PRESS_BG = Color3.new(0.5, 0.5, 0.5)        -- MobileButtons:ButtonActive (fondo presionado)
local GAME_LOW_HP = Color3.fromRGB(255, 78, 78)   -- CharacterStatus:SetHealth (vida < 25)

local PART_NAMES = {
    icon = { "Icono", "Icon" },
    bg = { "Fondo", "Background" },
    border = { "Borde", "Border" },
    main = { "Color", "Color" },
}

local function sameColor(a, b)
    if typeof(a) ~= "Color3" or typeof(b) ~= "Color3" then
        return false
    end
    return math.abs(a.R - b.R) < 0.004 and math.abs(a.G - b.G) < 0.004 and math.abs(a.B - b.B) < 0.004
end

local function toHex(c)
    return string.format("%02X%02X%02X", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
end

local function fromHex(s)
    s = tostring(s or ""):gsub("#", ""):gsub("%s", "")
    if not s:match("^%x%x%x%x%x%x$") then
        return nil
    end
    return Color3.fromRGB(tonumber(s:sub(1, 2), 16), tonumber(s:sub(3, 4), 16), tonumber(s:sub(5, 6), 16))
end

-- ---------- items ----------
-- kind: "wheel" (rueda), "health", "speed", "jump" (boton de Roblox), "button" (boton de celular del juego)
local function addItem(def)
    HC.Items[#HC.Items + 1] = def
    for _, part in ipairs(def.Parts) do
        local entry = { Item = def, Part = part, Key = def.Key .. ":" .. part, Targets = {}, Conns = {} }
        HC.Entries[#HC.Entries + 1] = entry
    end
    return def
end

local function entryOf(item, part)
    for _, e in ipairs(HC.Entries) do
        if e.Item == item and e.Part == part then
            return e
        end
    end
    return nil
end

