-- ---------- filas ----------
local rows = {}
local openPicker -- se define con el selector

local function rowRefresh(row)
    local item = row.Item
    local custom = {}
    for i, part in ipairs(item.Parts) do
        local c = shownColor(item, part)
        local isCustom = HC.Saved[item.Key .. ":" .. part] ~= nil
        local dot = row.Dots[i]
        dot.Frame.BackgroundColor3 = c
        dot.Stroke.Transparency = isCustom and 0.05 or 0.6
        if isCustom then
            custom[#custom + 1] = part
        end
    end
    local tintPart = table.find(item.Parts, "icon") and "icon" or (table.find(item.Parts, "main") and "main" or "border")
    if not row.NoTint then
        row.Preview.ImageColor3 = shownColor(item, tintPart)
    end
    if #custom == 0 then
        setBilingual(row.Sub, "Original", "Original")
    elseif #item.Parts == 1 then
        local hex = "#" .. toHex(HC.Saved[item.Key .. ":" .. custom[1]])
        setBilingual(row.Sub, hex, hex)
    else
        local es, en = {}, {}
        for _, part in ipairs(custom) do
            es[#es + 1] = PART_NAMES[part][1]
            en[#en + 1] = PART_NAMES[part][2]
        end
        setBilingual(row.Sub, table.concat(es, " · "), table.concat(en, " · "))
    end
end

local function refreshAllRows()
    for _, row in pairs(rows) do
        rowRefresh(row)
    end
end

