local function bottomButton(es, en, xScale, xOffset, role, textRole)
    local b = new("TextButton", {
        Size = UDim2.new(1 / 3, -12, 0, 34),
        Position = UDim2.new(xScale, xOffset, 1, -46),
        BackgroundColor3 = pal()[role],
        BorderSizePixel = 0,
        AutoButtonColor = false,
        Text = scriptText(es, en),
        TextColor3 = pal()[textRole] or AvatarContrastColor(pal()[role]),
        TextSize = 12,
        Font = Enum.Font.GothamBold,
        ZIndex = 273,
    }, panel)
    b:SetAttribute("ThemeRole", role)
    b:SetAttribute("TextSpanish", es)
    b:SetAttribute("TextEnglish", en)
    b:SetAttribute("IgnoreTextEffect", true)
    if textRole then
        b:SetAttribute("ThemeTextRole", textRole)
    end
    corner(b, 8)
    return b
end
