local applyButton = bottomButton("Aplicar", "Apply", 2 / 3, -2, "Accent", "AccentText")

-- ---------- logica del selector ----------
local function pickerColor()
    return Color3.fromHSV(Pk.H, Pk.S, Pk.V)
end

local function refreshChips()
    local row = Pk.Row
    if not row then
        return
    end
    local multi = #row.Item.Parts > 1
    chipRow.Visible = multi
    for part, chip in pairs(Pk.Chips) do
        local used = table.find(row.Item.Parts, part) ~= nil
        chip.Button.Visible = multi and used
        if used then
            chip.Dot.BackgroundColor3 = shownColor(row.Item, part)
            local active = part == Pk.Part
            chip.Stroke.Transparency = active and 0 or 1
            chip.Button.BackgroundTransparency = active and 0 or 0.4
        end
    end
end

local function refreshPicker()
    local selected = pickerColor()
    pickerArea.BackgroundColor3 = Color3.fromHSV(Pk.H, 1, 1)
    afterSwatch.BackgroundColor3 = selected
    svHandle.Position = UDim2.new(Pk.S, 0, 1 - Pk.V, 0)
    hueHandle.Position = UDim2.new(0.5, 0, Pk.H, 0)
    if not hexField:IsFocused() then hexField.Text = "#" .. toHex(selected) end
    if not redField:IsFocused() then redField.Text = tostring(math.floor(selected.R * 255 + 0.5)) end
    if not greenField:IsFocused() then greenField.Text = tostring(math.floor(selected.G * 255 + 0.5)) end
    if not blueField:IsFocused() then blueField.Text = tostring(math.floor(selected.B * 255 + 0.5)) end
end

-- aplica en vivo (sin guardar) el color de la parte que se esta editando
local function livePaint(color, force)
    local row = Pk.Row
    if not row then
        return
    end
    local now = os.clock()
    if not force and now - HC.LastLive < 1 / 30 then
        return
    end
    HC.LastLive = now
    local entry = entryOf(row.Item, Pk.Part)
    HC.Saved[entry.Key] = color
    applyEntry(entry)
    rowRefresh(row)
    refreshChips()
end

setPickerColor = function(color, paint)
    local h, s, v = color:ToHSV()
    if s > 0.001 then
        Pk.H = h -- en grises se conserva el tono para que la barra no salte
    end
    Pk.S, Pk.V = s, v
    refreshPicker()
    if paint then
        livePaint(color, true)
    end
end

local function selectPart(part)
    Pk.Part = part
    local key = Pk.Row.Item.Key .. ":" .. part
    local current = HC.Saved[key] or defaultColor(Pk.Row.Item, part)
    beforeSwatch.BackgroundColor3 = Pk.Before[key] or defaultColor(Pk.Row.Item, part)
    setPickerColor(current, false)
    refreshChips()
end

for part, chip in pairs(Pk.Chips) do
    chip.Button.Activated:Connect(function()
        if Pk.Row then
            selectPart(part)
        end
    end)
end

local function closePicker(keep)
    local row = Pk.Row
    if not row then
        return
    end
    if not keep then
        -- Cancelar: vuelve todo lo que se toco a como estaba al abrir
        for _, part in ipairs(row.Item.Parts) do
            local key = row.Item.Key .. ":" .. part
            HC.Saved[key] = Pk.Before[key]
            applyEntry(entryOf(row.Item, part))
        end
    else
        saveFile()
    end
    rowRefresh(row)
    statusRefresh()
    Pk.Row, Pk.Drag = nil, nil
    overlay.Visible = false
end

openPicker = function(row)
    Pk.Row = row
    Pk.Before = {}
    for _, part in ipairs(row.Item.Parts) do
        local key = row.Item.Key .. ":" .. part
        Pk.Before[key] = HC.Saved[key]
    end
    setBilingual(pickerTitle, "Color · " .. row.Item.Es, "Color · " .. row.Item.En)
    overlay.Visible = true
    selectPart(row.Item.Parts[1])
end

local function updateSV(position)
    local size = pickerArea.AbsoluteSize
    if size.X <= 0 or size.Y <= 0 then return end
    Pk.S = math.clamp((position.X - pickerArea.AbsolutePosition.X) / size.X, 0, 1)
    Pk.V = math.clamp(1 - (position.Y - pickerArea.AbsolutePosition.Y) / size.Y, 0, 1)
    refreshPicker()
    livePaint(pickerColor(), false)
end

local function updateHue(position)
    local size = hueBar.AbsoluteSize
    if size.Y <= 0 then return end
    Pk.H = math.clamp((position.Y - hueBar.AbsolutePosition.Y) / size.Y, 0, 0.999)
    refreshPicker()
    livePaint(pickerColor(), false)
end

local function isPress(input)
    return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end
pickerArea.InputBegan:Connect(function(input)
    if isPress(input) then
        Pk.Drag = "SV"
        updateSV(input.Position)
    end
end)
hueBar.InputBegan:Connect(function(input)
    if isPress(input) then
        Pk.Drag = "H"
        updateHue(input.Position)
    end
end)
UserInputService.InputChanged:Connect(function(input)
    if not Pk.Drag then return end
    if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
        if Pk.Drag == "SV" then updateSV(input.Position) else updateHue(input.Position) end
    end
end)
UserInputService.InputEnded:Connect(function(input)
    if Pk.Drag and isPress(input) then
        Pk.Drag = nil
        livePaint(pickerColor(), true) -- el ultimo punto siempre se aplica
    end
end)

hexField.FocusLost:Connect(function()
    local c = fromHex(hexField.Text)
    if c then
        setPickerColor(c, true)
    else
        refreshPicker()
    end
end)
local function applyRGB()
    local c = Color3.fromRGB(
        math.clamp(tonumber(redField.Text) or 0, 0, 255),
        math.clamp(tonumber(greenField.Text) or 0, 0, 255),
        math.clamp(tonumber(blueField.Text) or 0, 0, 255)
    )
    setPickerColor(c, true)
end
redField.FocusLost:Connect(applyRGB)
greenField.FocusLost:Connect(applyRGB)
blueField.FocusLost:Connect(applyRGB)

resetButton.Activated:Connect(function()
    local row = Pk.Row
    if not row then return end
    local entry = entryOf(row.Item, Pk.Part)
    HC.Saved[entry.Key] = nil
    applyEntry(entry)
    rowRefresh(row)
    setPickerColor(defaultColor(row.Item, Pk.Part), false)
    refreshChips()
end)
cancelButton.Activated:Connect(function() closePicker(false) end)
pickerClose.Activated:Connect(function() closePicker(false) end)
applyButton.Activated:Connect(function() closePicker(true) end)

-- ---------- temas rapidos + bordes animados ----------
-- (en una funcion aparte: setupColorTab ya tiene muchos locales y Luau permite 200 por funcion)
local function buildThemeCards()
    local function rgb(r, g, b)
        return Color3.fromRGB(r, g, b)
    end
    -- Icon = iconos y saltar · Bg = fondo de botones · Border = bordes y anillos · WheelBg = casilleros de las ruedas
    -- (se evitan a proposito los colores que el juego usa como aviso: blanco del anillo, grises de "presionado"
    --  y el rojo de poca vida)
    local THEMES = {
        { Id = "neon", Es = "Neón", En = "Neon", Icon = rgb(0, 255, 200), Bg = rgb(12, 10, 24), Border = rgb(255, 0, 200), Health = rgb(0, 255, 170), Speed = rgb(255, 0, 200), WheelBg = rgb(24, 18, 44) },
        { Id = "sunset", Es = "Atardecer", En = "Sunset", Icon = rgb(255, 205, 130), Bg = rgb(60, 20, 32), Border = rgb(255, 110, 60), Health = rgb(255, 175, 95), Speed = rgb(255, 125, 85), WheelBg = rgb(92, 32, 42) },
        { Id = "ocean", Es = "Océano", En = "Ocean", Icon = rgb(170, 230, 255), Bg = rgb(10, 35, 60), Border = rgb(60, 170, 255), Health = rgb(90, 220, 255), Speed = rgb(60, 170, 255), WheelBg = rgb(20, 52, 90) },
        { Id = "forest", Es = "Bosque", En = "Forest", Icon = rgb(190, 255, 170), Bg = rgb(15, 40, 20), Border = rgb(90, 200, 90), Health = rgb(120, 255, 120), Speed = rgb(200, 230, 90), WheelBg = rgb(26, 62, 32) },
        { Id = "sakura", Es = "Sakura", En = "Sakura", Icon = rgb(255, 222, 236), Bg = rgb(70, 25, 45), Border = rgb(255, 140, 190), Health = rgb(255, 150, 200), Speed = rgb(255, 182, 212), WheelBg = rgb(110, 40, 70) },
        { Id = "gold", Es = "Oro", En = "Gold", Icon = rgb(255, 215, 90), Bg = rgb(26, 20, 6), Border = rgb(255, 190, 40), Health = rgb(255, 222, 100), Speed = rgb(255, 190, 40), WheelBg = rgb(46, 36, 10) },
        { Id = "ice", Es = "Hielo", En = "Ice", Icon = rgb(236, 250, 255), Bg = rgb(30, 45, 60), Border = rgb(200, 240, 255), Health = rgb(180, 240, 255), Speed = rgb(200, 240, 255), WheelBg = rgb(50, 70, 92) },
        { Id = "blood", Es = "Sangre", En = "Blood", Icon = rgb(255, 96, 96), Bg = rgb(30, 2, 4), Border = rgb(205, 0, 20), Health = rgb(232, 40, 62), Speed = rgb(255, 92, 92), WheelBg = rgb(62, 6, 8) },
        { Id = "purple", Es = "Galaxia", En = "Galaxy", Icon = rgb(222, 192, 255), Bg = rgb(35, 15, 60), Border = rgb(170, 100, 255), Health = rgb(190, 140, 255), Speed = rgb(170, 100, 255), WheelBg = rgb(56, 26, 92) },
        { Id = "mono", Es = "Mono", En = "Mono", Icon = rgb(245, 245, 245), Bg = rgb(16, 16, 16), Border = rgb(232, 232, 232), Health = rgb(240, 240, 240), Speed = rgb(240, 240, 240), WheelBg = rgb(32, 32, 32) },
    }

    -- "Mi hub": se arma al tocarlo con el tema actual de la libreria
    local function hubTheme()
        local p = GetAvatarPalette()
        return { Id = "hub", Es = "Mi hub", En = "My hub", Icon = p.Text, Bg = p.Background, Border = p.Accent, Health = p.Accent, Speed = p.Accent, WheelBg = p.Secondary }
    end

    local function themeColor(t, item, part)
        if item.Kind == "button" or item.Kind == "topbar" then
            if part == "icon" then return t.Icon end
            if part == "bg" then return t.Bg end
            return t.Border
        elseif item.Kind == "wheel" then
            if part == "bg" then return t.WheelBg end
            return t.Border
        elseif item.Kind == "health" then
            return t.Health
        elseif item.Kind == "speed" then
            return t.Speed
        end
        if part == "border" then return t.Border end -- borde del botón de saltar
        return t.Icon -- jump
    end

    local undoButton -- se crea con la tarjeta
    local function applyAllEntries()
        for _, entry in ipairs(HC.Entries) do
            applyEntry(entry)
        end
        saveFile()
        refreshAllRows()
        statusRefresh()
    end

    -- t = nil vuelve todo a los colores del juego
    local function applyTheme(t)
        HC.Undo = table.clone(HC.Saved)
        table.clear(HC.Saved)
        if t then
            for _, entry in ipairs(HC.Entries) do
                HC.Saved[entry.Key] = themeColor(t, entry.Item, entry.Part)
            end
        end
        applyAllEntries()
        if undoButton then
            local es = t and t.Es or "Original"
            local en = t and t.En or "Original"
            setBilingual(undoButton.Label, "Deshacer · " .. es, "Undo · " .. en)
            undoButton.Button.Visible = true
        end
    end

    -- ----- tarjeta: temas rapidos -----
    local function card(name, order)
        local c = new("Frame", {
            Name = name,
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = pal().Secondary,
            BackgroundTransparency = 0.78,
            BorderSizePixel = 0,
            LayoutOrder = order,
            ZIndex = 10,
        }, page)
        c:SetAttribute("ThemeRole", "Secondary")
        corner(c, 12)
        stroke(c, 0.55)
        new("UIPadding", { PaddingTop = UDim.new(0, 10), PaddingBottom = UDim.new(0, 10), PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }, c)
        new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }, c)
        return c
    end

    local function cardTitle(parent, es, en, subEs, subEn)
        local holder = new("Frame", { Size = UDim2.new(1, 0, 0, subEs and 34 or 18), BackgroundTransparency = 1, LayoutOrder = 1, ZIndex = 11 }, parent)
        textLabel(holder, es, en, 12, Enum.Font.GothamBlack, "Text", { Size = UDim2.new(1, -130, 0, 16) })
        if subEs then
            textLabel(holder, subEs, subEn, 10, Enum.Font.GothamMedium, "TextDim", {
                Size = UDim2.new(1, 0, 0, 14),
                Position = UDim2.fromOffset(0, 18),
            })
        end
        return holder
    end

    local function hScroller(parent, height, order)
        local sc = new("ScrollingFrame", {
            Size = UDim2.new(1, 0, 0, height),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ScrollingDirection = Enum.ScrollingDirection.X,
            AutomaticCanvasSize = Enum.AutomaticSize.X,
            CanvasSize = UDim2.new(0, 0, 0, 0),
            ScrollBarThickness = 0,
            ElasticBehavior = Enum.ElasticBehavior.Always,
            LayoutOrder = order,
            ZIndex = 11,
        }, parent)
        new("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            Padding = UDim.new(0, 8),
            SortOrder = Enum.SortOrder.LayoutOrder,
        }, sc)
        new("UIPadding", { PaddingLeft = UDim.new(0, 2), PaddingRight = UDim.new(0, 2) }, sc)
        return sc
    end

    local function pressBounce(button)
        local scale = new("UIScale", { Scale = 1 }, button)
        button.MouseButton1Down:Connect(function()
            KeyTweenService:Create(scale, TweenInfo.new(0.08), { Scale = 0.94 }):Play()
        end)
        local function up()
            KeyTweenService:Create(scale, TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
        end
        button.MouseButton1Up:Connect(up)
        button.MouseLeave:Connect(up)
    end

    local themesCard = card("ColorThemes", -90)
    local themesTitle = cardTitle(themesCard, "TEMAS RÁPIDOS", "QUICK THEMES", "Un toque y se pinta todo el HUD. Después podés retocar cada parte.", "One tap paints the whole HUD. You can fine-tune each part later.")

    -- boton deshacer (aparece despues de aplicar un tema)
    local undo = new("TextButton", {
        AnchorPoint = Vector2.new(1, 0),
        Position = UDim2.new(1, 0, 0, -2),
        Size = UDim2.fromOffset(0, 20),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundColor3 = pal().AccentOff,
        BorderSizePixel = 0,
        AutoButtonColor = false,
        Text = "",
        Visible = false,
        ZIndex = 12,
    }, themesTitle)
    undo:SetAttribute("ThemeRole", "AccentOff")
    corner(undo, 999)
    new("UIPadding", { PaddingLeft = UDim.new(0, 9), PaddingRight = UDim.new(0, 9) }, undo)
    local undoLabel = textLabel(undo, "Deshacer", "Undo", 10, Enum.Font.GothamBold, "Text", {
        Size = UDim2.fromOffset(0, 20),
        AutomaticSize = Enum.AutomaticSize.X,
        TextTruncate = Enum.TextTruncate.None,
        ZIndex = 13,
    })
    undoButton = { Button = undo, Label = undoLabel }
    undo.Activated:Connect(function()
        if not HC.Undo then
            return
        end
        table.clear(HC.Saved)
        for key, c in pairs(HC.Undo) do
            HC.Saved[key] = c
        end
        HC.Undo = nil
        applyAllEntries()
        undo.Visible = false
    end)

    local themeRow = hScroller(themesCard, 78, 2)

    -- la tarjeta muestra el tema tal cual: fondo = fondo de botones, borde = bordes, texto = iconos
    local function themeTile(order, getTheme, isOriginal)
        local t = getTheme()
        local tile = new("TextButton", {
            Size = UDim2.fromOffset(92, 72),
            BackgroundColor3 = isOriginal and Color3.fromRGB(28, 28, 32) or t.Bg,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            LayoutOrder = order,
            ZIndex = 12,
        }, themeRow)
        corner(tile, 12)
        local tileStroke = new("UIStroke", { Color = isOriginal and Color3.fromRGB(120, 120, 130) or t.Border, Thickness = 2, Transparency = 0.05 }, tile)
        local dots = new("Frame", {
            Size = UDim2.fromOffset(0, 18),
            AutomaticSize = Enum.AutomaticSize.X,
            Position = UDim2.fromOffset(9, 9),
            BackgroundTransparency = 1,
            ZIndex = 13,
        }, tile)
        new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, -5), SortOrder = Enum.SortOrder.LayoutOrder }, dots)
        local dotFrames = {}
        for i = 1, 3 do
