        name:SetAttribute("IgnoreTextEffect", true)
        name:SetAttribute("TextSpanish", t.Es)
        name:SetAttribute("TextEnglish", t.En)
        local function paintTile(th)
            if isOriginal then
                dotFrames[1].BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                dotFrames[2].BackgroundColor3 = Color3.fromRGB(112, 255, 73)
                dotFrames[3].BackgroundColor3 = Color3.fromRGB(255, 170, 40)
