            end
            tile.BackgroundColor3 = th.Bg
            tileStroke.Color = th.Border
            name.TextColor3 = th.Icon
            dotFrames[1].BackgroundColor3 = th.Icon
            dotFrames[2].BackgroundColor3 = th.Border
            dotFrames[3].BackgroundColor3 = th.Health
