    -- =====================================================================
    -- PREMIUM "Yin Yang Colors" (gamepass 2026508642): bordes animados
    -- =====================================================================
    -- El pase queda en la CUENTA de Roblox: se consulta a Roblox cada vez que carga el script.
    -- El archivo local solo se usa si Roblox no responde. En su propia función por el límite de locales.
    local function buildColorsPremium()
        local CFG = { GamepassId = 2026508642, Owners = { "mousoza", "sephtis_morana", "user_0r009omn", "Phamdat8FRnw", "Doreayi", "WFenixxvw" }, CacheFile = "YinYang_ColorsPremium.json" }
        local MPS = game:GetService("MarketplaceService")
        local PR = { owned = false, checking = true, listeners = {}, price = nil }
        local PASS_URL = "https://www.roblox.com/game-pass/" .. tostring(CFG.GamepassId)
        local GOLD_A, GOLD_B = Color3.fromRGB(255, 214, 90), Color3.fromRGB(255, 140, 40)
        local DARK_GOLD = Color3.fromRGB(60, 34, 8)
        local Z = 280 -- por encima del selector de color (270-276)

        local function readCache()
            local ok, data = pcall(function()
                if type(isfile) == "function" and type(readfile) == "function" and isfile(CFG.CacheFile) then
                    return HttpService:JSONDecode(readfile(CFG.CacheFile))
                end
                return nil
            end)
            return ok and type(data) == "table" and data.UserId == LocalPlayer.UserId and data.Pass == CFG.GamepassId and data.Owned == true
        end
        local function writeCache(owned)
            pcall(function()
                if type(writefile) == "function" then
                    writefile(CFG.CacheFile, HttpService:JSONEncode({ UserId = LocalPlayer.UserId, Pass = CFG.GamepassId, Owned = owned == true, At = os.time() }))
                end
            end)
        end
        function PR.set(owned, fromApi)
            PR.owned = owned == true
            PR.checking = false
            if fromApi then writeCache(PR.owned) end
            for _, fn in ipairs(PR.listeners) do pcall(fn, PR.owned) end
        end
        function PR.check()
            PR.checking = true
            for _, fn in ipairs(PR.listeners) do pcall(fn, PR.owned) end
            task.spawn(function()
                local me = string.lower(LocalPlayer.Name)
                for _, n in ipairs(CFG.Owners) do
                    if string.lower(n) == me then PR.set(true, false) return end
                end
                local okOwn, owns = false, nil
                for attempt = 1, 3 do
                    okOwn, owns = pcall(function()
                        return MPS:UserOwnsGamePassAsync(LocalPlayer.UserId, CFG.GamepassId)
                    end)
                    if okOwn then break end
                    task.wait(attempt * 1.5)
                end
                local okInfo, info = pcall(function()
                    return MPS:GetProductInfo(CFG.GamepassId, Enum.InfoType.GamePass)
                end)
                if okInfo and type(info) == "table" then
                    PR.price = tonumber(info.PriceInRobux)
                    local creator = info.Creator
                    if type(creator) == "table" and tonumber(creator.CreatorTargetId) == LocalPlayer.UserId then
                        owns, okOwn = true, true -- el creador del pase siempre tiene acceso
                    end
                end
                if okOwn then
                    PR.set(owns == true, true)
                else
                    PR.set(readCache(), false) -- Roblox no respondió: última verificación buena de esta cuenta
                end
            end)
        end
        pcall(function()
            MPS.PromptGamePassPurchaseFinished:Connect(function(player, passId, purchased)
                if player == LocalPlayer and tonumber(passId) == CFG.GamepassId and purchased then
                    PR.set(true, true)
                end
            end)
        end)

        -- ---------- piezas doradas ----------
        local function gold(parent, rotation)
            return new("UIGradient", { Rotation = rotation or 45, Color = ColorSequence.new(GOLD_A, GOLD_B) }, parent)
        end
        local function drawLock(parent, px, z)
            local holder = new("Frame", { Size = UDim2.fromOffset(px, px), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), BackgroundTransparency = 1, ZIndex = z }, parent)
            local shackle = new("Frame", { Size = UDim2.fromScale(0.56, 0.62), AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale(0.5, 0.02), BackgroundTransparency = 1, ZIndex = z }, holder)
            corner(shackle, 999)
            gold(new("UIStroke", { Color = WHITE, Thickness = math.max(1.5, px * 0.1) }, shackle), 90)
            local body = new("Frame", { Size = UDim2.fromScale(0.82, 0.56), AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.fromScale(0.5, 1), BackgroundColor3 = WHITE, BorderSizePixel = 0, ZIndex = z + 1 }, holder)
            corner(body, math.max(2, math.floor(px * 0.14)))
            gold(body, 90)
            local hole = new("Frame", { Size = UDim2.fromScale(0.16, 0.36), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.48), BackgroundColor3 = DARK_GOLD, BorderSizePixel = 0, ZIndex = z + 2 }, body)
            corner(hole, 999)
            return holder
        end
        local function goldChip(parent, es, en, size, z, props)
            local c = new("TextLabel", {
                Size = UDim2.fromOffset(0, size + 6),
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundColor3 = WHITE,
                Text = scriptText(es, en),
                TextColor3 = DARK_GOLD,
                TextSize = size,
                Font = Enum.Font.GothamBlack,
                ZIndex = z,
            }, parent)
            c:SetAttribute("IgnoreTextEffect", true)
            c:SetAttribute("TextSpanish", es)
            c:SetAttribute("TextEnglish", en)
            corner(c, 999)
            new("UIPadding", { PaddingLeft = UDim.new(0, 7), PaddingRight = UDim.new(0, 7) }, c)
            gold(c, 0)
            for k, v in pairs(props or {}) do c[k] = v end
            return c
        end

