        KeyTweenService:Create(cardGrad, TweenInfo.new(4, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), { Rotation = 360 }):Play()
        local cardScale = new("UIScale", { Scale = 1 }, Card)
        new("UIPadding", { PaddingTop = UDim.new(0, 14), PaddingBottom = UDim.new(0, 14), PaddingLeft = UDim.new(0, 16), PaddingRight = UDim.new(0, 16) }, Card)

        -- encabezado
        local head = new("Frame", { Size = UDim2.new(1, 0, 0, 60), BackgroundTransparency = 1, ZIndex = Z + 2 }, Card)
        local icon = new("Frame", { Size = UDim2.fromOffset(56, 56), BackgroundColor3 = Color3.fromRGB(40, 26, 8), BorderSizePixel = 0, ZIndex = Z + 2 }, head)
        corner(icon, 16)
