        local headLock = drawLock(icon, 28, Z + 3)
        KeyTweenService:Create(headLock, TweenInfo.new(1.6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { Position = UDim2.new(0.5, 0, 0.5, -3) }):Play()
        goldChip(head, "PREMIUM", "PREMIUM", 10, Z + 3, { Position = UDim2.fromOffset(68, 0) })
        textLabel(head, "Yin Yang Colors", "Yin Yang Colors", 17, Enum.Font.GothamBlack, "Text", { Size = UDim2.new(1, -110, 0, 22), Position = UDim2.fromOffset(68, 20), ZIndex = Z + 3 })
        textLabel(head, "Bordes animados para tu HUD", "Animated borders for your HUD", 10, Enum.Font.GothamMedium, "TextDim", { Size = UDim2.new(1, -110, 0, 14), Position = UDim2.fromOffset(68, 42), ZIndex = Z + 3 })
        local closeBtn = new("TextButton", { Size = UDim2.fromOffset(28, 28), AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 0), BackgroundColor3 = pal().Secondary, Text = "×", TextColor3 = pal().Text, TextSize = 19, Font = Enum.Font.GothamBold, AutoButtonColor = false, ZIndex = Z + 4 }, head)
        closeBtn:SetAttribute("ThemeRole", "Secondary")
        closeBtn:SetAttribute("ThemeTextRole", "Text")
        corner(closeBtn, 999)

        local body = new("Frame", { Size = UDim2.new(1, 0, 1, -70), Position = UDim2.fromOffset(0, 70), BackgroundTransparency = 1, ZIndex = Z + 2 }, Card)
