        new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }, right)

        -- ===== demostración: botones reales del HUD con el borde girando, pasando por cada modo =====
        local demo = new("Frame", { Size = UDim2.new(0.5, -6, 1, 0), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.25, -3, 0.5, 0), BackgroundColor3 = WHITE, BorderSizePixel = 0, ClipsDescendants = true, ZIndex = Z + 2 }, body)
        new("UIAspectRatioConstraint", { AspectRatio = 1 }, demo)
        corner(demo, 14)
        new("UIGradient", { Rotation = 90, Color = ColorSequence.new(Color3.fromRGB(26, 30, 44), Color3.fromRGB(12, 14, 22)) }, demo)
