        for i = 1, 4 do
            new("Frame", { Size = UDim2.new(1, 0, 0, 1), Position = UDim2.fromScale(0, 0.55 + (i / 5) ^ 1.5 * 0.45), BackgroundColor3 = WHITE, BackgroundTransparency = 0.92, BorderSizePixel = 0, ZIndex = Z + 3 }, demo)
        end
        local demoGrads = {}
        local function demoButton(itemKey, x, y, size)
            local item = nil
            for _, it in ipairs(HC.Items) do
                if it.Key == itemKey then item = it end
            end
            local b = new("Frame", { Size = UDim2.fromScale(size, size), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(x, y), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.35, BorderSizePixel = 0, ZIndex = Z + 4 }, demo)
