        local caption = new("TextLabel", { Size = UDim2.new(0.86, 0, 0, 22), AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -8), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.35, Text = "", TextColor3 = WHITE, TextSize = 11, Font = Enum.Font.GothamBlack, ZIndex = Z + 6 }, demo)
        caption:SetAttribute("IgnoreTextEffect", true)
        corner(caption, 999)
        local captionScale = new("UIScale", { Scale = 1 }, caption)
        local demoTweens = {}
        local demoGen = 0
        local DEMO_STEPS = {
            { "rainbow", 2.6, "Arcoíris", "Rainbow" },
            { "neon", 2.6, "Neón", "Neon" },
            { "fire", 1.5, "Fuego · rápido", "Fire · fast" },
            { "ice", 5, "Hielo · lento", "Ice · slow" },
            { "gold", 2.6, "Oro", "Gold" },
            { "galaxy", 2.6, "Galaxia", "Galaxy" },
            { "sunset", 2.6, "Atardecer", "Sunset" },
            { "aurora", 2.6, "Aurora", "Aurora" },
            { "theme", 2.6, "Mi color", "My color" },
        }
        local function spinAll(duration)
            for _, t in ipairs(demoTweens) do t:Cancel() end
            table.clear(demoTweens)
            for _, g in ipairs(demoGrads) do
                g.Rotation = 0
                local t = KeyTweenService:Create(g, TweenInfo.new(duration, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), { Rotation = 360 })
                t:Play()
                table.insert(demoTweens, t)
            end
        end
        local function runDemo(gen)
            local i = 0
            while demoGen == gen and Sheet.Visible do
                i = i % #DEMO_STEPS + 1
                local step = DEMO_STEPS[i]
                local seq = ANIM_MODES[step[1]]
                if step[1] == "theme" then
                    local c = pal().Accent
                    local h, sat = c:ToHSV()
                    seq = gradientOf({ c, Color3.fromHSV(h, sat * 0.3, 1), c })
                end
                for _, g in ipairs(demoGrads) do g.Color = seq end
                spinAll(step[2])
                caption.Text = scriptText(step[3], step[4])
                captionScale.Scale = 0.8
                KeyTweenService:Create(captionScale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
                task.wait(2.4)
            end
        end
        local function startDemo()
            demoGen += 1
            task.spawn(runDemo, demoGen)
        end
        local function stopDemo()
            demoGen += 1
            for _, t in ipairs(demoTweens) do t:Cancel() end
            table.clear(demoTweens)
        end

