    local MODES = {
        { Id = "off", Es = "Apagado", En = "Off" },
        { Id = "rainbow", Es = "Arcoíris", En = "Rainbow" },
        { Id = "neon", Es = "Neón", En = "Neon" },
        { Id = "fire", Es = "Fuego", En = "Fire" },
        { Id = "ice", Es = "Hielo", En = "Ice" },
        { Id = "gold", Es = "Oro", En = "Gold" },
        { Id = "galaxy", Es = "Galaxia", En = "Galaxy" },
        { Id = "sunset", Es = "Atardecer", En = "Sunset" },
        { Id = "ocean", Es = "Océano", En = "Ocean" },
        { Id = "aurora", Es = "Aurora", En = "Aurora" },
        { Id = "toxic", Es = "Tóxico", En = "Toxic" },
        { Id = "candy", Es = "Caramelo", En = "Candy" },
        { Id = "blood", Es = "Sangre", En = "Blood" },
        { Id = "mono", Es = "Blanco y negro", En = "Black & White" },
        { Id = "theme", Es = "Mi color", En = "My color" },
    }
    local STYLES = {
        { Id = "spin", Es = "Girar", En = "Spin" },
        { Id = "swing", Es = "Vaivén", En = "Swing" },
        { Id = "sweep", Es = "Barrido", En = "Sweep" },
    }
    local SPEEDS = {
        { Id = "slow", Es = "Lento", En = "Slow" },
        { Id = "normal", Es = "Normal", En = "Normal" },
        { Id = "fast", Es = "Rápido", En = "Fast" },
    }

    local function loadAnim()
        pcall(function()
            if type(isfile) == "function" and type(readfile) == "function" and isfile(HC.AnimFile) then
                local data = HttpService:JSONDecode(readfile(HC.AnimFile))
                if type(data) == "table" then
                    if data.mode == "off" or ANIM_MODES[data.mode] or data.mode == "theme" then
                        HC.Anim.Mode = data.mode
                    end
                    if ANIM_SPEEDS[data.speed] then
                        HC.Anim.Speed = data.speed
                    end
                    if ANIM_STYLES[data.style] then
                        HC.Anim.Style = data.style
                    end
                end
            end
        end)
    end
    local function saveAnim()
        pcall(function()
            if type(writefile) == "function" then
                writefile(HC.AnimFile, HttpService:JSONEncode({ mode = HC.Anim.Mode, speed = HC.Anim.Speed, style = HC.Anim.Style }))
            end
        end)
    end

    local chips = { mode = {}, speed = {}, style = {} }
    local function refreshAnimChips()
        local p = pal()
        for group, list in pairs(chips) do
            local current = (group == "mode" and (HC.Anim.Locked and "off" or HC.Anim.Mode)) or (group == "style" and HC.Anim.Style) or HC.Anim.Speed
            for id, chip in pairs(list) do
                local on = id == current
                if chip.Lock then chip.Lock.Visible = HC.Anim.Locked end
                chip.Button.BackgroundColor3 = on and p.Accent or p.Secondary
                chip.Button.BackgroundTransparency = on and 0 or 0.35
                chip.Label.TextColor3 = on and AvatarContrastColor(p.Accent) or p.Text
            end
        end
    end

    local function setAnim(mode, speed, style)
        local speedChanged = (speed ~= nil and speed ~= HC.Anim.Speed) or (style ~= nil and style ~= HC.Anim.Style)
        if mode ~= nil then
            HC.Anim.Mode = mode
        end
        if speed ~= nil then
            HC.Anim.Speed = speed
        end
        if style ~= nil then
            HC.Anim.Style = style
        end
        if speedChanged then
            resetAnimGradients()
        end
        for _, entry in ipairs(HC.Entries) do
            applyEntry(entry)
        end
        saveAnim()
        refreshAnimChips()
    end

    local function chip(parent, group, def, order)
        local b = new("TextButton", {
            Size = UDim2.fromOffset(0, 30),
            AutomaticSize = Enum.AutomaticSize.X,
            BackgroundColor3 = pal().Secondary,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            LayoutOrder = order,
            ZIndex = 12,
        }, parent)
        corner(b, 999)
        new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 12) }, b)
        new("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            Padding = UDim.new(0, 6),
            SortOrder = Enum.SortOrder.LayoutOrder,
        }, b)
        if group == "mode" and def.Id ~= "off" then
            -- muestra del degradado (gira solo la del modo activo: un tween nativo)
            local sw = new("Frame", { Size = UDim2.fromOffset(14, 14), BackgroundColor3 = WHITE, BorderSizePixel = 0, LayoutOrder = 1, ZIndex = 13 }, b)
            corner(sw, 999)
            local g = new("UIGradient", {}, sw)
            if def.Id == "theme" then
                local c = pal().Accent
                local h, sat = c:ToHSV()
                g.Color = gradientOf({ c, Color3.fromHSV(h, sat * 0.3, 1), c })
            else
                g.Color = ANIM_MODES[def.Id]
            end
            KeyTweenService:Create(g, TweenInfo.new(3, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), { Rotation = 360 }):Play()
        end
        local label = textLabel(b, def.Es, def.En, 11, Enum.Font.GothamBold, "Text", {
            Size = UDim2.fromOffset(0, 30),
            AutomaticSize = Enum.AutomaticSize.X,
            TextTruncate = Enum.TextTruncate.None,
            LayoutOrder = 2,
            ZIndex = 13,
        })
        label:SetAttribute("ThemeTextRole", nil) -- el color lo maneja refreshAnimChips (activo / no activo)
        local lock = nil
        if (group == "mode" and def.Id ~= "off") or group == "style" then
            -- candado dorado chiquito (premium)
            lock = new("Frame", { Size = UDim2.fromOffset(14, 14), BackgroundColor3 = Color3.fromRGB(40, 26, 8), BorderSizePixel = 0, LayoutOrder = 3, ZIndex = 13 }, b)
            corner(lock, 999)
            CPR.drawLock(lock, 9, 14)
        end
        chips[group][def.Id] = { Button = b, Label = label, Lock = lock }
        pressBounce(b)
        b.Activated:Connect(function()
            if ((group == "mode" and def.Id ~= "off") or group == "style") and HC.Anim.Locked then
                CPR.show() -- sin el pase: ventana premium con la demostración
                return
            end
            if group == "mode" then
                setAnim(def.Id, nil)
            elseif group == "style" then
                setAnim(nil, nil, def.Id)
            else
                setAnim(nil, def.Id)
            end
        end)
    end

    local modeRow = hScroller(animCard, 34, 2)
    for i, def in ipairs(MODES) do
        chip(modeRow, "mode", def, i)
    end
    local speedHolder = new("Frame", { Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1, LayoutOrder = 3, ZIndex = 11 }, animCard)
    textLabel(speedHolder, "Velocidad", "Speed", 11, Enum.Font.GothamBold, "TextDim", { Size = UDim2.fromOffset(70, 30) })
    local speedRow = new("Frame", { Size = UDim2.new(1, -74, 1, 0), Position = UDim2.fromOffset(74, 0), BackgroundTransparency = 1, ZIndex = 11 }, speedHolder)
    new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, speedRow)
    for i, def in ipairs(SPEEDS) do
        chip(speedRow, "speed", def, i)
    end
    -- variantes de movimiento (premium)
    local styleHolder = new("Frame", { Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1, LayoutOrder = 4, ZIndex = 11 }, animCard)
    textLabel(styleHolder, "Movimiento", "Motion", 11, Enum.Font.GothamBold, "TextDim", { Size = UDim2.fromOffset(70, 30) })
    local styleRow = new("Frame", { Size = UDim2.new(1, -74, 1, 0), Position = UDim2.fromOffset(74, 0), BackgroundTransparency = 1, ZIndex = 11 }, styleHolder)
    new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, styleRow)
    for i, def in ipairs(STYLES) do
        chip(styleRow, "style", def, i)
    end

    loadAnim()
    refreshAnimChips()
    table.insert(CPR.listeners, function(owned)
        if CPR.checking then return end
        local was = HC.Anim.Locked
        HC.Anim.Locked = not owned
        animPremiumChip.Visible = not owned
        if was ~= HC.Anim.Locked then
            for _, entry in ipairs(HC.Entries) do
                applyEntry(entry) -- pone o saca los degradados según el pase
            end
        end
        refreshAnimChips()
    end)
    CPR.check()
    -- si el tema de la libreria cambia, los chips toman los colores nuevos
    pcall(function()
        page:GetPropertyChangedSignal("Visible"):Connect(function()
            if page.Visible then
                refreshAnimChips()
            end
        end)
    end)

    -- ----- API para los perfiles (pestaña Extra) -----
    HudColorsAPI = {
        Export = function()
            local out = {}
            for key, c in pairs(HC.Saved) do
                out[key] = toHex(c)
            end
            return out
        end,
        Import = function(map)
            if type(map) ~= "table" then
                return false
            end
            HC.Undo = table.clone(HC.Saved)
            table.clear(HC.Saved)
            for key, hex in pairs(map) do
                local c = fromHex(hex)
                if c then
                    HC.Saved[tostring(key)] = c
                end
            end
            applyAllEntries()
            return true
        end,
        GetAnim = function()
            return { mode = HC.Anim.Mode, speed = HC.Anim.Speed, style = HC.Anim.Style }
        end,
        SetAnim = function(mode, speed, style)
            local okMode = mode == "off" or mode == "theme" or ANIM_MODES[mode] ~= nil
            setAnim(okMode and mode or nil, ANIM_SPEEDS[speed] and speed or nil, ANIM_STYLES[style] and style or nil)
        end,
        RandomTheme = function()
            local t = THEMES[math.random(1, #THEMES)]
            applyTheme(t)
            return t.Es, t.En
        end,
        Themes = THEMES,
        ApplyTheme = applyTheme,
    }
end
