-- BOOMBOX + PERFILES DE LOOK + LOOK SORPRESA (pestana Extra, debajo del toggle Unlock All).
-- Funcion global (no local) por el limite de 200 registros del chunk principal.
function setupUnlockExtras(holder)
    if not holder then
        return
    end
    local PROFILE_FILE = "YinYang_Perfiles.json"
    local MAX_PROFILES = 20
    local WHITE = Color3.new(1, 1, 1)

    local function ua()
        local env = (type(getgenv) == "function" and getgenv()) or _G
        return env.YY_UnlockAll
    end
    local function uaActive()
        local m = ua()
        local ok, on = pcall(function() return m and m.IsEnabled() end)
        return ok and on == true
    end
    local function pal()
        return GetAvatarPalette()
    end
    local function new(class, props, parent)
        local o = YYKitMake(class)
        for k, v in pairs(props) do
            o[k] = v
        end
        if parent then
            o.Parent = parent
        end
        return o
    end
    local function corner(parent, r)
        return new("UICorner", { CornerRadius = UDim.new(0, r) }, parent)
    end
    local function stroke(parent, transparency, role)
        local s = new("UIStroke", { Color = pal()[role or "Stroke"], Thickness = 1, Transparency = transparency or 0.55 }, parent)
        s:SetAttribute("ThemeRole", role or "Stroke")
        return s
    end
    local function setText(label, es, en)
        label:SetAttribute("TextSpanish", es)
        label:SetAttribute("TextEnglish", en)
        label.Text = scriptText(es, en)
    end
    local function text(parent, es, en, size, font, role, props)
        local l = new("TextLabel", {
            BackgroundTransparency = 1,
            Text = scriptText(es, en),
            TextColor3 = pal()[role or "Text"],
            TextSize = size,
            Font = font,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 12,
        }, parent)
        l:SetAttribute("ThemeTextRole", role or "Text")
        l:SetAttribute("IgnoreTextEffect", true)
        l:SetAttribute("TextSpanish", es)
        l:SetAttribute("TextEnglish", en)
        for k, v in pairs(props or {}) do
            l[k] = v
        end
        return l
    end
    local function pressBounce(button)
        local scale = new("UIScale", { Scale = 1 }, button)
        button.MouseButton1Down:Connect(function()
            KeyTweenService:Create(scale, TweenInfo.new(0.08), { Scale = 0.95 }):Play()
        end)
        local function up()
            KeyTweenService:Create(scale, TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
        end
        button.MouseButton1Up:Connect(up)
        button.MouseLeave:Connect(up)
    end
    -- boton con rol de tema (Accent / Secondary / AccentOff)
    local function pill(parent, es, en, role, props)
        local p = pal()
        local b = new("TextButton", {
            BackgroundColor3 = p[role],
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = scriptText(es, en),
            TextColor3 = role == "Accent" and AvatarContrastColor(p.Accent) or p.Text,
            TextSize = 12,
            Font = Enum.Font.GothamBold,
            ZIndex = 13,
        }, parent)
        b:SetAttribute("ThemeRole", role)
        if role ~= "Accent" then
            b:SetAttribute("ThemeTextRole", "Text")
        end
        b:SetAttribute("TextSpanish", es)
        b:SetAttribute("TextEnglish", en)
        b:SetAttribute("IgnoreTextEffect", true)
        corner(b, 9)
        for k, v in pairs(props or {}) do
            b[k] = v
        end
        pressBounce(b)
        return b
    end

    new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }, holder)
    new("UIPadding", { PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 4) }, holder)

    local function card(name, order)
        local c = new("Frame", {
            Name = name,
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = pal().Secondary,
            BackgroundTransparency = 0.78,
            BorderSizePixel = 0,
            LayoutOrder = order,
            ZIndex = 10,
        }, holder)
        c:SetAttribute("ThemeRole", "Secondary")
        corner(c, 12)
        stroke(c, 0.55)
        new("UIPadding", { PaddingTop = UDim.new(0, 10), PaddingBottom = UDim.new(0, 10), PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }, c)
        new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }, c)
        return c
    end
    local function cardTitle(parent, es, en, subEs, subEn)
        local h = new("Frame", { Size = UDim2.new(1, 0, 0, 34), BackgroundTransparency = 1, LayoutOrder = 1, ZIndex = 11 }, parent)
        text(h, es, en, 13, Enum.Font.GothamBlack, "Text", { Size = UDim2.new(1, -110, 0, 16) })
        text(h, subEs, subEn, 10, Enum.Font.GothamMedium, "TextDim", {
            Size = UDim2.new(1, 0, 0, 14),
            Position = UDim2.fromOffset(0, 18),
        })
        return h
    end
    local function statusLine(parent, order)
        local f = new("Frame", { Size = UDim2.new(1, 0, 0, 16), BackgroundTransparency = 1, LayoutOrder = order, ZIndex = 11 }, parent)
        local dot = new("Frame", { Size = UDim2.fromOffset(7, 7), Position = UDim2.new(0, 0, 0.5, -3), BorderSizePixel = 0, BackgroundColor3 = Color3.fromRGB(160, 160, 170), ZIndex = 12 }, f)
        corner(dot, 999)
        local l = text(f, "", "", 10, Enum.Font.GothamBold, "TextDim", { Size = UDim2.new(1, -14, 1, 0), Position = UDim2.fromOffset(13, 0) })
        return function(es, en, color)
            setText(l, es, en)
            dot.BackgroundColor3 = color or Color3.fromRGB(160, 160, 170)
        end
    end
    local GREEN = Color3.fromRGB(110, 235, 140)
    local GRAY = Color3.fromRGB(160, 160, 170)
    local AMBER = Color3.fromRGB(255, 196, 80)

    ------------------------------------------------------------------ BOOMBOX
    local boomCard = card("UnlockBoombox", 1)
    local boomTitle = cardTitle(boomCard, "BOOMBOX", "BOOMBOX", "Aunque no la tengas: elegí cuál llevás en la espalda. Visual, solo en tu pantalla.", "Even if you don't own it: pick the one on your back. Visual, only on your screen.")
    local boomReload = pill(boomTitle, "Actualizar", "Refresh", "AccentOff", {
        AnchorPoint = Vector2.new(1, 0),
        Position = UDim2.new(1, 0, 0, -2),
        Size = UDim2.fromOffset(84, 22),
        TextSize = 10,
    })
    local boomStatus = statusLine(boomCard, 2)
    local boomRow = new("ScrollingFrame", {
        Size = UDim2.new(1, 0, 0, 64),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ScrollingDirection = Enum.ScrollingDirection.X,
        AutomaticCanvasSize = Enum.AutomaticSize.X,
        CanvasSize = UDim2.new(0, 0, 0, 0),
        ScrollBarThickness = 0,
        LayoutOrder = 3,
        ZIndex = 11,
    }, boomCard)
    new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, VerticalAlignment = Enum.VerticalAlignment.Center, Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }, boomRow)
    new("UIPadding", { PaddingLeft = UDim.new(0, 2), PaddingRight = UDim.new(0, 2) }, boomRow)

    local B = { Tiles = {}, Skins = {}, LastActive = nil }

    local function paintBoomTiles()
        local m = ua()
        local current = nil
        pcall(function() current = m.GetBoombox() end)
        local p = pal()
        for id, tile in pairs(B.Tiles) do
            local on = (id == 0 and current == nil) or id == current
            tile.Stroke.Color = on and p.Accent or p.Stroke
            tile.Stroke.Transparency = on and 0 or 0.6
            tile.Stroke.Thickness = on and 2 or 1
            tile.Check.Visible = on and id ~= 0
        end
        local name = nil
        for _, s in ipairs(B.Skins) do
            if s.id == current then
                name = s.name
            end
        end
        if not uaActive() then
            boomStatus("Activá Unlock All para elegir", "Turn on Unlock All to choose", GRAY)
        elseif #B.Skins == 0 then
            boomStatus("Cargando la lista del juego...", "Loading the game list...", AMBER)
        elseif current then
            local n = name or tostring(current)
            boomStatus("Visual: " .. n .. " · se ve al aparecer/reaparecer", "Visual: " .. n .. " · shows on (re)spawn", GREEN)
        else
            boomStatus("Sin boombox visual (se ve la tuya real si tenés)", "No visual boombox (your real one shows if you own it)", GRAY)
        end
    end

    local function boomTile(id, nameEs, nameEn, badge, order)
        local p = pal()
        local t = new("TextButton", {
            Size = UDim2.fromOffset(116, 56),
            BackgroundColor3 = p.Background,
            BackgroundTransparency = 0.25,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            LayoutOrder = order,
            ZIndex = 12,
        }, boomRow)
        t:SetAttribute("ThemeRole", "Background")
        corner(t, 11)
        local st = new("UIStroke", { Color = p.Stroke, Thickness = 1, Transparency = 0.6 }, t)
        text(t, nameEs, nameEn, 11, Enum.Font.GothamBold, "Text", {
            Size = UDim2.new(1, -16, 0, 30),
            Position = UDim2.fromOffset(8, 6),
            TextWrapped = true,
            TextYAlignment = Enum.TextYAlignment.Top,
            ZIndex = 13,
        })
        if badge then
            local bf = new("Frame", {
                Size = UDim2.fromOffset(0, 14),
                AutomaticSize = Enum.AutomaticSize.X,
                Position = UDim2.new(0, 8, 1, -20),
                BackgroundColor3 = p.AccentOff,
                BorderSizePixel = 0,
                ZIndex = 13,
            }, t)
            bf:SetAttribute("ThemeRole", "AccentOff")
            corner(bf, 999)
            new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }, bf)
            text(bf, badge, badge, 9, Enum.Font.GothamBold, "TextDim", {
                Size = UDim2.fromOffset(0, 14),
                AutomaticSize = Enum.AutomaticSize.X,
                TextTruncate = Enum.TextTruncate.None,
                ZIndex = 14,
            })
        end
        local check = new("Frame", {
            AnchorPoint = Vector2.new(1, 1),
            Size = UDim2.fromOffset(10, 10),
            Position = UDim2.new(1, -8, 1, -8),
            BackgroundColor3 = GREEN,
            BorderSizePixel = 0,
            Visible = false,
            ZIndex = 14,
        }, t)
        corner(check, 999)
        B.Tiles[id] = { Button = t, Stroke = st, Check = check }
        pressBounce(t)
        t.Activated:Connect(function()
            local m = ua()
            if not uaActive() then
                boomStatus("Primero activá Unlock All (arriba)", "Turn on Unlock All first (above)", AMBER)
                return
            end
            pcall(function() m.SetBoombox(id ~= 0 and id or nil) end)
            paintBoomTiles()
        end)
    end

    local function rebuildBoombox()
        for _, tile in pairs(B.Tiles) do
            tile.Button:Destroy()
        end
        B.Tiles = {}
        B.Skins = {}
        local m = ua()
        if uaActive() then
            pcall(function() B.Skins = m.GetBoomboxSkins() or {} end)
        end
        boomTile(0, "Ninguna", "None", nil, 0)
        for i, s in ipairs(B.Skins) do
            boomTile(s.id, s.name, s.name, s.ugc and "Relics" or nil, i)
        end
        paintBoomTiles()
    end
    boomReload.Activated:Connect(rebuildBoombox)

    ------------------------------------------------------------------ PERFILES
    local profCard = card("UnlockProfiles", 2)
    cardTitle(profCard, "PERFILES DE LOOK", "LOOK PROFILES", "Guarda emotes, cosméticos, skins, boombox y colores del HUD juntos.", "Saves emotes, cosmetics, skins, boombox and HUD colors together.")
    local profStatus = statusLine(profCard, 2)

    local inputRow = new("Frame", { Size = UDim2.new(1, 0, 0, 34), BackgroundTransparency = 1, LayoutOrder = 3, ZIndex = 11 }, profCard)
    local nameBox = new("TextBox", {
        Size = UDim2.new(1, -98, 1, 0),
        BackgroundColor3 = pal().Background,
        BackgroundTransparency = 0.25,
        BorderSizePixel = 0,
        Text = "",
        PlaceholderText = scriptText("Nombre del perfil", "Profile name"),
        PlaceholderColor3 = pal().TextDim,
