    }, inputRow)
    nameBox:SetAttribute("ThemeRole", "Background")
    nameBox:SetAttribute("ThemeTextRole", "Text")
    nameBox:SetAttribute("PlaceholderSpanish", "Nombre del perfil")
    nameBox:SetAttribute("PlaceholderEnglish", "Profile name")
    corner(nameBox, 9)
    new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10) }, nameBox)
    stroke(nameBox, 0.6)
    local saveBtn = pill(inputRow, "Guardar", "Save", "Accent", {
        AnchorPoint = Vector2.new(1, 0),
        Position = UDim2.new(1, 0, 0, 0),
        Size = UDim2.new(0, 90, 1, 0),
    })

    local listHolder = new("Frame", {
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        LayoutOrder = 4,
        ZIndex = 11,
    }, profCard)
    new("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, listHolder)

    local P = { List = {} }

    local function loadProfiles()
        P.List = {}
        pcall(function()
            if type(isfile) == "function" and type(readfile) == "function" and isfile(PROFILE_FILE) then
                local data = HttpService:JSONDecode(readfile(PROFILE_FILE))
                if type(data) == "table" and type(data.profiles) == "table" then
                    for _, prof in ipairs(data.profiles) do
                        if type(prof) == "table" and type(prof.name) == "string" then
                            P.List[#P.List + 1] = prof
                        end
                    end
                end
            end
        end)
    end
    local function saveProfiles()
        local ok = pcall(function()
            writefile(PROFILE_FILE, HttpService:JSONEncode({ version = 1, profiles = P.List }))
        end)
        return ok
    end

    local function count(t)
        local n = 0
        for _ in pairs(type(t) == "table" and t or {}) do
            n += 1
        end
        return n
    end
    local function summary(prof)
        local look = prof.look or {}
        local cos = count(look.cosmetics)
        local hasBoom = type(look.cosmetics) == "table" and look.cosmetics.BoomboxSlot ~= nil
        if hasBoom then
            cos -= 1
        end
        local partsEs, partsEn = {}, {}
        local function add(es, en)
            partsEs[#partsEs + 1] = es
            partsEn[#partsEn + 1] = en
        end
        local e, sk = count(look.emotes), count(look.skins)
        if e > 0 then add(e .. " emotes", e .. " emotes") end
        if cos > 0 then add(cos .. " cosm.", cos .. " cosm.") end
        if sk > 0 then add(sk .. " skins", sk .. " skins") end
        if hasBoom then add("boombox", "boombox") end
        if count(prof.hud) > 0 or (type(prof.anim) == "table" and prof.anim.mode ~= "off") then add("HUD", "HUD") end
        if #partsEs == 0 then
            return "Vacío", "Empty"
        end
        return table.concat(partsEs, " · "), table.concat(partsEn, " · ")
    end

    local rebuildList -- forward

    local function applyProfile(prof)
        local hudApplied = false
        pcall(function()
            if HudColorsAPI then
                if type(prof.hud) == "table" then
                    HudColorsAPI.Import(prof.hud)
                    hudApplied = true
                end
                if type(prof.anim) == "table" then
                    HudColorsAPI.SetAnim(prof.anim.mode, prof.anim.speed, prof.anim.style)
                end
            end
        end)
        if type(prof.look) ~= "table" then
            profStatus("Perfil \"" .. prof.name .. "\" aplicado", "Profile \"" .. prof.name .. "\" applied", GREEN)
            return
        end
        if not uaActive() then
            profStatus("Colores aplicados. Activá Unlock All para cargar el look", "Colors applied. Turn on Unlock All to load the look", AMBER)
            return
        end
        profStatus("Aplicando \"" .. prof.name .. "\"...", "Applying \"" .. prof.name .. "\"...", AMBER)
        task.spawn(function()
            local m = ua()
            local ok, applied, skipped = pcall(function() return m.ApplySnapshot(prof.look) end)
            paintBoomTiles()
            if ok and applied then
                if type(skipped) == "number" and skipped > 0 then
                    profStatus("\"" .. prof.name .. "\" listo · " .. skipped .. " items ya no existen", "\"" .. prof.name .. "\" ready · " .. skipped .. " items no longer exist", AMBER)
                else
                    profStatus("\"" .. prof.name .. "\" listo" .. (hudApplied and " (look + HUD)" or ""), "\"" .. prof.name .. "\" ready" .. (hudApplied and " (look + HUD)" or ""), GREEN)
                end
            else
                profStatus("No se pudo aplicar el look", "Couldn't apply the look", AMBER)
            end
        end)
    end

    local function profileRow(prof, order)
        local p = pal()
        local row = new("Frame", {
            Size = UDim2.new(1, 0, 0, 50),
            BackgroundColor3 = p.Background,
            BackgroundTransparency = 0.3,
            BorderSizePixel = 0,
            LayoutOrder = order,
            ZIndex = 12,
        }, listHolder)
        row:SetAttribute("ThemeRole", "Background")
        corner(row, 10)
        stroke(row, 0.65)
        local initial = new("TextLabel", {
            Size = UDim2.fromOffset(32, 32),
            Position = UDim2.fromOffset(9, 9),
            BackgroundColor3 = p.Accent,
            BorderSizePixel = 0,
            Text = string.upper(string.sub(prof.name, 1, 1)),
            TextColor3 = AvatarContrastColor(p.Accent),
            TextSize = 15,
            Font = Enum.Font.GothamBlack,
            ZIndex = 13,
        }, row)
        initial:SetAttribute("IgnoreTextEffect", true)
        corner(initial, 999)
        text(row, prof.name, prof.name, 13, Enum.Font.GothamBold, "Text", {
            Size = UDim2.new(1, -190, 0, 16),
            Position = UDim2.fromOffset(50, 8),
            ZIndex = 13,
        })
        local es, en = summary(prof)
        text(row, es, en, 10, Enum.Font.GothamMedium, "TextDim", {
            Size = UDim2.new(1, -190, 0, 14),
            Position = UDim2.fromOffset(50, 27),
            ZIndex = 13,
        })
        local useBtn = pill(row, "Usar", "Use", "Accent", {
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -82, 0.5, 0),
            Size = UDim2.fromOffset(62, 30),
            TextSize = 11,
        })
        local delBtn = pill(row, "Borrar", "Delete", "AccentOff", {
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -9, 0.5, 0),
            Size = UDim2.fromOffset(68, 30),
            TextSize = 11,
        })
        useBtn.Activated:Connect(function()
            applyProfile(prof)
        end)
        -- borrar en dos toques (el primero pide confirmacion por 3 s)
        local armed = false
        delBtn.Activated:Connect(function()
            if not armed then
                armed = true
                delBtn.Text = scriptText("¿Seguro?", "Sure?")
                delBtn.BackgroundColor3 = Color3.fromRGB(200, 60, 70)
                task.delay(3, function()
                    if armed and delBtn.Parent then
                        armed = false
                        delBtn.Text = scriptText("Borrar", "Delete")
                        delBtn.BackgroundColor3 = pal().AccentOff
                    end
                end)
                return
            end
            armed = false
            for i, other in ipairs(P.List) do
                if other == prof then
                    table.remove(P.List, i)
                    break
                end
            end
            saveProfiles()
            profStatus("Perfil \"" .. prof.name .. "\" borrado", "Profile \"" .. prof.name .. "\" deleted", GRAY)
            rebuildList()
        end)
    end

    rebuildList = function()
        for _, child in ipairs(listHolder:GetChildren()) do
            if child:IsA("Frame") then
                child:Destroy()
            end
        end
        if #P.List == 0 then
            local empty = new("Frame", { Size = UDim2.new(1, 0, 0, 34), BackgroundTransparency = 1, LayoutOrder = 0, ZIndex = 12 }, listHolder)
            text(empty, "Todavía no guardaste perfiles. Armá tu look y tocá Guardar.", "No profiles yet. Build your look and tap Save.", 10, Enum.Font.GothamMedium, "TextDim", {
                Size = UDim2.new(1, 0, 1, 0),
                TextXAlignment = Enum.TextXAlignment.Center,
                TextWrapped = true,
                TextTruncate = Enum.TextTruncate.None,
            })
            return
        end
        for i, prof in ipairs(P.List) do
            profileRow(prof, i)
        end
    end

    saveBtn.Activated:Connect(function()
        local name = tostring(nameBox.Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if name == "" then
            name = "Look " .. (#P.List + 1)
        end
        name = string.sub(name, 1, 24)
        local m = ua()
        local look = nil
        if uaActive() then
            pcall(function() look = m.Snapshot() end)
        end
        local prof = {
            name = name,
            time = os.time(),
            look = look,
            hud = HudColorsAPI and HudColorsAPI.Export() or nil,
            anim = HudColorsAPI and HudColorsAPI.GetAnim() or nil,
        }
        local replaced = false
        for i, other in ipairs(P.List) do
            if other.name == name then
                P.List[i] = prof
                replaced = true
                break
            end
        end
        if not replaced then
            if #P.List >= MAX_PROFILES then
                profStatus("Máximo " .. MAX_PROFILES .. " perfiles: borrá uno primero", "Max " .. MAX_PROFILES .. " profiles: delete one first", AMBER)
                return
            end
            table.insert(P.List, 1, prof)
        end
        local okSave = type(writefile) == "function" and saveProfiles()
        nameBox.Text = ""
        rebuildList()
        if not okSave then
            profStatus("Guardado solo en esta sesión (tu ejecutor no tiene writefile)", "Saved for this session only (no writefile)", AMBER)
        elseif not look then
            profStatus("\"" .. name .. "\" guardado (solo colores: Unlock All estaba apagado)", "\"" .. name .. "\" saved (colors only: Unlock All was off)", AMBER)
        else
            profStatus("\"" .. name .. "\" " .. (replaced and "actualizado" or "guardado"), "\"" .. name .. "\" " .. (replaced and "updated" or "saved"), GREEN)
        end
    end)

    ------------------------------------------------------------------ LOOK SORPRESA
    local surprise = new("TextButton", {
        Size = UDim2.new(1, 0, 0, 46),
        BackgroundColor3 = pal().Background,
        BackgroundTransparency = 0.15,
        BorderSizePixel = 0,
        AutoButtonColor = false,
        Text = "",
        LayoutOrder = 5,
        ZIndex = 12,
    }, profCard)
    surprise:SetAttribute("ThemeRole", "Background")
    corner(surprise, 11)
    local surpriseStroke = new("UIStroke", { Color = WHITE, Thickness = 2, Transparency = 0 }, surprise)
    local surpriseGrad = new("UIGradient", {
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 90, 90)),
            ColorSequenceKeypoint.new(0.2, Color3.fromRGB(255, 210, 80)),
            ColorSequenceKeypoint.new(0.4, Color3.fromRGB(110, 255, 120)),
            ColorSequenceKeypoint.new(0.6, Color3.fromRGB(80, 200, 255)),
            ColorSequenceKeypoint.new(0.8, Color3.fromRGB(170, 110, 255)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 90, 90)),
        }),
    }, surpriseStroke)
    KeyTweenService:Create(surpriseGrad, TweenInfo.new(3, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), { Rotation = 360 }):Play()
    text(surprise, "LOOK SORPRESA", "SURPRISE LOOK", 13, Enum.Font.GothamBlack, "Text", {
        Size = UDim2.new(1, -20, 0, 16),
        Position = UDim2.fromOffset(12, 7),
        ZIndex = 13,
    })
    text(surprise, "Emotes, cosméticos, skins, boombox y tema del HUD al azar", "Random emotes, cosmetics, skins, boombox and HUD theme", 10, Enum.Font.GothamMedium, "TextDim", {
        Size = UDim2.new(1, -20, 0, 14),
        Position = UDim2.fromOffset(12, 25),
        ZIndex = 13,
    })
    pressBounce(surprise)
    local rolling = false
    surprise.Activated:Connect(function()
        if rolling then
            return
        end
        local themeEs, themeEn = nil, nil
        pcall(function()
            if HudColorsAPI then
                themeEs, themeEn = HudColorsAPI.RandomTheme()
            end
        end)
        if not uaActive() then
            if themeEs then
                profStatus("Tema " .. themeEs .. " · activá Unlock All para el look completo", "Theme " .. themeEn .. " · turn on Unlock All for the full look", AMBER)
            else
                profStatus("Activá Unlock All primero", "Turn on Unlock All first", AMBER)
            end
            return
        end
        rolling = true
        profStatus("Tirando los dados...", "Rolling the dice...", AMBER)
        task.spawn(function()
            local m = ua()
            local ok, applied = pcall(function()
                local snap = m.RandomLook()
                return snap and m.ApplySnapshot(snap)
            end)
            rolling = false
            paintBoomTiles()
            local suffixEs = themeEs and (" · tema " .. themeEs) or ""
            local suffixEn = themeEn and (" · " .. themeEn .. " theme") or ""
            if ok and applied then
                profStatus("Look sorpresa listo" .. suffixEs .. " · guardalo si te gusta", "Surprise look ready" .. suffixEn .. " · save it if you like it", GREEN)
            else
                profStatus("No se pudo armar el look", "Couldn't build the look", AMBER)
            end
        end)
    end)

    ------------------------------------------------------------------ arranque
    loadProfiles()
    rebuildList()
    profStatus("Tus perfiles se guardan en " .. PROFILE_FILE, "Your profiles are saved in " .. PROFILE_FILE, GRAY)
    rebuildBoombox()

    -- La lista de boombox se arma cuando Unlock All termina de activarse (carga las listas en segundo plano):
    -- se revisa cada 1.5 s SOLO mientras la pestaña Extra esta abierta.
    local page = holder:FindFirstAncestorWhichIsA("ScrollingFrame") or holder.Parent
    task.spawn(function()
        while holder.Parent do
            task.wait(1.5)
            if page and page.Visible then
                local on = uaActive()
                local m = ua()
                local n = 0
                if on then
                    pcall(function() n = #(m.GetBoomboxSkins()) end)
                end
                if on ~= B.LastActive or (on and n ~= #B.Skins) then
                    B.LastActive = on
                    rebuildBoombox()
                else
                    paintBoomTiles()
                end
            end
        end
    end)
end
do
    local okExtras, errExtras = pcall(setupUnlockExtras, UnlockExtrasHolder)
    if not okExtras then
        warn("[Unlock All] Panel de boombox/perfiles fallo: " .. tostring(errExtras))
    end
end


function setupAllTab()
local TabAll = UI:CreateTab("All", "All", "rbxassetid://125111822154519")
local AllStatus
local AllCount

-- ===== Carrusel de All: Catálogo <-> Cosmetics Changer (misma lógica que el carrusel de Emote) =====
local AllCarousel = nil
local AllCarouselPages = {
    Catalog = nil,
    Cosmetics = nil,
    Skins = nil,
}
local AllActivePage = nil
local AllCarouselMode = nil
local AllCarouselAnimating = false
local AllCarouselHeightUpdating = false
local AllCarouselSwipe = {
    input = nil,
    start = nil,
    threshold = 36,
}

local function allTrackInstance(inst)
    if type(inst) == "table" then
        inst = inst.Holder
    end
    return inst
end

local function allEnsureCarousel()
    if AllCarousel and AllCarousel.Parent then
        return AllCarousel
    end

    AllCarousel = YYKitMake("Frame")
    AllCarousel.Name = "AllCarousel"
    AllCarousel.Parent = TabAll.Page
    AllCarousel.Size = UDim2.new(1, 0, 0, 430)
    AllCarousel.BackgroundTransparency = 1
    AllCarousel.BorderSizePixel = 0
    AllCarousel.ClipsDescendants = true
    AllCarousel.LayoutOrder = -900
    AllCarousel.ZIndex = 8

    return AllCarousel
end

local function allUpdateCarouselHeight(page)
    if AllCarouselHeightUpdating then return end
    if not page or not page.Parent then return end

    AllCarouselHeightUpdating = true
    task.defer(function()
        if page and page.Parent then
            local layout = page:FindFirstChildOfClass("UIListLayout")
            if layout then
                local contentHeight = layout.AbsoluteContentSize.Y + 8
                local h = math.max(430, contentHeight)
                if page.Size.Y.Offset ~= h then
                    page.Size = UDim2.new(1, 0, 0, h)
                end
                if AllActivePage == page and AllCarousel and AllCarousel.Parent
                    and AllCarousel.Size.Y.Offset ~= h then
                    AllCarousel.Size = UDim2.new(1, 0, 0, h)
                end
            end
        end
        AllCarouselHeightUpdating = false
    end)
end

local function allMakeCarouselPage(name)
    local viewport = allEnsureCarousel()
    local page = YYKitMake("Frame")
    page.Name = name or "AllCarouselContent"
    page.Size = UDim2.new(1, 0, 0, 430)
    page.Position = UDim2.new(1, 0, 0, 0)
    page.BackgroundTransparency = 1
    page.BorderSizePixel = 0
    page.ZIndex = 9
    page.ClipsDescendants = false
    page.Parent = viewport

    local pageLayout = YYKitMake("UIListLayout")
    pageLayout.Padding = UDim.new(0, 6)
    pageLayout.SortOrder = Enum.SortOrder.LayoutOrder
    pageLayout.VerticalAlignment = Enum.VerticalAlignment.Top
    pageLayout.Parent = page

    pageLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        allUpdateCarouselHeight(page)
    end)

    task.defer(function()
        allUpdateCarouselHeight(page)
    end)

    return page
end

local function allSetCarouselMode(mode, direction)
    if AllCarouselAnimating then return end
    local newPage = AllCarouselPages[mode]
    if not newPage or not newPage.Parent then return end

    local oldPage = AllActivePage
    if oldPage == newPage and AllCarouselMode == mode then
        return
    end

    AllCarouselMode = mode

    allUpdateCarouselHeight(newPage)
    if not oldPage or not oldPage.Parent then
        newPage.Position = UDim2.new(0, 0, 0, 0)
        AllActivePage = newPage
        return
    end

    local incomingStart = direction and direction > 0 and 1 or -1
    local outgoingEnd = direction and direction > 0 and -1 or 1
    newPage.Position = UDim2.new(incomingStart, 0, 0, 0)
    AllCarouselAnimating = true

    KeyTweenService:Create(oldPage, TweenInfo.new(0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
        Position = UDim2.new(outgoingEnd, 0, 0, 0)
    }):Play()

    local tween = KeyTweenService:Create(newPage, TweenInfo.new(0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
        Position = UDim2.new(0, 0, 0, 0)
    })
    tween:Play()
    AllActivePage = newPage
    tween.Completed:Connect(function()
        AllCarouselAnimating = false
    end)
end

