local AllEquipped = {} -- [module] = { candidate = c, clone = model }
local AllEquippedCount = 0

function allSetCount(value)
    if AllCount and AllCount.Parent then
        AllCount.Text = tostring(value) .. scriptText(" items · ", " items · ")
            .. tostring(AllEquippedCount) .. scriptText(" equipados", " equipped")
    end
end

function allLower(value)
    return string.lower(tostring(value or ""))
end

local AllExcludedNames = {
    defectrebel = true,
    davethebrickbattler = true,
    darkestknight = true,
    cursedkrampus = true,
    combustor = true,
    clark = true,
    catbobosuit = true,
    capeofposeidon = true,
    bunnyjard = true,
    bobo = true,
    anniversaryfireworks = true,
    anniversarycatjard = true,
    duckywaterfall = true,
    frostysnowman = true,
    gardenerjard = true,
    ghost = true,
    ghostlyanchor = true,
    frankenstein = true,
    interloper = true,
    jardclown = true,
    jard = true,
    jardsunderland = true,
    jollysanta = true,
    krampus = true,
    leviathananchor = true,
    lupen = true,
    markv = true,
    masterchief = true,
    mechanicalbugler = true,
    overseer = true,
    pootis = true,
    poseidon = true,
    retrosunset = true,
    seal = true,
    sharkbobo = true,
    spy = true,
    summerjard = true,
    thecorrupted = true,
    thehidden = true,
    trooper = true,
    vanguard = true,
    weepingbobo = true,
    werewolf = true,
    woodennutcracker = true,
    workerelf = true,
    zombie = true,
    zombieskeleton = true,
}

function allIsExcludedName(name)
    return AllExcludedNames[allLower(name)] == true
end

function allPathOf(instance)
    local parts = {}
    local current = instance
    while current and current ~= game do
        parts[#parts + 1] = current.Name
        current = current.Parent
    end
    local result = {}
    for index = #parts, 1, -1 do
        result[#result + 1] = parts[index]
    end
    return table.concat(result, ".")
end

function allIsCosmeticsPath(instance)
    local path = allLower(allPathOf(instance))
    return string.find(path, ".cosmetics", 1, true) ~= nil
        or allLower(instance.Name) == "cosmetics"
end

function allMatchesSearch(candidate)
    if allIsExcludedName(candidate.name) then return false end
    if AllUI.Filter == "equipped" then
        if not AllEquipped[candidate.module] then return false end
    elseif AllUI.Filter ~= "all" and candidate.kind ~= AllUI.Filter then
        return false
    end
    local query = allLower(AllSearch.Text)
    if query == "" then return true end
    return string.find(allLower(candidate.name), query, 1, true) ~= nil
        or string.find(allLower(candidate.path), query, 1, true) ~= nil
end

function allClearRows()
    for _, row in ipairs(AllRows) do
        pcall(function()
            if row and row.Destroy then
                row:Destroy()
            elseif row and row.Holder and row.Holder.Destroy then
                row.Holder:Destroy()
            end
        end)
    end
    AllRows = {}
end

local bodyNames = {
    ["head"] = true, ["torso"] = true, ["left arm"] = true, ["right arm"] = true,
    ["left leg"] = true, ["right leg"] = true, ["uppertorso"] = true,
    ["lowertorso"] = true, ["lefthand"] = true, ["righthand"] = true,
    ["leftupperarm"] = true, ["rightupperarm"] = true,
    ["leftlowerarm"] = true, ["rightlowerarm"] = true,
    ["leftupperleg"] = true, ["rightupperleg"] = true,
    ["leftlowerleg"] = true, ["rightlowerleg"] = true,
    ["leftfoot"] = true, ["rightfoot"] = true,
    ["humanoidrootpart"] = true, ["torsorot"] = true, ["armrot"] = true,
}

function allIsReferenceBodyPart(instance)
    if not instance:IsA("BasePart") then return false end
    local name = allLower(instance.Name)
    return bodyNames[name]
        or string.find(name, "body", 1, true) ~= nil
        or string.find(name, "limb", 1, true) ~= nil
end

function allPrepareVisualModel(model)
    local hidden = 0
    local parts = 0
    local vfx = 0
    local sounds = 0
    for _, instance in ipairs(model:GetDescendants()) do
        if instance:IsA("BasePart") then
            parts = parts + 1
            instance.CanCollide = false
            instance.CanTouch = false
            instance.CanQuery = false
            instance.Massless = true
            if allIsReferenceBodyPart(instance) then
                instance.Transparency = 1
                hidden = hidden + 1
            end
        elseif instance:IsA("ParticleEmitter")
            or instance:IsA("Beam")
            or instance:IsA("Trail")
            or instance:IsA("Highlight")
            or instance:IsA("PointLight")
            or instance:IsA("SpotLight")
            or instance:IsA("SurfaceLight") then
            vfx = vfx + 1
        elseif instance:IsA("Sound") then
            sounds = sounds + 1
        end
    end
    return hidden, parts, vfx, sounds
end

function allRepairInternalJoints(model)
    local repaired = 0
    for _, joint in ipairs(model:GetDescendants()) do
        if joint:IsA("Motor6D") or joint:IsA("Weld") then
            local p0 = joint.Part0
            local p1 = joint.Part1
            if p0 and not p0:IsDescendantOf(model) then
                local replacement = model:FindFirstChild(p0.Name, true)
                if replacement and replacement:IsA("BasePart") then
                    pcall(function() joint.Part0 = replacement end)
                    repaired = repaired + 1
                end
            end
            if p1 and not p1:IsDescendantOf(model) then
                local replacement = model:FindFirstChild(p1.Name, true)
                if replacement and replacement:IsA("BasePart") then
                    pcall(function() joint.Part1 = replacement end)
                    repaired = repaired + 1
                end
            end
        end
    end
    return repaired
end

function allGetTargetRig()
    local rigs = Workspace:FindFirstChild("Rigs")
    local rig = rigs and rigs:FindFirstChild(LocalPlayer.Name)
    if not rig then rig = Workspace:FindFirstChild(LocalPlayer.Name) end
    if not rig then return nil, nil end
    local root = rig:FindFirstChild("HumanoidRootPart")
        or rig:FindFirstChild("Torso")
        or rig:FindFirstChild("UpperTorso")
        or rig.PrimaryPart
    return rig, root
end

function allGetContainer()
    local container = Workspace:FindFirstChild("__YY_AllVisualCandidates")
    if not container then
        container = Instance.new("Folder")
        container.Name = "__YY_AllVisualCandidates"
        container.Parent = Workspace
    end
    return container
end

-- Arma el visual de un candidato y lo suelda al rig. Devuelve el clon o nil + mensaje.
function allBuildVisual(candidate)
    local sourceModule = candidate.module
    if not sourceModule or not sourceModule.Parent then
        return nil, candidate.name .. " ya no está disponible"
    end
    local rig, targetRoot = allGetTargetRig()
    if not rig or not targetRoot then
        return nil, "No se encontró el rig visual o su root"
    end

    local characterModel = sourceModule:FindFirstChild("CharacterClassic")
        or sourceModule:FindFirstChild("Character")
    local sourceAura = sourceModule:FindFirstChild("Aura")
    local useModel = candidate.kind == "model" and characterModel and characterModel:IsA("Model")
    local useAura = candidate.kind == "aura"
        and sourceAura
        and (sourceAura:IsA("BasePart") or sourceAura:IsA("Model"))
    if not useModel and not useAura then
        return nil, candidate.name .. " ya no tiene un formato visual compatible"
    end

    local ok, clone = pcall(function()
        if useModel then
            return characterModel:Clone()
        end
        if sourceAura:IsA("BasePart") then
            local wrapper = Instance.new("Model")
            local auraClone = sourceAura:Clone()
            auraClone.Parent = wrapper
            wrapper.PrimaryPart = auraClone
            return wrapper
        end
        return sourceAura:Clone()
    end)
    if not ok or not clone then
        return nil, "No se pudo clonar " .. candidate.name
    end

    clone.Name = candidate.name .. (useModel and "_VisualOnly" or "_AuraVisualOnly")
    clone.Parent = allGetContainer()
    allPrepareVisualModel(clone)
    if useAura then
        local carrier = clone:FindFirstChild("Aura", true)
        if carrier and carrier:IsA("BasePart") then
            carrier.Transparency = 1
        end
    end
    allRepairInternalJoints(clone)
    local cloneRoot = clone:FindFirstChild("HumanoidRootPart", true)
        or clone:FindFirstChild("Torso", true)
        or clone.PrimaryPart
    if not cloneRoot or not cloneRoot:IsA("BasePart") then
        pcall(function() clone:Destroy() end)
        return nil, candidate.name .. " no tiene root part"
    end

    clone.PrimaryPart = cloneRoot
    pcall(function() clone:PivotTo(targetRoot.CFrame) end)
    local weld = Instance.new("WeldConstraint")
    weld.Name = "__YY_AllFollowTarget"
    weld.Part0 = cloneRoot
    weld.Part1 = targetRoot
    weld.Parent = cloneRoot
    return clone
end

function allRefreshCards()
    for _, row in ipairs(AllRows) do
        if type(row) == "table" and row.Refresh then
            row.Refresh()
        end
    end
    allSetCount(#AllCandidates)
end

function allRemoveCurrent()
    local container = Workspace:FindFirstChild("__YY_AllVisualCandidates")
    if container then pcall(function() container:Destroy() end) end
    AllEquipped = {}
    AllEquippedCount = 0
    AllCurrentRoot = nil
    allSetStatus("Se quitaron todos los cosméticos y auras")
    if AllUI.Filter == "equipped" then
        AllUI.Dirty = true
        allRebuildRows()
    else
        allRefreshCards()
    end
end

function allUnequip(candidate)
    local entry = AllEquipped[candidate.module]
    if not entry then return end
    if entry.clone then
        pcall(function() entry.clone:Destroy() end)
    end
    AllEquipped[candidate.module] = nil
    AllEquippedCount = math.max(0, AllEquippedCount - 1)
end

-- Tocar una tarjeta: si estaba equipado se quita, si no se agrega (se pueden tener varios a la vez)
function allTestCandidate(candidate)
    if AllEquipped[candidate.module] then
        allUnequip(candidate)
        allSetStatus(candidate.name .. " quitado • " .. tostring(AllEquippedCount) .. " equipados")
    else
        local clone, err = allBuildVisual(candidate)
        if not clone then
            allSetStatus(err)
            return
        end
        AllEquipped[candidate.module] = { candidate = candidate, clone = clone }
        AllEquippedCount = AllEquippedCount + 1
        AllCurrentRoot = allGetContainer()
        allSetStatus(candidate.name .. " equipado • " .. tostring(AllEquippedCount) .. " equipados")
    end
    if AllUI.Filter == "equipped" then
        AllUI.Dirty = true
        allRebuildRows()
    else
        allRefreshCards()
    end
end

-- Si el rig visual se vuelve a crear (respawn), se re-equipa todo lo que estaba puesto
function allReequipAll()
    for module, entry in pairs(AllEquipped) do
        if entry.clone then
            pcall(function() entry.clone:Destroy() end)
        end
        local clone = allBuildVisual(entry.candidate)
        if clone then
            entry.clone = clone
        else
            AllEquipped[module] = nil
            AllEquippedCount = math.max(0, AllEquippedCount - 1)
        end
    end
    allRefreshCards()
end

function allCreateCard(candidate, order)
    local palette = GetAvatarPalette()
    local kindColor = AllUI.KindColor[candidate.kind] or AllUI.KindColor.model

    local card = YYKitMake("TextButton")
    card.Name = "AllCard_" .. tostring(order)
    card.BackgroundColor3 = palette.Secondary
    card.BackgroundTransparency = 0.6
    card.BorderSizePixel = 0
    card.AutoButtonColor = false
    card.Text = ""
    card.LayoutOrder = order
    card.ClipsDescendants = true
    card.ZIndex = 10
    card.Parent = AllGrid
    card:SetAttribute("ThemeRole", "Secondary")
    AvatarCorner(card, 12)

    local stroke = YYKitMake("UIStroke")
    stroke.Thickness = 1
    stroke.Parent = card

    -- franja superior con degradado del color del tipo
    local band = YYKitMake("Frame")
    band.Size = UDim2.new(1, 0, 0, 46)
    band.BackgroundColor3 = kindColor
    band.BackgroundTransparency = 0.55
    band.BorderSizePixel = 0
    band.ZIndex = 10
    band.Parent = card
    local bandGradient = YYKitMake("UIGradient")
    bandGradient.Rotation = 90
    bandGradient.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 0),
        NumberSequenceKeypoint.new(1, 1),
    })
    bandGradient.Parent = band

    local glyph = YYKitMake("TextLabel")
    glyph.Size = UDim2.fromOffset(36, 36)
    glyph.Position = UDim2.fromOffset(10, 10)
    glyph.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    glyph.BackgroundTransparency = 0.45
    glyph.BorderSizePixel = 0
    glyph.Text = candidate.kind == "aura" and "✦" or "◆"
    glyph.TextColor3 = kindColor
    glyph.Font = Enum.Font.GothamBlack
    glyph.TextSize = 18
    glyph.ZIndex = 12
    glyph.Parent = card
    glyph:SetAttribute("IgnoreTextEffect", true)
    AvatarCorner(glyph, 18)
    local glyphStroke = YYKitMake("UIStroke")
    glyphStroke.Color = kindColor
    glyphStroke.Thickness = 1.5
    glyphStroke.Transparency = 0.3
    glyphStroke.Parent = glyph

    local badge = YYKitMake("TextLabel")
    badge.AnchorPoint = Vector2.new(1, 0)
    badge.Size = UDim2.fromOffset(0, 18)
    badge.AutomaticSize = Enum.AutomaticSize.X
    badge.Position = UDim2.new(1, -8, 0, 10)
    badge.BackgroundColor3 = kindColor
    badge.BackgroundTransparency = 0.25
    badge.BorderSizePixel = 0
    badge.Text = candidate.kind == "aura" and "AURA" or scriptText("COSMÉTICO", "COSMETIC")
    badge.TextColor3 = Color3.fromRGB(255, 255, 255)
    badge.Font = Enum.Font.GothamBlack
    badge.TextSize = 8
    badge.ZIndex = 12
    badge.Parent = card
    badge:SetAttribute("IgnoreTextEffect", true)
    AvatarCorner(badge, 9)
    local badgePadding = YYKitMake("UIPadding")
    badgePadding.PaddingLeft = UDim.new(0, 7)
    badgePadding.PaddingRight = UDim.new(0, 7)
    badgePadding.Parent = badge

    local title = YYKitMake("TextLabel")
    title.Size = UDim2.new(1, -20, 0, 30)
    title.Position = UDim2.fromOffset(10, 52)
    title.BackgroundTransparency = 1
    title.Text = tostring(candidate.name)
    title.TextColor3 = palette.Text
    title.Font = Enum.Font.GothamBold
    title.TextSize = 12
    title.TextWrapped = true
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.TextYAlignment = Enum.TextYAlignment.Top
    title.TextTruncate = Enum.TextTruncate.AtEnd
    title.ZIndex = 12
    title.Parent = card
    title:SetAttribute("ThemeTextRole", "Text")
    title:SetAttribute("IgnoreTextEffect", true)

    -- pie: estado (Tocá para equipar / ✓ Equipado)
    local state = YYKitMake("TextLabel")
    state.Size = UDim2.new(1, -20, 0, 20)
    state.Position = UDim2.new(0, 10, 1, -26)
    state.BackgroundColor3 = kindColor
    state.BackgroundTransparency = 1
    state.BorderSizePixel = 0
    state.Font = Enum.Font.GothamBold
    state.TextSize = 10
    state.ZIndex = 12
    state.Parent = card
    state:SetAttribute("IgnoreTextEffect", true)
    AvatarCorner(state, 10)

    local scale = YYKitMake("UIScale")
    scale.Scale = 1
    scale.Parent = card

    local function refresh()
        if not card.Parent then return end
        local equipped = AllEquipped[candidate.module] ~= nil
        local pal = GetAvatarPalette()
        stroke.Color = equipped and kindColor or pal.Stroke
        stroke.Thickness = equipped and 2 or 1
        stroke.Transparency = equipped and 0 or 0.55
        state.BackgroundTransparency = equipped and 0.15 or 1
        state.TextColor3 = equipped and Color3.fromRGB(255, 255, 255) or pal.TextDim
        state.Text = equipped and scriptText("✓ EQUIPADO", "✓ EQUIPPED") or scriptText("Tocá para equipar", "Tap to equip")
        band.BackgroundTransparency = equipped and 0.25 or 0.55
    end
    refresh()

    card.MouseButton1Down:Connect(function()
        KeyTweenService:Create(scale, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Scale = 0.96 }):Play()
    end)
    card.MouseButton1Up:Connect(function()
        KeyTweenService:Create(scale, TweenInfo.new(0.16, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
    end)
    card.MouseLeave:Connect(function()
        KeyTweenService:Create(scale, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Scale = 1 }):Play()
    end)
    card.MouseButton1Click:Connect(function()
        allTestCandidate(candidate)
    end)

    return { Holder = card, Refresh = refresh }
end

function allRebuildRows()
    if not AllTabVisible then
        allSetStatus(tostring(#AllCandidates) .. " candidatos descubiertos • abrí la pestaña para verlos")
        return
    end
    -- Abrir/cerrar la pestaña ya no destruye y recrea las tarjetas: solo se rearma si algo cambio
    if not AllUI.Dirty and #AllRows > 0 then
        allRefreshCards()
        return
    end
    AllUI.Dirty = false
    allClearRows()
    local matched = 0
    local shown = 0
    for _, candidate in ipairs(AllCandidates) do
        if allMatchesSearch(candidate) then
            matched = matched + 1
            if shown < ALL_MAX_VISIBLE then
                shown = shown + 1
                AllRows[#AllRows + 1] = allCreateCard(candidate, shown)
            end
        end
    end
    allSetCount(#AllCandidates)
    if matched > shown then
        allSetStatus(tostring(shown) .. "/" .. tostring(matched) .. " tarjetas visibles (máx " .. tostring(ALL_MAX_VISIBLE) .. ") • buscá para encontrar rápido")
    elseif matched == 0 and AllUI.Filter == "equipped" then
        allSetStatus("No tenés nada equipado • tocá una tarjeta para equiparla")
    else
        allSetStatus(tostring(shown) .. " tarjetas visibles • " .. tostring(#AllCandidates) .. " candidatos descubiertos")
    end
end

function allDiscoverCandidates()
    if AllDiscoveryRunning then return end
    AllDiscoveryRunning = true
    AllDiscoveryToken = AllDiscoveryToken + 1
    local token = AllDiscoveryToken
    allClearRows()
    AllUI.Dirty = true
    AllCandidates = {}
    allSetCount(0)
    allSetStatus("Descubriendo módulos bajo Cosmetics...")

    task.spawn(function()
        local items = ReplicatedStorage:FindFirstChild("Items")
        local roots = {}
        if items then
            local baseItems = items:FindFirstChild("BaseItems")
            local baseCosmetics = baseItems and baseItems:FindFirstChild("Cosmetics")
            if baseCosmetics then roots[#roots + 1] = baseCosmetics end
            local itemPacks = items:FindFirstChild("ItemPacks")
            if itemPacks then roots[#roots + 1] = itemPacks end
        end

        local queue = {}
        for _, root in ipairs(roots) do queue[#queue + 1] = root end
        local queueIndex = 1
        local visited = {}
        local seenModules = {}
        local scanned = 0
        local limitReached = false

        while queueIndex <= #queue and scanned < AllMaxDiscoveryNodes and token == AllDiscoveryToken do
            local batch = 0
            while batch < AllDiscoveryBatch
                and queueIndex <= #queue
                and scanned < AllMaxDiscoveryNodes
                and token == AllDiscoveryToken do
                local node = queue[queueIndex]
                queueIndex = queueIndex + 1
                batch = batch + 1
                scanned = scanned + 1
                if node and not visited[node] then
                    visited[node] = true
                    if node:IsA("ModuleScript") and allIsCosmeticsPath(node)
                        and not allIsExcludedName(node.Name)
                        and not seenModules[node] then
                        local characterModel = node:FindFirstChild("CharacterClassic")
                            or node:FindFirstChild("Character")
                        local auraObject = node:FindFirstChild("Aura")
                        local candidateKind
                        if characterModel and characterModel:IsA("Model") then
                            candidateKind = "model"
                        elseif auraObject
                            and (auraObject:IsA("BasePart") or auraObject:IsA("Model")) then
                            candidateKind = "aura"
                        end
                        if candidateKind then
                            seenModules[node] = true
                            AllCandidates[#AllCandidates + 1] = {
                                name = node.Name,
                                path = allPathOf(node),
                                module = node,
                                kind = candidateKind,
                            }
                        end
                    end
                    if node:IsA("Folder") then
                        local nodeName = allLower(node.Name)
                        local skipFolder = nodeName == "emotes"
                            or nodeName == "boomboxes"
                            or nodeName == "loadout"
                            or nodeName == "carryanimations"
                        if not skipFolder then
                            for _, child in ipairs(node:GetChildren()) do
                                if child:IsA("Folder") or child:IsA("ModuleScript") then
                                    queue[#queue + 1] = child
                                end
                            end
                        end
                    end
                end
            end
            allSetCount(#AllCandidates)
            allSetStatus("Escaneando " .. tostring(scanned) .. " nodos • " .. tostring(#AllCandidates) .. " candidatos")
            task.wait(AllDiscoveryWait)
        end

        if scanned >= AllMaxDiscoveryNodes and queueIndex <= #queue then
            limitReached = true
        end
        table.sort(AllCandidates, function(a, b)
            local al = allLower(a.name)
            local bl = allLower(b.name)
            if al == bl then return allLower(a.path) < allLower(b.path) end
            return al < bl
        end)
        AllDiscoveryRunning = false
        allSetCount(#AllCandidates)
        if AllTabVisible then
            allRebuildRows()
        end
        if limitReached then
            allSetStatus("Límite alcanzado • " .. tostring(#AllCandidates) .. " candidatos • pulsa REFRESH")
        else
            allSetStatus("Terminado • " .. tostring(#AllCandidates) .. " candidatos • busca o desplázate")
        end
    end)
end

