task.spawn(function()
    local rigs = Workspace:FindFirstChild("Rigs") or Workspace:WaitForChild("Rigs", 30)
    if not rigs then return end
    rigs.ChildAdded:Connect(function(child)
        if child.Name ~= LocalPlayer.Name or AllEquippedCount == 0 then return end
        task.delay(0.6, function()
            if child.Parent then
                allReequipAll()
            end
        end)
    end)
end)

