-- Cosmético visual con el método de Unlock All (antes: swap de dara, que intercambiaba los hijos de los dos
-- cosméticos dentro de ReplicatedStorage.Items). Ahora, al armarse TU personaje (Objects.Game.Character.Rig → BuildRig)
-- se cambia la lista Cosmetics solo en tu cliente: se quita el actual y se pone el nuevo. Nada se manda al servidor.
-- Se ve al aparecer / reaparecer (un personaje ya armado no se vuelve a armar). Sirve para cosméticos, personajes y
-- auras (van en la misma lista). Nombres: Items.Registry.TryGetByName (y sin distinguir mayúsculas si no coincide).
-- cosSwaps[idActual] = { to = idNuevo, fromName, toName }. Una sola tabla local por el límite de 200 registros.
local CosVis = {}
function CosVis.Req(...)
    local names = { ... }
    local ok, res = pcall(function()
        local cur = ReplicatedStorage
        for _, name in ipairs(names) do
            cur = cur and cur:WaitForChild(name, 10)
        end
        if not cur then error("ruta no encontrada") end
        return require(cur)
    end)
    if ok then return res end
    warn("[Cosmetics Changer] no se pudo cargar " .. table.concat(names, ".") .. " -> " .. tostring(res))
    return nil
end
function CosVis.Load()
    CosVis.Registry = CosVis.Registry or CosVis.Req("Items", "Registry")
    CosVis.Rig = CosVis.Rig or CosVis.Req("Objects", "Game", "Character", "Rig")
    return CosVis.Registry ~= nil and CosVis.Rig ~= nil
end
-- nombre exacto primero; si no, sin distinguir mayúsculas
function CosVis.Find(name)
    local entry = nil
    pcall(function() entry = CosVis.Registry.TryGetByName(name) end)
    if entry and entry.Id then return entry.Id, entry.Module.Name end
    local lower = string.lower(name)
    local okAll, all = pcall(CosVis.Registry.GetAll)
    if okAll and type(all) == "table" then
        local n = 0
        for id, e in pairs(all) do
            n = n + 1
            if n % 200 == 0 then task.wait() end
            local okN, modName = pcall(function() return e.Module.Name end)
            if okN and type(modName) == "string" and string.lower(modName) == lower then
                return id, modName
            end
        end
    end
    return nil, nil
end
-- los módulos del juego pueden venir congelados: igual que Unlock All, se pide poder escribir
function CosVis.Writable(tbl)
    local function probe() return pcall(function() tbl.__yy_probe = nil end) end
    if probe() then return true end
    if type(setreadonly) == "function" then pcall(setreadonly, tbl, false) end
    if probe() then return true end
    if type(make_writeable) == "function" then pcall(make_writeable, tbl) end
    return probe()
end
function CosVis.Wrap(orig)
    return function(self, ...)
        if next(cosSwaps) ~= nil and not self.Built and type(self.Cosmetics) == "table"
            and self.RigTerm and self.Actions and self.ToolSkins and self.Boombox
        then
            local isLocal = false
            pcall(function() isLocal = self.Parent ~= nil and self.Parent.Local == true end)
            if isLocal then
                local ok, err = pcall(function()
                    local out, seen, present, applied, missing = {}, {}, {}, {}, {}
                    for _, id in ipairs(self.Cosmetics) do present[id] = true end
                    for _, id in ipairs(self.Cosmetics) do
                        local s = cosSwaps[id]
                        local final = s and s.to or id
                        if not seen[final] then
                            out[#out + 1] = final
                            seen[final] = true
                        end
                        if s then applied[#applied + 1] = s.fromName .. " → " .. s.toName end
                    end
                    for from, s in pairs(cosSwaps) do
                        if not present[from] then missing[#missing + 1] = s.fromName end
                    end
                    self.Cosmetics = out
                    task.defer(function()
                        if #applied > 0 then
                            cosSetStatus(scriptText("Aplicado en tu personaje: ", "Applied on your character: ") .. table.concat(applied, ", "), Color3.fromRGB(150, 255, 190))
                        elseif #missing > 0 then
                            cosSetStatus(scriptText("No tenías puesto: ", "You were not wearing: ") .. table.concat(missing, ", "), Color3.fromRGB(255, 185, 115))
                        end
                    end)
                end)
                if not ok then warn("[Cosmetics Changer] BuildRig: " .. tostring(err)) end
            end
        end
        return orig(self, ...)
    end
end
-- pone el gancho (o lo vuelve a poner si Unlock All lo sacó al apagarse y restaurar su original)
function CosVis.Ensure()
    local rig = CosVis.Rig
    if not rig then return false end
    if CosVis.Wrapper and rig.BuildRig == CosVis.Wrapper then return true end
    if type(rig.BuildRig) ~= "function" or not CosVis.Writable(rig) then return false end
    CosVis.Wrapper = CosVis.Wrap(rig.BuildRig)
    rig.BuildRig = CosVis.Wrapper
    return true
end

local function cosApply()
    local current = cosTrim(cosCurrentName)
    local target = cosTrim(cosNewName)
    if current == "" or target == "" then
        cosSetStatus(scriptText("Faltan los dos nombres de cosmético.", "Both cosmetic names are required."), Color3.fromRGB(255, 185, 115))
        return
    end
    if current == target then
        cosSetStatus(scriptText("El cosmético actual y el nuevo deben ser diferentes.", "The current and new cosmetic must be different."), Color3.fromRGB(255, 185, 115))
        return
    end
    cosSetStatus(scriptText("Buscando cosméticos...", "Searching cosmetics..."), Color3.fromRGB(175, 185, 205))
    task.spawn(function()
        if not CosVis.Load() then
            cosSetStatus(scriptText("No se cargaron los módulos del juego.", "The game modules did not load."), Color3.fromRGB(255, 125, 125))
            return
        end
        local fromId, fromName = CosVis.Find(current)
        local toId, toName = CosVis.Find(target)
        if not fromId or not toId then
            cosSetStatus(scriptText("No se encontró alguno de los nombres. Revisá cómo se escribe.", "One of the names was not found. Check the spelling."), Color3.fromRGB(255, 125, 125))
            return
        end
        if fromId == toId then
            cosSetStatus(scriptText("El cosmético actual y el nuevo deben ser diferentes.", "The current and new cosmetic must be different."), Color3.fromRGB(255, 185, 115))
            return
        end
        if not CosVis.Ensure() then
            cosSetStatus(scriptText("No se pudo enganchar el armado del personaje.", "Could not hook the character build."), Color3.fromRGB(255, 125, 125))
            return
        end
        cosSwaps[fromId] = { to = toId, fromName = fromName, toName = toName }
        cosSetStatus(scriptText("Aplicado: ", "Applied: ") .. fromName .. " → " .. toName
            .. scriptText(" · se ve al aparecer o reaparecer.", " · it shows when you spawn or respawn."), Color3.fromRGB(150, 255, 190))
        print("✅ COSMETICS CHANGER: " .. fromName .. " → " .. toName)
    end)
end

local function cosReset()
    local count = 0
    for _ in pairs(cosSwaps) do count = count + 1 end
    table.clear(cosSwaps)
    if count == 0 then
        cosSetStatus(scriptText("No hay cosméticos cambiados para restablecer.", "There are no swapped cosmetics to reset."), Color3.fromRGB(255, 185, 115))
    else
        cosSetStatus(scriptText("Cosméticos restablecidos: vuelven los tuyos al reaparecer.", "Cosmetics reset: yours come back when you respawn."), Color3.fromRGB(150, 255, 190))
    end
end

AllDesign.Button(AllCosmeticsPage, "APLICAR COSMÉTICO", "APPLY COSMETIC", cosApply, true)
AllDesign.Button(AllCosmeticsPage, "RESTABLECER COSMÉTICOS", "RESET COSMETICS", cosReset, false)
cosStatusLabel = AllDesign.Status(AllCosmeticsPage, "Listo para aplicar un cambio de cosmético.", "Ready to apply a cosmetic change.")

TabAll:ResetContentContainer()

-- Orden de la página según el orden en que se crearon los elementos (mezcla de elementos de la librería y cajas propias)
for index, child in ipairs(AllCosmeticsPage:GetChildren()) do
    if child:IsA("GuiObject") then
        child.LayoutOrder = index
    end
end
allUpdateCarouselHeight(AllCosmeticsPage)
allUpdateCarouselHeight(AllCatalogPage)

-- ===== Página 3 del carrusel: Tools Skin Changer =====
-- Lógica: skin visual de Unlock All (antes: swap de Dara Hub, que intercambiaba los hijos de dos skins dentro de
-- ReplicatedStorage.Tools.<Tool>.Variants). Ahora, cuando TU herramienta lee DataRegistry:Get("ToolSkins") al
-- equiparse (ToolProfile.CharacterVisuals), en tu cliente se quita la skin real de ese tool y se pone la elegida.
-- Los colocables (trampolín, mina...) los arma DeployableService.Build con el atributo "Skin": si son tuyos se les
-- pone la skin elegida, solo en tu pantalla. Nada se manda al servidor. Se ve al volver a equipar el tool.
do
    local AllSkinsPage = allMakeCarouselPage("AllSkinsCarouselContent")
    AllCarouselPages.Skins = AllSkinsPage
    TabAll:SetContentContainer(AllSkinsPage)

    AllDesign.Header(
        AllSkinsPage,
        "CAMBIADOR DE SKINS DE TOOLS", "TOOLS SKIN CHANGER",
        "Escribe el tool, la skin actual y la skin que quieres usar.",
        "Enter the tool, the current skin and the skin you want to use."
    )

    -- Swaps[nombreDelTool] = { skin = idSkin o false (= Default), skinName }; ToolOf[idSkin] = nombre del tool
    local ToolVis = { Swaps = {}, ToolOf = {} }
    local currentToolInput = ""
    local currentSkinInput = ""
    local selectedSkinInput = ""
    local skinStatusLabel

    local function skinTrim(value)
        local text = tostring(value or "")
        text = text:gsub("^%s+", "")
        text = text:gsub("%s+$", "")
        return text
    end

    local function skinSetStatus(text, color)
        AllDesign.SetStatus(skinStatusLabel, text, color)
    end

    local function skinCreateBox(titleSpanish, titleEnglish, placeholderSpanish, placeholderEnglish, setter)
        local input = AllDesign.Field(AllSkinsPage, titleSpanish, titleEnglish, placeholderSpanish, placeholderEnglish)
        input.Name = "AllSkinNameInput"
        input:GetPropertyChangedSignal("Text"):Connect(function()
            setter(skinTrim(input.Text))
        end)
        return input
    end

    skinCreateBox(
        "NOMBRE DEL TOOL", "TOOL NAME",
        "Nombre del tool", "Enter tool name",
        function(value) currentToolInput = value end
    )
    skinCreateBox(
        "SKIN ACTUAL", "CURRENT SKIN",
        "Skin que tenés (opcional)", "Skin you have (optional)",
        function(value) currentSkinInput = value end
    )
    skinCreateBox(
        "SKIN NUEVA", "NEW SKIN",
        "Skin que querés ver (Default = sin skin)", "Skin you want (Default = no skin)",
        function(value) selectedSkinInput = value end
    )

    local function skinKey(text) return string.lower((tostring(text or ""):gsub("%s+", ""))) end

    function ToolVis.Req(...)
        local names = { ... }
        local ok, res = pcall(function()
            local cur = ReplicatedStorage
            for _, name in ipairs(names) do
                cur = cur and cur:WaitForChild(name, 10)
            end
            if not cur then error("ruta no encontrada") end
            return require(cur)
        end)
        if ok then return res end
        warn("[Tools Skin Changer] no se pudo cargar " .. table.concat(names, ".") .. " -> " .. tostring(res))
        return nil
    end

    -- tool por nombre (sin espacios ni mayúsculas): ReplicatedStorage.Tools.<Tool> con su carpeta Variants
    function ToolVis.FindTool(name)
        local tools = ReplicatedStorage:FindFirstChild("Tools")
        if not tools then return nil end
        local exact = tools:FindFirstChild(name)
        if exact and exact:FindFirstChild("Variants") then return exact end
        local key = skinKey(name)
        for _, tool in ipairs(tools:GetChildren()) do
            if skinKey(tool.Name) == key and tool:FindFirstChild("Variants") then return tool end
        end
        return nil
    end

    -- skins del Registry: items con "Original" (ObjectValue al tool), igual que Unlock All y el menú del juego
    function ToolVis.FindSkin(tool, name)
        if not ToolVis.Registry then return nil end
        local key = skinKey(name)
        local okAll, all = pcall(ToolVis.Registry.GetAll)
        if not okAll or type(all) ~= "table" then return nil end
        local n = 0
        for id, entry in pairs(all) do
            n = n + 1
            if n % 200 == 0 then task.wait() end
            local okE, toolName, moduleName = pcall(function()
                local original = entry.Module:FindFirstChild("Original")
                if original and original:IsA("ObjectValue") and original.Value then
                    return original.Value.Name, entry.Module.Name
                end
                return nil, nil
            end)
            if okE and toolName then
                ToolVis.ToolOf[id] = toolName
                if toolName == tool.Name and skinKey(moduleName) == key then return id, moduleName end
            end
        end
        return nil
    end

    -- lista ToolSkins (ids de skins): se sacan las skins de los tools cambiados y se ponen las elegidas
    function ToolVis.Substitute(value)
        local out, seen = {}, {}
        if type(value) == "table" then
            for _, id in ipairs(value) do
                local toolName = ToolVis.ToolOf[id]
                if toolName == nil then
                    pcall(function()
                        local entry = ToolVis.Registry.TryGetById(id)
                        local original = entry and entry.Module:FindFirstChild("Original")
                        toolName = (original and original.Value and original.Value.Name) or false
                    end)
                    ToolVis.ToolOf[id] = toolName or false
                end
                if not (toolName and ToolVis.Swaps[toolName]) and not seen[id] then
                    out[#out + 1] = id
                    seen[id] = true
                end
            end
        end
        for _, swap in pairs(ToolVis.Swaps) do
            if swap.skin and not seen[swap.skin] then
                out[#out + 1] = swap.skin
                seen[swap.skin] = true
            end
        end
        return out
    end

    -- los módulos del juego pueden venir congelados: igual que Unlock All, se pide poder escribir
    function ToolVis.Writable(tbl)
        local function probe() return pcall(function() tbl.__yy_probe = nil end) end
        if probe() then return true end
        if type(setreadonly) == "function" then pcall(setreadonly, tbl, false) end
        if probe() then return true end
        if type(make_writeable) == "function" then pcall(make_writeable, tbl) end
        return probe()
    end

    -- engancha DataRegistry.Get (o lo vuelve a enganchar si Unlock All lo sacó al apagarse)
    function ToolVis.Ensure()
        local class = ToolVis.DataReg
        if not class then return false end
        if ToolVis.GetWrapper and class.Get == ToolVis.GetWrapper then return true end
        if type(class.Get) ~= "function" or not ToolVis.Writable(class) then return false end
        local orig = class.Get
        ToolVis.GetWrapper = function(self, term, ...)
            local value = orig(self, term, ...)
            if term == "ToolSkins" and next(ToolVis.Swaps) ~= nil then
                local okL, isLocal = pcall(function() return self.Parent ~= nil and self.Parent.Local == true end)
                if okL and isLocal then
                    local okS, res = pcall(ToolVis.Substitute, value)
                    if okS and res ~= nil then return res end
                end
            end
            return value
        end
        class.Get = ToolVis.GetWrapper
        return true
    end

    -- colocables: DeployableService espera a workspace.Effects.Deployables, por eso se carga en un hilo aparte
    function ToolVis.EnsureDeployables()
        if ToolVis.DeployStarted then return end
        ToolVis.DeployStarted = true
        task.spawn(function()
            local svc = ToolVis.Req("Services", "Items", "DeployableService")
            if not svc or type(svc.Build) ~= "function" or not ToolVis.Writable(svc) then return end
            local orig = svc.Build
            svc.Build = function(self, model, ...)
                if next(ToolVis.Swaps) ~= nil and typeof(model) == "Instance" then
                    pcall(function()
                        local swap = ToolVis.Swaps[model.Name]
                        if not swap then return end
                        local owner = model:GetAttribute("Owner")
                        local lp = Players.LocalPlayer
                        if owner == lp.Name or owner == lp.DisplayName or owner == lp.UserId then
                            model:SetAttribute("Skin", swap.skin or nil) -- solo en tu cliente
                        end
                    end)
                end
                return orig(self, model, ...)
            end
        end)
    end

    local function swapSkins(toolName, currentSkinName, selectedSkinName)
        if toolName == "" or skinKey(selectedSkinName) == "" then
            skinSetStatus(scriptText("Escribí el tool y la skin nueva.", "Enter the tool and the new skin."), Color3.fromRGB(255, 185, 115))
            return false
        end
        if currentSkinName ~= "" and skinKey(currentSkinName) == skinKey(selectedSkinName) then
            skinSetStatus(scriptText("Los nombres de skin no pueden ser iguales.", "Skin names cannot be the same"), Color3.fromRGB(255, 185, 115))
            return false
        end
        skinSetStatus(scriptText("Buscando skin...", "Searching skin..."), Color3.fromRGB(175, 185, 205))
        task.spawn(function()
            ToolVis.Registry = ToolVis.Registry or ToolVis.Req("Items", "Registry")
            ToolVis.DataReg = ToolVis.DataReg or ToolVis.Req("Objects", "Game", "Character", "DataRegistry")
            if not (ToolVis.Registry and ToolVis.DataReg) then
                skinSetStatus(scriptText("No se cargaron los módulos del juego.", "The game modules did not load."), Color3.fromRGB(255, 125, 125))
                return
            end
            local tool = ToolVis.FindTool(toolName)
            if not tool then
                skinSetStatus(scriptText("Tool no encontrado: ", "Tool not found: ") .. toolName, Color3.fromRGB(255, 125, 125))
                return
            end
            local skinId, skinName = false, "Default"
            if skinKey(selectedSkinName) ~= "default" then
                skinId, skinName = ToolVis.FindSkin(tool, selectedSkinName)
                if not skinId then
                    skinSetStatus(scriptText("Skin nueva no encontrada para ", "New skin not found for ") .. tool.Name .. ": " .. selectedSkinName, Color3.fromRGB(255, 125, 125))
                    return
                end
                if not tool.Variants:FindFirstChild(skinName) then
                    skinSetStatus(scriptText("Esa skin no tiene modelo en ", "That skin has no model in ") .. tool.Name .. ".Variants", Color3.fromRGB(255, 125, 125))
                    return
                end
            end
            if not ToolVis.Ensure() then
                skinSetStatus(scriptText("No se pudo enganchar las skins de herramientas.", "Could not hook the tool skins."), Color3.fromRGB(255, 125, 125))
                return
            end
            ToolVis.EnsureDeployables()
            ToolVis.Swaps[tool.Name] = { skin = skinId, skinName = skinName }
            skinSetStatus(
                scriptText("Cambio aplicado: ", "Swap applied: ") .. tool.Name .. " → " .. skinName
                    .. scriptText(" · se ve al volver a equipar el tool.", " · it shows when you equip the tool again."),
                Color3.fromRGB(150, 255, 190)
            )
            print("✅ TOOLS SKIN CHANGER: " .. tool.Name .. " → " .. skinName)
        end)
        return true
    end

    AllDesign.Button(AllSkinsPage, "REEMPLAZAR SKIN", "REPLACE SKIN SWAP", function()
        swapSkins(currentToolInput, currentSkinInput, selectedSkinInput)
    end, true)
    AllDesign.Button(AllSkinsPage, "RESTABLECER SKINS", "RESET ALL SKINS", function()
        local had = next(ToolVis.Swaps) ~= nil
        table.clear(ToolVis.Swaps)
        if had then
            skinSetStatus(
                scriptText("Skins restablecidas: vuelven las tuyas al volver a equipar.", "Skins reset: yours come back when you equip again."),
                Color3.fromRGB(150, 255, 190)
            )
        else
            skinSetStatus(scriptText("No hay skins cambiadas para restablecer.", "There are no swapped skins to reset."), Color3.fromRGB(255, 185, 115))
        end
    end, false)
    skinStatusLabel = AllDesign.Status(AllSkinsPage, "Listo para cambiar una skin.", "Ready to swap a skin.")

    TabAll:ResetContentContainer()

    -- Orden de la página según el orden de creación (mezcla de elementos de la librería y cajas propias)
    for index, child in ipairs(AllSkinsPage:GetChildren()) do
        if child:IsA("GuiObject") then
            child.LayoutOrder = index
        end
    end
    allUpdateCarouselHeight(AllSkinsPage)
end

allSetCarouselMode("Catalog")

UserInputService.InputBegan:Connect(function(input)
    if input.UserInputType ~= Enum.UserInputType.Touch
        and input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
    if UserInputService:GetFocusedTextBox() then return end
    local page = TabAll.Page
    if not page.Visible then return end
    local pos = input.Position
    local ap, as = page.AbsolutePosition, page.AbsoluteSize
    if pos.X < ap.X or pos.X > ap.X + as.X or pos.Y < ap.Y or pos.Y > ap.Y + as.Y then return end
    AllCarouselSwipe.input = input
    AllCarouselSwipe.start = input.Position
end)

UserInputService.InputEnded:Connect(function(input)
    if input ~= AllCarouselSwipe.input or not AllCarouselSwipe.start then return end
    local delta = input.Position - AllCarouselSwipe.start
    AllCarouselSwipe.input = nil
    AllCarouselSwipe.start = nil
    if math.abs(delta.X) < AllCarouselSwipe.threshold
        or math.abs(delta.X) <= math.abs(delta.Y) * 1.20
        or UserInputService:GetFocusedTextBox() then return end

    local direction = delta.X < 0 and 1 or -1
    local carouselOrder = { "Catalog", "Cosmetics", "Skins" }
    local currentIndex = table.find(carouselOrder, AllCarouselMode) or 1
    local nextMode = carouselOrder[currentIndex + direction]
    if not nextMode then return end
    allSetCarouselMode(nextMode, direction)
end)

TabAll.Page:GetPropertyChangedSignal("Visible"):Connect(function()
    AllTabVisible = TabAll.Page.Visible
    if not AllDiscoveryRunning then
        allRebuildRows()
    end
end)

local AllSearchDebounceToken = 0
AllSearch:GetPropertyChangedSignal("Text"):Connect(function()
    AllSearchDebounceToken = AllSearchDebounceToken + 1
    local token = AllSearchDebounceToken
    task.delay(0.25, function()
        if token ~= AllSearchDebounceToken then return end
        AllUI.Dirty = true
        if not AllDiscoveryRunning and AllTabVisible then
            allRebuildRows()
        end
    end)
end)

local oldAllVisuals = Workspace:FindFirstChild("__YY_AllVisualCandidates")
if oldAllVisuals then pcall(function() oldAllVisuals:Destroy() end) end

local AllInitOk, AllInitError = pcall(allDiscoverCandidates)
if not AllInitOk then
    allSetStatus("Error de All: " .. tostring(AllInitError))
    warn("[All] Error al iniciar el descubrimiento: " .. tostring(AllInitError))
end

end

setupAllTab()

-- ===== PESTAÑA GUÍA: tutorial de cada pestaña y de cada opción =====
-- Todo el texto sale de lo que hace el código de cada opción en este script (revisado opción por opción).
-- Diseño: tarjeta de inicio con buscador, chips por pestaña y tarjetas que se abren al tocarlas.
-- Funcion global (no local) por el limite de 200 registros del chunk principal.
function setupGuideTab()
    -- ícono: el mismo que la librería usa por defecto cuando falta uno (rbxassetid://83456197177232)
    local TabGuide = UI:CreateTab("Guía", "Guide", "rbxassetid://83456197177232")
    local page = TabGuide.Page

    -- la guía (tarjeta de inicio, buscador, chips y tarjetas que se abren) la arma la librería (YinYang.Kit.Page.Guide)
    -- con el tema activo; acá queda solo el contenido

    -- ---------- contenido ----------
    -- n = nombre, s = resumen de una línea, h = cómo usarlo, sl = sliders/sub-opciones, t = etiquetas
    local TAGS = {
        FLOAT = { "Flotante", "Floating" },
        BUTTON = { "Botón", "Button" },
        MOBILE = { "Solo celular", "Mobile only" },
        NOSOLARA = { "No en Solara", "Not on Solara" },
        PREMIUM = { "Premium", "Premium" },
        VISUAL = { "Solo lo ves vos", "Only you see it" },
    }
    local GUIDE = {
        {
            Key = "start", Es = "Inicio", En = "Start", Icon = "rbxassetid://83456197177232",
            Sum = { "Lo básico para usar el script en 1 minuto.", "The basics to use the script in 1 minute." },
            Sections = {
                { "PRIMEROS PASOS", "FIRST STEPS", {
                    { n = { "1 · Cambiar de pestaña", "1 · Switch tabs" }, s = { "Las pestañas están en la barra de la ventana.", "Tabs are in the window's bar." },
                      h = { "Tocá una pestaña para ver sus opciones. Cada pestaña está dividida en secciones con un título (por ejemplo VELOCIDAD o SALTO).", "Tap a tab to see its options. Each tab is split into sections with a title (for example SPEED or JUMP)." } },
                    { n = { "2 · Prender y apagar", "2 · Turn on and off" }, s = { "Tocá el interruptor de la derecha.", "Tap the switch on the right." },
                      h = { "Encendido = la opción funciona. Apagado = todo vuelve a la normalidad.", "On = the option works. Off = everything goes back to normal." } },
                    { n = { "3 · Sliders", "3 · Sliders" }, s = { "Deslizá para cambiar un valor.", "Slide to change a value." },
                      h = { "Si una opción tiene varios sliders juntos, aparecen en un carrusel: deslizá hacia el costado para pasar de uno a otro.", "If an option has several sliders together, they show in a carousel: swipe sideways to go from one to another." } },
                    { n = { "4 · Botones de cada opción", "4 · Each option's buttons" }, s = { "Las opciones grandes tienen botones extra.", "Big options have extra buttons." },
                      h = { "Debajo del nombre de esas opciones hay botones pequeños:", "Under those options' names there are small buttons:" },
                      sl = {
                          { "★", "la agrega a la pestaña Favs para tenerla a mano.", "adds it to the Favs tab to keep it handy." },
                          { "↗", "la saca a un botón flotante en la pantalla (← la devuelve).", "turns it into a floating button on screen (← brings it back)." },
                          { "📌", "fija el botón flotante para que no se mueva sin querer.", "locks the floating button so it doesn't move by accident." },
                          { "Combo", "la suma a Combinado (pestaña Move) para prender varias de una.", "adds it to Combined (Move tab) to turn several on at once." },
                          { "Tecla", "le asigna una tecla del teclado para prenderla.", "assigns a keyboard key to turn it on." },
                      } },
                    { n = { "5 · Ajustes y Favs", "5 · Settings and Favs" }, s = { "Dos pestañas que trae la interfaz.", "Two tabs built into the interface." },
                      h = { "Favs junta las opciones que marcaste con ★. Ajustes tiene opciones de la interfaz: congelar el ícono, sonidos, ocultar sliders, shaders y el modo rendimiento máximo.", "Favs groups the options you starred. Settings has interface options: freeze the icon, sounds, hide sliders, shaders and max performance mode." } },
                    { n = { "6 · Pases", "6 · Passes" }, s = { "Botón de bolsa en la barra de arriba.", "Bag button in the top bar." },
                      h = { "Abre la tienda de Yin Yang con nuestros pases. Los pases quedan en tu cuenta de Roblox para siempre.", "Opens the Yin Yang shop with our passes. Passes stay on your Roblox account forever." } },
                } },
                { "ETIQUETAS", "TAGS", {
                    { n = { "Qué significa cada etiqueta", "What each tag means" }, s = { "Aparecen al lado de cada opción en esta guía.", "They appear next to each option in this guide." },
                      sl = {
                          { "Flotante", "se puede sacar como botón en pantalla.", "can be turned into an on-screen button." },
                          { "Solo celular", "solo aparece si jugás en celular.", "only shows if you play on mobile." },
                          { "No en Solara", "no funciona con el ejecutor Solara.", "doesn't work with the Solara executor." },
                          { "Solo lo ves vos", "es visual: los demás no lo ven.", "it's visual: others don't see it." },
                          { "Premium", "necesita el pase Yin Yang Colors.", "needs the Yin Yang Colors pass." },
                      } },
                } },
                { "PALABRAS QUE VAS A VER", "WORDS YOU'LL SEE", {
                    { n = { "¿No entendés una palabra?", "Don't get a word?" }, s = { "Acá está lo que significa cada una, sin vueltas.", "Here's what each one means, plain and simple." },
                      sl = {
                          { "Slider", "la barrita que deslizás para cambiar un número (más a la derecha = más).", "the little bar you slide to change a number (further right = more)." },
                          { "Multiplicador", "multiplica algo normal del juego: 1 = igual que siempre, 2 = el doble, 0,5 = la mitad.", "multiplies something normal in the game: 1 = same as always, 2 = double, 0.5 = half." },
                          { "Stud", "la medida de distancia de Roblox. Tu personaje mide unos 5 studs de alto.", "Roblox's distance unit. Your character is about 5 studs tall." },
                          { "Bhop (bunny hop)", "saltar justo cuando tocás el piso para no perder velocidad.", "jumping right when you touch the ground so you don't lose speed." },
                          { "Trimp", "saltar desde una rampa o pendiente yendo rápido para salir volando más alto y más lejos.", "jumping off a ramp or slope while going fast to fly higher and farther." },
                          { "Air-strafe", "en el aire, girar la cámara y apretar hacia el costado para doblar y ganar velocidad.", "in the air, turning the camera and pressing sideways to curve and gain speed." },
                          { "Slide", "deslizarte agachándote mientras corrés.", "sliding by crouching while you run." },
                          { "Bot", "los enemigos de Evade que te persiguen.", "Evade's enemies that chase you." },
                          { "Caído", "un jugador que atraparon y espera que lo revivan.", "a player who got caught and is waiting to be revived." },
                          { "ESP", "ver jugadores o cosas a través de las paredes.", "seeing players or things through walls." },
                          { "FOV", "cuánto ves a los costados (campo de visión).", "how much you see to the sides (field of view)." },
                          { "HUD", "los botones, barras e íconos del juego en tu pantalla.", "the game's buttons, bars and icons on your screen." },
                          { "AFK", "estar sin jugar (por ejemplo, dejar el celu quieto).", "being away without playing (for example, leaving your phone idle)." },
                          { "Ejecutor", "el programa con el que cargás el script (Solara es uno de PC).", "the program you load the script with (Solara is a PC one)." },
                      } },
                } },
            },
        },
        {
            Key = "move", Es = "Move", En = "Move", Icon = "rbxassetid://113840719109563",
            Sum = { "Todo lo que cambia cómo te movés: velocidad, saltos y trucos.", "Everything that changes how you move: speed, jumps and tricks." },
            Sections = {
                { "VELOCIDAD", "SPEED", {
                    { n = { "Velocidad", "Speed" }, t = { "FLOAT" }, s = { "Corrés más rápido.", "You run faster." },
                      h = { "Prendela y elegí cuánto con el slider.", "Turn it on and pick how much with the slider." }, sl = { { "Speed", "multiplicador: multiplica tu velocidad normal de correr. 1 = normal, 2 = el doble, 5 = cinco veces.", "multiplier: multiplies your normal running speed. 1 = normal, 2 = double, 5 = five times." } } },
                    { n = { "Paso rápido", "TP Walk" }, t = { "FLOAT" }, s = { "Te adelanta un poco en cada paso.", "Moves you a bit forward on every step." },
                      h = { "Funciona mientras caminás.", "Works while you walk." }, sl = { { "TP Speed", "más alto = más rápido (muy alto se nota a saltos).", "higher = faster (very high looks jumpy)." } } },
                    { n = { "Slide infinito", "Infinite Slide" }, t = { "FLOAT" }, s = { "Deslizás sin frenar.", "You slide without stopping." },
                      h = { "Prendelo y deslizate como siempre.", "Turn it on and slide as usual." }, sl = { { "Slide Speed", "cuánta velocidad ganás por segundo mientras deslizás (más alto = llegás antes a la máxima del slide). Al levantarte salís con la velocidad normal de correr.", "how much speed you gain per second while sliding (higher = you reach the slide's max sooner). When you stand up you leave at normal running speed." } } },
                    { n = { "Auto agachar", "Auto Crouch" }, t = { "FLOAT" }, s = { "Se agacha y levanta solo, sin parar.", "Crouches and stands up by itself, nonstop." },
                      sl = { { "Crouch Rate", "cuántas veces por segundo.", "how many times per second." } } },
                } },
                { "SALTO", "JUMP", {
                    { n = { "Altura de salto", "Jump Height" }, t = { "FLOAT" }, s = { "Saltás más alto.", "You jump higher." }, sl = { { "Height", "la altura del salto.", "the jump height." } } },
                    { n = { "Auto salto", "Auto Jump" }, t = { "FLOAT" }, s = { "Salta solo cada vez que tocás el piso.", "Jumps by itself every time you touch the ground." }, sl = { { "Jump Rate", "saltos por segundo.", "jumps per second." } } },
                    { n = { "Bunny Hop", "Bunny Hop" }, t = { "FLOAT" }, s = { "Saltos encadenados sin perder velocidad.", "Chained jumps without losing speed." },
                      sl = {
                          { "Mantener salto", "solo hace bhop mientras mantenés el botón de salto.", "only bhops while you hold the jump button." },
                          { "Bhop acelerado", "ganás velocidad en cada salto.", "you gain speed on every jump." },
                          { "Salto realista", "salta como lo haría un jugador real.", "jumps the way a real player would." },
                          { "Bhop Accel", "cuánta velocidad ganás en cada salto. Ojo: va al revés, cuanto más bajo (más negativo) el número, más ganás.", "how much speed you gain on each jump. Careful: it's backwards, the lower (more negative) the number, the more you gain." },
                      } },
                    { n = { "Auto acelerar", "Auto Accel" }, s = { "Acelera de a poco hasta tu velocidad máxima.", "Speeds up little by little to your max speed." },
                      sl = { { "Max / Min Accel", "la aceleración más alta y más baja que puede usar mientras te lleva a la velocidad tope.", "the highest and lowest acceleration it can use while taking you to the top speed." }, { "Max Speed", "la velocidad tope.", "the top speed." } } },
                    { n = { "Multi salto", "Multi Jump" }, t = { "FLOAT" }, s = { "Podés saltar varias veces en el aire.", "You can jump several times in the air." }, sl = { { "Jumps", "cuántos saltos seguidos.", "how many jumps in a row." } } },
                    { n = { "Salto impulso", "Impulse Jump" }, t = { "FLOAT" }, s = { "En el aire te empuja hacia donde mirás.", "In the air it pushes you where you look." }, sl = { { "Impulse", "la fuerza del empuje.", "the push strength." } } },
                    { n = { "Salto frontal", "Front Jump" }, t = { "FLOAT" }, s = { "Salta solo y te lanza hacia adelante.", "Jumps by itself and launches you forward." },
                      h = { "Si hay una rampa adelante, el salto es más fuerte. Mientras está prendido apaga Paso rápido, Altura de salto y Gravedad; al apagarlo vuelven.", "If there's a ramp ahead, the jump is stronger. While on it turns off TP Walk, Jump Height and Gravity; they come back when you turn it off." },
                      sl = { { "Front Speed", "velocidad hacia adelante.", "forward speed." }, { "Front Ramp", "cuánto más fuerte es todo cuando hay una rampa o algo adelante: el salto sube más y el empujón hacia adelante es mayor. Es un multiplicador: 1 = igual que siempre, 2 = el doble de fuerte. De fábrica (1,55) saltás bastante más alto que en un salto normal.", "how much stronger everything gets when there's a ramp or something ahead: the jump goes higher and the forward push is bigger. It's a multiplier: 1 = same as always, 2 = twice as strong. By default (1.55) you jump quite a bit higher than a normal jump." } } },
                    { n = { "Salto atrás", "Back Jump" }, t = { "FLOAT" }, s = { "Lo mismo, pero hacia atrás.", "The same, but backwards." }, sl = { { "Back Speed", "velocidad hacia atrás.", "backward speed." }, { "Back Ramp", "lo mismo que Front Ramp pero para Salto atrás. En 0 (de fábrica) las rampas no hacen nada especial.", "the same as Front Ramp but for Back Jump. At 0 (default) ramps do nothing special." } } },
                    { n = { "Entrenador", "Trainer" }, t = { "FLOAT" }, s = { "Panel con tu velocidad y la puntuación de cada salto.", "Panel with your speed and a score for every jump." },
                      h = { "Mide cuánto tardás en volver a saltar al tocar el piso: ¡Perfecto! (hasta 60 ms), Bien o Tarde. Muestra la racha de perfectos y cuánta velocidad ganaste.", "Measures how fast you jump again after landing: Perfect! (up to 60 ms), Good or Late. Shows your perfect streak and the speed you gained." } },
                    { n = { "Impulso de salto", "Jump Boost" }, t = { "FLOAT" }, s = { "Saltos seguidos que ganan velocidad hacia donde mirás.", "Chained jumps that gain speed where you look." }, sl = { { "Boost", "la velocidad del impulso.", "the boost speed." } } },
                } },
                { "TRIMP", "TRIMP", {
                    { n = { "Dara Trimp", "Dara Trimp" }, t = { "FLOAT" }, s = { "Te mantiene a mucha velocidad hacia donde mira la cámara.", "Keeps you at high speed where the camera looks." },
                      h = { "En PC también se prende y apaga con la tecla Q.", "On PC you can also toggle it with the Q key." },
                      sl = {
                          { "Speed / Accel", "velocidad máxima y qué tan rápido llega.", "max speed and how fast it gets there." },
                          { "Suave", "acelera de a poco en vez de golpe.", "accelerates gradually instead of instantly." },
                          { "Seguir movimiento", "usa la dirección en que caminás en vez de la cámara.", "uses the direction you walk instead of the camera." },
                      } },
                    { n = { "Trimp x Frontal", "Trimp x Frontal" }, t = { "FLOAT" }, s = { "El movimiento de Dara Trimp con el salto multiplicado de Salto frontal.", "Dara Trimp's movement with Front Jump's multiplied jump." },
                      h = { "Te lleva rápido hacia donde mira la cámara, igual que Dara Trimp. Nunca salta en piso plano: solo cuando tenés una rampa u obstáculo adelante, y ahí salta con el multiplicador. En el aire, si chocás algo, lo usa de rampa y seguís sin trabarte. No lo uses junto con Salto frontal ni Dara Trimp.", "Takes you fast where the camera looks, like Dara Trimp. It never jumps on flat ground: only when there's a ramp or obstacle ahead, and then it jumps with the multiplier. In the air, if you hit something, it uses it as a ramp and you keep going without getting stuck. Don't use it together with Front Jump or Dara Trimp." },
                      sl = {
                          { "Velocidad TxF / Aceleración TxF", "velocidad máxima y qué tan rápido llega.", "max speed and how fast it gets there." },
                          { "Fuerza salto TxF / Multiplicador salto TxF", "qué tan alto saltás en las rampas. La Fuerza es la base y el Multiplicador la agranda: 2 = el doble de alto. Si queda corto o te pasás, ajustá el Multiplicador.", "how high you jump on ramps. Power is the base and the Multiplier makes it bigger: 2 = twice as high. If it falls short or overshoots, adjust the Multiplier." },
                          { "Suave (TxF)", "acelera de a poco y frena suave al soltar.", "accelerates gradually and slows down smoothly when you let go." },
                          { "Seguir movimiento (TxF)", "usa la dirección en que caminás en vez de la cámara.", "uses the direction you walk instead of the camera." },
                          { "Potenciar mis saltos", "tus saltos a mano también salen con el multiplicador (apagado de fábrica).", "your own jumps also get the multiplier (off by default)." },
                      } },
                    { n = { "Auto Trimp", "Auto Trimp" }, t = { "FLOAT" }, s = { "En el aire te da más impulso y controla tu caída.", "In the air it gives more push and controls your fall." },
                      sl = { { "Trimp Power", "fuerza del impulso.", "push strength." }, { "Fall Speed", "qué tan rápido caés.", "how fast you fall." } } },
                    { n = { "Trimp + Walk", "Trimp + Walk" }, t = { "FLOAT" }, s = { "Auto Trimp y Paso rápido juntos.", "Auto Trimp and TP Walk together." } },
                    { n = { "Edge Trimp", "Edge Trimp" }, t = { "FLOAT" }, s = { "Al caerte de un borde te hace rebotar hacia arriba.", "When you fall off an edge it bounces you up." },
                      sl = { { "Edge Power", "fuerza del rebote.", "bounce strength." }, { "Fall Limit", "desde qué velocidad de caída rebota.", "from which fall speed it bounces." } } },
                    { n = { "Impulso rampa", "Ramp Boost" }, t = { "FLOAT" }, s = { "En rampas y escalones vas más rápido.", "On ramps and steps you go faster." }, sl = { { "Ramp Power", "cuánto más rápido vas y más alto saltás cuando tenés una rampa, escalón u obstáculo justo adelante. Es un multiplicador: 1 = sin cambio, 2 = el doble.", "how much faster you go and how much higher you jump when there's a ramp, step or obstacle right ahead. It's a multiplier: 1 = no change, 2 = double." } } },
                    { n = { "Wall Hop", "Wall Hop" }, s = { "Hace el wall hop solo al saltar contra una pared.", "Does the wall hop by itself when jumping at a wall." } },
                } },
                { "AIRE", "AIR", {
                    { n = { "Súper rebote", "Super Bounce" }, t = { "FLOAT" }, s = { "Un toque y das un salto gigante.", "One tap and you do a giant jump." },
                      h = { "Se apaga solo después de cada salto: tocalo cada vez que lo quieras usar.", "It turns itself off after each jump: tap it every time you want it." }, sl = { { "Bounce", "la altura del salto.", "the jump height." } } },
                    { n = { "Salto Goat", "Goat Jump" }, t = { "FLOAT" }, s = { "Al caer te lleva suave al objeto pequeño más cercano a donde vas a aterrizar.", "When falling it smoothly guides you to the small object nearest to where you'll land." },
                      sl = {
                          { "Goat Range", "qué tan lejos busca el objeto.", "how far it looks for the object." },
                          { "Goat Height", "altura del salto al tocarlo.", "jump height when you touch it." },
                          { "Apuntar con cámara", "elige el objeto hacia donde mirás.", "picks the object you're looking at." },
                          { "Saltar", "salta solo al tocar ese objeto.", "jumps by itself when you touch that object." },
                      } },
                    { n = { "Anti caída", "No Fall" }, t = { "FLOAT" }, s = { "Pone un piso invisible a la altura de tus pies.", "Puts an invisible floor at your feet's height." },
                      h = { "La altura se guarda al prenderlo. Si reaparecés, apagalo y prendelo de nuevo.", "The height is saved when you turn it on. If you respawn, turn it off and on again." } },
                    { n = { "Gravedad", "Gravity" }, t = { "FLOAT" }, s = { "Cambia qué tan rápido caés.", "Changes how fast you fall." }, sl = { { "Gravity", "menos de 1 = caés más lento, más de 1 = más rápido.", "under 1 = you fall slower, over 1 = faster." } } },
                } },
                { "PATRONES", "PATTERNS", {
                    { n = { "Ocho · Lissajous · Espirógrafo", "Figure 8 · Lissajous · Spirograph" }, t = { "FLOAT" }, s = { "Te mueven solos dibujando una figura.", "They move you by themselves drawing a shape." },
